insert into public.library_dojos (id, title, content, pptx_path) values ('b60cd224-7b69-5495-a8bb-94ac23214282', 'L''accueil personnalisé', $dojo${"version": 1, "tagline": "Créer un premier impact et favoriser la création de lien", "objective": "Le commercial sait aller vers le client en moins de 20 secondes, adapter son accueil au signal non-verbal perçu, proposer la boisson et amorcer une conversation sur le client avant de parler voiture.", "duration": "20-30 min", "theory": {"intro": "Les 7 premières secondes créent une impression qui durera toute la relation commerciale. L'accueil n'est pas une politesse — c'est le premier acte de vente. Il pose la confiance, crée le lien, et ouvre la découverte.", "standardTitle": "Le standard : l'accueil en 4 gestes clés", "standard": [{"label": "< 20 SEC", "title": "Aller vers le client", "description": "Se lever, quitter son bureau ou poste, aller physiquement à la rencontre du client. Ne pas attendre qu'il s'approche. Sourire déclenché avant le contact visuel.", "why": "Le client qui n'est pas accueilli en moins de 20 secondes se sent ignoré. L'initiative du commercial installe immédiatement qui est aux commandes."}, {"label": "SOURIRE + REGARD", "title": "Créer le premier contact", "description": "Contact visuel direct, sourire franc (pas commercial). Poignée de main ferme si le client tend la main, sinon ne pas forcer. Se présenter par son prénom : \"Bonjour, je m'appelle [prénom].\"", "why": "Le prénom crée une relation humaine immédiate. Le contact visuel signale l'engagement. L'absence de sourire sincère se détecte en 50 millisecondes."}, {"label": "LA BOISSON", "title": "Proposer une boisson", "description": "\"Je vous propose quelque chose à boire — un café, une eau ?\" Accompagner le client jusqu'à l'espace d'accueil. Ce déplacement crée un temps de transition qui détend et humanise.", "why": "La boisson n'est pas un gadget — c'est un rituel d'hospitalité universel. Elle ralentit la conversation, crée un cadre chaleureux, et positionne le commercial en hôte, pas en vendeur."}, {"label": "L'AMORCE", "title": "Amorcer la conversation par le client", "description": "Avant de parler voiture : une phrase d'ouverture sur le client lui-même. \"Vous venez de loin ? / Vous avez trouvé facilement ?\" Écouter vraiment la réponse et rebondir naturellement.", "why": "La première minute de conversation doit créer du lien, pas qualifier le projet. Le client qui parle de lui avant de parler de son besoin s'ouvre davantage ensuite."}], "criteria": [{"title": "Il lit les signaux non-verbaux dès l'entrée", "description": "Un client qui entre rapidement, les bras croisés, regard fuyant — il est en mode défensif. Un client qui regarde autour de lui avec curiosité — il est ouvert. L'accueil s'adapte à ce que le commercial voit, pas à un script."}, {"title": "Il ne parle pas voiture avant 2 minutes", "description": "Les 2 premières minutes appartiennent à l'humain, pas au projet. Le commercial qui demande \"vous cherchez quoi comme véhicule ?\" avant même de s'être présenté grille la relation avant qu'elle commence."}, {"title": "Il personnalise l'amorce", "description": "\"Vous avez trouvé facilement ?\" vaut mieux que \"bienvenue chez nous\". Une question sur le client — même banale — est une invitation à exister. C'est ça qui crée le lien, pas la formule de politesse."}, {"title": "Son énergie est constante quel que soit le profil", "description": "Le 12ème client de la journée mérite le même accueil que le premier. La fatigue se voit, l'enthousiasme se joue. Un commercial qui arrive avant le client — sourire déclenché avant le contact — installe l'énergie."}, {"title": "Il accompagne, il ne précède pas", "description": "Il marche avec le client jusqu'à l'espace d'accueil — pas devant lui. Ce geste crée une coprésence immédiate. Le client qui suit un commercial qu'il ne connaît pas se sent comme un numéro."}], "mistakes": [{"title": "Erreur 1 — Accueillir depuis son bureau", "description": "Le commercial qui lève la tête et dit \"j'arrive !\" en restant assis envoie un message clair : le client peut attendre. Cette posture installe une hiérarchie inversée dès le départ. Le client se sent en visite, pas en rendez-vous."}, {"title": "Erreur 2 — Démarrer par le projet avant le lien", "description": "\"Bonjour, vous cherchez quel type de véhicule ?\" — c'est la question d'un formulaire, pas d'un commercial. Le client passe immédiatement en mode réponse/défense. Le lien humain n'a jamais eu le temps de se créer."}, {"title": "Erreur 3 — Un accueil identique pour tout le monde", "description": "Le script \"bonjour, bienvenue, je vous propose un café\" appliqué mécaniquement se ressent. L'accueil qui crée du lien est celui qui s'adapte — au profil, à l'énergie, au contexte. Un client pressé et un client détendu n'ont pas besoin du même accueil."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer le commercial sur le persona : \"Je vais jouer un client qui entre dans la concession. Tu m'accueilles exactement comme si c'était un vrai client. Je n'aiderai pas.\" Durée : 3-4 minutes max pour l'accueil seul."}, {"title": "Lancer le scénario", "description": "Entrer dans la concession (ou simuler l'entrée dans une salle). Jouer le persona fidèlement — comportement, langage non-verbal, rythme. Ne pas sourire si le persona est fermé. Ne pas aider si le commercial est en difficulté."}, {"title": "Débriefer", "description": "\"En combien de secondes tu es venu vers moi ? Qu'est-ce que tu as observé sur moi quand je suis entré ? Est-ce que tu as parlé voiture dans les 2 premières minutes ? Qu'est-ce que tu as fait pour créer du lien ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client, tu t'engages à aller vers lui avant 20 secondes et à ne pas parler voiture dans la première minute. Tu me fais un retour vendredi : comment tu as adapté ton accueil à ce client-là.\""}], "scenarios": [{"level": "debutant", "title": "Le client ouvert et curieux", "objective": "Appliquer les 4 gestes dans l'ordre : aller vers le client avant 20 sec, créer le contact, proposer la boisson, amorcer par une question sur le client. Ne pas parler voiture dans la première minute.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 34 ans, graphiste indépendant, décontracté, sourit en entrant. Premier achat dans cette concession."}, {"label": "Comportement à l'entrée", "text": "Entre calmement, regarde les véhicules exposés avec curiosité. S'arrête près d'un modèle, le touche. Disponible, pas pressé."}, {"label": "Signal non-verbal", "text": "Posture ouverte, regard qui explore, léger sourire. Facile à accueillir — le contexte est favorable."}, {"label": "Motivation d'achat probable", "text": "Envie de changer, curiosité pour les nouvelles motorisations. Budget flexible."}, {"label": "Frein / tension probable", "text": "Aucun frein particulier — c'est un client idéal pour pratiquer les fondamentaux sans pression."}], "context": "Samedi matin, concession peu fréquentée. Le commercial est disponible et au poste. Le client entre seul, sans rendez-vous, juste \"pour voir\". Il n'a pas été contacté en amont.", "stakes": "Condition idéale pour travailler les 4 gestes dans l'ordre sans contrainte externe. Le manager observe si le commercial prend l'initiative du contact ou attend.", "observe": ["Va-t-il vers le client avant 20 secondes ?", "Crée-t-il le contact avec un prénom et un sourire franc ?", "Propose-t-il la boisson et accompagne-t-il le client ?", "Amorce-t-il la conversation sur le client avant de parler voiture ?"]}, {"level": "intermediaire", "title": "Le client pressé qui veut aller vite", "objective": "Adapter l'accueil au rythme imposé par le client sans sauter les étapes clés. Créer le lien en 45 secondes au lieu de 2 minutes. Proposer la boisson sans imposer une pause si le client résiste.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 43 ans, directrice commerciale, habituée à être efficace. A rendez-vous dans 1h en dehors de la concession."}, {"label": "Comportement à l'entrée", "text": "Entre rapidement, regarde directement les vendeurs, cherche visuellement quelqu'un à qui parler. Pose sa question avant même d'être à portée normale de conversation."}, {"label": "Signal non-verbal", "text": "Pas croissant rapide, regard direct et intense, sac en bandoulière qu'elle ne pose pas. Signaux clairs d'efficacité et d'impatience."}, {"label": "Motivation d'achat probable", "text": "Renouveler son véhicule de fonction rapidement. A fait ses recherches en ligne, sait ce qu'elle veut. Ne veut pas perdre de temps."}, {"label": "Frein / tension probable", "text": "\"J'ai pas beaucoup de temps.\" — phrase qu'elle va dire dans les 10 premières secondes."}], "context": "Jeudi à 12h30, heure de déjeuner. Concession active. La cliente entre directement et interpelle visuellement. Elle a déjà dit au téléphone qu'elle passait \"juste pour voir\" le modèle.", "stakes": "Le commercial doit créer du lien rapidement sans ignorer les signaux d'impatience, et gérer le \"j'ai pas le temps\" sans abandonner l'étape d'accueil.", "observe": ["Capte-t-il le signal \"pressée\" et adapte-t-il son rythme d'accueil ?", "Crée-t-il quand même un mini-lien humain avant de parler voiture ?", "Gère-t-il le refus de la boisson sans abandonner la chaleur de l'accueil ?", "Évite-t-il de basculer directement en mode \"qualification\" face à l'impatience ?"]}, {"level": "avance", "title": "Le couple avec tension non-verbale", "objective": "Lire les signaux non-verbaux de deux interlocuteurs aux énergies différentes, inclure les deux dans l'accueil, créer le lien avec celui qui est fermé sans ignorer celui qui est ouvert.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Couple, 38 ans / 41 ans. Elle a initié le projet — enthousiaste. Lui est venu par devoir — sceptique sur la nécessité de changer de véhicule."}, {"label": "Comportement à l'entrée", "text": "Elle entre avec de l'énergie et regarde autour d'elle. Lui suit légèrement en retrait, les mains dans les poches, regard neutre. Ils ne se parlent pas en entrant."}, {"label": "Signal non-verbal", "text": "Elle : posture ouverte, sourire anticipé. Lui : épaules légèrement rentrées, contact visuel minimal, position en retrait de 30 cm par rapport à elle."}, {"label": "Motivation d'achat probable", "text": "Elle veut un SUV plus grand pour les vacances. Lui veut garder la voiture actuelle \"qui marche très bien\"."}, {"label": "Frein / tension probable", "text": "Désaccord latent sur la nécessité du changement. Le mari peut devenir un frein si le commercial ne l'inclut pas dès l'accueil."}], "context": "Samedi après-midi, affluence modérée. Le couple entre sans rendez-vous. Le commercial risque naturellement de s'adresser à la personne la plus engagée (elle) et d'ignorer l'autre.", "stakes": "L'enjeu : inclure les deux dans les 30 premières secondes, créer un lien avec le mari sans braquer la femme, et détecter la tension latente sans la nommer.", "observe": ["Adresse-t-il son accueil aux deux personnes simultanément dès le départ ?", "Détecte-t-il les signaux non-verbaux de retrait du mari ?", "Crée-t-il une amorce qui inclut le mari (question qui le concerne aussi) ?", "Évite-t-il de parler uniquement à la personne la plus engagée ?"]}]}, "online": {"focus": "l'accueil et la prise de contact", "attentionPoints": ["Va-t-il vers le client avant 20 secondes ?", "Lit-il et adapte-t-il l'accueil aux signaux non-verbaux ?", "Propose-t-il la boisson et accompagne-t-il le client ?", "Parle-t-il d'abord du client avant de parler voiture ?"], "grid": ["Vers le client < 20 sec", "Accueil adapté au non-verbal", "Boisson + accompagnement", "Lien humain avant voiture"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"En combien de secondes tu es allé vers le client ? Qu'est-ce que tu as vu sur lui quand il est entré — et est-ce que tu en as tenu compte ? Quand est-ce que tu as parlé voiture pour la première fois ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand [client] est entré, tu as [action précise observée]. Le client a [réaction : souri / s'est détendu / s'est ouvert]. C'est exactement ce geste qui crée le lien dès les premières secondes.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as parlé voiture au bout de 40 secondes — avant même d'avoir créé le lien]. La prochaine fois, pose une question sur le client avant de poser une question sur le projet. Une seule suffit.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client, tu t'engages à aller vers lui avant 20 secondes et à ne pas parler voiture dans la première minute. Viens me voir vendredi — dis-moi comment tu as adapté ton accueil à ce client-là.\""}], "sections": []}, "takeaways": {"theory": "Les 4 gestes clés sont connus — aller vers, contact, boisson, amorce sur le client", "offline": "Le geste a été travaillé sur 3 profils différents — la lecture du non-verbal est ancrée", "online": "Le coach a observé et débriefé l'accueil en situation réelle avec précision", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/1- Accueil personnalisé/Accueil personnalisé.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('b60cd224-7b69-5495-a8bb-94ac23214282', 'c5b6577c-2748-563d-888e-9806ffca0bd5');
insert into public.library_dojos (id, title, content, pptx_path) values ('31002c45-6000-529d-a1b5-040fcf149bbd', 'Attitude positive & expérience unique', $dojo${"version": 1, "tagline": "Créer dès les premières secondes une expérience mémorable", "objective": "Le commercial sait mobiliser les 3 leviers (posture, voix, intention) de façon cohérente et adaptée au profil du client, et créer un moment personnalisé qui se distingue d'un accueil standard.", "duration": "20-25 min", "theory": {"intro": "L'attitude positive n'est pas un état d'esprit — c'est une décision. Elle se construit sur 3 leviers concrets, observables, et entraînables. Un client ne se souvient pas de ce qu'on lui a dit — il se souvient de ce qu'il a ressenti.", "standardTitle": "Le standard : les 3 leviers de l'attitude positive", "standard": [{"label": null, "title": "LE CORPS", "description": "La posture physique", "why": "Dos droit, épaules ouvertes, regard direct, déplacement orienté vers le client. Le corps précède les mots — le client lit la posture avant d'entendre la voix."}, {"label": null, "title": "55% de la communication est non-verbale (Mehrabian). Un commercial avachi, regard fuyant, bras croisés communique le désintérêt avant même d'avoir parlé.", "description": "Se lever immédiatement, se tourner vers le client, sourire déclenché avant le contact visuel.", "why": "LA VOIX"}, {"label": null, "title": "Le ton & l'énergie vocale", "description": "Voix posée, débit modéré, énergie légèrement au-dessus du neutre. Ni trop enthousiaste (commercial forcé), ni trop plat (désintérêt). Prononcer son prénom clairement.", "why": "38% de la communication passe par le ton. Un \"bonjour\" dit du bout des lèvres en regardant son écran vaut moins qu'un silence bienveillant."}, {"label": null, "title": "\"Bonjour, je m'appelle [prénom]\" — dit en regardant le client, avec un débit naturel et une inflexion montante.", "description": "L'INTENTION", "why": "L'attention portée au client"}, {"label": null, "title": "Être mentalement présent — pas en train de penser au client précédent ou au dossier ouvert. L'intention se voit : le client qui se sent vraiment vu s'ouvre immédiatement.", "description": "Un commercial physiquement présent mais mentalement absent crée une expérience froide. La présence attentionnée est le levier le plus puissant et le plus rare.", "why": "Poser ce qu'on a en main, couper toute distraction, regarder le client entrer comme si c'était la première personne de la journée."}, {"label": null, "title": "LEVIER", "description": "POURQUOI ÇA COMPTE", "why": "EXEMPLE CONCRET"}], "criteria": [{"title": "Son énergie est stable sur toute la journée", "description": "Le 1er client du matin et le 12ème de l'après-midi reçoivent le même niveau d'énergie. La fatigue est réelle — l'afficher ne l'est pas. Le commercial qui gère son énergie comme une ressource professionnelle se distingue."}, {"title": "Il sourit avant le contact visuel", "description": "Le sourire déclenché avant que le client le voit est authentique. Celui qui apparaît après le regard du client semble calculé. Un demi-seconde d'avance change tout dans la perception de sincérité."}, {"title": "Il personnalise la micro-attention", "description": "Un détail observé sur le client (un badge professionnel, une tenue de sport, un enfant qui l'accompagne) et mentionné naturellement crée immédiatement une expérience unique. Le client se sent vu, pas traité."}, {"title": "Il maintient l'énergie si le client est fermé", "description": "Face à un client froid ou méfiant, le commercial qui baisse d'un ton fait une erreur. Maintenir une chaleur bienveillante sans forcer — l'énergie positive est contagieuse à condition d'être patiente."}, {"title": "Il crée un moment — pas une procédure", "description": "L'expérience unique naît d'une imprévisibilité positive : une remarque spontanée, un moment de légèreté, un geste attentionné inattendu. Le script parfaitement récité ne crée jamais d'expérience mémorable."}], "mistakes": [{"title": "Erreur 1 — L'enthousiasme forcé", "description": "\"Bonjour BIENVENUE ! Je suis ravi de vous accueillir !\" dit avec un volume et une énergie disproportionnés. Le client perçoit immédiatement l'artificiel. L'enthousiasme forcé crée de la méfiance — pas du lien. La chaleur sincère est sobre."}, {"title": "Erreur 2 — Le sourire de façade sans présence réelle", "description": "Sourire affiché, regard qui traîne vers l'écran ou le collègue, corps orienté à moitié. Le client qui reçoit un sourire sans attention complète le ressent comme un signe de politesse vide. La présence attentionnée vaut plus que n'importe quel sourire."}, {"title": "Erreur 3 — La phrase générique qui efface l'expérience", "description": "\"Bienvenue chez [concession], que puis-je faire pour vous ?\" — cette phrase annule en une seconde tout l'effet d'un accueil chaleureux. Elle standardise, désindividualise, et signale que le client est l'un parmi d'autres."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer le commercial sur le persona et son humeur. Préciser : \"Je vais entrer dans la concession avec cette énergie-là. Tu m'accueilles avec une attitude positive et tu essaies de créer quelque chose de mémorable pour moi — pas un script.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona fidèlement — humeur, rythme, non-verbal. Durée : 2-3 minutes max. Ne pas sourire si le persona est froid. Ne pas aider si le commercial cherche ses mots. Observer les 3 leviers en parallèle."}, {"title": "Débriefer", "description": "\"Sur une échelle de 1 à 10, comment tu évalues ton niveau d'énergie ? Est-ce que tu penses que j'ai vécu quelque chose d'unique ou de standard ? Qu'est-ce qui t'a personnalisé l'accueil pour moi spécifiquement ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client, tu t'engages à identifier UN détail sur lui dès son entrée et à l'utiliser pour créer un moment personnalisé. Tu me le racontes vendredi — le détail, ce que tu as fait avec, et comment le client a réagi.\""}], "scenarios": [{"level": "debutant", "title": "Le client neutre du lundi matin", "objective": "Mobiliser les 3 leviers de façon cohérente dans un contexte neutre. Créer un minimum de personnalisation sans que le contexte le rende difficile. Éviter la phrase générique d'ouverture.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 36 ans, comptable, tenue sobre. Entre seul, pas pressé. Visage neutre, ni souriant ni fermé."}, {"label": "Humeur à l'entrée", "text": "Neutre, légèrement fatigué. C'est lundi matin, il a l'air de \"se forcer\" à être là. Pas de tension particulière."}, {"label": "Signal non-verbal", "text": "Regard qui explore la salle d'exposition sans chercher de contact. Mains dans les poches. Démarche lente."}, {"label": "Attente implicite", "text": "Être accueilli correctement sans être assailli. Ne pas se sentir comme un prospect à convaincre."}, {"label": "Déclencheur d'expérience positive", "text": "Une remarque légère sur le lundi matin ou une question ouverte bienveillante qui lui laisse de l'espace."}], "context": "Lundi 9h30. Concession calme, peu de monde. Le commercial vient de finir un appel téléphonique. Le client entre sans rendez-vous.", "stakes": "Contexte idéal pour travailler les fondamentaux sans pression. Le manager observe si le commercial se lève immédiatement, quelle énergie il projette, et s'il crée un moment ou applique un script.", "observe": ["Les 3 leviers sont-ils cohérents entre eux (corps + voix + intention) ?", "Évite-t-il la phrase générique de bienvenue ?", "Crée-t-il une micro-personnalisation adaptée au profil neutre ?", "Son énergie est-elle naturelle — ni forcée ni plate ?"]}, {"level": "intermediaire", "title": "La cliente stressée avec un enfant en bas âge", "objective": "Lire rapidement l'état émotionnel du client, adapter l'énergie et le ton à une personne sous pression, inclure l'enfant dans l'accueil pour créer immédiatement un contexte bienveillant.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 32 ans, infirmière en congé parental. Arrive avec une poussette et un enfant de 18 mois qui pleure légèrement."}, {"label": "Humeur à l'entrée", "text": "Stressée, légèrement débordée. Elle a l'air d'avoir eu du mal à organiser cette sortie. Regarde autour d'elle avec un mélange d'espoir et d'impatience."}, {"label": "Signal non-verbal", "text": "Gère la poussette d'une main, sac sur l'épaule. Sourit poliment mais regard épuisé. Corps en tension."}, {"label": "Attente implicite", "text": "Être accueillie avec chaleur et sans jugement sur l'enfant. Se sentir à l'aise, pas de pression commerciale."}, {"label": "Déclencheur d'expérience positive", "text": "Un regard bienveillant vers l'enfant, une phrase légère sur la situation (\"il a l'air curieux !\"), proposer un espace confortable rapidement."}], "context": "Mercredi 11h. Concession modérément fréquentée. La cliente entre en manœuvrant la poussette à travers la porte d'entrée.", "stakes": "Le commercial doit gérer la complexité du duo parent/enfant tout en maintenant une attitude positive et en créant une expérience pour la mère — pas seulement gérer la logistique de la poussette.", "observe": ["Lit-il le niveau de stress de la cliente et adapte-t-il son énergie (chaleureux, pas enthousiaste) ?", "Inclut-il l'enfant dans l'accueil de façon naturelle ?", "Aide-t-il physiquement sans que la cliente ait besoin de demander (porte, espace) ?", "Crée-t-il un moment de détente avant d'aller sur le fond ?"]}, {"level": "avance", "title": "Le client méfiant qui a eu une mauvaise expérience", "objective": "Maintenir une attitude positive et chaleureuse face à un client dont la méfiance est explicite dès l'entrée. Désamorcer sans forcer, créer un espace de confiance progressif sans paraître dans l'effort.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 55 ans, artisan, a été mal conseillé lors d'un précédent achat dans une autre concession il y a 2 ans. Il le mentionne dès le départ."}, {"label": "Humeur à l'entrée", "text": "Méfiant, légèrement sur la défensive. Pas agressif mais clairement en mode \"je surveille\". A décidé de donner une chance mais s'attend à être déçu."}, {"label": "Signal non-verbal", "text": "Entre lentement, regarde le commercial dans les yeux avec une intensité qui teste. Bras légèrement croisés. Mâchoire serrée. Ne sourit pas en premier."}, {"label": "Attente implicite", "text": "Être traité comme un adulte qui sait ce qu'il veut. Ne pas être pris pour un naïf. Que le commercial soit honnête et direct."}, {"label": "Déclencheur d'expérience positive", "text": "Accuser réception de sa méfiance sans la nier : \"Je comprends\" dit avec calme et sincérité — pas avec empathie exagérée."}], "context": "Vendredi 16h. Concession active, fin de semaine chargée. Le commercial est légèrement fatigué. Le client entre et dit dès les 10 premières secondes : \"J'espère que ça va mieux se passer qu'ailleurs.\"", "stakes": "Le commercial doit résister à deux pièges : l'excès d'empathie performatif (\"bien sûr, ne vous inquiétez pas !\") et la baisse d'énergie face à la méfiance. L'attitude positive ici est sobre, stable, et rassurante — pas enthousiaste.", "observe": ["Maintient-il une énergie positive stable face à la méfiance sans forcer l'enthousiasme ?", "Accuse-t-il réception de la remarque de façon sobre et sincère ?", "Évite-t-il les formules rassurantes vides (\"ne vous inquiétez pas\") ?", "Crée-t-il un espace de confiance par sa présence — pas par ses mots ?"]}]}, "online": {"focus": "l'attitude & l'expérience créée", "attentionPoints": ["Les 3 leviers sont-ils cohérents (corps, voix, intention) ?", "Son énergie est-elle adaptée au profil du client ?", "Crée-t-il un moment personnalisé ou applique-t-il un script ?", "Quelle est la réaction du client — s'ouvre-t-il ou reste-t-il fermé ?"], "grid": ["Posture physique engagée", "Voix & ton adaptés", "Présence & intention réelles", "Moment personnalisé créé"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Comment tu évalues ton attitude sur cet accueil ? Qu'est-ce que tu as fait de spécifique pour ce client — pas de générique ? Qu'est-ce que tu as observé sur lui dès son entrée et comment tu en as tenu compte ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand [client] est entré, tu as [geste ou mot précis]. Le client a réagi en [réaction observable]. C'est exactement ça qui crée une expérience — pas le script, ce moment-là.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: ta voix était plate malgré un corps engagé — les 3 leviers n'étaient pas cohérents]. La prochaine fois, avant d'accueillir un client, prends 2 secondes pour décider de ton niveau d'énergie.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client : identifie UN détail sur lui à l'entrée et utilise-le pour personnaliser l'accueil. Reviens me voir avec le détail que tu as observé, ce que tu en as fait, et la réaction du client.\""}], "sections": []}, "takeaways": {"theory": "Les 3 leviers sont connus — posture, voix, intention — et leur cohérence est comprise", "offline": "Le geste a été travaillé sur 3 profils d'énergie différents — la personnalisation est un réflexe", "online": "Le coach a observé et débriefé l'attitude et l'expérience créée en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/1- Accueil personnalisé/Attitude positive et expérience unique.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('31002c45-6000-529d-a1b5-040fcf149bbd', '9e91a232-5d7f-55ce-a738-9d43477a0221');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('31002c45-6000-529d-a1b5-040fcf149bbd', 'a27db590-2f6e-5a0d-9abb-eacf2507d43c');
insert into public.library_dojos (id, title, content, pptx_path) values ('75f7bcfc-2291-5c0c-81a3-58841d4b6bd7', 'La boisson comme outil de lien', $dojo${"version": 1, "tagline": "Transformer un geste d'hospitalité en levier commercial", "objective": "Le commercial propose la boisson naturellement dès l'accueil, gère le refus avec aisance, exploite le temps d'absence pour observer, et utilise le retour comme rebond conversationnel.", "duration": "20-25 min", "theory": {"intro": "La boisson n'est pas une politesse — c'est un outil. Proposer un café ou une eau crée un rituel d'hospitalité qui ralentit l'entretien, détend l'atmosphère, et positionne le commercial en hôte. Ce geste simple a 4 fonctions commerciales précises.", "standardTitle": "Le standard : les 4 fonctions de la boisson", "standard": [{"label": "RALENTIR", "title": "Créer une pause dans le rythme", "description": "Le moment de proposer et préparer la boisson crée une micro-pause naturelle. Elle sort le client du mode \"je suis en concession pour acheter\" et l'installe dans un mode \"je suis reçu\".", "why": "Un client installé et détendu est un client qui parle davantage. La découverte qui suit une boisson est plus riche qu'une découverte démarrée debout."}, {"label": "POSITIONNER", "title": "Installer le commercial en hôte", "description": "Celui qui offre à boire est l'hôte. L'hôte a une légitimité naturelle à poser des questions, à guider la conversation. Ce changement de statut est subtil mais puissant.", "why": "Le client qui accepte une boisson entre implicitement dans une relation d'hospitalité — pas de transaction. Il baisse sa garde de prospect et s'ouvre à l'échange."}, {"label": "OBSERVER", "title": "Gagner du temps d'observation", "description": "Pendant que le commercial prépare ou va chercher la boisson, le client est seul quelques secondes. Il regarde autour de lui, touche les véhicules, révèle des comportements riches d'informations.", "why": "Ce que le client fait quand il n'est pas \"en train d'être accueilli\" dit beaucoup sur ses centres d'intérêt. Le commercial qui observe à son retour a de l'or pour la découverte."}, {"label": "PERSONNALISER", "title": "Créer un premier moment unique", "description": "\"Vous prenez comment votre café ?\" est une question banale qui devient mémorable quand elle est posée avec une vraie attention. Le client qui se sent préparé se souvient de l'expérience.", "why": "Un simple \"sucre, sans sucre ?\" posé en regardant le client dans les yeux vaut plus qu'un discours de bienvenue. C'est l'attention portée au détail qui crée l'expérience unique."}], "criteria": [{"title": "Il propose avant de s'asseoir", "description": "La boisson se propose dès l'accueil — pas une fois installé. \"Je vous emmène par ici, je vous propose quelque chose à boire ?\" — en marchant, naturellement, avant même de s'asseoir."}, {"title": "Il accompagne le client, ne le laisse pas seul au mauvais moment", "description": "Aller chercher la boisson laisse le client seul 30-60 secondes — c'est précieux. Mais le quitter alors que la conversation venait de démarrer casse le rythme. Le timing du départ pour la boisson est une compétence."}, {"title": "Il utilise le retour comme rebond conversationnel", "description": "\"Tenez — et vous venez de loin ?\" En posant la boisson, il rebondit naturellement sur ce qui vient de se passer ou sur ce qu'il a observé pendant son absence. La boisson repose la conversation sur des bases plus légères."}, {"title": "Il adapte la proposition au contexte", "description": "Un client pressé qui a dit \"j'ai 20 minutes\" n'attend pas qu'on aille faire un expresso. Dans ce cas : \"Une eau, ça vous va ?\" — rapide, attentionné, sans imposer une pause."}, {"title": "Il traite le refus sans le laisser tomber à plat", "description": "\"Non merci.\" — \"Pas de problème !\" dit avec le même sourire, sans insister, sans gêne. Le refus d'une boisson n'est pas un refus de la relation. Un commercial qui encaisse le refus avec aisance rassure le client."}], "mistakes": [{"title": "Erreur 1 — Oublier de proposer ou proposer trop tard", "description": "\"Ah au fait, vous voulez un café ?\" demandé 10 minutes après l'arrivée du client, une fois la découverte engagée, perd toute sa valeur. La boisson proposée après le début de l'entretien ressemble à une pensée après coup — pas à une intention d'hôte."}, {"title": "Erreur 2 — Proposer mécaniquement sans regarder le client", "description": "\"Café, thé, eau ?\" récité en regardant le plateau ou le sol. La proposition de boisson est un geste de lien — elle demande le même contact visuel et la même intention que n'importe quelle autre étape de l'accueil. Sans regard, c'est une procédure."}, {"title": "Erreur 3 — Ne pas exploiter le temps de préparation / d'absence", "description": "Partir chercher la boisson et revenir sans avoir observé ce que le client a fait pendant ce temps. Ces 30-60 secondes sont précieuses : le client s'est peut-être approché d'un véhicule, a regardé une fiche prix, a sorti son téléphone. Ce sont des signaux pour la découverte."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Si possible, avoir un accès à un espace café pour rendre le jeu de rôle plus réaliste. Sinon, simuler le déplacement. Briefer le commercial : \"Je vais entrer dans la concession — tu m'accueilles et tu gères la boisson comme tu le ferais avec un vrai client.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona fidèlement. Si le scénario prévoit un refus de boisson, refuser naturellement. Observer : le timing de la proposition, le contact visuel pendant la proposition, ce que le commercial fait pendant son absence, et comment il rebondit au retour."}, {"title": "Débriefer", "description": "\"Quand est-ce que tu m'as proposé la boisson — avant ou après qu'on s'installe ? Est-ce que tu m'as regardé en le proposant ? Qu'est-ce que tu as observé pendant que tu allais chercher ? Comment tu as rebondi en revenant ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client : propose la boisson en marchant, avant même de s'asseoir. Note mentalement ce que le client fait pendant que tu t'absentes. Rebondis dessus en revenant. On en parle vendredi.\""}], "scenarios": [{"level": "debutant", "title": "Le client disponible qui accepte tout", "objective": "Maîtriser les fondamentaux : proposer en marchant avant de s'asseoir, contact visuel pendant la proposition, exploiter l'absence pour observer, rebondir au retour avec ce qui a été vu.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Femme, 38 ans, institutrice, calme et souriante. Samedi matin, pas pressée. Premier contact avec la concession."}, {"label": "Comportement", "text": "Entre tranquillement, regarde les véhicules exposés avec curiosité. Sourit au commercial. Disponible à la conversation."}, {"label": "Non-verbal", "text": "Posture détendue, regard ouvert. Pose son sac, prend son temps. S'arrête devant un SUV compact."}, {"label": "Motivation d'achat", "text": "Renouveler son vieux monospace. Cherche quelque chose de plus moderne et plus économique."}, {"label": "Frein probable", "text": "Aucun frein particulier — contexte idéal pour travailler les fondamentaux sans résistance."}], "context": "Samedi 10h. Concession calme. Le commercial est disponible et de bonne humeur. La cliente entre sans rendez-vous, \"juste pour voir\".", "stakes": "Condition idéale pour travailler le geste dans l'ordre : proposition en marchant → absence → observation → retour avec rebond. Pas de pression de temps, pas de résistance.", "observe": ["Propose-t-il la boisson en marchant, avant de s'asseoir ?", "Maintient-il le contact visuel pendant la proposition ?", "Observe-t-il ce que la cliente fait pendant son absence ?", "Rebondit-il sur cette observation au retour ?"]}, {"level": "intermediaire", "title": "Le client pressé qui refuse la boisson", "objective": "Gérer le refus de boisson avec aisance, adapter la proposition au rythme imposé (eau rapide vs café long), et maintenir la chaleur de l'accueil même sans la boisson comme support.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 44 ans, directeur d'agence bancaire. Veste, montre. Arrive pile à l'heure pour un rdv de 30 minutes qu'il a fixé lui-même."}, {"label": "Comportement", "text": "Entre d'un pas décidé, cherche visuellement le commercial. Serre la main fermement. Pose directement sa question : \"On est bien à 30 minutes maxi ?\""}, {"label": "Non-verbal", "text": "Corps en mouvement, regard direct et efficace. Regarde sa montre dans les 2 premières minutes. Pas de temps pour flâner."}, {"label": "Motivation d'achat", "text": "Renouveler son véhicule de fonction. A une liste de critères précis. Veut décider vite."}, {"label": "Frein probable", "text": "Le temps. Toute impression de perdre du temps le fait se désengager immédiatement."}], "context": "Mardi 12h15. Le client a pris rdv entre midi et deux. Il a clairement dit au téléphone : \"30 minutes maxi.\"", "stakes": "Le commercial doit adapter le geste de la boisson : ne pas proposer un café long, adapter à \"une eau ?\", et si le client dit non — encaisser sans gêne et repartir avec la même énergie. L'absence pour chercher la boisson ne peut pas être longue.", "observe": ["Adapte-t-il la proposition au rythme du client (\"juste une eau ?\") ?", "Gère-t-il le refus sans gêne ni insistance ?", "Maintient-il la chaleur de l'accueil même sans la boisson ?", "Ne perd-il pas de temps sur la boisson face à un client pressé ?"]}, {"level": "avance", "title": "Le couple où l'un veut partir et l'autre s'attarder", "objective": "Utiliser la boisson pour ralentir le rythme imposé par l'un des interlocuteurs, inclure les deux dans le geste d'hospitalité, et exploiter le moment de déplacement pour observer la dynamique du couple.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Couple : Elle, 35 ans, enthousiaste pour le projet. Lui, 38 ans, venu par devoir, aurait préféré rester chez lui le samedi."}, {"label": "Comportement", "text": "Elle entre en regardant les véhicules avec intérêt. Lui suit, mains dans les poches, regarde son téléphone brièvement. Ils parlent peu entre eux en entrant."}, {"label": "Non-verbal", "text": "Elle : posture ouverte, sourit spontanément. Lui : légèrement en retrait, bras croisés par moments, regard qui décroche."}, {"label": "Motivation d'achat", "text": "Elle veut un SUV plus grand. Lui accepte le principe mais freine sur le budget."}, {"label": "Frein probable", "text": "Lui est le frein potentiel. Si le commercial ne l'intègre pas dès l'accueil, il peut devenir un obstacle à la décision."}], "context": "Samedi 14h. Concession active. Le couple entre ensemble mais avec des énergies très différentes.", "stakes": "L'enjeu de la boisson ici : inclure les deux dans la proposition (\"je vous propose quelque chose à boire — et vous ?\"), utiliser l'absence pour observer qui regarde quoi, et rebondir au retour avec quelque chose qui intègre lui dans la conversation.", "observe": ["Propose-t-il la boisson aux deux en les regardant chacun ?", "Observe-t-il la dynamique du couple pendant son absence ?", "Rebondit-il au retour avec quelque chose qui inclut monsieur ?", "Utilise-t-il la boisson pour ralentir et installer les deux ?"]}]}, "online": {"focus": "le geste de la boisson", "attentionPoints": ["Propose-t-il la boisson en marchant, avant de s'asseoir ?", "Adapte-t-il la proposition au rythme et profil du client ?", "Exploite-t-il l'absence pour observer le comportement du client ?", "Rebondit-il sur ses observations au retour ?"], "grid": ["Proposition avant de s'asseoir", "Proposition adaptée au client", "Observation pendant l'absence", "Rebond au retour"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Quand est-ce que tu lui as proposé la boisson — avant ou après qu'on s'installe ? Est-ce que tu l'as regardé en proposant ? Qu'est-ce que tu as observé pendant ton absence ? Tu en as fait quelque chose au retour ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé qu'en revenant avec [boisson], tu as dit [phrase précise de rebond]. Le client a réagi en [réaction observable]. C'est exactement ça — la boisson t'a donné une info que tu as utilisée.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as proposé la boisson une fois assis — c'est trop tard, le rythme était déjà lancé]. La prochaine fois : proposition en marchant, avant même qu'on s'installe. Ça change tout.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client : note mentalement ce qu'il fait pendant que tu t'absentes. Un seul détail suffit. Rebondis dessus en revenant. Reviens me voir vendredi avec l'exemple concret.\""}], "sections": []}, "takeaways": {"theory": "Les 4 fonctions de la boisson sont connues — ce n'est plus un geste de politesse mais un outil", "offline": "Le geste a été travaillé sur 3 contextes différents — la proposition et l'exploitation de l'absence sont des réflexes", "online": "Le coach a observé et débriefé le geste de la boisson en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/1- Accueil personnalisé/Utilisation boisson.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('75f7bcfc-2291-5c0c-81a3-58841d4b6bd7', 'd7af16ae-d88e-5f55-9464-d7635abcd6b8');
insert into public.library_dojos (id, title, content, pptx_path) values ('27271ec1-013c-5356-be56-4a6cf4af9eab', 'Planifier son activité', $dojo${"version": 1, "tagline": "Lisser son activité pour assurer un suivi adapté de tous les clients", "objective": "Le commercial construit un agenda hebdomadaire équilibré avec les 3 blocs, protège le bloc prospection, anticipe les suivis post-livraison, et fait une revue en fin de semaine.", "duration": "20-25 min", "theory": {"intro": "Un commercial qui remplit son agenda de RDV sans planifier les relances et le suivi crée une désorganisation en cascade. Le lissage de l'activité est ce qui sépare un commercial occupé d'un commercial efficace.", "standardTitle": "Le standard : la logique du lissage & les 3 blocs hebdo", "standard": [{"label": null, "title": "BLOC RDV", "description": "Plages dédiées aux rendez-vous clients. Idéalement concentrées sur 3 jours pour laisser du temps aux autres blocs.", "why": "Un agenda 100% RDV ne laisse aucun temps pour le suivi et les relances. Les dossiers refroidissent."}, {"label": null, "title": "BLOC SUIVI", "description": "Plages dédiées aux relances, suivis post-livraison, confirmations de RDV. Planifié — pas improvisé.", "why": "Le suivi non planifié ne se produit pas. Une plage fixe garantit que chaque dossier est traité dans le bon timing."}, {"label": null, "title": "BLOC PROSPECTION", "description": "Plages dédiées à la création de nouveaux contacts. Ce bloc est souvent le premier sacrifié — c'est le plus stratégique.", "why": "Sans prospection régulière, le pipeline se vide en 4-6 semaines. Protéger ce bloc même en période chargée."}], "criteria": [{"title": "Il planifie à la semaine — pas au jour le jour", "description": "Un agenda construit la veille ne permet pas de lisser. La planification hebdomadaire (vendredi ou lundi matin) donne la visibilité pour équilibrer les 3 blocs."}, {"title": "Il protège le bloc prospection", "description": "Le bloc prospection est le premier à sauter quand l'agenda se remplit. Sacrifié régulièrement, il crée un creux dans 4-6 semaines. Ce bloc est non-négociable."}, {"title": "Il anticipe les pics d'activité", "description": "Une série de livraisons → prévoir les suivis J+7 dans l'agenda dès la livraison. L'anticipation évite les accumulations."}, {"title": "Il adapte son agenda aux rythmes clients", "description": "Appeler des particuliers le lundi matin génère des non-réponses. Adapter ses plages de suivi aux moments de disponibilité des clients améliore le taux de contact."}, {"title": "Il revoit son planning en fin de semaine", "description": "15 minutes le vendredi : qu'est-ce qui a été fait, qu'est-ce qui a glissé, qu'est-ce qu'on replanifie. Cette revue est le régulateur du lissage."}], "mistakes": [{"title": "Erreur 1 — Remplir l'agenda de RDV sans prévoir le suivi", "description": "Un agenda plein de RDV est rassurant visuellement — mais s'il ne laisse aucun temps pour les relances, les dossiers refroidissent. Le commercial \"occupé\" n'est pas forcément efficace."}, {"title": "Erreur 2 — Ne pas planifier la prospection", "description": "\"Je prospecterai quand j'aurai le temps.\" Ce temps n'arrive jamais. Sans bloc prospection fixe, le pipeline se vide progressivement et le commercial se retrouve en creux sans comprendre pourquoi."}, {"title": "Erreur 3 — Gérer les urgences à la place du planning", "description": "Sauter la revue hebdomadaire pour traiter les urgences du moment. Les urgences sont inévitables — mais elles ne doivent pas remplacer la planification. Un commercial qui gère uniquement les urgences perd le contrôle de son activité."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Donner la situation de départ : agenda partiel avec RDV confirmés, livraisons prévues, dossiers en suivi. Briefer : \"Construis ton agenda de la semaine prochaine. Je regarde si les 3 blocs sont présents et si la prospection est protégée.\""}, {"title": "Lancer le scénario", "description": "Observer la construction. Créer des conflits : \"Tu as une livraison jeudi — tu as prévu le J+7 de celle de la semaine dernière ?\" Observer : 3 blocs présents, prospection protégée, suivis anticipés."}, {"title": "Débriefer", "description": "\"Les 3 blocs sont dans ton agenda ? Tu as protégé la prospection malgré les RDV ? Tu as anticipé les suivis des livraisons ? Tu as prévu une revue vendredi ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Cette semaine : construis ton agenda avec les 3 blocs avant lundi 9h. Bilan vendredi. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Agenda vierge — construire les 3 blocs", "objective": "Construire un agenda hebdomadaire avec les 3 blocs équilibrés, identifier les créneaux optimaux.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Commercial, 24 ans, 3 mois en poste. Agenda vierge pour la semaine prochaine."}, {"label": "Situation", "text": "3 RDV confirmés (lundi 14h, mercredi 10h, jeudi 16h). 2 livraisons (mardi, vendredi). 5 dossiers en suivi."}, {"label": "Comportement", "text": "Remplirait naturellement tous les créneaux de RDV en priorité."}, {"label": "Frein", "text": "Ne pense pas à bloquer des créneaux pour le suivi et la prospection."}, {"label": "Attente", "text": "Un agenda structuré qui lui évite de courir après ses dossiers."}], "context": "Lundi matin. Son agenda est vierge hormis les 3 RDV confirmés.", "stakes": "L'enjeu : construire les 3 blocs, anticiper les J+7 des livraisons, protéger la prospection.", "observe": ["Crée-t-il les 3 blocs distincts ?", "Anticipe-t-il les J+7 des livraisons ?", "Protège-t-il le bloc prospection malgré les RDV ?", "Prévoit-il une revue de fin de semaine ?"]}, {"level": "intermediaire", "title": "Semaine surchargée — prioriser et arbitrer", "objective": "Gérer une semaine surchargée en arbitrant sans sacrifier la prospection.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 32 ans. Agenda plein + client chaud qui veut un RDV urgent demain."}, {"label": "Situation", "text": "Agenda structuré avec les 3 blocs + urgence qui s'impose."}, {"label": "Comportement", "text": "Tendance à sacrifier le bloc prospection pour caser l'urgent."}, {"label": "Frein", "text": "Gestion des urgences sans vision sur l'impact la semaine suivante."}, {"label": "Attente", "text": "Un arbitrage qui intègre l'urgent sans détruire le planning."}], "context": "Mardi 17h. Un client chaud appelle pour un RDV demain matin. Agenda déjà structuré.", "stakes": "L'enjeu : intégrer l'urgent en déplaçant ce qui peut l'être, sans toucher au bloc prospection.", "observe": ["Intègre-t-il l'urgent sans sacrifier la prospection ?", "Identifie-t-il ce qui peut être déplacé vs ce qui est critique ?", "Maintient-il une vision sur la semaine suivante ?", "Replanifie-t-il ce qui a glissé immédiatement ?"]}, {"level": "avance", "title": "Période creuse — relancer le pipeline", "objective": "Analyser un creux, identifier l'origine (prospection sacrifiée), construire un plan de relance structuré.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 38 ans. Creux d'activité — agenda vide depuis 2 semaines."}, {"label": "Situation", "text": "Pipeline vide. Les 6 semaines précédentes étaient chargées — prospection sacrifiée."}, {"label": "Comportement", "text": "Cherche des solutions à court terme sans analyser la cause."}, {"label": "Frein", "text": "Ne fait pas le lien entre le creux actuel et la prospection sacrifiée."}, {"label": "Attente", "text": "Un diagnostic précis et un plan structuré — pas juste \"il faut appeler plus\"."}], "context": "Lundi matin. Agenda vide cette semaine et la suivante. Il faut l'aider à diagnostiquer et construire un plan.", "stakes": "L'enjeu : faire le lien creux = prospection sacrifiée, construire un plan sur 3 semaines, intégrer la protection comme règle permanente.", "observe": ["Fait-il le diagnostic cause/effet ?", "Construit-il un plan sur 3 semaines ?", "Intègre-t-il la protection du bloc prospection comme règle ?", "Son plan est-il réaliste et actionnable ?"]}]}, "online": {"focus": "la planification activité", "attentionPoints": ["Les 3 blocs sont-ils présents dans l'agenda ?", "Le bloc prospection est-il protégé ?", "Les suivis sont-ils anticipés (J+7 livraisons) ?", "Une revue de fin de semaine est-elle planifiée ?"], "grid": ["3 blocs présents", "Prospection protégée", "Suivis anticipés", "Revue fin de semaine"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Les 3 blocs étaient dans ton agenda ? Tu as protégé la prospection ? Tu as anticipé les J+7 ? Tu as une revue vendredi ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que tu as bloqué [bloc] à [moment]. Ça garantit que [résultat]. C'est exactement le lissage qui évite les creux.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as sacrifié la prospection pour caser un RDV urgent]. Le bloc prospection est non-négociable — si un urgent arrive, déplace un RDV mais jamais la prospection.\""}, {"title": "Engagement", "prompt": "\"Cette semaine : construis ton agenda avec les 3 blocs avant lundi 9h. Bilan vendredi. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Les 3 blocs sont connus — protéger la prospection est non-négociable", "02  Offline", "3 situations pratiquées — construire les 3 blocs est un réflexe", "03  Online", "Le coach a observé et débriefé la planification en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/10- Organisation/a. Plannifier son activité.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('27271ec1-013c-5356-be56-4a6cf4af9eab', '6a66a9b3-757d-5fd2-add2-99a8f3afb32c');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('27271ec1-013c-5356-be56-4a6cf4af9eab', '3657674c-707e-52cf-8a2a-afa9271c9491');
insert into public.library_dojos (id, title, content, pptx_path) values ('ec4e1d08-5855-55e9-b156-843832f450c7', 'Confirmer les RDV', $dojo${"version": 1, "tagline": "Confirmer 100% des RDV en creusant le projet pour éviter les lapins", "objective": "Le commercial confirme 100% des RDV J-1, apporte un micro-élément de valeur, creuse le projet pour actualiser, et adapte sa préparation.", "duration": "20-25 min", "theory": {"intro": "Un RDV non confirmé a 3× plus de risques de no-show. La confirmation n'est pas une formalité — c'est une opportunité de creuser le projet, actualiser les informations, et préparer un RDV de qualité.", "standardTitle": "Le standard : pourquoi confirmer & la formule J-1", "standard": [{"label": null, "title": "J-1 SMS/EMAIL", "description": "Message court la veille : confirmer l'horaire et donner un micro-prétexte de valeur (\"j'ai regardé quelques modèles qui pourraient correspondre à votre profil\").", "why": "J-1 réduit les no-shows et crée de l'anticipation positive. Le micro-prétexte donne une raison de venir."}, {"label": null, "title": "APPEL MATIN J", "description": "\"Bonjour — je confirme notre RDV de 15h. Est-ce que votre projet a évolué depuis notre dernier contact ?\"", "why": "L'appel du matin permet de détecter un changement (véhicule trouvé ailleurs, annulation) et d'adapter avant de perdre 2 heures."}, {"label": null, "title": "CREUSER LE PROJET", "description": "Lors de la confirmation, poser 1-2 questions d'actualisation : \"Avez-vous eu d'autres visites depuis ?\" / \"Y a-t-il des points précis que vous voulez qu'on regarde ?\"", "why": "Actualiser avant le RDV permet d'arriver préparé. Un commercial qui sait ce qui a changé démarre avec une longueur d'avance."}], "criteria": [{"title": "Il confirme 100% sans exception", "description": "Même les clients qu'il connaît. Même les RDV du jour même. La confirmation est systématique. Un lapin d'un client connu coûte autant de temps qu'un lapin d'un inconnu."}, {"title": "Sa confirmation apporte quelque chose", "description": "\"Je confirme notre RDV de demain\" n'apporte rien. \"J'ai trouvé 2-3 modèles qui pourraient vraiment vous intéresser\" crée de l'anticipation et réduit les no-shows."}, {"title": "Il creuse le projet à la confirmation", "description": "\"Est-ce que votre projet a évolué depuis notre dernier contact ?\" Cette question révèle des informations précieuses avant le RDV."}, {"title": "Il adapte le contenu du RDV selon la confirmation", "description": "Si le client mentionne un concurrent à la confirmation, le commercial adapte sa préparation. La confirmation n'est utile que si elle informe ce qui suit."}, {"title": "Il gère les tentatives d'annulation", "description": "\"En fait je sais pas si je viens\" est une objection à traiter — pas une raison de reprogrammer sans résistance. Creuser et proposer une alternative avant de reporter."}], "mistakes": [{"title": "Erreur 1 — Ne pas confirmer les RDV proches", "description": "\"Il vient demain matin — pas la peine.\" C'est exactement le RDV qu'on ne confirme pas qui génère le no-show. Systématique = sans exception."}, {"title": "Erreur 2 — Confirmer sans valeur", "description": "Un SMS qui dit juste \"RDV demain 15h confirmé\" est administratif. Ajouter une micro-valeur transforme la confirmation en communication positive."}, {"title": "Erreur 3 — Ne pas creuser à la confirmation", "description": "Confirmer sans demander si le projet a évolué, c'est rater l'occasion de se préparer. Le commercial surpris par un concurrent aurait pu préparer sa différenciation."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Briefer : \"Il est J-1. Tu dois confirmer le RDV. Ton objectif : apporter quelque chose dans la confirmation, creuser le projet, détecter si quelque chose a changé.\""}, {"title": "Lancer le scénario", "description": "Jouer le client. Répondre positivement si la confirmation apporte de la valeur. Donner les infos nouvelles seulement si la question est posée. Observer : valeur apportée, question de creusement posée."}, {"title": "Débriefer", "description": "\"Ta confirmation apportait quoi de concret ? As-tu posé la question d'évolution ? Qu'est-ce que tu as appris ? Comment tu as adapté ta préparation ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain RDV : confirme J-1 avec micro-valeur + question d'évolution. Note ce que tu as appris. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Confirmation standard — RDV sans complication", "objective": "Confirmer avec un micro-élément de valeur, poser la question d'évolution, noter ce qui a changé.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Femme, 36 ans, comptable. RDV pris il y a 4 jours. Projet stable."}, {"label": "Comportement", "text": "Répond rapidement. Confirme sans hésiter. Ne donne pas d'info spontanément."}, {"label": "Info cachée", "text": "Si on demande : son conjoint l'accompagnera finalement."}, {"label": "Attente", "text": "Un commercial préparé qui montre qu'il a pensé à son dossier."}, {"label": "Frein", "text": "Si le commercial ne pose pas la question, il ne saura pas que le conjoint vient."}], "context": "J-1 du RDV. Tout est stable — mais une question d'actualisation révélera que le conjoint vient.", "stakes": "L'enjeu : confirmer avec valeur, poser la question, détecter la présence du conjoint, adapter la préparation.", "observe": ["Apporte-t-il un micro-élément de valeur ?", "Pose-t-il la question d'évolution ?", "Détecte-t-il la présence du conjoint ?", "Adapte-t-il sa préparation ?"]}, {"level": "intermediaire", "title": "Confirmation — le client a vu un concurrent", "objective": "Détecter à la confirmation que le client a visité un concurrent, récupérer les infos, adapter la préparation.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 42 ans, artisan. A visité un concurrent depuis — ne le dit pas spontanément."}, {"label": "Comportement", "text": "Neutre. Répond \"oui ça va\" si question fermée. Donne l'info si question ouverte."}, {"label": "Info cachée", "text": "Si on creuse : offre 1 500€ moins chère ailleurs. Pas encore décidé."}, {"label": "Attente", "text": "Que le commercial sache justifier la différence avant le RDV."}, {"label": "Frein", "text": "Si le commercial arrive sans savoir, il sera en situation de surprise."}], "context": "J-1 du RDV pris il y a 6 jours. Le client a eu le temps de faire d'autres visites.", "stakes": "L'enjeu : creuser jusqu'à révéler la visite, récupérer les infos précises, préparer l'argument de différenciation.", "observe": ["Creuse-t-il jusqu'à révéler la visite ?", "Récupère-t-il les infos précises ?", "Reste-t-il calme sans se braquer ?", "Adapte-t-il sa préparation ?"]}, {"level": "avance", "title": "Tentative d'annulation à la confirmation", "objective": "Gérer une tentative d'annulation à J-1, identifier la vraie raison, proposer une alternative, maintenir le RDV.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 48 ans, responsable RH. Dit à la confirmation qu'elle \"ne sait pas si elle peut venir\"."}, {"label": "Vraie raison", "text": "A reçu une offre par email d'un concurrent. Hésite mais n'ose pas le dire."}, {"label": "Comportement", "text": "Vague. Dit \"j'ai un truc qui s'est organisé\" sans préciser."}, {"label": "Attente", "text": "Que le commercial creuse avec douceur et propose une alternative."}, {"label": "Frein", "text": "Si le commercial accepte sans creuser, il perd le RDV sans savoir pourquoi."}], "context": "J-1. Elle dit qu'elle n'est pas sûre de pouvoir venir demain.", "stakes": "L'enjeu : ne pas capituler, identifier l'offre concurrente, proposer une alternative de timing.", "observe": ["Ne capitule-t-il pas immédiatement ?", "Creuse-t-il la vraie raison ?", "Détecte-t-il l'offre concurrente ?", "Propose-t-il une alternative concrète ?"]}]}, "online": {"focus": "la confirmation RDV", "attentionPoints": ["Apporte-t-il une valeur dans la confirmation ?", "Pose-t-il la question d'évolution du projet ?", "Adapte-t-il sa préparation selon les infos ?", "Gère-t-il une tentative d'annulation sans capituler ?"], "grid": ["Valeur dans la confirmation", "Question évolution posée", "Préparation adaptée", "Annulation gérée"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Ta confirmation apportait quoi ? Tu as posé la question d'évolution — et qu'est-ce que ça t'a appris ? Comment tu as adapté ta préparation ? Si j'ai hésité — comment tu as géré ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que tu as dit [micro-valeur]. Et quand tu as posé [question], j'ai répondu [info]. Tu as immédiatement [adaptation]. C'est une confirmation qui prépare un meilleur RDV.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu n'as pas posé la question d'évolution]. Après la confirmation d'horaire, toujours : 'Votre projet a évolué depuis ?' — 10 secondes qui changent tout.\""}, {"title": "Engagement", "prompt": "\"Sur ton prochain RDV : confirme J-1 avec micro-valeur + question d'évolution. Note ce que tu as appris. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "La formule J-1 est connue — micro-valeur + question d'évolution systématiques", "02  Offline", "3 situations pratiquées — creuser le projet est un réflexe", "03  Online", "Le coach a observé et débriefé la confirmation de RDV en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/10- Organisation/b. Confirmer les RDV.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('ec4e1d08-5855-55e9-b156-843832f450c7', '2067116b-a471-55fe-b965-10fc73f6355c');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('ec4e1d08-5855-55e9-b156-843832f450c7', '3710200f-5219-5782-80cf-05d2a87fc34c');
insert into public.library_dojos (id, title, content, pptx_path) values ('c2f439aa-aa9d-549a-89c0-7f8e8c28c40d', 'Volume d''apps portefeuille', $dojo${"version": 1, "tagline": "Maintenir le bon volume d'opportunités actives dans son portefeuille", "objective": "Le commercial connaît son taux de conversion, surveille son pipeline hebdomadairement, alerte avant le creux, et diversifie ses sources.", "duration": "20-25 min", "theory": {"intro": "Un commercial dont le pipeline est vide aujourd'hui avait trop peu de prospection il y a 6 semaines. Le pilotage du volume d'apps ne se gère pas dans l'urgence — il s'anticipe. 3 indicateurs permettent de détecter un problème avant qu'il devienne un creux.", "standardTitle": "Le standard : la logique du pipeline & les indicateurs clés", "standard": [{"label": null, "title": "VOLUME TOTAL", "description": "Nombre d'opportunités actives à date. Un volume minimum est nécessaire pour garantir un flux de ventes régulier.", "why": "En dessous d'un seuil critique, même une bonne conversion ne suffit pas. Le volume est le carburant du pipeline."}, {"label": null, "title": "TAUX DE CONVERSION", "description": "Ratio RDV → ventes. Permet de calibrer le volume nécessaire : si je convertis 1 sur 4, il me faut 4× mon objectif en opportunités actives.", "why": "Un commercial qui ne connaît pas son taux pilote à l'aveugle. Connaître son taux permet de calculer le volume nécessaire."}, {"label": null, "title": "DÉLAI MOYEN", "description": "Temps moyen entre premier contact et signature. Permet d'anticiper les ventes à venir selon la maturité des dossiers.", "why": "Tous les dossiers en phase découverte = zéro vente cette semaine. La répartition par stade est aussi importante que le volume."}], "criteria": [{"title": "Il connaît son taux de conversion", "description": "Un commercial qui ne connaît pas son ratio RDV/ventes ne peut pas calculer le volume nécessaire. La première étape est de connaître ses ratios sur les 3 derniers mois minimum."}, {"title": "Il surveille son pipeline hebdomadairement", "description": "10 minutes par semaine suffisent pour détecter une anomalie : trop peu en découverte (prospection insuffisante), trop peu en phase finale (conversion à travailler)."}, {"title": "Il alerte avant le creux — pas pendant", "description": "\"Mon pipeline sera insuffisant dans 3 semaines si je n'augmente pas la prospection\" est du pilotage. \"Mon pipeline est vide cette semaine\" est un constat d'échec."}, {"title": "Il diversifie ses sources d'apps", "description": "Un pipeline alimenté uniquement par les entrants est fragile. Ajouter les recommandations, anciens clients, et prospection active crée un pipeline plus résilient."}, {"title": "Il purge régulièrement les dossiers inactifs", "description": "Un dossier sans contact depuis 3 mois encombre et fausse les indicateurs. La purge mensuelle maintient un pipeline réaliste."}], "mistakes": [{"title": "Erreur 1 — Piloter par le résultat plutôt que les indicateurs avancés", "description": "\"Je n'ai pas atteint mon objectif ce mois\" est un indicateur retardé. \"Mon volume en découverte est insuffisant\" est avancé. Le pilotage efficace s'appuie sur les indicateurs avancés."}, {"title": "Erreur 2 — Ne pas purger les dossiers froids", "description": "30 dossiers dont 20 inactifs = pipeline de 10 dossiers réels. Garder les dossiers froids gonfle artificiellement et crée une fausse impression de sécurité."}, {"title": "Erreur 3 — Confondre activité et volume utile", "description": "8 RDV par semaine dont 6 ne sont pas en projet réel = énergie consommée sans alimenter le pipeline. La qualification est aussi importante que le volume."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Donner la situation pipeline (dossiers par stade, taux de conversion, objectif). Briefer : \"Avec ces données, analyse ton pipeline. Est-ce que tu vas atteindre ton objectif ce mois et le mois prochain ?\""}, {"title": "Lancer le scénario", "description": "Observer l'analyse. Poser des questions : \"Ton dossier X est en découverte depuis 6 semaines — comment tu le gères ?\" / \"Tu as 3 livraisons la semaine prochaine — tu as des dossiers pour les remplacer ?\""}, {"title": "Débriefer", "description": "\"Tu connais ton taux de conversion actuel ? À partir de là, quel est le volume minimum nécessaire ? Tu es au-dessus ou en dessous ? Qu'est-ce que tu vas faire dans les 2 prochaines semaines ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Cette semaine : calcule ton taux sur 3 mois et donne-moi le nombre d'apps nécessaire. On en parle vendredi. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Calculer son volume nécessaire", "objective": "Calculer son taux de conversion, en déduire le volume minimum, identifier l'écart avec son pipeline actuel.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Commercial, 24 ans, 6 mois en poste. Ne connaît pas son taux de conversion."}, {"label": "Données", "text": "15 RDV le mois dernier, 4 ventes. Objectif : 6 ventes/mois. Pipeline actuel : 12 apps."}, {"label": "Comportement", "text": "Se concentre sur les RDV de cette semaine sans regarder l'ensemble."}, {"label": "Frein", "text": "Ne fait pas le calcul : taux 27%, besoin de 22 apps minimum pour objectif 6 ventes."}, {"label": "Attente", "text": "Comprendre pourquoi son pipeline est insuffisant malgré un bon rythme de RDV."}], "context": "Revue pipeline. Il pense que ça va — il a du travail cette semaine. Mais son pipeline est en dessous du seuil critique.", "stakes": "L'enjeu : lui faire calculer le taux, en déduire le volume nécessaire, et détecter l'écart.", "observe": ["Calcule-t-il son taux (4/15 = 27%) ?", "En déduit-il le volume nécessaire (6/27% ≈ 22 apps) ?", "Identifie-t-il l'écart (22 nécessaires vs 12 actifs) ?", "Propose-t-il un plan pour combler l'écart ?"]}, {"level": "intermediaire", "title": "Pipeline déséquilibré par stade", "objective": "Détecter un déséquilibre (tout en découverte, rien en phase finale), identifier l'impact sur les ventes à venir.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 32 ans. Pipeline de 20 apps — mais toutes en phase de découverte récente."}, {"label": "Situation", "text": "20 apps, taux 30%, délai moyen 3 semaines. Mais zéro dossier en phase finale."}, {"label": "Comportement", "text": "Pense que son pipeline est sain parce que le volume est bon."}, {"label": "Frein", "text": "Toutes en découverte = zéro vente dans les 3 prochaines semaines."}, {"label": "Attente", "text": "Un diagnostic précis et un plan pour accélérer les dossiers mûrs."}], "context": "Revue pipeline. 20 apps actives — mais toutes en découverte récente.", "stakes": "L'enjeu : détecter le déséquilibre, calculer l'impact à 3 semaines, identifier les dossiers à accélérer.", "observe": ["Analyse-t-il la répartition par stade (pas juste le volume) ?", "Calcule-t-il l'impact sur les ventes à 3 semaines ?", "Identifie-t-il les dossiers à accélérer ?", "Propose-t-il un plan de rééquilibrage ?"]}, {"level": "avance", "title": "Pipeline en creux — anticipation et relance", "objective": "Analyser un pipeline insuffisant, identifier la cause, construire un plan sur 4 semaines.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 38 ans. Pipeline de 8 apps — objectif nécessite 22 minimum."}, {"label": "Cause", "text": "Mois précédent très chargé — prospection sacrifiée pendant 3 semaines."}, {"label": "Comportement", "text": "Cherche des solutions rapides sans plan structuré."}, {"label": "Frein", "text": "Solution court terme sans traitement de la cause — le problème reviendra."}, {"label": "Attente", "text": "Un diagnostic cause/effet et un plan sur 4 semaines avec indicateurs."}], "context": "Revue mensuelle. 8 apps pour un besoin de 22. Situation de crise.", "stakes": "L'enjeu : diagnostic cause/effet, plan réaliste sur 4 semaines, indicateurs de suivi hebdomadaires.", "observe": ["Fait-il le diagnostic cause/effet ?", "Son plan est-il sur 4 semaines ?", "Intègre-t-il des indicateurs hebdomadaires ?", "Traite-t-il la cause, pas juste le symptôme ?"]}]}, "online": {"focus": "le pilotage pipeline", "attentionPoints": ["Connaît-il son taux de conversion ?", "En déduit-il le volume minimum nécessaire ?", "Analyse-t-il la répartition par stade ?", "Anticipe-t-il avant que ce soit un creux ?"], "grid": ["Taux conversion connu", "Volume nécessaire calculé", "Répartition stade analysée", "Anticipation (pas constat)"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Tu connais ton taux ? Quel volume minimum il te faut ? Tu es au-dessus ou en dessous ? Qu'est-ce qui explique la situation et que vas-tu faire ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que tu as calculé [taux] et en déduit [volume nécessaire]. Tu as identifié l'écart et proposé [plan]. C'est exactement le pilotage proactif.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu gères le symptôme sans traiter la cause]. Avant de chercher à remplir en urgence, demande-toi pourquoi le pipeline s'est vidé.\""}, {"title": "Engagement", "prompt": "\"Cette semaine : calcule ton taux sur 3 mois et donne-moi ton volume nécessaire. Vendredi. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "La logique pipeline est connue — connaître son taux est le premier levier", "02  Offline", "3 situations pratiquées — anticiper avant le creux est un réflexe", "03  Online", "Le coach a observé et débriefé le pilotage pipeline en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/10- Organisation/c. Volume portefeuille.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('c2f439aa-aa9d-549a-89c0-7f8e8c28c40d', '82c18e89-d4c6-57e3-8d83-6a39bbd6b5b2');
insert into public.library_dojos (id, title, content, pptx_path) values ('c32ba9cf-315d-57f5-b01c-41b124676764', 'Optimiser la boite mail', $dojo${"version": 1, "tagline": "Gérer sa boite mail sans oubli ni retard pour maintenir la réactivité", "objective": "Le commercial traite sa boite 2 fois par jour, répond aux clients sous 24h, archive après traitement, et détecte les opportunités cachées.", "duration": "20-25 min", "theory": {"intro": "Un email de client qui attend 3 jours sans réponse peut coûter une vente. La méthode des 3 boites transforme la gestion des emails en processus fiable et prévisible.", "standardTitle": "Le standard : la méthode des 3 boites & les 4 types", "standard": [{"label": null, "title": "BOITE À TRAITER", "description": "Tous les emails entrants non traités. L'objectif : la vider chaque jour. Un email traité = répondu, délégué, ou archivé.", "why": "Une boite vide en fin de journée garantit qu'aucune opportunité ne dort. C'est l'indicateur le plus simple de la maîtrise."}, {"label": null, "title": "BOITE EN ATTENTE", "description": "Emails qui nécessitent une réponse mais dépendent d'une action tierce. À consulter chaque matin pour relancer si nécessaire.", "why": "Sans cette boite, les emails \"en attente\" se perdent dans la principale. Une boite dédiée crée un système de relance visuel."}, {"label": null, "title": "BOITE ARCHIVES", "description": "Emails traités, classés. Accessibles en recherche — pas visibles dans la vue principale. Archiver immédiatement après traitement.", "why": "L'archivage maintient la boite principale propre. Un email archivé est retrouvable en 10 secondes. Un email noyé dans 3 000 prend 5 minutes."}], "criteria": [{"title": "Il traite sa boite 2 fois par jour — pas en continu", "description": "Vérifier ses emails toutes les 10 minutes fragmente la concentration. 2 plages dédiées (matin et après-midi) suffisent pour être réactif sans être esclave de la boite."}, {"title": "Il répond dans les 24h aux emails clients", "description": "Un client qui attend 3 jours sans réponse cherche ailleurs. Les emails clients sont prioritaires — leur réponse ne se reporte pas."}, {"title": "Il utilise des réponses types pour les demandes fréquentes", "description": "Reformuler la même réponse 10 fois est du temps perdu. Des templates personnalisables réduisent le temps de traitement tout en maintenant la qualité."}, {"title": "Il archive immédiatement après traitement", "description": "Traité = archivé. Laisser un email traité dans la boite principale crée de l'encombrement et du stress visuel."}, {"title": "Il détecte les opportunités cachées", "description": "\"Juste pour avoir des infos\" est souvent un lead qualifié déguisé. Chaque email entrant client mérite une qualification rapide."}], "mistakes": [{"title": "Erreur 1 — Vérifier ses emails en continu", "description": "Chaque notification interrompt une tâche. 23 minutes pour retrouver sa concentration après une interruption. Multiplié par 30 emails/jour = une journée entière perdue. 2 plages valent mieux que 30 interruptions."}, {"title": "Erreur 2 — Laisser des emails sans réponse plus de 24h", "description": "Le client sans réponse après 24h considère que son interlocuteur n'est pas fiable. Il appelle un concurrent — ou rappelle agacé. La réactivité email est un marqueur fort de professionnalisme."}, {"title": "Erreur 3 — Garder tous les emails dans la boite principale", "description": "3 000 emails non archivés = boite inutilisable. Retrouver un email prend 5 minutes. Le stress visuel d'une boite pleine consomme de l'énergie cognitive. Archiver = libérer de l'espace mental."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Donner une simulation de boite avec 15 emails variés (client, interne, newsletter, lead caché, relance). Briefer : \"Tu as 20 minutes pour traiter cette boite. Je regarde si les priorités sont bonnes et si tu détectes le lead caché.\""}, {"title": "Lancer le scénario", "description": "Observer le traitement. Chronomètrer. Poser des questions : \"Cet email de M. Dupont qui demande des infos — tu en fais quoi ?\" Observer : priorisation client vs interne, détection du lead, archivage."}, {"title": "Débriefer", "description": "\"Dans quel ordre as-tu traité — et pourquoi ? As-tu détecté l'email de M. Dupont comme lead potentiel ? Tu as archivé ? Combien de temps tu as mis ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Cette semaine : traite ta boite en 2 plages — matin et après-midi. Note combien de temps par plage. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Boite de 15 emails — trier et prioriser", "objective": "Identifier les 3 catégories de priorité, traiter dans l'ordre, archiver après chaque traitement.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Commercial, 25 ans, 4 mois en poste. Boite de 15 emails non traités depuis hier matin."}, {"label": "Contenu", "text": "3 emails clients, 4 internes (1 urgent), 5 newsletters, 2 leads entrants, 1 email RH."}, {"label": "Comportement", "text": "Traite dans l'ordre d'arrivée sans prioriser."}, {"label": "Frein", "text": "Traite les newsletters avant les clients — risque de retard sur les priorités."}, {"label": "Attente", "text": "Un traitement structuré en moins de 20 minutes."}], "context": "Matin. 15 emails non lus après une demi-journée de RDV. 20 minutes avant le prochain client.", "stakes": "L'enjeu : prioriser clients → interne urgent → reste, répondre aux clients, archiver, détecter les 2 leads.", "observe": ["Priorise-t-il les emails clients en premier ?", "Détecte-t-il les 2 leads entrants ?", "Archive-t-il après chaque traitement ?", "Traite-t-il les 15 emails en moins de 20 minutes ?"]}, {"level": "intermediaire", "title": "Email ambigu — lead caché ou simple info ?", "objective": "Détecter un email \"demande d'info\" comme lead qualifié, qualifier, décider si un appel s'impose.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 38 ans, chef d'équipe. Email : \"Bonjour, je cherche des infos sur vos SUV.\""}, {"label": "Indice de qualification", "text": "Son email mentionne : \"mon bail se termine en mars\". Projet réel et daté."}, {"label": "Comportement", "text": "N'appellera pas spontanément — attend une réponse."}, {"label": "Attente", "text": "Une réponse rapide et personnalisée — pas un copier-coller de brochure."}, {"label": "Frein", "text": "Un commercial qui traite ça comme info simple rate le projet concret."}], "context": "Mardi matin. L'email est arrivé hier soir. Il est dans la boite non traitée avec 8 autres.", "stakes": "L'enjeu : détecter l'indice de qualification (mars), répondre avec personnalisation, proposer un RDV.", "observe": ["Détecte-t-il l'indice de qualification (mars) ?", "Sa réponse est-elle personnalisée ?", "Propose-t-il un RDV plutôt que juste des infos ?", "Répond-il dans les 4 heures ?"]}, {"level": "avance", "title": "Boite de 40 emails après 2 jours d'absence", "objective": "Gérer un stock accumulé, prioriser efficacement, traiter le critique sans se noyer dans le volume.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 42 ans. Revient de 2 jours de formation — 40 emails non lus."}, {"label": "Critique", "text": "1 réclamation urgente, 2 leads chauds entrants, 1 email manager urgent."}, {"label": "Reste", "text": "12 internes informatifs, 8 newsletters, 6 confirmations auto, 9 suivis non urgents."}, {"label": "Comportement", "text": "Risque de se noyer et de ne pas détecter les urgences."}, {"label": "Attente", "text": "Tri rapide en 3 catégories et traitement des urgences dans l'heure."}], "context": "Lundi matin après 2 jours de formation. 40 emails. Réunion à 10h. 45 minutes pour traiter le critique.", "stakes": "L'enjeu : scanner rapidement, identifier les 4 emails critiques, traiter en priorité, organiser le reste.", "observe": ["Scanne-t-il avant de traiter (pas dans l'ordre) ?", "Identifie-t-il les 4 critiques en moins de 5 min ?", "Traite-t-il le critique avant les informatifs ?", "Archive-t-il intelligemment le reste ?"]}]}, "online": {"focus": "la gestion boite mail", "attentionPoints": ["Priorise-t-il clients → urgent interne → reste ?", "Détecte-t-il les leads cachés ?", "Archive-t-il après chaque traitement ?", "Traite-t-il en plages dédiées (pas en continu) ?"], "grid": ["Priorisation correcte", "Leads cachés détectés", "Archivage systématique", "Plages dédiées respectées"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Dans quel ordre as-tu traité — et pourquoi ? As-tu détecté [lead ou urgence] ? Tu as archivé ? Combien de temps tu as mis ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que tu as traité [critique] en premier et détecté [lead]. Tu as archivé après chaque email — la boite est vide à la fin. C'est exactement ça qui évite les oublis.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu n'as pas détecté le lead de M. Dupont]. Dans chaque email client, cherche toujours l'indice de qualification — une date, un délai, un événement.\""}, {"title": "Engagement", "prompt": "\"Cette semaine : 2 plages dédiées par jour. Note le temps par plage. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "La méthode 3 boites est connue — 2 plages dédiées remplacent les interruptions continues", "02  Offline", "3 situations pratiquées — détecter les leads et archiver sont des réflexes", "03  Online", "Le coach a observé et débriefé la gestion de la boite mail en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/10- Organisation/d. Optimiser la boite mail.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('c32ba9cf-315d-57f5-b01c-41b124676764', '6f11612e-43e0-5819-bdcc-67ffd05bb629');
insert into public.library_dojos (id, title, content, pptx_path) values ('62a4ab6c-3cce-569c-9c1c-86828cf10140', 'Positionnement face à la concurrence', $dojo${"version": 1, "tagline": "Connaître les forces et faiblesses des concurrents pour mieux différencier", "objective": "Le commercial qualifie l'offre concurrente avant de répondre, différencie sur un argument ancré dans la découverte, et ne termine pas sur le concurrent.", "duration": "20-25 min", "theory": {"intro": null, "standardTitle": null, "standard": [], "criteria": [], "mistakes": [], "sections": [{"title": "Carte concurrentielle — les acteurs en présence", "lines": ["Concurrent", "Type", "Force principale", "Faiblesse principale", "Notre argument de diff.", "✏ [CONCURRENT_1]", "✏ [TYPE_CONCURRENT_1]", "✏ [FORCE_CONCURRENT_1]", "✏ [FAIBLESSE_CONCURRENT_1]", "✏ [ARGUMENT_DIFFÉRENCIATION_1]", "✏ [CONCURRENT_2]", "✏ [TYPE_CONCURRENT_2]", "✏ [FORCE_CONCURRENT_2]", "✏ [FAIBLESSE_CONCURRENT_2]", "✏ [ARGUMENT_DIFFÉRENCIATION_2]", "✏ [CONCURRENT_3]", "✏ [TYPE_CONCURRENT_3]", "✏ [FORCE_CONCURRENT_3]", "✏ [FAIBLESSE_CONCURRENT_3]", "✏ [ARGUMENT_DIFFÉRENCIATION_3]", "⚡ Carte à mettre à jour à chaque évolution de l'offre concurrente — date de dernière mise à jour : [DATE_MAJ]"]}, {"title": "Nos arguments de différenciation", "intro": "Se différencier ne signifie pas attaquer le concurrent — c'est valoriser ce qui est unique dans notre offre en lien avec ce que le client a dit en découverte. L'argument de diff n'est efficace que s'il répond à un besoin exprimé.", "items": [{"title": "PRIX / COÛT TOTAL", "description": "✏ [ARG_DIFF_PRIX]", "example": "Ne pas défendre le prix seul — défendre la valeur totale. \"Pas le moins cher, mais le coût le plus bas sur [X] ans.\""}, {"title": "SERVICE & ACCOMPAGNEMENT", "description": "✏ [ARG_DIFF_SERVICE]", "example": "L'argument service est fort sur les clients qui ont eu une mauvaise expérience ailleurs. Connecter à ce qu'ils ont exprimé."}, {"title": "GAMME & DISPONIBILITÉ", "description": "✏ [ARG_DIFF_GAMME]", "example": "L'argument gamme est fort quand le client hésite entre plusieurs modèles ou types de financement."}, {"title": "EXPERTISE & CONFIANCE", "description": "✏ [ARG_DIFF_EXPERTISE]", "example": "L'argument expertise est fort sur les clients anxieux (Sécurité SONCASE) ou sur les profils professionnels."}]}, {"title": "La méthode : répondre à un concurrent sans attaquer", "lines": ["Quand un client mentionne un concurrent, la première réaction ne doit pas être la défense. C'est une information précieuse qui permet de comprendre ce que le client valorise — et d'y répondre avec précision.", "1", "Accuser réception sans se braquer", "\"Je comprends — vous avez fait le tour, c'est normal.\" Ne pas défendre immédiatement. Accuser réception maintient la posture de conseiller — pas de vendeur en défense.", "Interdit : \"Oui mais eux c'est pas pareil...\" dit à chaud. C'est la réponse qui fait perdre la crédibilité.", "2", "Qualifier l'offre concurrente", "\"Vous pouvez me dire ce que leur offre incluait exactement ? C'est sur quel modèle, quelle durée ?\" Comparer à périmètre égal — pas taux brut vs taux brut.", "La plupart des offres concurrentes \"moins chères\" ne sont pas comparables à périmètre égal. La qualification révèle les différences réelles.", "3", "Différencier sur ce qui compte pour lui", "\"La différence c'est [argument ancré dans sa découverte].\" Pas un argument générique — un argument connecté à ce que le client a dit qu'il valorisait.", "Exemple : \"Vous m'avez dit que la fiabilité du SAV était importante — sur ce point, voilà ce qui nous différencie concrètement.\"", "4", "Ne pas terminer sur le concurrent", "Après l'argument de différenciation, revenir sur le client et le projet. \"Ce qui compte c'est que ça réponde à votre usage — et sur ce point, voilà ce qu'on vous propose.\"", "Terminer sur le concurrent laisse le client avec le concurrent en tête. Terminer sur la valeur de l'offre laisse le client avec l'offre en tête."]}]}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je joue un client qui mentionne [CONCURRENT_X]. Ton objectif : accuser réception sans défense, qualifier l'offre, différencier sur un argument lié à ma découverte. Je lève la main si tu attaques le concurrent directement.\""}, {"title": "Lancer le scénario", "description": "Jouer le client qui mentionne le concurrent. Donner l'offre concurrente si on la demande. Résister si l'argument de diff n'est pas ancré dans la découverte. Observer : qualification de l'offre, argument ancré, fin sur l'offre et non sur le concurrent."}, {"title": "Débriefer", "description": "\"Tu as qualifié l'offre concurrente — à périmètre égal c'était quoi la différence réelle ? Sur quel argument as-tu différencié — et c'était ancré dans quoi que je t'avais dit ? Tu as terminé sur le concurrent ou sur ta valeur ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client qui mentionne un concurrent : note l'offre qualifiée, l'argument utilisé et sur quoi tu as terminé. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Concurrent mentionne un écart de prix — [CONCURRENT_1]", "objective": "Qualifier l'offre à périmètre égal, montrer que l'écart réel est différent de l'écart annoncé, différencier sans attaquer.", "duration": "20 min", "persona": [{"label": "Concurrent", "text": "[CONCURRENT_1]"}, {"label": "Objection", "text": "[OBJECTION_PRIX_CONCURRENT_1]"}, {"label": "Périmètre réel", "text": "[PÉRIMÈTRE_OFFRE_CONCURRENT_1] — manque [ÉLÉMENT_MANQUANT_1]"}, {"label": "Découverte clé", "text": "[USAGE_QUI_JUSTIFIE_DIFF_1]"}, {"label": "Argument de diff", "text": "[ARG_DIFF_PRIX]"}], "context": "RDV en cours. Le client dit qu'il a vu une offre moins chère chez [CONCURRENT_1]. Il annonce un écart de [MONTANT_ÉCART].", "stakes": "L'enjeu : qualifier exactement ce que l'offre inclut, calculer l'écart réel à périmètre égal, et différencier sur [ARG_DIFF_1] ancré dans sa découverte.", "observe": ["Accuse-t-il réception sans se braquer ?", "Qualifie-t-il le périmètre exact de l'offre concurrente ?", "Montre-t-il l'écart réel à périmètre égal ?", "Différencie-t-il sur un argument ancré dans la découverte ?"]}, {"level": "intermediaire", "title": "Offre financement concurrente — [CONCURRENT_2]", "objective": "Comparer les offres de financement à périmètre égal, identifier ce qui rend l'offre concurrente moins avantageuse qu'elle n'y paraît, et repositionner.", "duration": "25 min", "persona": [{"label": "Concurrent", "text": "[CONCURRENT_2]"}, {"label": "Offre concurrente", "text": "[OBJECTION_OFFRE_CONCURRENT_2]"}, {"label": "Ce que cache l'offre", "text": "[CE_QUE_CACHE_OFFRE_CONCURRENT_2] — ex: taux plus élevé, sans garanties"}, {"label": "Découverte clé", "text": "[USAGE_QUI_JUSTIFIE_DIFF_2]"}, {"label": "Argument de diff", "text": "[ARG_DIFF_SERVICE]"}], "context": "RDV après présentation du financement. Le client mentionne une offre de financement de [CONCURRENT_2] qui semble plus avantageuse en surface.", "stakes": "L'enjeu : qualifier les conditions réelles de l'offre (taux, durée, inclusions), comparer à périmètre égal, et repositionner sur la valeur globale.", "observe": ["Qualifie-t-il les conditions exactes de l'offre Fi concurrente ?", "Compare-t-il à périmètre égal ?", "Son argument de diff est-il ancré dans la découverte ?", "Termine-t-il sur sa valeur — pas sur le concurrent ?"]}, {"level": "avance", "title": "Concurrent non identifié — offre vue en ligne", "objective": "Gérer une objection sur une offre vue sur internet dont on ne connaît pas le détail, qualifier sans avoir toutes les infos, et maintenir la crédibilité.", "duration": "25 min", "persona": [{"label": "Concurrent", "text": "[CONCURRENT_3]"}, {"label": "Objection", "text": "[OBJECTION_COMPLEXE_CONCURRENT_3]"}, {"label": "Difficulté", "text": "Le commercial n'a pas le détail de cette offre. Il doit qualifier avec les questions."}, {"label": "Découverte clé", "text": "[USAGE_QUI_JUSTIFIE_DIFF_3]"}, {"label": "Argument de diff", "text": "[ARG_DIFF_EXPERTISE]"}], "context": "RDV en fin de parcours. Le client mentionne une offre vue sur un site en ligne dont il n'a pas tous les détails.", "stakes": "L'enjeu : qualifier progressivement avec des questions (provenance, garanties, historique véhicule), identifier les zones de risque pour le client, et différencier sur la sécurité et l'expertise.", "observe": ["Pose-t-il les bonnes questions de qualification ?", "Identifie-t-il les zones de risque de l'offre en ligne ?", "Son argument de diff (expertise/sécurité) est-il ancré dans la découverte ?", "Maintient-il sa crédibilité sans dénigrement ?"]}]}, "online": {"focus": "le positionnement conc.", "attentionPoints": ["Accuse-t-il réception sans attaquer immédiatement ?", "Qualifie-t-il l'offre à périmètre égal avant de répondre ?", "Son argument de diff est-il ancré dans la découverte ?", "Termine-t-il sur sa valeur — pas sur le concurrent ?"], "grid": ["A.R. sans attaque", "Offre qualifiée", "Arg. ancré découverte", "Fin sur sa valeur"], "debrief": [], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "La carte concurrentielle est connue — qualifier avant de répondre est la règle", "02  Offline", "3 situations pratiquées — différencier sans attaquer est un réflexe", "03  Online", "Le coach a observé et débriefé le positionnement concurrence en situation réelle", "⚡ Version [DATE_MAJ] — [NOM_STRUCTURE] — Carte concurrentielle à mettre à jour régulièrement"]}]}, "takeaways": null, "hasPlaceholders": true}$dojo$::jsonb, 'bibliotheque/11- Connaissance produit & gamme/dojo_template_concurrence.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('62a4ab6c-3cce-569c-9c1c-86828cf10140', 'bef8cb22-e10a-52f4-88ef-41e0472d1e6b');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('62a4ab6c-3cce-569c-9c1c-86828cf10140', '730b7dbf-20e1-501e-bdf2-48952f697a94');
insert into public.library_dojos (id, title, content, pptx_path) values ('64dfff1a-df10-5fc2-9b38-e1c2d4bc6883', 'Offres de financement & conditions', $dojo${"version": 1, "tagline": "Maîtriser les produits, les taux et les offres pour conseiller avec précision", "objective": "Le commercial recommande le bon produit selon le profil découvert, le présente avec le B ancré dans la découverte, maîtrise les conditions en vigueur, et ramène au coût mensuel.", "duration": "20-25 min", "theory": {"intro": null, "standardTitle": null, "standard": [], "criteria": [], "mistakes": [], "sections": [{"title": "Les produits de financement disponibles", "lines": ["Produit", "Description", "Avantages clés", "Profil adapté", "Conditions", "✏ [PRODUIT_FI_1]", "✏ [DESC_PRODUIT_1]", "✏ [AVANTAGES_1]", "✏ [PROFIL_1]", "✏ [CONDITION_1]", "✏ [PRODUIT_FI_2]", "✏ [DESC_PRODUIT_2]", "✏ [AVANTAGES_2]", "✏ [PROFIL_2]", "✏ [CONDITION_2]", "✏ [PRODUIT_FI_3]", "✏ [DESC_PRODUIT_3]", "✏ [AVANTAGES_3]", "✏ [PROFIL_3]", "✏ [CONDITION_3]", "⚡ Taux en vigueur — LOA : [TAUX_LOA_ACTUEL]  |  Crédit classique : [TAUX_CC_ACTUEL]  |  Balloon : [TAUX_BALLOON_ACTUEL]  |  Offre 0% : [OFFRE_TAUX_ZÉRO]  |  MAJ : [DATE_MAJ]"]}, {"title": "Offres du moment — en vigueur au [DATE_MAJ]", "intro": "⚡  ATTENTION — Cette slide est la plus volatile du Dojo. Les offres changent souvent. Vérifier auprès du responsable financements avant chaque formation ou RDV.", "items": [{"title": "✏ [OFFRE_1]", "description": "✏ [DÉTAIL_OFFRE_1]", "example": "✏ [VALIDITÉ_1]"}, {"title": "✏ [OFFRE_2]", "description": "✏ [DÉTAIL_OFFRE_2]", "example": "✏ [VALIDITÉ_2]"}, {"title": "✏ [OFFRE_3]", "description": "✏ [DÉTAIL_OFFRE_3]", "example": "✏ [VALIDITÉ_3]"}]}, {"title": "Comment présenter les offres et les adapter au profil", "lines": ["Connaître les produits Fi ne suffit pas — il faut savoir quel produit proposer à quel profil, et le présenter avec le B ancré dans la découverte. Un produit bien connu mais mal présenté ne convainc pas.", "1", "Écouter avant de proposer", "La découverte financière (budget mensuel, apport, durée préférée, rapport à la propriété) détermine quel produit est adapté. Proposer un produit sans avoir fait cette découverte, c'est jouer à pile ou face.", "\"Et pour le financement, vous avez réfléchi à comment vous l'envisagez ?\" — avant toute présentation de produit.", "2", "Présenter 1 produit adapté — pas le catalogue", "\"Vu ce que vous m'avez dit, je vous recommande [PRODUIT] parce que [AVANTAGE_ANCRÉ_DÉCOUVERTE].\" Une recommandation ciblée est perçue comme du conseil. Le catalogue des produits est perçu comme de la vente.", "Présenter 2 produits maximum. Au-delà, le client est paralysé par le choix et ne décide pas.", "3", "Maîtriser les conditions en vigueur", "Ne jamais annoncer un taux ou une condition de mémoire sans vérification récente. Un taux annoncé faux crée une déception à la signature — et détruit la confiance construite pendant tout le RDV.", "Règle : vérifier les taux et offres avant chaque RDV. Date de la dernière vérification : [DATE_MAJ]", "4", "Présenter le coût mensuel — pas le taux", "\"C'est un taux de 5,9%\" ne dit rien à la plupart des clients. \"Avec ce financement, ça représente [X]€/mois\" est concret et actionnable. Toujours ramener à la mensualité.", "Exception : le client expert qui demande le taux explicitement. Dans ce cas, donner le taux ET la mensualité correspondante."]}]}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Vérifier que les taux et conditions utilisés sont à jour. Briefer : \"Je joue un client avec un profil Fi précis. Ton objectif : identifier le bon produit, le présenter avec le B lié à ma découverte, et me donner le coût mensuel — pas le taux brut.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona avec un profil financier précis (budget mensuel, apport, rapport à la propriété). Donner les infos de découverte progressivement. Observer : quel produit est recommandé, comment il est présenté, est-ce que le coût mensuel est donné."}, {"title": "Débriefer", "description": "\"Quel produit as-tu recommandé — et pourquoi ce produit pour ce profil ? Comment as-tu présenté l'avantage — tu as fait le lien avec ma découverte ? Tu m'as donné un taux ou un coût mensuel ? Les conditions que tu m'as annoncées — elles sont à jour ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Avant ton prochain RDV avec un volet Fi : vérifie les taux et offres en vigueur. Note le produit que tu vas recommander selon le profil et le B que tu vas utiliser. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Client profil propriété — choisir le bon produit", "objective": "Identifier que le profil client correspond à [PRODUIT_FI_2] (crédit classique), le recommander avec le B adapté, donner le coût mensuel.", "duration": "20 min", "persona": [{"label": "Profil Fi", "text": "[PROFIL_PROPRIÉTÉ] — veut être propriétaire, garde longtemps ses véhicules"}, {"label": "Budget mensuel", "text": "[BUDGET_MENSUEL_SC1]"}, {"label": "Apport disponible", "text": "[APPORT_SC1]"}, {"label": "Produit recommandé", "text": "[PRODUIT_RECOMMANDÉ_SC1] — [RAISON_SC1]"}, {"label": "Offre du moment applicable", "text": "[OFFRE_APPLICABLE_SC1]"}], "context": "Client qui dit clairement qu'il veut \"être propriétaire de son véhicule\". Budget mensuel : [BUDGET_MENSUEL_SC1]. Apport : [APPORT_SC1].", "stakes": "L'enjeu : identifier que [PRODUIT_FI_2] est le bon produit, le présenter avec le B ancré dans la découverte (propriété = correspond à son système de valeur), et donner le coût mensuel précis.", "observe": ["Identifie-t-il le bon produit selon le profil ?", "Présente-t-il le B ancré dans la découverte (propriété) ?", "Donne-t-il le coût mensuel — pas juste le taux ?", "Mentionne-t-il l'offre du moment applicable ?"]}, {"level": "intermediaire", "title": "Client profil mobilité — LOA ou location longue durée", "objective": "Identifier un profil qui veut changer souvent de véhicule, recommander [PRODUIT_FI_1], expliquer les conditions, gérer l'inquiétude sur \"ne pas être propriétaire\".", "duration": "25 min", "persona": [{"label": "Profil Fi", "text": "[PROFIL_MOBILITÉ] — change de véhicule tous les 2-3 ans, budget mensuel prioritaire"}, {"label": "Budget mensuel", "text": "[BUDGET_MENSUEL_SC2]"}, {"label": "Inquiétude", "text": "\"Mais avec la LOA je ne suis pas propriétaire — ça m'inquiète un peu.\""}, {"label": "Produit recommandé", "text": "[PRODUIT_FI_1] — [RAISON_SC2]"}, {"label": "Condition clé à maîtriser", "text": "[CONDITION_LOA_IMPORTANTE]"}], "context": "Client qui change tous les 3 ans et qui veut \"toujours avoir un véhicule récent\". Il est légèrement inquiet sur le fait de ne pas être propriétaire avec la LOA.", "stakes": "L'enjeu : recommander [PRODUIT_FI_1] avec le B adapté à son profil mobilité, et lever l'inquiétude sur la propriété avec un argument factuel.", "observe": ["Identifie-t-il le bon produit pour le profil mobilité ?", "Présente-t-il le B ancré dans la découverte (renouvellement facilité) ?", "Lève-t-il l'inquiétude propriété avec un argument factuel ?", "Maîtrise-t-il les conditions en vigueur ?"]}, {"level": "avance", "title": "Client qui connaît bien les offres — question sur les taux", "objective": "Répondre précisément à une question sur les taux, maintenir la crédibilité face à un profil informé, et démontrer la valeur globale au-delà du taux brut.", "duration": "25 min", "persona": [{"label": "Profil", "text": "[PROFIL_EXPERT_FI] — a comparé les taux en ligne, sait ce qu'il cherche"}, {"label": "Question", "text": "\"Votre taux LOA c'est [TAUX_LOA_ACTUEL] — j'ai vu des offres à [TAUX_CONCURRENT] ailleurs.\""}, {"label": "Réponse correcte", "text": "[RÉPONSE_TAUX_ANCRÉ_PÉRIMÈTRE_ÉGAL]"}, {"label": "Ce qui compte", "text": "Comparer à périmètre égal — inclusions, garanties, services associés"}, {"label": "Offre applicable", "text": "[OFFRE_DU_MOMENT_APPLICABLE_SC3]"}], "context": "Client très informé. Il a fait ses recherches en ligne et compare les taux bruts. Il mentionne un taux concurrent plus bas.", "stakes": "L'enjeu : ne pas se défendre sur le taux seul, qualifier ce que l'offre concurrente inclut, et repositionner sur la valeur totale — en maîtrisant les conditions exactes en vigueur.", "observe": ["Répond-il sans paniquer sur le taux brut ?", "Qualifie-t-il l'offre concurrente à périmètre égal ?", "Repositionne-t-il sur la valeur totale ?", "Maîtrise-t-il les taux et conditions en vigueur à la date du RDV ?"]}]}, "online": {"focus": "la maîtrise des offres Fi", "attentionPoints": ["Recommande-t-il le bon produit selon le profil découvert ?", "Présente-t-il le B ancré dans la découverte ?", "Donne-t-il le coût mensuel (pas seulement le taux) ?", "Les conditions et taux annoncés sont-ils à jour ?"], "grid": ["Bon produit recommandé", "B ancré découverte", "Coût mensuel donné", "Taux/conditions à jour"], "debrief": [], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Les produits et offres du moment sont connus — recommander selon le profil est la règle", "02  Offline", "3 profils Fi pratiqués — B ancré découverte et coût mensuel sont des réflexes", "03  Online", "Le coach a observé et débriefé la maîtrise des offres Fi en situation réelle", "⚡ VERSION [DATE_MAJ] — Taux et offres à vérifier avant chaque utilisation"]}]}, "takeaways": null, "hasPlaceholders": true}$dojo$::jsonb, 'bibliotheque/11- Connaissance produit & gamme/dojo_template_financement.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('64dfff1a-df10-5fc2-9b38-e1c2d4bc6883', '55779971-d1b4-51e6-965e-4705bb926f31');
insert into public.library_dojos (id, title, content, pptx_path) values ('bf4f6ba7-4c10-5e0c-b56e-d3900a783e24', 'Caractéristiques techniques gamme', $dojo${"version": 1, "tagline": "Maîtriser les points clés de chaque modèle pour argumenter avec précision", "objective": "Le commercial restitue les 3 points clés d'un modèle en les liant au profil client, gère ses angles morts sans perdre en crédibilité, et positionne le modèle dans la gamme.", "duration": "20-25 min", "theory": {"intro": null, "standardTitle": null, "standard": [], "criteria": [{"title": "Il maîtrise les 3 points clés de chaque modèle", "description": "Pas toute la fiche technique — les 3 caractéristiques les plus différenciantes de chaque modèle, liées aux profils clients les plus fréquents. C'est le minimum opérationnel en RDV."}, {"title": "Il restitue en liant au profil client", "description": "\"Ce modèle correspond à votre usage parce que [caractéristique précise]\" vaut 10 fois plus qu'une liste de specs. La restitution technique est toujours contextualisée au profil découvert."}, {"title": "Il sait positionner chaque modèle dans la gamme", "description": "Savoir situer un modèle par rapport aux autres de la gamme — \"c'est le modèle d'entrée qui couvre 80% des usages\" ou \"c'est le haut de gamme avec [différence clé]\" — permet de guider le client vers le bon véhicule."}, {"title": "Il assume ses angles morts sans perdre en crédibilité", "description": "\"Je vérifie et je reviens vers vous\" dit avec assurance maintient la confiance. \"Je crois que...\" suivi d'une approximation la détruit. Reconnaître ce qu'on ne sait pas est une marque de professionnalisme."}, {"title": "Il se met à jour proactivement", "description": "À chaque évolution de gamme, chaque nouvelle motorisation, chaque mise à jour de finition — le commercial proactif se documente avant d'être en situation client. Il ne découvre pas une nouveauté pendant un RDV."}], "mistakes": [], "sections": [{"title": "La gamme — vue d'ensemble", "lines": ["Segment", "Modèle", "Motorisations clés", "Points différenciants", "Profil client type", "✏ [SEGMENT_1]", "✏ [MODÈLE_1]", "✏ [MOTO_1]", "✏ [POINTS_CLÉS_1]", "✏ [PROFIL_CLIENT_1]", "✏ [SEGMENT_2]", "✏ [MODÈLE_2]", "✏ [MOTO_2]", "✏ [POINTS_CLÉS_2]", "✏ [PROFIL_CLIENT_2]", "✏ [SEGMENT_3]", "✏ [MODÈLE_3]", "✏ [MOTO_3]", "✏ [POINTS_CLÉS_3]", "✏ [PROFIL_CLIENT_3]", "✏ [SEGMENT_4]", "✏ [MODÈLE_4]", "✏ [MOTO_4]", "✏ [POINTS_CLÉS_4]", "✏ [PROFIL_CLIENT_4]", "⚡ Ce tableau est à mettre à jour à chaque évolution de gamme — date de dernière mise à jour : [DATE_MAJ]"]}, {"title": "Comment mémoriser et restituer efficacement", "intro": "Connaître les caractéristiques techniques n'a de valeur que si on peut les restituer dans le bon contexte — lié au profil client. Ce n'est pas un concours de mémoire : c'est savoir quel argument technique répond à quel besoin.", "items": [{"title": "1 — ANCRER PAR PROFIL", "description": "Associer chaque modèle à un profil client type plutôt qu'à une liste de caractéristiques. \"Ce modèle, c'est le client X.\" L'ancrage par profil rend la restitution naturelle en RDV.", "example": "\"[MODÈLE_1], c'est le [PROFIL_CLIENT_1] — parce que [POINTS_CLÉS_1].\""}, {"title": "2 — 3 POINTS MAX PAR MODÈLE", "description": "Ne retenir que les 3 points les plus différenciants par modèle. Pas toute la fiche technique — les 3 points qui font la différence en RDV avec un client de ce profil.", "example": "Préparation : avant chaque RDV, noter les 3 points du modèle que ce client va demander."}, {"title": "3 — LIER AU BESOIN DÉCOUVERT", "description": "Restituer une caractéristique technique en la connectant à quelque chose dit en découverte. \"Vous m'avez dit [usage] — sur ce modèle, [caractéristique] répond exactement à ça.\"", "example": "Pas : \"Ce modèle a un couple de 320 Nm.\" Mais : \"Vous faites de l'autoroute chargé — le couple de 320 Nm, c'est exactement fait pour ça.\""}, {"title": "4 — RECONNAÎTRE SES ANGLES MORTS", "description": "Savoir ce qu'on ne sait pas est une compétence. \"Je vérifie et je vous confirme\" dit avec assurance est plus fort qu'une approximation. Ne jamais inventer une caractéristique technique.", "example": "\"Je n'ai pas le chiffre exact en tête — je vous confirme ça avant la fin de la journée.\""}]}]}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Donner au commercial la fiche du modèle [MODÈLE_X] avant. Briefer : \"Je joue un client avec un usage précis. Ton objectif : restituer les 3 points clés de ce modèle en les connectant à mon usage. Je lève la main si tu récites la fiche sans faire le lien avec mon profil.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona avec un usage précis. Donner les infos de découverte progressivement. Attendre que le commercial fasse le lien entre le besoin exprimé et la caractéristique technique. Observer : 3 points clés, lien profil, gestion des angles morts."}, {"title": "Débriefer", "description": "\"Quels 3 points tu as choisi de mettre en avant — et pourquoi ces 3-là pour ce profil ? Est-ce que tu as fait le lien avec ce que je t'avais dit en découverte ? Tu as eu un angle mort — comment tu l'as géré ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain RDV : avant de présenter un modèle, note les 3 points clés que tu vas utiliser pour CE client. Pas la même liste pour tout le monde. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Question simple sur [MODÈLE_ENTRÉE_GAMME]", "objective": "Restituer les 3 points clés du modèle, faire le lien avec le profil client, positionner dans la gamme.", "duration": "20 min", "persona": [{"label": "Modèle concerné", "text": "[MODÈLE_ENTRÉE_GAMME]"}, {"label": "Profil client", "text": "[PROFIL_CLIENT_TYPE_1] — [USAGE_TYPE_1]"}, {"label": "Question posée", "text": "[QUESTION_TECHNIQUE_SIMPLE]"}, {"label": "Réponse idéale", "text": "[RÉPONSE_IDÉALE_SIMPLE]"}, {"label": "Angle mort possible", "text": "[CARACTÉRISTIQUE_TECHNIQUE_RARE_1]"}], "context": "RDV en cours. Le client a exprimé un usage précis : [USAGE_TYPE_1]. Il pose une question directe sur [MODÈLE_1].", "stakes": "L'enjeu : ne pas réciter la fiche technique mais sélectionner les 3 points qui répondent à cet usage précis et les restituer avec le lien découverte.", "observe": ["Sélectionne-t-il les bons points pour [PROFIL_CLIENT_TYPE_1] ?", "Fait-il le lien avec l'usage exprimé en découverte ?", "Positionne-t-il le modèle dans la gamme ?", "Gère-t-il l'angle mort sans perdre en crédibilité ?"]}, {"level": "intermediaire", "title": "Choix de motorisation sur [MODÈLE_MID_GAMME]", "objective": "Guider le client vers la bonne motorisation selon son usage, argumenter techniquement avec précision, éviter la sur-info.", "duration": "25 min", "persona": [{"label": "Modèle concerné", "text": "[MODÈLE_MID_GAMME]"}, {"label": "Profil client", "text": "[PROFIL_CLIENT_TYPE_2] — [USAGE_TYPE_2]"}, {"label": "Question posée", "text": "[QUESTION_MOTORISATION]"}, {"label": "Réponse idéale", "text": "[RÉPONSE_IDÉALE_MOTO]"}, {"label": "Piège", "text": "Le client mentionne [MOTO_ALTERNATIVE] — le commercial doit expliquer pourquoi elle ne correspond pas à son usage."}], "context": "RDV de mi-parcours. La découverte a révélé [USAGE_TYPE_2]. Le client hésite entre plusieurs motorisations sur [MODÈLE_2].", "stakes": "L'enjeu : utiliser les caractéristiques techniques comme arguments — pas comme catalogue. Guider vers [MOTO_RECOMMANDÉE] avec le raisonnement adapté au profil.", "observe": ["Recommande-t-il la bonne motorisation selon l'usage ?", "Son argument technique est-il ancré dans la découverte ?", "Évite-t-il de lister toutes les motorisations disponibles ?", "Traite-t-il l'alternative mentionnée par le client ?"]}, {"level": "avance", "title": "Question complexe sur [MODÈLE_HAUT_GAMME] — angle mort", "objective": "Gérer une question technique précise hors de sa zone de confort, maintenir la crédibilité, et donner une réponse partielle de qualité.", "duration": "25 min", "persona": [{"label": "Modèle concerné", "text": "[MODÈLE_HAUT_GAMME]"}, {"label": "Profil client", "text": "[PROFIL_EXPERT] — client technique qui sait ce qu'il cherche"}, {"label": "Question posée", "text": "[QUESTION_COMPLEXE]"}, {"label": "Réponse idéale", "text": "[RÉPONSE_IDÉALE_COMPLEXE]"}, {"label": "Angle mort", "text": "[DONNÉE_TECHNIQUE_PRÉCISE] — le commercial ne connaît pas exactement ce chiffre."}], "context": "RDV avec un client expert. Il pose une question technique très précise sur [MODÈLE_3] à laquelle le commercial ne peut répondre qu'approximativement.", "stakes": "L'enjeu : ne pas inventer, ne pas botter en touche, restituer ce qu'on sait avec précision et assumer clairement ce qu'on va vérifier.", "observe": ["Restitue-t-il ce qu'il sait avec précision ?", "Assume-t-il clairement son angle mort sans excuse ?", "Propose-t-il un délai de réponse concret ?", "Maintient-il la crédibilité face au profil expert ?"]}]}, "online": {"focus": "la restitution technique", "attentionPoints": ["Sélectionne-t-il les bons points pour CE profil (pas la fiche complète) ?", "Fait-il le lien entre la caractéristique et l'usage exprimé en découverte ?", "Positionne-t-il le modèle dans la gamme si nécessaire ?", "Gère-t-il ses angles morts sans inventer ni perdre en crédibilité ?"], "grid": ["Bons points sélectionnés", "Lien découverte fait", "Positionnement gamme", "Angles morts gérés"], "debrief": [], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "La carte de la gamme est connue — 3 points clés par modèle liés au profil client", "02  Offline", "3 situations pratiquées — restituer en liant à la découverte est un réflexe", "03  Online", "Le coach a observé et débriefé la restitution technique en situation réelle", "⚡ Version [DATE_MAJ] — [NOM_STRUCTURE] — À mettre à jour à chaque évolution de gamme"]}]}, "takeaways": null, "hasPlaceholders": true}$dojo$::jsonb, 'bibliotheque/11- Connaissance produit & gamme/dojo_template_gamme.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('bf4f6ba7-4c10-5e0c-b56e-d3900a783e24', '0ffdcfd2-23a8-5c71-9bda-8ddba1fc0f36');
insert into public.library_dojos (id, title, content, pptx_path) values ('79f9bdd7-2162-5c1a-b9dd-c782d434ff5b', 'Auto-fixation d''objectifs', $dojo${"version": 1, "tagline": "Se fixer ses propres objectifs de progression pour ne pas subir son activité", "objective": "Le commercial sort de l'entretien avec 1 objectif de comportement SMART, lié à un axe de progression identifié, avec une date de mesure et une date de revue.", "duration": "20-25 min", "theory": {"intro": null, "standardTitle": "Le standard : résultat vs comportement & méthode SMART", "standard": [{"label": null, "title": "Un commercial qui attend que son manager lui fixe tous ses objectifs subit son activité. Un commercial qui se fixe ses propres objectifs de progression la pilote. La différence ne tient pas au talent — elle tient à cette habitude.", "description": "OBJECTIF DE RÉSULTAT", "why": "\"Faire 8 ventes ce mois-ci\""}, {"label": null, "title": "\"Atteindre 15% de Fi\"", "description": "\"Améliorer mon taux de closing\"", "why": "⚠ Dépend de facteurs externes (flux entrants, comportement client). Non pilotable directement."}, {"label": null, "title": "OBJECTIF DE COMPORTEMENT", "description": "\"Teaser le financement sur 100% de mes RDV cette semaine\"", "why": "\"Poser la question RNV sur chaque RDV sans vente\""}, {"label": null, "title": "\"Confirmer J-1 sans exception\"", "description": "✅ 100% pilotable. Ne dépend que de soi. C'est sur ces objectifs que se construit la progression.", "why": "LA MÉTHODE SMART APPLIQUÉE À UN OBJECTIF COMPORTEMENT"}, {"label": null, "title": "S", "description": "Spécifique", "why": "Un geste précis — pas 'améliorer la découverte' mais 'poser les 5 questions de découverte sur chaque RDV'"}, {"label": null, "title": "M", "description": "Mesurable", "why": "Un indicateur concret — 0/1 par RDV, %, nombre"}, {"label": null, "title": "A", "description": "Atteignable", "why": "Un effort réel mais réaliste — pas ×2 sur une semaine"}, {"label": null, "title": "R", "description": "Relié", "why": "Lié à un axe de progression identifié en entretien"}, {"label": null, "title": "T", "description": "Temporel", "why": "Une date de revue précise — pas 'à terme'"}], "criteria": [{"title": "Il se fixe au moins 1 objectif de comportement par semaine", "description": "Pas un objectif de résultat — un objectif sur ce qu'il fait, pas sur ce qui arrive. \"Cette semaine, je teaser le Fi sur 100% de mes RDV\" est pilotable. \"Cette semaine, je fais 3 ventes\" ne l'est pas."}, {"title": "Son objectif est lié à un axe de progression identifié", "description": "L'objectif ne sort pas de nulle part. Il découle d'un constat : \"mon taux de RNV qualifiée est faible\" → objectif comportement : \"poser la question RNV sur chaque RDV sans vente cette semaine\". Le lien cause/objectif est explicite."}, {"title": "Il mesure son objectif chaque soir", "description": "Un objectif sans mesure quotidienne est un voeu. Cocher 0 ou 1 chaque soir sur son objectif comportement prend 30 secondes — et change la dynamique en transformant chaque RDV en occasion de réussir l'objectif."}, {"title": "Il fait une revue hebdomadaire avec son manager", "description": "L'objectif se construit seul mais se révise avec le manager. La revue hebdomadaire permet d'ajuster : trop facile → monter le niveau, trop difficile → identifier le frein. Sans revue, l'objectif dérive."}, {"title": "Il célèbre les petites victoires comportementales", "description": "Avoir posé la RNV sur 5 RDV sans vente consécutifs est une victoire — même si aucune de ces RNV n'a abouti à une vente. Reconnaître la progression comportementale indépendamment du résultat est la clé de la régularité."}], "mistakes": [], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer le commercial : \"Je vais jouer le manager en entretien de suivi. Ton objectif : arriver avec ta propre analyse de ton axe de progression et proposer un objectif de comportement SMART. Je lève la main si tu proposes un objectif de résultat.\""}, {"title": "Lancer le scénario", "description": "Jouer le manager. Poser les questions d'exploration : \"Sur quoi tu as progressé cette semaine ? Qu'est-ce qui te freine encore ? Sur quoi tu veux travailler ?\" Observer : le commercial identifie-t-il lui-même son axe, propose-t-il un objectif comportement ou résultat, l'objectif est-il SMART."}, {"title": "Débriefer", "description": "\"Ton objectif est un objectif de résultat ou de comportement ? Est-ce qu'il est lié à un frein que tu as toi-même identifié ? Comment tu vas le mesurer ? À quelle date on le revoit ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Cette semaine : applique ton objectif comportement. Mesure chaque soir. On en parle vendredi. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Le commercial sans objectif de progression personnel", "objective": "Aider le commercial à identifier lui-même son axe de progression et à formuler son premier objectif de comportement SMART.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Commercial, 8 mois en poste. Bons résultats par moments, mais n'a jamais formalisé d'objectif de progression."}, {"label": "Comportement", "text": "Attend les objectifs du manager. Ne s'est jamais demandé sur quoi progresser."}, {"label": "Axe de progression", "text": "Son taux de RNV qualifiée est très faible — il repart souvent de RDV sans RNV précise."}, {"label": "Objectif comportement", "text": "\"Poser la question RNV sur chaque RDV sans vente cette semaine\" — mesurable, pilotable."}, {"label": "Frein", "text": "Confond objectif de résultat et objectif de comportement. Propose naturellement \"faire X ventes\"."}], "context": "Entretien de suivi hebdomadaire. Le manager demande sur quoi le commercial veut travailler. Silence gêné.", "stakes": "L'enjeu : l'aider à identifier lui-même son axe (RNV) et à formuler un objectif comportement — pas lui donner la réponse.", "observe": ["L'aide-t-il à identifier l'axe sans lui donner la réponse ?", "Le commercial propose-t-il un objectif comportement (pas résultat) ?", "L'objectif est-il SMART — mesurable et temporel ?", "Le commercial sort-il avec un engagement clair ?"]}, {"level": "intermediaire", "title": "Le commercial aux objectifs vagues", "objective": "Transformer un objectif vague en objectif comportement SMART — mesurable, spécifique, avec une date.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 2 ans en poste. Se fixe des objectifs mais toujours vagues et non mesurables."}, {"label": "Comportement", "text": "Proactif mais flou. Dit \"je veux m'améliorer en découverte\" sans préciser quoi ni comment."}, {"label": "Objectif initial", "text": "\"Je veux mieux faire la découverte financement.\""}, {"label": "Objectif SMART cible", "text": "\"Je teaser le financement sur 100% de mes RDV cette semaine — je coche chaque soir.\""}, {"label": "Frein", "text": "Ne sait pas comment rendre son objectif mesurable. A besoin d'être guidé sur l'indicateur."}], "context": "Entretien de suivi. Il arrive avec un objectif — \"mieux faire la découverte Fi\" — mais impossible à mesurer ou à suivre.", "stakes": "L'enjeu : l'aider à passer de vague à SMART en posant les bonnes questions — pas en réécrivant l'objectif à sa place.", "observe": ["Pose-t-il les bonnes questions pour rendre l'objectif spécifique ?", "Guide-t-il vers un indicateur mesurable ?", "Le commercial reformule-t-il lui-même son objectif en SMART ?", "La date de revue est-elle fixée avant la fin de l'entretien ?"]}, {"level": "avance", "title": "Le commercial aux objectifs de résultat uniquement", "objective": "Faire comprendre la différence résultat/comportement, identifier pourquoi les objectifs de résultat seuls sont insuffisants, et construire l'objectif comportement complémentaire.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 4 ans en poste. Très orienté résultats. Se fixe des objectifs ambitieux mais tous de résultat."}, {"label": "Comportement", "text": "\"Je veux faire 10 ventes ce mois.\" Résiste à l'idée d'objectifs comportement — \"c'est des détails\"."}, {"label": "Situation", "text": "Mois difficile — 5 ventes en 3 semaines. Ne comprend pas pourquoi malgré ses efforts."}, {"label": "Objectif comportement manquant", "text": "Il ne mesure aucun geste. Ne sait pas à quelle étape du tunnel il perd ses dossiers."}, {"label": "Frein", "text": "Résistance culturelle aux objectifs comportement — les perçoit comme du micro-management."}], "context": "Entretien après un mois difficile. Il est frustré. A travaillé dur mais les résultats ne suivent pas.", "stakes": "L'enjeu : l'aider à voir que sans mesure comportementale, il ne peut pas identifier où ça coince — et qu'un objectif comportement n'est pas du contrôle mais un outil de pilotage pour lui.", "observe": ["Crée-t-il la prise de conscience résultat vs comportement ?", "Le commercial identifie-t-il lui-même l'étape où il perd des dossiers ?", "Propose-t-il un objectif comportement complémentaire — pas à la place de son objectif résultat ?", "Le commercial perçoit-il l'objectif comportement comme un outil pour lui — pas comme du contrôle ?"]}]}, "online": {"focus": null, "attentionPoints": [], "grid": [], "debrief": [], "sections": [{"title": "Template — Plan de progression personnel", "lines": ["À remplir par", "le commercial", "MES OBJECTIFS", "1", "Mon objectif de COMPORTEMENT", "Ex : Poser la question RNV sur chaque RDV sans vente cette semaine", "Spécifique • Mesurable • Pilotable à 100% par moi", "2", "Mon objectif de RÉSULTAT", "Ex : Atteindre 35% de taux de financement ce mois-ci", "Dépend aussi des clients — suivi en parallèle, pas à la place", "3", "Mon axe de progression identifié", "Ex : Ma RNV est trop vague — je repars souvent sans info actionnable", "1 axe par cycle — pas plusieurs en même temps", "MES JALONS", "Mesure quotidienne :", "Oui / Non chaque soir — 30 secondes", "Revue J+7 :", "[DATE] — bilan avec le manager", "Ajustement si besoin :", "Monter le niveau si trop facile / identifier le frein si difficile", "Prochain objectif :", "[DATE] — fixer le suivant en revue", "MA REVUE AVEC LE MANAGER", "Date de revue :", "[DATE]", "Résultat mesuré :", "X / Y jours réussis", "Ce qui a fonctionné :", "...", "Ce qu'on ajuste :", "..."]}, {"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "La distinction résultat / comportement est comprise — l'objectif SMART comportement est le seul pilotable", "02  Offline", "3 entretiens pratiqués — guider vers l'objectif comportement sans le donner est un réflexe", "03  Plan d'action", "Le commercial repart avec 1 objectif comportement SMART, une mesure quotidienne et une date de revue", "Règle d'or : 1 objectif comportement à la fois — mesuré chaque soir — revu chaque semaine"]}]}, "takeaways": null, "hasPlaceholders": true}$dojo$::jsonb, 'bibliotheque/12- Posture & attitude commerciale/a. Auto-fixation d''objectifs.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('79f9bdd7-2162-5c1a-b9dd-c782d434ff5b', 'e920543c-6c20-5036-82e4-f2735d2642e1');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('79f9bdd7-2162-5c1a-b9dd-c782d434ff5b', '9f1b588f-b0d2-5917-94ce-42ee794cc388');
insert into public.library_dojos (id, title, content, pptx_path) values ('1c44dc7f-c2f7-5ba0-8879-031ee0f18026', 'Résilience commerciale', $dojo${"version": 1, "tagline": "Gérer les refus et les creux sans décrocher — rebondir plus vite", "objective": "Le manager aide le commercial à analyser sans ruminer, maintenir ses rituels, et identifier une victoire comportementale. L'entretien ne doit pas renforcer la spirale négative.", "duration": "20-25 min", "theory": {"intro": "Le refus fait partie du métier — pas comme exception mais comme réalité structurelle. Un taux de conversion de 30% signifie que 70% des RDV ne donnent pas de vente. La résilience n'est pas l'absence d'impact émotionnel — c'est la vitesse à laquelle on rebondit.", "standardTitle": "Le standard : comprendre et gérer la courbe de résilience", "standard": [{"label": "1 — SÉPARER LE REFUS DE SOI", "title": "\"Il a dit non au véhicule — pas à moi.\" La première compétence de résilience est de ne pas personnaliser le refus. Un client qui ne signe pas n'est pas un jugement sur la valeur du commercial.", "description": "Réflexe : après chaque RDV sans vente, se poser la question \"qu'est-ce que j'aurais pu faire différemment ?\" — pas \"qu'est-ce qui ne va pas chez moi ?\"", "why": "2 — ANALYSER SANS RUMINER"}, {"label": "Regarder chaque RDV sans vente comme une source d'information. Qu'est-ce qui s'est passé ? À quelle étape ? Qu'est-ce qu'on ferait différemment ? Puis passer à autre chose.", "title": "Outil : la RNV bien qualifiée transforme un échec en donnée actionnable. \"Il avait un concurrent à 1 500€ moins cher\" est une info — pas un jugement.", "description": "3 — MAINTENIR LES RITUELS D'ÉNERGIE", "why": "Les périodes de creux fragilisent les rituels (préparation, confirmation J-1, suivi). C'est exactement quand ça va moins bien qu'il faut tenir ses gestes. Un commercial qui lâche ses rituels en creux s'enfonce."}, {"label": "Règle : en période de creux, réduire les objectifs de résultat mais tenir les objectifs comportement. Le geste juste en période difficile construit la sortie de creux.", "title": "4 — CRÉER SES VICTOIRES INTERMÉDIAIRES", "description": "Ne pas attendre la vente pour se féliciter. Un teasing Fi bien placé, une RNV précise, une relance personnalisée — ce sont des victoires comportementales indépendantes du résultat.", "why": "\"J'ai posé la question RNV sur les 4 RDV sans vente d'aujourd'hui.\" C'est une victoire réelle — même si aucune vente ce jour-là."}], "criteria": [{"title": "Il analyse — il ne rumine pas", "description": "Après un RDV sans vente : 5 minutes d'analyse factuelle (qu'est-ce qui s'est passé, à quelle étape), puis passage à autre chose. Ruminer une heure le soir sur un refus ne produit aucune information supplémentaire."}, {"title": "Il maintient ses rituels en période de creux", "description": "Préparation avant chaque RDV, confirmation J-1, suivi post-livraison — ces gestes ne se négocient pas en période difficile. C'est quand ça va moins bien que les rituels ont le plus de valeur."}, {"title": "Il communique à son manager avant d'aller trop loin", "description": "Signaler à son manager qu'on traverse une période difficile — avant que ça devienne visible dans les résultats. Un commercial qui alerte tôt reçoit un appui. Celui qui cache reçoit une réclamation."}, {"title": "Il crée ses victoires comportementales", "description": "Identifier chaque soir 1 geste réussi dans la journée — indépendamment du résultat. Cette pratique maintient le sentiment d'efficacité personnelle même quand les résultats tardent."}, {"title": "Il sait que le creux est temporaire", "description": "Tout commercial expérimenté a traversé des creux. La différence entre ceux qui s'en sortent et les autres : la conviction que le creux est une phase — pas un état permanent. Cette conviction se construit sur les expériences passées."}], "mistakes": [], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je vais jouer un commercial en difficulté. Ton objectif : l'aider à analyser sans ruminer, identifier 1 geste qu'il a bien fait malgré le creux, et fixer 1 action concrète. Je lève la main si tu te focalises uniquement sur les résultats.\""}, {"title": "Lancer le scénario", "description": "Jouer le commercial en difficulté selon le persona. Donner des signaux de découragement. Résister légèrement si les questions sont trop centrées sur les chiffres. Observer : le manager crée-t-il de l'espace pour l'analyse, identifie-t-il une victoire comportementale, fixe-t-il une action concrète."}, {"title": "Débriefer", "description": "\"Comment as-tu ouvert l'entretien — par les chiffres ou par l'état du commercial ? Tu as identifié 1 geste réussi malgré le creux ? L'action que tu lui as fixée — c'est un objectif résultat ou comportement ? Le commercial repart-il plus ou moins motivé qu'en entrant ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain commercial en creux : note les 3 choses — qu'est-ce qui s'est passé, quel geste il a réussi, quelle 1 action il repart avec. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "3 refus consécutifs — premier vrai creux", "objective": "Aider le commercial à analyser les 3 refus factuellement, identifier 1 geste réussi par RDV, et repartir avec 1 action comportementale.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Commercial, 6 mois en poste. 3 RDV sans vente cette semaine. Premier creux réel."}, {"label": "État émotionnel", "text": "Découragé mais pas effondré. Commence à douter de ses capacités."}, {"label": "Ce qui s'est passé", "text": "3 RNV différentes (budget, délai, comparaison) — pas le même problème à chaque fois."}, {"label": "Ce qu'il a bien fait", "text": "A bien qualifié les RNV sur les 3 RDV — information précise à chaque fois."}, {"label": "Action concrète", "text": "\"Cette semaine, je prépare 1 alternative avant chaque relance budget.\""}], "context": "Vendredi après-midi. Il entre dans le bureau avec l'air de quelqu'un qui a eu une mauvaise semaine.", "stakes": "L'enjeu : ne pas ouvrir par les chiffres, créer l'espace pour l'analyse factuelle, identifier que ses RNV étaient bien qualifiées (victoire comportementale), et fixer 1 action sur les relances.", "observe": ["Ouvre-t-il par l'état du commercial — pas par les chiffres ?", "Analyse-t-il les 3 RDV factuellement avec lui ?", "Identifie-t-il la victoire comportementale (RNV bien qualifiée) ?", "Le commercial repart-il avec 1 action concrète ?"]}, {"level": "intermediaire", "title": "Creux de 2 semaines — rituels qui lâchent", "objective": "Identifier que les rituels ont lâché pendant le creux, comprendre le lien creux → lâchage rituels → creux plus profond, et reconstruire les rituels.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 2 ans. 2 semaines difficiles. A commencé à bâcler les confirmations J-1."}, {"label": "État émotionnel", "text": "Fatigué, démotivé. Dit \"à quoi ça sert\" sur les rituels."}, {"label": "Ce qui s'est passé", "text": "A arrêté de confirmer J-1 et de préparer ses RDV — pensait que ça ne changerait rien."}, {"label": "Conséquence", "text": "2 lapins en 10 jours. Le creux s'est aggravé."}, {"label": "Action concrète", "text": "\"Cette semaine, je reprends les confirmations J-1 sans exception — même si j'en ai pas envie.\""}], "context": "Entretien de mi-semaine. Il est clairement dans une spirale. A eu 2 lapins dont il minimise l'impact.", "stakes": "L'enjeu : l'aider à voir le lien entre le lâchage des rituels et l'aggravation du creux — et lui faire reformuler lui-même pourquoi les rituels sont encore plus importants quand ça va moins bien.", "observe": ["Identifie-t-il le lien lâchage rituels → aggravation creux ?", "Le commercial reformule-t-il lui-même la règle des rituels en creux ?", "L'action fixée est-elle sur les rituels — pas sur les résultats ?", "Le ton est-il de soutien — pas de réclamation ?"]}, {"level": "avance", "title": "Commercial qui cache sa difficulté", "objective": "Créer l'espace pour que le commercial exprime sa difficulté, déconstruire le réflexe de cacher, et établir que alerter tôt est une force.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 5 ans. En difficulté depuis 3 semaines. N'a rien dit. Fait semblant que ça va."}, {"label": "État émotionnel", "text": "Sous pression. Fier. A du mal à admettre qu'il traverse quelque chose."}, {"label": "Ce qui se passe", "text": "A changé ses indicateurs dans le CRM pour masquer le creux. Travaille de plus en plus tard."}, {"label": "Ce dont il a besoin", "text": "Être vu sans jugement. Comprendre qu'alerter tôt est une marque de maturité professionnelle."}, {"label": "Frein", "text": "Peur du jugement. Confond vulnérabilité avec faiblesse."}], "context": "Entretien de revue mensuelle. Les chiffres montrent clairement un creux. Il minimise et change de sujet.", "stakes": "L'enjeu : créer un espace de confiance pour qu'il exprime ce qui se passe, sans le mettre en difficulté — et lui faire comprendre qu'alerter son manager tôt est une compétence, pas un aveu de faiblesse.", "observe": ["Crée-t-il l'espace de confiance avant d'aborder les chiffres ?", "Le commercial finit-il par exprimer ce qui se passe ?", "Le manager positionne-t-il l'alerte comme une force ?", "L'entretien se termine-t-il sur une action et un engagement mutuel ?"]}]}, "online": {"focus": null, "attentionPoints": [], "grid": [], "debrief": [], "sections": [{"title": "Template — Plan de progression personnel", "lines": ["À remplir par", "le commercial", "MES OBJECTIFS", "1", "Mon geste réussi aujourd'hui", "Ex : J'ai bien qualifié la RNV sur mes 3 RDV sans vente", "1 victoire comportementale par jour — indépendante du résultat", "2", "Mon rituel à tenir cette semaine", "Ex : Confirmation J-1 sur 100% de mes RDV — sans exception", "En creux, les rituels sont non-négociables", "3", "Mon action de rebond", "Ex : Préparer 1 alternative avant chaque relance budget cette semaine", "1 action concrète — pas \"faire des efforts\"", "MES JALONS", "Geste réussi J+1 :", "Note 1 victoire comportementale ce soir", "Rituel tenu J+7 :", "[DATE] — bilan des rituels tenus avec le manager", "Signe de rebond :", "1 RDV bien préparé, 1 relance personnalisée...", "Revue manager :", "[DATE] — point de soutien, pas de réclamation", "MA REVUE AVEC LE MANAGER", "Date de revue :", "[DATE]", "Rituels tenus :", "X / 5 jours", "Victoire identifiée :", "...", "Prochain cap :", "..."]}, {"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "La courbe de résilience est comprise — analyser sans ruminer, maintenir les rituels", "02  Offline", "3 entretiens en difficulté pratiqués — créer l'espace et identifier la victoire comportementale", "03  Plan d'action", "Le commercial repart avec 1 victoire identifiée, 1 rituel à tenir, 1 action de rebond", "Règle d'or : le creux est temporaire — les rituels tenus en creux construisent la sortie"]}]}, "takeaways": null, "hasPlaceholders": true}$dojo$::jsonb, 'bibliotheque/12- Posture & attitude commerciale/b. Résilience commerciale.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('1c44dc7f-c2f7-5ba0-8879-031ee0f18026', '77cd90e3-6c06-51f5-b9ca-5c5e288678d7');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('1c44dc7f-c2f7-5ba0-8879-031ee0f18026', '19d36587-6728-5027-b120-053bfd29ef58');
insert into public.library_dojos (id, title, content, pptx_path) values ('b30d1e8d-020b-5b2c-bd04-c99a34ec8d61', 'Relation manager', $dojo${"version": 1, "tagline": "Utiliser son manager comme ressource de progression — pas seulement comme contrôleur", "objective": "Le commercial arrive préparé, pose sa demande spécifique, accepte le feedback sans défense, et repart avec un engagement de suivi.", "duration": "20-25 min", "theory": {"intro": "La relation manager est l'une des ressources les plus sous-utilisées en commerce. La plupart des commerciaux attendent les entretiens imposés. Les meilleurs en font un levier de progression actif.", "standardTitle": "Le standard : 3 postures face au manager", "standard": [{"label": null, "title": "POSTURE SUBIE", "description": "Le commercial attend les entretiens imposés. Répond aux questions du manager. Ne prend aucune initiative sur sa progression.", "why": "Signal : \"Mon manager me convoque\" — pas \"j'ai demandé un point à mon manager.\""}, {"label": null, "title": "POSTURE TRANSACTIONNELLE", "description": "Le commercial utilise le manager pour résoudre des problèmes immédiats. Vient avec des questions mais pas d'analyse ni de proposition.", "why": "Signal : \"Mon manager m'aide quand j'en ai besoin\" — relation utilitaire, pas de progression active."}, {"label": null, "title": "POSTURE PROACTIVE", "description": "Le commercial prépare ses entretiens avec son analyse, ses axes de progression, et ses demandes spécifiques. Vient avec des questions préparées et des propositions.", "why": "Signal : \"J'ai demandé un point à mon manager parce que j'ai identifié quelque chose sur lequel je veux progresser.\""}], "criteria": [{"title": "Il prépare ses entretiens manager", "description": "Avant chaque point avec son manager : noter son bilan de la semaine, son axe de progression, sa demande spécifique. Un commercial qui arrive sans préparation n'utilise pas le temps de son manager efficacement — et ne tire pas le meilleur de l'entretien."}, {"title": "Il demande du feedback proactivement", "description": "\"Sur le RDV de ce matin — qu'est-ce que tu aurais fait différemment ?\" Le commercial qui demande du feedback avant qu'on le lui donne signale qu'il veut progresser. C'est cette posture qui accélère le développement."}, {"title": "Il alerte tôt — avant que ça devienne visible", "description": "Signaler un doute, une difficulté, une question avant que ça devienne un problème. \"Je suis pas à l'aise avec les objections Fi depuis 2 semaines — tu peux me faire un debrief là-dessus ?\" C'est une marque de maturité professionnelle."}, {"title": "Il accepte le feedback sans défense", "description": "Recevoir un feedback difficile sans se justifier immédiatement. Écouter, reformuler pour valider la compréhension, puis répondre. Le commercial qui se défend à chaque feedback n'en reçoit plus — le manager se lasse."}, {"title": "Il revient avec les résultats de l'action fixée", "description": "\"Tu m'avais dit de travailler la RNV — voilà ce que j'ai observé cette semaine.\" Le feedback boucle sur lui-même. Un commercial qui revient avec des résultats montre qu'il a intégré — et mérite le prochain investissement du manager."}], "mistakes": [], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je vais jouer le manager. Ton objectif : venir préparé avec ton bilan, ton axe de progression et ta demande spécifique. Je vais te donner un feedback difficile — ton job : l'accueillir sans te défendre.\""}, {"title": "Lancer le scénario", "description": "Jouer le manager. Donner un feedback difficile mais factuel à mi-entretien. Observer : le commercial avait-il préparé quelque chose, comment accueille-t-il le feedback difficile, reformule-t-il, propose-t-il lui-même une action de suivi."}, {"title": "Débriefer", "description": "\"Tu avais préparé ton bilan — qu'est-ce que tu avais noté ? Quand je t'ai donné le feedback difficile, quelle a été ta première réaction ? Tu as reformulé pour valider ta compréhension ? Tu as proposé une action de suivi ou attendu que je le fasse ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain entretien manager : prépare 3 choses — ton bilan, ton axe, ta demande. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Le commercial qui attend tout du manager", "objective": "Aider le commercial à prendre conscience de sa posture subie et à faire le premier pas vers une posture proactive.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Commercial, 10 mois en poste. Attend les entretiens imposés. N'a jamais demandé de feedback."}, {"label": "Comportement", "text": "Passif. Répond aux questions. N'a rien préparé pour l'entretien."}, {"label": "Axe de progression", "text": "Son taux de closing est faible — il ne comprend pas pourquoi."}, {"label": "Demande idéale", "text": "\"Est-ce que tu peux observer mon prochain RDV et me donner un feedback sur le closing ?\""}, {"label": "Frein", "text": "Ne sait pas qu'il peut faire une demande. Attend qu'on lui propose."}], "context": "Entretien hebdomadaire. Il entre sans rien avoir préparé. Le manager lui demande ce sur quoi il veut travailler. Silence.", "stakes": "L'enjeu : l'aider à identifier lui-même son axe et à formuler une vraie demande — pas une liste de plaintes.", "observe": ["Identifie-t-il lui-même son axe de progression ?", "Formule-t-il une demande spécifique et actionnable ?", "Prend-il conscience de sa posture passive ?", "Repart-il avec un engagement personnel — pas seulement une tâche donnée par le manager ?"]}, {"level": "intermediaire", "title": "Le commercial qui se défend face au feedback", "objective": "Accueillir un feedback difficile sans réaction défensive, reformuler pour valider, et proposer une action de suivi.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 3 ans. Compétent mais réactif. Se justifie systématiquement quand on pointe quelque chose."}, {"label": "Comportement", "text": "Dès qu'un feedback arrive : \"oui mais...\", \"c'est parce que le client...\", \"j'avais pas le choix\"."}, {"label": "Feedback difficile", "text": "\"Sur ton RDV de vendredi — tu as pas fait la découverte Fi avant de présenter l'offre.\""}, {"label": "Réaction idéale", "text": "\"Tu as raison — je comprends. Je vais travailler ça cette semaine. Tu peux m'observer là-dessus ?\""}, {"label": "Frein", "text": "Peur du jugement. Confond feedback avec attaque personnelle."}], "context": "Entretien de debrief post-observation. Le manager lui donne un feedback factuel sur un manque en découverte Fi.", "stakes": "L'enjeu : recevoir ce feedback sans \"oui mais\", reformuler pour montrer qu'il a compris, et proposer lui-même une action — pas attendre que le manager la fixe.", "observe": ["Accueille-t-il le feedback sans réaction défensive immédiate ?", "Reformule-t-il le feedback pour valider sa compréhension ?", "Propose-t-il lui-même une action de suivi ?", "Ne dit-il pas \"oui mais\" — même une fois ?"]}, {"level": "avance", "title": "Le commercial qui prépare son entretien et demande du feedback ciblé", "objective": "Simuler un entretien manager préparé avec bilan, axe de progression et demande spécifique — et revenir avec les résultats de l'action précédente.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 5 ans. A travaillé sa posture. Arrive avec un bilan structuré."}, {"label": "Préparation", "text": "A noté son bilan de la semaine, son axe, et une demande : \"Je veux qu'on regarde ensemble mes relances Fi — je sens que je rate des closings.\""}, {"label": "Résultat action précédente", "text": "\"Tu m'avais dit de travailler la RNV — voilà ce que j'ai noté sur mes 5 RDV sans vente.\""}, {"label": "Ce qu'il cherche", "text": "Un vrai échange sur ses relances Fi — pas un entretien descendant."}, {"label": "Frein résiduel", "text": "Tend encore à chercher validation plutôt que challenge. A besoin d'être challengé sur son analyse."}], "context": "Entretien hebdomadaire. Il entre avec une vraie préparation — bilan, axe, demande et résultats de la semaine précédente.", "stakes": "L'enjeu : simuler un entretien de haut niveau où les deux parties apportent quelque chose — et le challenger sur son analyse pour qu'il monte encore en niveau.", "observe": ["Arrive-t-il avec bilan + axe + demande préparés ?", "Revient-il avec les résultats de l'action précédente ?", "Accepte-t-il d'être challengé sur son propre diagnostic ?", "L'entretien est-il un échange — pas une consultation descendante ?"]}]}, "online": {"focus": null, "attentionPoints": [], "grid": [], "debrief": [], "sections": [{"title": "Template — Plan de progression personnel", "lines": ["À remplir par", "le commercial", "MES OBJECTIFS", "1", "Mon bilan de la semaine", "Ex : 5 RDV — 2 ventes — 3 RNV (1 budget, 1 délai, 1 comparaison)", "Factuel et concis — ce qui s'est passé, pas comment je me sens", "2", "Mon axe de progression", "Ex : Mes relances Fi — je sens que je rate des closings à ce stade", "1 axe identifié par moi — pas assigné par le manager", "3", "Ma demande spécifique", "Ex : Peux-tu observer mon prochain RDV sur le volet closing Fi ?", "Une demande actionnable — pas \"j'aimerais progresser\"", "MES JALONS", "Préparation entretien :", "Note bilan + axe + demande avant chaque point", "Prochain entretien :", "[DATE] — je reviens avec les résultats de cette action", "Feedback demandé :", "Sur [geste précis] — pas en général", "Action issue du feedback :", "[ACTION] à appliquer dès cette semaine", "MA REVUE AVEC LE MANAGER", "Date de revue :", "[DATE]", "Bilan préparé :", "Oui / Non", "Demande formulée :", "...", "Action de la semaine :", "..."]}, {"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Les 3 postures sont connues — la posture proactive se prépare et se demande", "02  Offline", "3 entretiens pratiqués — arriver préparé et accueillir le feedback sont des réflexes", "03  Plan d'action", "Le commercial repart avec bilan + axe + demande préparés pour son prochain entretien", "Règle d'or : préparer chaque entretien manager — bilan, axe, demande"]}]}, "takeaways": null, "hasPlaceholders": true}$dojo$::jsonb, 'bibliotheque/12- Posture & attitude commerciale/c. Relation manager.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('b30d1e8d-020b-5b2c-bd04-c99a34ec8d61', '7ad4ce0b-8a2b-525a-a48e-b06a094bf73c');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('b30d1e8d-020b-5b2c-bd04-c99a34ec8d61', '3a638dc1-a5ff-59f3-b2f6-43aba3a19fd2');
insert into public.library_dojos (id, title, content, pptx_path) values ('1bba9ad4-e158-5ac2-a56a-b2d9e8c8ff94', 'Posture proactive', $dojo${"version": 1, "tagline": "Créer ses opportunités sans attendre — ne pas subir son activité", "objective": "Le commercial identifie ses sources d'opportunités, construit une routine proactive hebdomadaire, et mesure ses actions — pas seulement ses résultats.", "duration": "20-25 min", "theory": {"intro": "La différence entre un commercial qui subit son activité et un commercial qui la pilote n'est pas le talent — c'est la proactivité. Attendre les entrants, c'est dépendre du flux. Créer des opportunités, c'est piloter son pipeline.", "standardTitle": "Le standard : les 4 sources d'opportunités proactives", "standard": [{"label": "ANCIENS CLIENTS", "title": "Le portefeuille existant est la source d'opportunités la plus sous-exploitée. Un client livré il y a 18 mois sans contact depuis est une opportunité perdue.", "description": "→ Action : identifier chaque semaine 3 anciens clients sans contact depuis 6+ mois. Prétexte : contrôle technique, mise à jour gamme, offre en vigueur.", "why": "RECOMMANDATIONS"}, {"label": "Un client satisfait parle de son expérience à 2-3 personnes en moyenne. Sans demande explicite, ces conversations ne génèrent pas de leads. Avec une demande bien formulée, elles en génèrent.", "title": "→ Action : demander systématiquement à J+30 — voir Dojo Recommandation. C'est la source de leads la plus qualifiée.", "description": "LEADS ENTRANTS NON EXPLOITÉS", "why": "Des leads arrivent chaque semaine via le site, les emails, les formulaires. Certains ne reçoivent pas de réponse dans les 4 heures — et contactent un concurrent."}, {"label": "→ Action : traiter tout lead entrant dans les 4 heures. Un lead non traité en 4h perd 80% de ses chances de conversion.", "title": "RÉSEAU & ENTOURAGE", "description": "Famille, amis, anciens collègues, fournisseurs — chaque commercial a un réseau de plusieurs centaines de personnes qui ne savent pas forcément ce qu'il fait.", "why": "→ Action : 1 message par semaine dans son réseau — pas commercial, mais utile (info sur la gamme, offre du moment). Maintenir la visibilité sans harceler."}], "criteria": [{"title": "Il a une action proactive tous les jours", "description": "Pas juste quand il a le temps. 15 minutes par jour dédiées à une action proactive — 1 appel ancien client, 1 demande recommandation, 1 lead entrant traité rapidement. La proactivité quotidienne est ce qui sépare un pipeline sain d'un pipeline qui s'assèche."}, {"title": "Il varie ses sources d'opportunités", "description": "Un commercial qui ne compte que sur les entrants concession est fragile à toute variation de flux. Anciens clients + recommandations + leads entrants + réseau = 4 sources indépendantes qui se compensent."}, {"title": "Il prospecte même en période chargée", "description": "C'est quand le pipeline est plein qu'il faut prospecter — pas quand il est vide. Un commercial qui prospecte uniquement en creux crée des cycles de pics et de creux. La prospection hebdomadaire régulière lisse l'activité."}, {"title": "Son approche est utile — pas commerciale", "description": "Un message à un ancien client qui dit \"nous avons un véhicule qui correspond à votre profil\" est commercial. Un message qui dit \"votre contrôle technique approche — vous voulez qu'on en discute ?\" est utile. L'approche utile génère 3× plus de réponses."}, {"title": "Il mesure ses actions proactives", "description": "Combien d'anciens clients contactés cette semaine ? Combien de demandes recommandation formulées ? Combien de leads entrants traités en moins de 4h ? Ce qui n'est pas mesuré n'est pas géré."}], "mistakes": [], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Donner au commercial un état de son pipeline (volume, sources, ancienneté). Briefer : \"Avec ce pipeline, je veux qu'on regarde ensemble d'où viennent tes opportunités et ce que tu fais proactivement pour en créer. Je lève la main si tu parles uniquement des entrants concession.\""}, {"title": "Lancer le scénario", "description": "Observer l'analyse du pipeline. Poser des questions : \"Sur tes 15 apps actives, combien viennent de ton initiative vs des entrants ? Quand as-tu contacté un ancien client pour la dernière fois ? Tu as combien de demandes recommandation faites ce mois ?\" Observer : conscience des sources, actions proactives identifiées."}, {"title": "Débriefer", "description": "\"Sur tes apps actives — quelle proportion vient de toi vs des entrants ? Tu as utilisé les 4 sources cette semaine ? Quelle est ton action proactive quotidienne — combien de temps ça prend ? Ce que tu as fait proactivement cette semaine — tu peux me le chiffrer ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Cette semaine : 1 action proactive par jour — anciens clients, recommandations, leads, réseau. Note-la chaque soir. Bilan vendredi. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Commercial 100% entrants — zéro action proactive", "objective": "Faire prendre conscience que l'activité repose uniquement sur les entrants, identifier 1 première source proactive, et construire 1 action quotidienne.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Commercial, 8 mois. Bon avec les clients qui viennent — ne crée aucune opportunité lui-même."}, {"label": "Pipeline", "text": "12 apps actives — 12 viennent des entrants concession. Zéro d'anciens clients, recommandations ou réseau."}, {"label": "Comportement", "text": "Ne voit pas le problème. \"Les clients arrivent, je fais mon travail.\""}, {"label": "Prise de conscience", "text": "Si le flux entrant baisse de 30% — son pipeline passe à 8. Il n'a aucun levier."}, {"label": "1ère action proactive", "text": "\"Cette semaine, je contacte 3 clients livrés il y a 6 mois sans contact depuis.\""}], "context": "Revue pipeline. Tout vient des entrants. Le flux a légèrement baissé cette semaine et il est inquiet.", "stakes": "L'enjeu : lui faire voir qu'il n'a aucun levier sur son pipeline — et l'aider à construire sa première action proactive simple.", "observe": ["Prend-il conscience de sa dépendance aux entrants ?", "Identifie-t-il lui-même une première source proactive ?", "Son action est-elle concrète et mesurable ?", "Comprend-il pourquoi prospecter maintenant — pas quand c'est vide ?"]}, {"level": "intermediaire", "title": "Commercial qui prospecte en creux seulement", "objective": "Comprendre pourquoi prospecter uniquement en creux crée des cycles, et construire une routine proactive hebdomadaire régulière.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 3 ans. Prospecte activement quand le pipeline est vide — jamais quand il est plein."}, {"label": "Pattern observé", "text": "Alternance : pipeline vide → prospection intensive → pipeline plein → arrêt → pipeline vide..."}, {"label": "Comportement", "text": "\"Quand j'ai des RDV, j'ai pas le temps de prospecter.\""}, {"label": "Prise de conscience", "text": "La prospection en creux est réactive et moins efficace que la prospection régulière."}, {"label": "Objectif", "text": "\"15 minutes de prospection chaque matin — même en semaine chargée.\""}], "context": "Revue pipeline. Il vient de sortir d'un creux en prospectant intensément. Le pipeline se remplit.", "stakes": "L'enjeu : lui faire voir le pattern cycle, et l'aider à construire une routine quotidienne de 15 minutes — même en période chargée.", "observe": ["Identifie-t-il lui-même le pattern creux/prospection réactive ?", "Comprend-il pourquoi prospecter en période chargée est contre-intuitif mais essentiel ?", "Son engagement est-il sur une routine quotidienne fixe ?", "La durée est-elle réaliste — 15 min, pas 1 heure ?"]}, {"level": "avance", "title": "Commercial proactif — optimiser ses sources", "objective": "Analyser la performance de chaque source proactive, identifier laquelle est sous-exploitée, et optimiser l'allocation de temps entre les 4 sources.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Commercial, 5 ans. Proactif sur 2 sources (entrants + relances) — n'utilise pas les recommandations."}, {"label": "Analyse sources", "text": "Entrants : 8 apps. Relances : 4 apps. Recommandations : 0. Réseau : 0."}, {"label": "Taux de conversion", "text": "Recommandations historiques : 60% de conversion vs 25% entrants. Potentiel énorme non utilisé."}, {"label": "Frein", "text": "\"Je sais pas trop comment demander des recommandations sans être gênant.\""}, {"label": "Action", "text": "Voir Dojo Recommandation — appliquer la formule indirecte sur ses 3 prochains clients satisfaits."}], "context": "Revue pipeline avancée. Il a un bon pipeline mais ne demande jamais de recommandations.", "stakes": "L'enjeu : lui faire voir le potentiel de conversion des recommandations vs les autres sources, et l'aider à franchir le pas sur cette source.", "observe": ["Analyse-t-il la performance comparée de ses sources ?", "Identifie-t-il lui-même la recommandation comme source sous-exploitée ?", "Son plan est-il concret — formule, timing, nombre cible ?", "Comprend-il pourquoi la recommandation est la source la plus efficace ?"]}]}, "online": {"focus": null, "attentionPoints": [], "grid": [], "debrief": [], "sections": [{"title": "Template — Plan de progression personnel", "lines": ["À remplir par", "le commercial", "MES OBJECTIFS", "1", "Mon action proactive quotidienne", "Ex : 15 min chaque matin — 1 ancien client ou 1 recommandation ou 1 lead entrant", "Quotidien et mesurable — même en semaine chargée", "2", "Ma source à développer cette semaine", "Ex : Recommandations — je n'en demande jamais. Objectif : 3 demandes cette semaine.", "1 source ciblée par cycle — pas les 4 en même temps", "3", "Mon indicateur de proactivité", "Ex : Actions proactives faites / 5 jours ouvrés cette semaine", "Mesurer l'action — pas le résultat (qui dépend des clients)", "MES JALONS", "Action quotidienne J+1 :", "Notée ce soir — oui / non", "Revue J+7 :", "[DATE] — X actions proactives sur 5 jours", "Premier résultat :", "1 lead généré proactivement cette semaine", "Ajustement :", "Quelle source développer la semaine suivante ?", "MA REVUE AVEC LE MANAGER", "Date de revue :", "[DATE]", "Actions proactives :", "X / 5 jours", "Sources utilisées :", "Anciens clients / Recommandations / Leads / Réseau", "Lead généré :", "Oui / Non — source : ..."]}, {"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Les 4 sources sont connues — 1 action proactive quotidienne est non-négociable", "02  Offline", "3 profils pratiqués — prospecter en période chargée est un réflexe, pas une exception", "03  Plan d'action", "Le commercial repart avec 1 action quotidienne mesurable et 1 source à développer", "Règle d'or : prospecter quand le pipeline est plein — pas quand il est vide"]}]}, "takeaways": null, "hasPlaceholders": true}$dojo$::jsonb, 'bibliotheque/12- Posture & attitude commerciale/d. Posture proactive.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('1bba9ad4-e158-5ac2-a56a-b2d9e8c8ff94', 'a22e93ca-bd06-526a-8376-4728080e09e8');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('1bba9ad4-e158-5ac2-a56a-b2d9e8c8ff94', '250eb186-8686-5594-8c28-570d8f5b4256');
insert into public.library_dojos (id, title, content, pptx_path) values ('b40c1e9f-b72a-501b-b660-7a09ec362b18', 'Découvrir les besoins d''un prospect', $dojo${"version": 1, "tagline": "Introduction à la découverte complète, en 3 phases", "objective": null, "duration": null, "theory": {"intro": "La découverte est une étape clé de l'entretien de vente pour mieux comprendre qui est le client et quels sont ses besoins. L'objectif : créer un lien fort, trouver LA bonne voiture, valoriser les avantages de son offre par rapport aux besoins du client.", "standardTitle": "Le standard : les 3 étapes de la découverte", "standard": [{"label": "1", "title": "Découverte du véhicule actuel / anciens véhicules", "description": "S'intéresser au véhicule du client et ses habitudes de consommation", "why": "Connaître la raison du changement"}, {"label": "S'intéresser au client, à qui il est", "title": "2", "description": "Découverte du véhicule recherché", "why": "Comprendre le contexte d'utilisation (trajet, kilométrage...)"}, {"label": "Savoir ce que recherche le client (catégorie, marque, motorisation, équipements...)", "title": "3", "description": "Découverte du financement et assurances", "why": "Comment le client a prévu de financer son véhicule"}], "criteria": [{"title": "Étape 1 — Véhicule actuel", "description": "Se servir du contexte d'utilisation pour apprendre plus sur le client (travail, lieux de vacances...) — créer du lien"}, {"title": "Savoir comment il a financé son précédent véhicule et comment il l'a acheté — orienter son offre", "description": "Étape 2 — Véhicule recherché"}, {"title": "S'assurer que les caractéristiques recherchées soient cohérentes pour légitimer le conseil", "description": "Utiliser le cadre d'utilisation pour valider les besoins réels vs les envies exprimées"}, {"title": "Étape 3 — Financement & assurances", "description": "Comprendre ce que le client entend par \"paiement comptant\" — banque ? épargne ?"}, {"title": "Comprendre comment son budget est construit : reprise, apport, soulte...", "description": "Ne pas argumenter le financement dès la découverte"}], "mistakes": [{"title": "Erreur 1 — Passer directement au véhicule recherché", "description": "Sauter la découverte du véhicule actuel, c'est rater l'opportunité de créer un vrai lien avec le client et de comprendre ses habitudes. On se prive d'informations précieuses pour légitimer son conseil."}, {"title": "Erreur 2 — Parler financement trop tôt", "description": "Argumenter le crédit ou les mensualités dès la découverte crée de la méfiance. Le client a besoin de sentir qu'on comprend d'abord son projet avant de lui parler d'argent."}, {"title": "Erreur 3 — Poser des questions fermées en rafale", "description": "\"Vous voulez du diesel ? Automatique ? Moins de 300 km/semaine ?\" transforme la découverte en interrogatoire. L'effet interrogatoire coupe le lien — il faut créer une conversation, pas un formulaire."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario adapté au niveau du commercial. Prévoir 20-30 min. Briefer le commercial : \"On va travailler la phase de découverte. Je vais jouer le client, tu t'occupes de la découverte complète.\""}, {"title": "Lancer le scénario", "description": "Jouer le client naturellement — ne pas aider, laisser les silences. Observer sans interrompre. Aller jusqu'au bout du scénario même si le commercial fait des erreurs."}, {"title": "Débriefer", "description": "Commencer par l'auto-évaluation. Valoriser ce qui a bien fonctionné. Identifier UN seul axe de travail prioritaire. Relier à un critère d'excellence précis."}, {"title": "Fixer la prochaine étape", "description": "Formuler un engagement concret : \"La prochaine fois que tu as un client, tu t'engages à explorer les 3 étapes. On en reparle vendredi.\" Planifier le passage en Online."}], "scenarios": [{"level": "Scénarios — À piocher selon le profil", "title": "Choisir 1 scénario / séance", "objective": null, "duration": null, "persona": [], "context": null, "stakes": null, "observe": []}]}, "online": {"focus": "le geste de découverte", "attentionPoints": ["Le commercial explore-t-il les 3 étapes dans l'ordre ?", "Crée-t-il un vrai lien ou enchaîne-t-il les questions ?", "Utilise-t-il le contexte d'utilisation pour valider les besoins ?", "Aborde-t-il le financement sans l'argumenter prématurément ?"], "grid": ["Explore le véhicule actuel", "Crée le lien / conversation", "Découvre le contexte d'utilisation", "Aborde le financement sans argumenter"], "debrief": [{"title": "Auto-évaluation du commercial", "prompt": "\"Comment tu te sens sur ce rendez-vous ? Est-ce que tu as pu explorer les 3 étapes de la découverte ? Qu'est-ce qui t'a semblé naturel ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que tu as [point positif concret sur la découverte]. C'est exactement le geste attendu — tu as créé de la confiance.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point à travailler : [ex: mieux explorer le financement avant de proposer]. La prochaine fois, essaie de poser cette question : [question concrète].\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Dès ton prochain client, tu t'engages sur quoi précisément ? On se redonne rdv le [date] pour faire un point sur ta prochaine découverte.\""}], "sections": []}, "takeaways": {"theory": "La découverte en 3 étapes est connue — chacun sait ce qu'est le geste idéal", "offline": "Le geste a été travaillé en sécurité — l'erreur est permise et apprenante", "online": "Le coach a observé la découverte en situation réelle et a débriefé avec précision", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/2- Découverte complète/a. Introduction — Découverte client.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('b40c1e9f-b72a-501b-b660-7a09ec362b18', '9dcb87d0-6629-51d6-b854-b903a05a5c86');
insert into public.library_dojos (id, title, content, pptx_path) values ('8f5223f5-8d8d-5996-905a-e2714b3840f8', 'Découverte des habitudes & motivations', $dojo${"version": 1, "tagline": "Explorer le véhicule actuel pour comprendre qui est vraiment le client", "objective": "Le commercial explore les 4 axes naturellement en conversation, rebondit sur chaque réponse, identifie les frustrations du véhicule actuel, et utilise les informations collectées pour orienter sa sélection.", "duration": "25-30 min", "theory": {"intro": null, "standardTitle": "Le standard : les 4 axes d'exploration", "standard": [{"label": "Découvrir les habitudes et motivations d'achat, c'est comprendre le client derrière le projet. Le véhicule actuel est une mine d'or : il révèle les usages réels, les satisfactions, les frustrations, et les leviers d'orientation de l'offre.", "title": "LE VÉHICULE", "description": "Explorer le véhicule actuel", "why": "\"C'est quoi votre voiture en ce moment ? Vous l'avez depuis combien de temps ? Vous en êtes content ?\""}, {"label": "Marque, modèle, ancienneté, kilométrage, financement à l'époque. Ce n'est pas de la curiosité — c'est de l'orientation d'offre.", "title": "Le véhicule actuel révèle le niveau de gamme accepté, le cycle d'achat, et les attentes implicites. Un client qui a toujours eu du diesel va devoir être accompagné sur l'hybride.", "description": "LES USAGES", "why": "Comprendre les habitudes de conduite"}, {"label": "\"Vous faites combien de km par an à peu près ? C'est plutôt ville ou autoroute ? Vous êtes souvent seul ou avec des passagers ?\"", "title": "Kilométrage annuel, type de routes (ville / périphérique / autoroute), fréquence, passagers réguliers, charges transportées.", "description": "Les usages déterminent la motorisation adaptée, le gabarit nécessaire et les équipements pertinents. Sans ça, le conseil est une supposition.", "why": "LA RAISON"}, {"label": "Identifier la raison du changement", "title": "\"Qu'est-ce qui vous amène à changer de véhicule aujourd'hui ? Il se passe quelque chose en particulier ?\"", "description": "Pourquoi maintenant ? Fin de crédit, panne, changement de situation familiale ou professionnelle, envie pure. La raison oriente l'urgence et la priorité.", "why": "Un client qui change pour une fin de crédit dans 3 mois n'a pas les mêmes leviers qu'un client qui veut juste \"quelque chose de plus récent\". La raison crée l'urgence ou l'absence d'urgence."}, {"label": "LE CLIENT", "title": "S'intéresser à qui il est", "description": "\"Vous travaillez dans le coin ? / Vous avez des enfants ?\" — rebondir sur ce qu'il dit naturellement, pas un formulaire.", "why": "Situation familiale, activité professionnelle, centres d'intérêt mentionnés naturellement. Ce sont les ancres pour créer le lien et personnaliser les bénéfices."}, {"label": "Le client qui sent qu'on s'intéresse à lui — pas à son projet — s'ouvre davantage, donne plus d'informations, et fait confiance plus vite.", "title": "AXE + QUESTIONS TYPES", "description": "CE QU'ON CHERCHE", "why": "POURQUOI C'EST CLÉ"}], "criteria": [{"title": "Il rebondit sur chaque réponse avant de passer à la suivante", "description": "\"Ah vous avez une Clio depuis 8 ans — et vous en êtes content ?\" Ce rebond signale une vraie écoute. Le client qui sent qu'on s'intéresse à sa réponse donne beaucoup plus d'informations au suivant."}, {"title": "Il explore la satisfaction ET la frustration du véhicule actuel", "description": "\"Qu'est-ce qui vous plaisait là-dedans ? Et qu'est-ce qui vous manquait ?\" Les frustrations sont les leviers d'argumentation les plus puissants — ce sont les bénéfices qu'on va vendre."}, {"title": "Il utilise les informations dans la suite de l'entretien", "description": "Un commercial qui découvre que le client fait 40 000 km/an et ne le mentionne jamais ensuite a raté sa découverte. Chaque info collectée doit réapparaître dans la sélection du véhicule ou l'argumentation."}, {"title": "Il crée une conversation — pas un questionnaire", "description": "Les 4 axes ne s'explorent pas dans l'ordre avec une liste. La découverte suit le fil de la conversation, rebondit sur ce que le client dit spontanément, et s'adapte à ce qu'il révèle."}, {"title": "Il s'arrête quand il a assez — pas avant", "description": "Une découverte trop courte laisse des angles morts. Une découverte trop longue lasse. Le signal d'arrêt : quand on peut formuler une recommandation personnalisée avec les informations qu'on a."}], "mistakes": [{"title": "Erreur 1 — Sauter directement au véhicule recherché", "description": "\"Vous cherchez quoi comme voiture ?\" en première question. On court-circuite toute la richesse du véhicule actuel. Le client donne une réponse souvent incomplète ou influencée par ce qu'il croit vouloir — pas par ce dont il a besoin."}, {"title": "Erreur 2 — Poser les questions sans écouter vraiment les réponses", "description": "Enchaîner les questions sans rebondir sur les réponses transforme la découverte en formulaire. Le client donne des réponses courtes, retient l'information, et perd confiance dans le commercial qui ne semble pas s'intéresser à ce qu'il dit."}, {"title": "Erreur 3 — Ne pas exploiter les informations collectées", "description": "Découvrir que le client a deux enfants, fait beaucoup d'autoroute et cherche l'économie — puis lui proposer un coupé sportif essence. La découverte n'a servi à rien. L'information collectée sans utilisation détruit la crédibilité du conseil."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Préparer la fiche persona. Briefer le commercial : \"Je vais jouer un client qui vient pour changer de voiture. Tu fais la découverte des habitudes et motivations — pas la découverte du véhicule recherché. Je t'arrête quand tu glisses vers le projet.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona : répondre aux questions, donner les infos quand elles sont demandées, ne pas les donner spontanément. Si le commercial part trop vite sur le véhicule recherché, répondre \"oui mais d'abord vous avez quoi comme voiture ?\""}, {"title": "Débriefer", "description": "\"Combien d'axes as-tu exploré sur les 4 ? Est-ce que tu as demandé ce qui lui plaisait ET ce qui lui manquait dans son véhicule actuel ? Est-ce que tu as rebondi sur ses réponses ou tu as enchaîné les questions ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client, note les frustrations qu'il exprime sur son véhicule actuel. Ce sont tes arguments de vente pour la suite. Reviens me voir avec 2 frustrations que tu as collectées et comment tu les as utilisées.\""}], "scenarios": [{"level": "debutant", "title": "Le client bavard qui donne tout spontanément", "objective": "Explorer les 4 axes dans l'ordre, rebondir sur chaque réponse, identifier au moins 2 frustrations sur le véhicule actuel, et résumer les infos collectées avant de passer à la suite.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 42 ans, aide-soignante, bavarde et sympathique. Conduit une Renault Scénic 2016 depuis 7 ans."}, {"label": "Comportement", "text": "Parle facilement, donne des informations sans qu'on les lui demande. Sourit beaucoup. A tendance à digresser sur sa vie personnelle."}, {"label": "Non-verbal", "text": "Posture ouverte, gestuelle expressive. Contact visuel naturel. Se détend rapidement."}, {"label": "Motivation réelle", "text": "Changer parce que son Scénic commence à coûter cher en entretien. Elle a des enfants ados qui prennent de la place."}, {"label": "Frein / tension", "text": "Budget tendu — elle le dit dès le départ mais ne veut pas s'en tenir là."}], "context": "Mardi 10h. Elle arrive seule, sans rendez-vous. Voiture actuelle : Scénic diesel 145 000 km, entretien de 800€ il y a 3 mois, climatisation en panne depuis cet été.", "stakes": "Contexte idéal pour pratiquer les rebonds et la collection des frustrations. Le commercial ne doit pas se laisser emporter par le bavardage — il doit structurer mentalement les 4 axes même si la conversation n'est pas linéaire.", "observe": ["Explore-t-il les 4 axes même si la conversation n'est pas linéaire ?", "Rebondit-il sur chaque réponse avant de passer à la question suivante ?", "Identifie-t-il les frustrations (entretien coûteux, clim en panne) ?", "Résume-t-il les infos collectées avant de passer à la suite ?"]}, {"level": "intermediaire", "title": "Le client réservé qui répond par monosyllabes", "objective": "Ouvrir la conversation par des questions ouvertes, relancer sans brusquer, et obtenir assez d'informations sur les 4 axes malgré un client peu loquace.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 55 ans, technicien de maintenance, taiseux et méfiant. Conduit un Peugeot 308 depuis 5 ans. Vient seul."}, {"label": "Comportement", "text": "Répond aux questions par des phrases courtes. \"Oui.\" \"Non.\" \"C'est correct.\" Ne relance pas spontanément. Regarde autour de lui quand la question est trop personnelle."}, {"label": "Non-verbal", "text": "Bras croisés en début d'entretien. Contact visuel rare. Se détend progressivement si le commercial ne le presse pas."}, {"label": "Motivation réelle", "text": "Son 308 a 130 000 km, il veut anticiper avant une grosse panne. Pas d'urgence affichée mais une vraie inquiétude latente."}, {"label": "Frein / tension", "text": "Méfiance vis-à-vis du commercial. Ne veut pas donner d'informations qui pourraient être \"utilisées contre lui\" dans la négociation."}], "context": "Jeudi 14h. Il entre sans rendez-vous. A l'air de vouloir \"juste regarder\" mais a clairement un projet. Premier échange très court.", "stakes": "Le commercial doit utiliser des questions ouvertes courtes, laisser des silences, ne pas combler le vide avec sa propre voix. Les informations viendront progressivement si le commercial ne force pas.", "observe": ["Utilise-t-il des questions ouvertes courtes pour ouvrir le client ?", "Laisse-t-il des silences sans les combler immédiatement ?", "Obtient-il les 4 axes malgré la résistance — sans forcer ?", "Détecte-t-il l'inquiétude latente sur la panne à venir ?"]}, {"level": "avance", "title": "Le client qui ment sur son véhicule actuel", "objective": "Détecter les incohérences entre les déclarations et les indices comportementaux, approfondir discrètement sans confronter, et obtenir une image fiable des habitudes réelles.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 39 ans, commercial terrain, vêtements soignés. Dit avoir une Audi A4 récente. En réalité : une vieille Golf très usée qu'il gare loin de la concession par honte."}, {"label": "Comportement", "text": "Sur-joue le profil de client aisé. Parle de sa voiture avec vagueness (\"c'est récent, c'est bien\"). Dévie les questions précises sur le kilométrage ou l'année. Change de sujet quand on creuse."}, {"label": "Non-verbal", "text": "Micro-tensions quand on parle du véhicule actuel. Regard qui fuit légèrement sur les questions précises. Sujet clos non-verbalement."}, {"label": "Motivation réelle", "text": "Vouloir un véhicule plus récent pour son image professionnelle. Budget réel beaucoup plus bas que ce qu'il affiche."}, {"label": "Frein / tension", "text": "L'ego et la honte. Il ne veut pas admettre sa situation réelle de peur d'être jugé ou d'être orienté vers une gamme basse."}], "context": "Samedi 11h. Il entre avec assurance, belle montre, bien habillé. Dit immédiatement \"je cherche quelque chose dans la gamme premium\".", "stakes": "Le commercial doit creuser discrètement les incohérences sans confronter. Des questions indirectes sur l'usage, le financement de l'époque, le kilométrage annual permettent de reconstituer la réalité sans brusquer l'ego.", "observe": ["Détecte-t-il les incohérences dans le discours du client ?", "Creuse-t-il discrètement sans confronter ni embarrasser ?", "Oriente-t-il ses questions pour reconstituer la situation réelle ?", "Adapte-t-il son conseil à la réalité sans la nommer frontalement ?"]}]}, "online": {"focus": "la découverte des habitudes", "attentionPoints": ["Explore-t-il le véhicule actuel avant d'aller sur le projet ?", "Rebondit-il sur les réponses ou enchaîne-t-il les questions ?", "Identifie-t-il les frustrations sur le véhicule actuel ?", "Utilise-t-il les infos collectées dans sa sélection ensuite ?"], "grid": ["Véhicule actuel exploré", "Rebonds sur les réponses", "Frustrations identifiées", "Infos utilisées ensuite"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Combien d'axes as-tu exploré ? Est-ce que tu as demandé ce qui lui plaisait ET ce qui lui manquait dans son véhicule actuel ? Est-ce que tu as rebondi sur ses réponses ou tu as enchaîné les questions ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand le client a dit [réponse précise], tu as rebondi avec [question de relance]. C'est exactement ça — tu as creusé au bon endroit et ça t'a donné [information précieuse].\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu n'as pas demandé ce qui lui manquait dans son véhicule actuel]. Ces frustrations sont tes meilleurs arguments de vente. La prochaine fois, pose toujours cette question : 'Et qu'est-ce qui vous manquait ?'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client : note les 2 principales frustrations sur le véhicule actuel. Reviens me voir avec ces 2 frustrations et comment tu les as utilisées dans ta sélection ou ton argumentation.\""}], "sections": []}, "takeaways": {"theory": "Les 4 axes sont connus — véhicule actuel, usages, raison du changement, qui est le client", "offline": "Le geste a été pratiqué sur 3 profils différents — les rebonds et la collecte des frustrations sont des réflexes", "online": "Le coach a observé et débriefé la qualité de la découverte en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/2- Découverte complète/b. Découverte des habitudes.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('8f5223f5-8d8d-5996-905a-e2714b3840f8', '9dcb87d0-6629-51d6-b854-b903a05a5c86');
insert into public.library_dojos (id, title, content, pptx_path) values ('0f168237-badf-5b2d-98b8-4d9250027227', 'Découverte du véhicule recherché', $dojo${"version": 1, "tagline": "Comprendre le contexte d'usage pour valider les besoins réels", "objective": "Le commercial explore les 5 dimensions, challenge les incohérences entre la demande exprimée et le contexte d'usage, hiérarchise les besoins avec le client, et reformule avant de passer à la sélection.", "duration": "25-30 min", "theory": {"intro": "Ce que le client dit vouloir et ce dont il a besoin sont souvent deux choses différentes. La découverte du véhicule recherché sert à valider, challenger ou corriger la demande exprimée — grâce au contexte d'usage réel.", "standardTitle": "Le standard : les 5 dimensions à explorer", "standard": [{"label": "CONTEXTE", "title": "Le cadre d'utilisation", "description": "\"C'est pour quel usage principal ? Ville, autoroute, mixte ?\"", "why": "Détermine la motorisation et le gabarit. Un client qui fait 80% d'autoroute et demande un citadin a un problème de cohérence à corriger."}, {"label": "KILOMÉTRAGE", "title": "Le volume d'usage", "description": "\"Vous faites combien de km par an environ ?\"", "why": "Kilométrage élevé = motorisation économique prioritaire. Faible kilométrage = l'agrément prend le dessus sur la consommation."}, {"label": "CATÉGORIE", "title": "Le type & la taille de véhicule", "description": "\"Vous pensez à quel type de véhicule ? Vous avez besoin de beaucoup de place ?\"", "why": "Vérifier la cohérence entre le gabarit demandé et les usages déclarés. Un SUV 7 places pour une personne seule mérite d'être questionné."}, {"label": "ÉQUIPEMENTS", "title": "Les caractéristiques souhaitées", "description": "\"Il y a des équipements qui sont vraiment importants pour vous ? Des choses sans lesquelles vous ne pouvez pas ?\"", "why": "Distinguer les must-have des nice-to-have. Les équipements non-négociables cadrent la sélection — les autres sont des arguments CAB."}, {"label": "MOTORISATION", "title": "Les préférences énergétiques", "description": "\"Vous avez une préférence sur le type d'énergie — essence, diesel, hybride, électrique ?\"", "why": "Ne pas supposer. Un client qui a toujours eu du diesel peut être prêt à passer à l'hybride si on lui explique le bénéfice en termes de coût."}], "criteria": [{"title": "Il challenge le demande exprimée si elle est incohérente", "description": "\"Vous m'avez dit que vous faites 45 000 km/an sur autoroute — une citadine c'est peut-être un peu petit pour vous, non ?\" Le commercial qui valide sans questionner ne conseille pas, il exécute."}, {"title": "Il hiérarchise les besoins avec le client", "description": "\"Sur ces 5 critères que vous m'avez donnés, si vous deviez en garder 3 absolument, ce serait lesquels ?\" Cette question révèle les vrais non-négociables et ouvre une marge de manœuvre sur les autres."}, {"title": "Il utilise le contexte d'usage pour valider chaque caractéristique", "description": "Chaque caractéristique demandée est remise en face du contexte : \"Vous m'avez dit que vous transportez souvent des matériaux — le coffre de 350L que vous demandez, ça va suffire ?\""}, {"title": "Il explore sans suggérer la réponse", "description": "\"Vous préférez plutôt diesel ou essence ?\" laisse le client choisir. \"Vous êtes plutôt diesel comme tout le monde ?\" oriente la réponse. La question ouverte neutre donne une réponse vraie."}, {"title": "Il sait quand s'arrêter et reformuler", "description": "Quand il a les 5 dimensions, il reformule : \"Si j'ai bien compris, vous cherchez [résumé concis].\" Le client confirme ou corrige — et le commercial sait qu'il peut passer à la sélection."}], "mistakes": [{"title": "Erreur 1 — Prendre la demande exprimée pour argent comptant", "description": "\"Je veux un SUV 7 places.\" — \"Très bien, suivez-moi.\" Sans explorer l'usage, on risque de proposer un véhicule inadapté. La demande exprimée est un point de départ, pas un cahier des charges."}, {"title": "Erreur 2 — Poser toutes les questions sans utiliser les réponses", "description": "Collecter 5 dimensions sans jamais y revenir dans la sélection ou l'argumentation. Le client sent que les questions étaient une formalité. La découverte n'a de valeur que si elle influence la suite."}, {"title": "Erreur 3 — Ne pas challenger une demande incohérente par peur de contrarier", "description": "Le client demande un véhicule sportif mais fait 50 000 km/an. Le commercial qui ne dit rien pour \"ne pas contrarier\" rate son rôle de conseiller. Un challenge respectueux augmente la confiance — il ne la diminue pas."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Préparer la fiche persona avec ce que le client dit vouloir et son besoin réel caché. Briefer : \"Je vais jouer un client qui a une demande précise. Tu fais la découverte du véhicule recherché — et tu challenges si tu détectes une incohérence.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona : donner la demande exprimée dès le départ (\"je cherche un SUV hybride\"). Répondre aux questions sur l'usage honnêtement — les incohérences avec la demande doivent apparaître naturellement si le commercial creuse bien."}, {"title": "Débriefer", "description": "\"As-tu exploré les 5 dimensions ? As-tu détecté l'incohérence entre ce que le client demandait et son usage réel ? Est-ce que tu l'as challengé — et si oui, comment ? Est-ce que tu as reformulé avant de passer à la sélection ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client, note la demande exprimée et ce que tu comprends de son usage réel. Est-ce que c'est cohérent ? Si non, challenge. Reviens me voir avec l'exemple et comment le client a réagi.\""}], "scenarios": [{"level": "debutant", "title": "La cliente qui sait ce qu'elle veut — et a raison", "objective": "Explorer les 5 dimensions dans l'ordre, valider la cohérence entre la demande et l'usage, reformuler avec précision avant de passer à la sélection.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 36 ans, pharmacienne en libéral. Méthodique, préparée. A fait ses recherches avant de venir."}, {"label": "Comportement", "text": "Arrive avec une liste de critères clairs. Répond aux questions avec précision. Valide chaque point avant de passer au suivant."}, {"label": "Non-verbal", "text": "Posture droite, carnet de notes sorti. Regard attentif. Pas de tension — elle est dans son élément."}, {"label": "Ce qu'il dit vouloir", "text": "Un SUV compact hybride, 5 places, boîte auto, budget 450€/mois."}, {"label": "Ce dont il a vraiment besoin", "text": "Exactement ce qu'elle dit. La cohérence est totale — les usages (35 km/jour ville/périphérique, 2 enfants) correspondent parfaitement."}], "context": "Mardi 10h, RDV pris en ligne. Elle a envoyé un e-mail avant avec ses critères détaillés. 28 000 km/an, moitié ville moitié voies rapides, 2 enfants de 8 et 11 ans.", "stakes": "Contexte idéal pour pratiquer les 5 dimensions dans l'ordre sans résistance. L'enjeu : ne pas sauter les étapes parce que la cliente semble avoir déjà décidé — la découverte structure la reformulation.", "observe": ["Explore-t-il les 5 dimensions même si la cliente semble déjà décidée ?", "Valide-t-il la cohérence usage / demande ?", "Hiérarchise-t-il les besoins avec elle ?", "Reformule-t-il avec précision avant de passer à la sélection ?"]}, {"level": "intermediaire", "title": "Le client qui veut un SUV mais conduit peu", "objective": "Détecter l'incohérence entre le gabarit demandé et l'usage réel, challenger avec assertivité et bienveillance, proposer une alternative mieux adaptée sans braquer.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 48 ans, expert-comptable. Vit en centre-ville, gare en sous-sol. Veut \"quelque chose de grand et confortable\"."}, {"label": "Comportement", "text": "Sûr de lui sur sa demande. Un peu surpris si on la questionne. Pas agressif — juste persuadé que le SUV est la meilleure option."}, {"label": "Non-verbal", "text": "Posture décontractée. Mains croisées. Léger recul si la demande est challengée — puis réouverture si l'argument est bon."}, {"label": "Ce qu'il dit vouloir", "text": "Un grand SUV 5 places, de préférence premium. \"Je veux me sentir à l'aise.\""}, {"label": "Ce dont il a vraiment besoin", "text": "Un véhicule confortable et spacieux — mais ses usages (8 000 km/an, 90% ville, parking en sous-sol 2m10) rendent un grand SUV inadapté."}], "context": "Jeudi 14h30. Il vient sans rdv. A l'habitude d'acheter ses voitures seul, sans trop de questions. A eu 3 berlines dans sa vie, c'est sa première tentative vers le SUV \"parce que c'est tendance\".", "stakes": "Le commercial doit explorer le contexte d'usage (surtout le parking et le kilométrage faible), détecter la vraie motivation (confort / image), et challenger doucement vers une berline ou un SUV compact.", "observe": ["Découvre-t-il le kilométrage faible et l'usage 90% ville ?", "Pose-t-il la question du parking ?", "Challenge-t-il la demande de grand SUV avec bienveillance ?", "Oriente-t-il vers une alternative cohérente avec les usages ?"]}, {"level": "avance", "title": "Le client aux critères contradictoires", "objective": "Gérer une liste de critères incompatibles entre eux, hiérarchiser avec le client pour dégager les vrais non-négociables, et construire une recommandation cohérente malgré les contradictions.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 43 ans, technico-commercial, beaucoup de route. A des critères précis mais incompatibles."}, {"label": "Comportement", "text": "Donne une liste longue et contradictoire. Insiste sur chaque point. Devient légèrement défensif si on lui dit que tout ne peut pas s'avoir en même temps."}, {"label": "Non-verbal", "text": "S'anime en parlant de ses critères. Léger agacement si on lui signale une incompatibilité. Se détend quand on lui propose une solution."}, {"label": "Ce qu'il dit vouloir", "text": "Hybride rechargeable, gros coffre (minimum 600L), très sportif, moins de 400€/mois, full options, marque premium."}, {"label": "Ce dont il a vraiment besoin", "text": "Un break hybride rechargeable premium bien équipé — la sportivité est négociable, le coffre et le budget sont les vrais non-négociables."}], "context": "Lundi 11h. RDV de 45 min. Il a envoyé une liste de 12 critères par e-mail. Il fait 55 000 km/an, beaucoup d'autoroute, transporte du matériel. Chez lui depuis longtemps, 3ème achat dans la concession.", "stakes": "L'enjeu : dégager les 3-4 critères vraiment non-négociables de la liste, montrer avec tact les incompatibilités, et construire une recommandation que le client s'approprie comme sa propre décision.", "observe": ["Identifie-t-il les incompatibilités dans la liste de critères ?", "Hiérarchise-t-il avec le client sans imposer sa vision ?", "Dégage-t-il les vrais non-négociables (coffre, budget, hybride) ?", "Construit-il une recommandation que le client valide comme sienne ?"]}]}, "online": {"focus": "la découverte du véhicule", "attentionPoints": ["Explore-t-il les 5 dimensions ou s'arrête-t-il à la demande exprimée ?", "Challenge-t-il les incohérences usage / demande ?", "Hiérarchise-t-il les besoins avec le client ?", "Reformule-t-il avant de passer à la sélection ?"], "grid": ["5 dimensions explorées", "Incohérences challengées", "Besoins hiérarchisés", "Reformulation avant sélection"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"As-tu exploré les 5 dimensions ? Est-ce que la demande exprimée était cohérente avec le contexte d'usage ? As-tu challengé quelque chose ? As-tu reformulé avant de présenter le véhicule ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand le client a dit [demande], tu as demandé [question de contexte]. Ça t'a permis de détecter [incohérence ou confirmation]. C'est exactement le rôle de la découverte du véhicule recherché.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu n'as pas challengé l'incohérence entre l'usage et la demande]. La prochaine fois, pose cette question : 'Avec ce que vous m'avez dit sur vos usages, ce modèle vous correspond vraiment ?'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client : note la demande exprimée et les 5 dimensions d'usage. Est-ce cohérent ? Si tu challenges, reviens me voir avec ce que tu as dit et comment le client a réagi. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 5 dimensions sont connues — la demande exprimée se valide toujours par le contexte d'usage", "offline": "Le challenge de la demande incohérente est pratiqué — l'assertivité bienveillante est un réflexe", "online": "Le coach a observé et débriefé la qualité de l'exploration et du challenge en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/2- Découverte complète/c. Découverte véhicule recherché.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('0f168237-badf-5b2d-98b8-4d9250027227', 'ac5b2c3f-71fa-589e-a8cc-c2e22f41240d');
insert into public.library_dojos (id, title, content, pptx_path) values ('6fcb4c7a-a4fd-52aa-9283-4109f51f47a0', 'Découverte du financement & du PC', $dojo${"version": 1, "tagline": "Comprendre le budget réel pour orienter l'offre sans argumenter trop tôt", "objective": "Le commercial pose les 5 questions clés naturellement, creuse le \"comptant\", explore la reprise et l'apport, ne juge pas et n'argumente pas pendant la découverte, et reformule la situation budgétaire avant de passer à l'offre.", "duration": "25-30 min", "theory": {"intro": null, "standardTitle": "Le standard : les 5 questions clés du budget", "standard": [{"label": "La découverte du financement ne se fait pas pour vendre du crédit — elle se fait pour comprendre comment le client construit son budget et orienter l'offre juste. L'objectif est d'informer, pas d'argumenter. L'argumentation viendra plus tard.", "title": "MODE ACHAT", "description": "\"Vous avez prévu de financer comment votre véhicule ?\"", "why": "Ouvrir le sujet sans prendre de parti. Cette question neutre laisse le client choisir son angle d'entrée — comptant, crédit, LOA — et révèle ses représentations du financement."}, {"label": "COMPTANT ?", "title": "\"Quand vous dites comptant — c'est de l'épargne disponible ou vous pensez à un crédit bancaire ?\"", "description": "\"Comptant\" cache souvent un crédit bancaire personnel ou de l'épargne partiellement disponible. Sans creuser, on suppose. Avec cette question, on reconstruit la réalité.", "why": "BUDGET"}, {"label": "\"Vous avez un budget mensuel en tête ou c'est plutôt un budget global ?\"", "title": "Distinguer budget mensuel et budget global oriente vers LOA/crédit ou achat sec. Un client qui raisonne en mensualités est un client pour le financement — il ne le sait pas encore forcément.", "description": "REPRISE / APPORT", "why": "\"Vous avez un véhicule à reprendre ? Et un apport prévu en plus ?\""}, {"label": "La reprise et l'apport réduisent le besoin de financement — et peuvent changer complètement le véhicule accessible. Ne pas le découvrir en fin de rdv.", "title": "EXPÉRIENCE FI", "description": "\"Vous avez déjà financé un véhicule par le passé ? Comment ça s'était passé ?\"", "why": "L'expérience passée conditionne l'ouverture au financement. Un client qui a eu une mauvaise expérience sera fermé sans qu'on sache pourquoi si on ne pose pas cette question."}], "criteria": [{"title": "Il ne juge pas la réponse — il creuse", "description": "\"Je paie comptant\" n'est pas une réponse finale — c'est une ouverture. Le commercial qui creuse \"c'est-à-dire ?\" sans émettre de jugement obtient la vraie information. Celui qui acquiesce et passe à autre chose rate l'enjeu."}, {"title": "Il explore le PC avant de parler reprise", "description": "La reprise conditionne l'apport disponible, qui conditionne le budget global. Découvrir le PC tôt permet d'intégrer sa valeur dans la construction du dossier. Découvrir la reprise en fin de rdv crée de la complexité inutile."}, {"title": "Il n'argumente pas le financement pendant la découverte", "description": "La découverte financement sert à collecter — pas à convaincre. \"Le crédit c'est super parce que...\" pendant la découverte coupe l'échange et met le client en garde. L'argumentation Fi viendra à son moment."}, {"title": "Il reformule la construction budgétaire du client", "description": "\"Si je comprends bien : vous avez un véhicule à reprendre, pas d'apport particulier, et vous raisonnez plutôt en mensualités.\" Ce résumé valide la compréhension et ouvre la voie à une proposition cohérente."}, {"title": "Il gère le refus de parler budget avec fluidité", "description": "\"Je verrai ça plus tard.\" — \"Pas de problème — je vous pose juste la question pour mieux vous orienter, pas pour vous proposer quoi que ce soit maintenant.\" Désarmer la méfiance par la transparence sur l'intention."}], "mistakes": [{"title": "Erreur 1 — Prendre \"je paie comptant\" pour une vérité absolue", "description": "\"Comptant\" signifie parfois épargne disponible, parfois crédit bancaire déjà accordé, parfois juste une posture de négociation. Sans creuser, on se prive d'une opportunité de financement et on risque de proposer une offre mal calibrée."}, {"title": "Erreur 2 — Argumenter le financement pendant la découverte", "description": "Dès que le client dit \"je préfère pas le crédit\", sortir les avantages de la LOA. C'est trop tôt — le client n'est pas encore dans un état de réception. La découverte financement est un moment de collecte, pas de persuasion."}, {"title": "Erreur 3 — Oublier d'explorer le prix de cession", "description": "Ne pas demander si le client a un véhicule à reprendre, c'est construire un budget incomplet. La reprise peut représenter 5 000 à 15 000€ d'apport — ignorer cela fausse toute la construction de l'offre et peut créer une mauvaise surprise en fin de rdv."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Préparer la fiche persona avec ce que le client dit sur son budget et la réalité cachée. Briefer : \"Je vais jouer un client avec une situation financière complexe. Tu fais la découverte financement — pas l'argumentation. Si tu vends du crédit maintenant, je t'arrête.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona fidèlement. Donner des réponses de surface au départ (\"je paie comptant\"). Révéler les infos plus précises seulement si les bonnes questions sont posées. Si le commercial argumente le financement, réagir avec une résistance."}, {"title": "Débriefer", "description": "\"As-tu creusé le 'comptant' ? As-tu posé la question du PC et de l'apport ? Est-ce que tu as argumenté le financement pendant la découverte — et si oui, à quel moment ? As-tu reformulé la situation budgétaire avant de conclure ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client : pose toujours la question du PC dès la découverte. Note ce que le client dit sur le financement et ce que tu comprends de sa vraie situation. Reviens me voir avec l'exemple et ce que tu en as fait.\""}], "scenarios": [{"level": "debutant", "title": "Le client transparent qui pose tout sur la table", "objective": "Poser les 5 questions dans l'ordre naturel, valider la cohérence budgétaire, ne pas argumenter le financement, et reformuler la situation avant de passer à l'offre.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 33 ans, infirmière libérale, honnête et directe. Pas de blocage sur l'argent — elle parle budget facilement."}, {"label": "Comportement", "text": "Répond clairement aux questions. Dit ce qu'elle peut dépenser sans détour. A déjà fait un crédit auto — pas de mauvais souvenirs."}, {"label": "Non-verbal", "text": "Détendue, posture ouverte. Pas de tension sur les questions financières."}, {"label": "Ce qu'il dit sur le budget", "text": "\"Je peux mettre 300€/mois, j'ai 3 000€ d'apport, et j'ai mon ancienne Clio à reprendre.\""}, {"label": "Situation réelle", "text": "Exactement ce qu'elle dit. Budget réaliste, reprise à confirmer, apport disponible. Situation simple et cohérente."}], "context": "Mercredi 11h. Elle vient pour renouveler son véhicule, crédit actuel qui se termine dans 3 mois. Elle a déjà eu une LOA — en est satisfaite.", "stakes": "Contexte idéal pour pratiquer les 5 questions dans l'ordre, valider chaque info, et construire un résumé budgétaire complet avant de passer à la sélection. L'enjeu : ne pas sauter les questions parce que le client parle facilement.", "observe": ["Pose-t-il les 5 questions même si le client donne les infos spontanément ?", "Explore-t-il le PC (Clio à reprendre) et l'apport ?", "Évite-t-il d'argumenter le financement pendant la découverte ?", "Reformule-t-il la situation budgétaire complète avant de conclure ?"]}, {"level": "intermediaire", "title": "Le client qui dit \"comptant\" mais n'a pas l'argent", "objective": "Creuser le \"comptant\" sans brusquer, reconstituer la vraie situation budgétaire, et ouvrir le sujet du financement avec fluidité sans déclencher de résistance.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 47 ans, artisan plombier, indépendant. Fier. Ne veut pas \"devoir de l'argent\"."}, {"label": "Comportement", "text": "Dit \"comptant\" d'emblée avec une pointe de fierté. Devient légèrement défensif si on creuse. Se détend si la question est posée avec naturel et sans jugement."}, {"label": "Non-verbal", "text": "Torse légèrement en avant quand il parle du budget. Micro-tension si on pose une question sur la source de l'argent."}, {"label": "Ce qu'il dit sur le budget", "text": "\"Je paie comptant, j'ai pas besoin de crédit.\""}, {"label": "Situation réelle", "text": "Il a 8 000€ d'économies. Le véhicule qu'il vise est à 28 000€. Il pense à un crédit bancaire \"à sa banque\" — mais ne le dit pas spontanément."}], "context": "Vendredi 10h. Il entre avec assurance. A déjà eu une mauvaise expérience avec un commercial qui a \"insisté sur le crédit\" il y a 5 ans. Véhicule actuel : utilitaire diesel de 8 ans, pas de reprise prévue (il le garde pour le boulot).", "stakes": "Le commercial doit creuser le \"comptant\" avec des questions courtes et neutres, reconstituer que 8 000€ ne suffiront pas pour le véhicule visé, et ouvrir doucement la piste d'un financement partiel sans déclencher la résistance.", "observe": ["Creuse-t-il le \"comptant\" sans jugement ni insistance ?", "Reconstruit-il la situation réelle (8 000€ vs prix visé) ?", "Ouvre-t-il la piste financement avec fluidité et sans argumenter ?", "Gère-t-il la résistance potentielle avec la bonne formule ?"]}, {"level": "avance", "title": "Le couple avec des visions budgétaires opposées", "objective": "Gérer deux interlocuteurs avec des positions financières contradictoires, identifier qui prend vraiment la décision budgétaire, et construire une découverte financement qui inclut les deux sans créer de tension.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Couple : Lui, 41 ans, ingénieur, très à l'aise financièrement. Elle, 38 ans, prof, plus prudente sur le budget."}, {"label": "Comportement", "text": "Lui veut \"prendre ce qui lui plaît\" sans trop regarder le prix. Elle surveille le budget et intervient quand les chiffres montent. Ils se coupent la parole sur les questions financières."}, {"label": "Non-verbal", "text": "Lui : décontracté sur les questions d'argent, parfois condescendant. Elle : se redresse sur les questions de budget, regard qui juge discrètement."}, {"label": "Ce qu'il dit sur le budget", "text": "Lui : \"on a pas de contrainte budget\". Elle (en aparté) : \"on a quand même un budget raisonnable à respecter\"."}, {"label": "Situation réelle", "text": "Ils ont une capacité de financement réelle de 550€/mois. Lui vise 800€/mois. Elle ne veut pas dépasser 450€/mois. La décision finale se prendra à deux."}], "context": "Samedi 15h. Ils arrivent ensemble, lui en avance sur la conversation, elle plus mesurée. Ils ont une reprise (SUV actuel) — lui l'a mentionné, elle n'a pas confirmé la valeur attendue.", "stakes": "L'enjeu : inclure les deux dans la découverte financement, détecter la tension budgétaire sans la nommer, identifier le vrai décideur, et construire une proposition qui respectera les deux contraintes.", "observe": ["Inclut-il les deux dans les questions financement ?", "Détecte-t-il l'écart entre les deux positions budgétaires ?", "Gère-t-il la tension sans prendre de parti ?", "Construit-il un résumé financement qui reflète les deux contraintes ?"]}]}, "online": {"focus": "la découverte financement", "attentionPoints": ["Creuse-t-il le \"comptant\" ou l'accepte-t-il sans questionner ?", "Explore-t-il le PC et l'apport disponible ?", "Argumente-t-il le financement pendant la découverte ?", "Reformule-t-il la situation budgétaire complète ?"], "grid": ["Comptant creusé", "PC & apport explorés", "Pas d'argumentation Fi", "Résumé budgétaire fait"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Est-ce que tu as creusé le mode de financement ou tu l'as pris pour acquis ? As-tu posé la question du PC et de l'apport ? Est-ce que tu as argumenté le financement pendant la découverte ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand le client a dit [réponse sur le budget], tu as posé [question de creusement]. Ça t'a permis de comprendre [réalité budgétaire]. C'est exactement le rôle de la découverte financement.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu n'as pas exploré le PC]. La prochaine fois, pose toujours cette question avant de construire l'offre : 'Vous avez un véhicule à reprendre ?' — ça peut changer toute l'équation.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client : note ce qu'il dit sur le financement ET ce que tu comprends de sa vraie situation. Reviens me voir avec les deux colonnes. Date de retour : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 5 questions clés sont connues — \"comptant\" se creuse toujours, le PC s'explore dès la découverte", "offline": "Le geste est pratiqué sur 3 profils budgétaires différents — la collecte sans argumentation est ancrée", "online": "Le coach a observé et débriefé la qualité de la découverte financement en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/2- Découverte complète/d. Découverte Fi & PC.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('6fcb4c7a-a4fd-52aa-9283-4109f51f47a0', 'a114d7e7-031a-5b42-8c3b-92f0a6efd451');
insert into public.library_dojos (id, title, content, pptx_path) values ('f4cd318a-ce90-51b3-b0fc-9dd6c77ecaa5', 'Éviter l''effet interrogatoire', $dojo${"version": 1, "tagline": "Transformer la découverte en conversation naturelle", "objective": "Le commercial ne pose jamais 2 questions d'affilée, rebondit sur chaque réponse, utilise des questions ouvertes, laisse les silences, et crée une vraie conversation — pas un formulaire.", "duration": "20-25 min", "theory": {"intro": "L'effet interrogatoire naît quand les questions s'enchaînent sans rebond, sans écoute visible, sans espace pour le client. Il perçoit un formulaire — pas une conversation. 4 techniques simples cassent ce pattern.", "standardTitle": "Le standard : les 4 techniques anti-interrogatoire", "standard": [{"label": "REBONDIR", "title": "Rebondir avant de poser la suivante", "description": "Avant chaque nouvelle question, reformuler ou commenter la réponse précédente : \"Ah vous faites 40 000 km, c'est beaucoup — c'est surtout de l'autoroute ?\"", "why": "Le rebond prouve qu'on a entendu. La question qui suit devient naturelle — pas mécanique. Le client sent qu'il parle à quelqu'un, pas à un formulaire."}, {"label": "LAISSER PARLER", "title": "Laisser les silences et les digressions", "description": "Quand le client s'écarte du sujet et parle de sa vie — laisser faire. Ne pas recadrer. Ces digressions donnent des informations précieuses sur qui il est.", "why": "Un client qui digresse crée du lien. Le commercial qui recadre trop vite signale qu'il est en mode collecte d'infos, pas en mode écoute. La digression est un cadeau."}, {"label": "PARTAGER", "title": "Partager une information en retour", "description": "De temps en temps, donner une info sur soi ou sur d'autres clients : \"D'autres clients avec ce profil ont souvent opté pour l'hybride — ça vous parle ?\"", "why": "L'échange est bidirectionnel. Un commercial qui ne fait que poser des questions prend sans donner. Partager une info équilibre la relation et renforce la confiance."}, {"label": "QUESTIONS OUVERTES", "title": "Préférer les questions ouvertes larges", "description": "\"Qu'est-ce qui vous a poussé à changer maintenant ?\" plutôt que \"C'est parce que votre voiture est vieille ?\". La question ouverte laisse le client décider ce qui est important.", "why": "La question fermée oriente et rétrécit. La question ouverte large révèle des motivations qu'on n'aurait jamais devinées — et donne au commercial des angles d'argumentation inattendus."}], "criteria": [{"title": "Il ne pose jamais 2 questions d'affilée", "description": "Entre chaque question, il y a toujours un rebond, un commentaire, une reformulation. Le rythme question-réponse-question-réponse est le marqueur de l'interrogatoire. Le rythme question-réponse-rebond-question est celui de la conversation."}, {"title": "Il laisse le client finir ses phrases", "description": "Couper le client pour poser la question suivante est l'un des signaux les plus forts d'un commercial en mode questionnaire. L'écoute active commence par ne pas couper."}, {"title": "Il accuse réception des émotions", "description": "Quand le client dit quelque chose d'émotionnel (\"mon vieux véhicule me manque\", \"j'ai eu une mauvaise expérience\"), il ne rebondit pas immédiatement sur le projet. Il accuse réception : \"Je comprends\" dit avec sincérité ouvre plus qu'une question."}, {"title": "Son rythme suit le rythme du client", "description": "Un client rapide et efficace n'a pas besoin qu'on ralentisse avec des digressions. Un client qui aime parler n'a pas besoin qu'on accélère. Adapter son rythme au client est le niveau suivant de la conversation."}, {"title": "Il sait utiliser le silence comme outil", "description": "Après une question ouverte, laisser 2-3 secondes de silence. Le client qui n'a pas encore fini de penser va souvent donner l'information la plus importante dans ce silence. Le commercial qui le remplit rate cette information."}], "mistakes": [{"title": "Erreur 1 — Enchaîner les questions fermées", "description": "\"Vous avez des enfants ? Vous faites de l'autoroute ? Vous voulez du diesel ? Vous avez un budget mensuel ?\" — quatre questions en 20 secondes. Le client répond par oui/non et ferme progressivement. Chaque question fermée réduit l'espace d'expression du client."}, {"title": "Erreur 2 — Recadrer le client qui digresse", "description": "\"Oui oui — et donc niveau kilométrage vous faites combien ?\" dit pendant que le client parle de ses vacances. Ce recadrage signale que la digression était une perte de temps. Le client se ferme. La digression était pourtant pleine d'informations sur ses usages et sa vie."}, {"title": "Erreur 3 — Prendre des notes sans regarder le client", "description": "Tête baissée sur le CRM ou le carnet, stylo en main, en train de noter chaque réponse. Le client parle à quelqu'un qui ne le regarde pas. La prise de notes pendant la découverte signale qu'on est en mode collecte — pas en mode écoute. Mémoriser et noter après, pas pendant."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je vais jouer un client pour la découverte. Ton seul objectif : ne jamais poser 2 questions d'affilée sans rebond. Je compte. Si tu poses 2 questions de suite, je te le signale en levant la main.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona naturellement. Répondre aux questions. Si le commercial pose 2 questions d'affilée, lever la main discrètement sans interrompre. Observer aussi la qualité des rebonds : sont-ils sincères ou mécaniques ?"}, {"title": "Débriefer", "description": "\"Combien de fois j'ai levé la main ? Qu'est-ce que tu as fait après mes réponses — tu as rebondi ou tu as enchaîné ? Est-ce que tu as utilisé des questions ouvertes ou fermées ? Tu as laissé des silences ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client : après chaque réponse, dis-toi mentalement 'qu'est-ce que je peux rebondir là-dessus ?' avant de poser ta question suivante. Reviens me voir avec un exemple de rebond qui t'a ouvert quelque chose d'inattendu.\""}], "scenarios": [{"level": "debutant", "title": "Le client bavard qui donne tout — et part dans tous les sens", "objective": "Pratiquer les 4 techniques sur un client facile : rebondir sur les digressions, poser des questions ouvertes, laisser les silences, ne jamais poser 2 questions d'affilée.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 52 ans, chef cuisinier en restauration collective. Bavard, sympathique, aime parler de lui."}, {"label": "Comportement", "text": "Répond aux questions avec beaucoup de détails. Digresse souvent sur sa vie professionnelle et ses voyages. Ne perçoit pas l'effet interrogatoire car il parle naturellement."}, {"label": "Non-verbal", "text": "Expressif, gesticulant. Contact visuel facile. Souriant. Détendu."}, {"label": "Motivation d'achat", "text": "Renouveler son utilitaire pour le travail — besoin de coffre et de fiabilité."}, {"label": "Frein / tension", "text": "Aucun frein particulier — contexte idéal pour pratiquer sans résistance."}], "context": "Mercredi 10h. Il arrive avec de l'énergie et commence à parler avant même d'être assis. Véhicule actuel : Citroën Berlingo 2017, 180 000 km.", "stakes": "Contexte parfait pour pratiquer le rythme question-rebond-question. Le défi : structurer mentalement les 4 axes de découverte tout en laissant le client parler librement et en utilisant ses digressions comme matière.", "observe": ["Ne pose-t-il jamais 2 questions d'affilée ?", "Rebondit-il sur les digressions du client ?", "Utilise-t-il des questions ouvertes larges ?", "Laisse-t-il des silences après les questions ouvertes ?"]}, {"level": "intermediaire", "title": "Le client réservé qui répond court et attend qu'on creuse", "objective": "Utiliser les 4 techniques pour ouvrir progressivement un client peu loquace : rebonds sincères sur les réponses courtes, questions ouvertes ciblées, silences assumés.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 44 ans, contrôleuse de gestion, introvertie. Parle peu spontanément mais répond honnêtement si la question est bonne."}, {"label": "Comportement", "text": "Donne des réponses courtes et précises. N'élabore pas si on ne lui demande pas. Observe le commercial attentivement avant de s'ouvrir."}, {"label": "Non-verbal", "text": "Posture légèrement fermée au départ. Regard attentif mais peu expressif. Se détend progressivement si elle sent qu'on l'écoute vraiment."}, {"label": "Motivation d'achat", "text": "Remplacer sa voiture de fonction arrivée en fin de contrat. Efficacité et discrétion avant tout."}, {"label": "Frein / tension", "text": "La méfiance vis-à-vis du discours commercial. Elle teste silencieusement avant de faire confiance."}], "context": "Lundi 14h. RDV pris par e-mail. Elle est précise et ponctuelle. Le commercial doit résister à l'envie de combler les silences — ce sont eux qui vont la faire parler.", "stakes": "L'enjeu : rebondir sur des réponses très courtes (\"oui\", \"environ 20 000 km\", \"principalement autoroute\") sans poser immédiatement une nouvelle question. Le silence après le rebond est l'outil principal.", "observe": ["Rebondit-il sur les réponses courtes sans enchaîner immédiatement ?", "Laisse-t-il des silences assumés après ses questions ?", "Ses questions ouvertes sont-elles assez larges pour inviter à développer ?", "Évite-t-il de combler les silences avec sa propre voix ?"]}, {"level": "avance", "title": "Le client qui contre-interroge le commercial", "objective": "Maintenir le fil de la découverte quand le client retourne les questions, répondre brièvement sans perdre la main, et reprendre naturellement la posture de celui qui guide la conversation.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 49 ans, avocat d'affaires. Habitué à poser des questions, pas à y répondre. Teste le commercial dès les premières secondes."}, {"label": "Comportement", "text": "Répond à chaque question par une contre-question. \"Et vous, vous conduisez quoi ?\" / \"Pourquoi vous me demandez ça ?\" / \"C'est quoi le rapport avec le véhicule ?\" Pas agressif — c'est son mode naturel de communication."}, {"label": "Non-verbal", "text": "Regard direct et intense. Léger sourire quand il contre-interroge. S'attend à être déstabilisé — sera agréablement surpris si ce n'est pas le cas."}, {"label": "Motivation d'achat", "text": "Trouver un véhicule premium pour ses déplacements clients. L'image et le confort comptent autant que les prestations."}, {"label": "Frein / tension", "text": "Si le commercial perd la main de la conversation, le client perd confiance dans sa capacité à le conseiller."}], "context": "Vendredi 11h. Il arrive à l'heure exacte, poignée de main ferme, regarde le commercial dans les yeux. Dès la première question de découverte, il retourne la question.", "stakes": "Le commercial doit répondre brièvement et avec humour si possible, puis reprendre naturellement la main : \"Bonne question — et vous, dans votre cas ?\" ou \"Je vous le dirai après vous avoir entendu.\" L'enjeu est de rester celui qui guide sans entrer dans un rapport de force.", "observe": ["Gère-t-il les contre-questions sans se déstabiliser ?", "Répond-il brièvement et reprend-il naturellement la main ?", "Maintient-il un rythme de conversation — pas d'interrogatoire ni de duel ?", "Garde-t-il un ton léger et confiant face à la résistance ?"]}]}, "online": {"focus": "le rythme de la conversation", "attentionPoints": ["Pose-t-il 2 questions d'affilée sans rebond ?", "Ses rebonds sont-ils sincères ou mécaniques ?", "Utilise-t-il des questions ouvertes ou fermées ?", "Laisse-t-il des silences ou les comble-t-il ?"], "grid": ["Pas de 2 questions d'affilée", "Rebonds sincères", "Questions ouvertes", "Silences assumés"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Combien de fois tu as posé 2 questions d'affilée à ton avis ? Est-ce que tu as rebondi sur les réponses — et si oui sur lesquelles ? Tu as laissé des silences ou tu les as comblés ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand le client a dit [réponse], tu as rebondi avec [commentaire ou question ouverte]. Le client a continué à parler — c'est exactement ça qui crée la conversation plutôt que l'interrogatoire.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as posé 3 questions fermées d'affilée à la fin]. La prochaine fois, après chaque réponse, pause mentale de 1 seconde : 'qu'est-ce que je peux rebondir là-dessus ?' avant de poser la suivante.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client : après chaque réponse, pause mentale et rebond avant la question suivante. Reviens me voir avec un exemple de rebond qui t'a donné une information inattendue. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 4 techniques sont connues — rebond, digression, partage, questions ouvertes", "offline": "Le rythme conversation est pratiqué sur 3 profils — le réflexe rebond est ancré", "online": "Le coach a observé et débriefé le rythme de la conversation en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/3- Créer du lien/Eviter l''effet interrogatoire.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('f4cd318a-ce90-51b3-b0fc-9dd6c77ecaa5', '912d1952-44cf-5635-896f-2f8905411bdc');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('f4cd318a-ce90-51b3-b0fc-9dd6c77ecaa5', '231fa962-b241-5567-974a-edf309bf110d');
insert into public.library_dojos (id, title, content, pptx_path) values ('0f9ad597-d5ee-5d64-b28b-0c5a357e1fa9', 'Trouver des expériences communes', $dojo${"version": 1, "tagline": "Créer un lien humain durable au-delà du projet auto", "objective": "Le commercial capte les indices dans la découverte, rebondit naturellement sur au moins 1 point commun, l'utilise pour enrichir la conversation, et le mémorise pour le réutiliser dans l'argumentation.", "duration": "20-25 min", "theory": {"intro": null, "standardTitle": "Le standard : les 3 niveaux de connexion", "standard": [{"label": null, "title": "Un client qui se reconnaît dans son commercial achète plus facilement, reste plus longtemps, et revient. Trouver une expérience commune n'est pas de la manipulation — c'est reconnaître l'humanité de l'autre. Il y a 3 niveaux de connexion, du plus accessible au plus fort.", "description": "NIVEAU 1", "why": "La connexion de surface — les faits partagés"}, {"label": null, "title": "Même région d'origine, même marque de voiture précédente, mêmes trajets domicile-travail, mêmes contraintes (enfants, déplacements pro). Ces points communs émergent naturellement de la découverte.", "description": "\"Ah vous faites Paris-Lyon régulièrement ? Moi aussi je connais bien cet axe.\" Simple, honnête, immédiat. Ça ne crée pas une amitié — ça crée une humanité partagée.", "why": "Le client passe du mode prospect au mode personne. Le commercial cesse d'être un vendeur générique."}, {"label": null, "title": "NIVEAU 2", "description": "La connexion par les valeurs — ce qui compte", "why": "Même rapport à l'argent (\"pas de crédit\"), même priorité (la famille, l'environnement, la performance), même vision du service (\"je veux qu'on me fasse confiance\")."}, {"label": null, "title": "\"Je comprends — moi aussi j'aurais du mal à m'engager sur un crédit sans être sûr à 100%. C'est important de se sentir à l'aise avec ça.\"", "description": "La connexion sur les valeurs crée de la confiance profonde. Le client sent qu'on pense pareil — pas qu'on lui vend quelque chose.", "why": "NIVEAU 3"}, {"label": null, "title": "La connexion par l'émotion — le ressenti partagé", "description": "Une émotion commune autour de l'achat auto : la fierté du premier achat, l'attachement à une voiture, la nostalgie d'un modèle. Ces moments sont rares mais puissants.", "why": "\"Mon premier achat aussi c'était une Golf — je m'en souviens encore. Il y a quelque chose de particulier dans le premier véhicule qu'on choisit vraiment soi-même.\""}, {"label": null, "title": "Le niveau le plus fort de connexion. Rare, ne se force pas. Mais quand il arrive naturellement, la relation est scellée.", "description": "NIVEAU + EXEMPLE CONCRET", "why": "IMPACT SUR LA RELATION"}], "criteria": [{"title": "Il capte les indices dans la découverte", "description": "La région d'où le client vient, sa profession, ses habitudes de trajet, ses centres d'intérêt mentionnés spontanément — tout ça contient des points de connexion potentiels. Le commercial attentif les saisit au vol."}, {"title": "Il rebondit naturellement — pas de façon calculée", "description": "\"Ah vous venez de Lyon — j'y suis allé il y a deux mois pour un salon auto.\" Dit naturellement, en passant. Si ça semble calculé ou forcé, c'est pire que de ne rien dire. L'authenticité est la condition sine qua non."}, {"title": "Il ne force pas la connexion si elle n'existe pas", "description": "Ne pas inventer un point commun pour créer du lien artificiel. \"Moi aussi j'adore le ski\" dit par un commercial qui ne skie jamais se voit immédiatement. Le mensonge de connexion détruit plus de confiance qu'il n'en crée."}, {"title": "Il utilise la connexion pour enrichir la découverte", "description": "\"Vous faites beaucoup de déplacements en famille pour les vacances — comme moi. Est-ce que c'est plutôt en France ou vous partez à l'étranger ?\" La connexion ouvre de nouvelles questions de découverte, elle ne s'arrête pas à elle-même."}, {"title": "Il mémorise et réutilise", "description": "Une expérience commune mentionnée en début de RDV peut être rappelée en fin de RDV : \"Et avec ce que vous m'avez dit sur vos trajets Lyon-Paris, ce coffre va vraiment changer votre quotidien.\" La mémoire du lien prouve l'écoute."}], "mistakes": [{"title": "Erreur 1 — Inventer ou exagérer un point commun", "description": "\"Ah vous aimez le foot ? Moi aussi !\" dit par quelqu'un qui n'a jamais regardé un match. Le client qui s'y connaît va creuser — et détecter immédiatement le mensonge. Une fausse connexion est pire qu'une absence de connexion."}, {"title": "Erreur 2 — Rester trop longtemps sur la connexion et oublier le projet", "description": "Trouver un point commun et passer 10 minutes à en parler en oubliant complètement l'objectif du RDV. La connexion est un pont vers la vente — pas la destination. Elle enrichit la relation, elle ne la remplace pas."}, {"title": "Erreur 3 — Forcer une connexion là où il n'y en a pas", "description": "Chercher à tout prix un point commun alors que le client n'envoie aucun signal en ce sens. Certains clients ne veulent pas de lien personnel — ils veulent de l'efficacité. Forcer la connexion dans ce cas crée de l'inconfort et de la méfiance."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Intégrer dans le persona des indices de connexion potentiels (région, habitudes, centres d'intérêt). Briefer : \"Pendant la découverte, je vais glisser des informations sur ma vie. Tu dois en saisir au moins une pour créer un point commun — naturellement, pas de façon forcée.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona et donner des indices spontanément dans les réponses. Ex : \"Je fais le trajet Bordeaux-Paris toutes les 3 semaines pour le boulot.\" Attendre que le commercial rebondisse. Si aucun rebond, continuer — noter l'occasion manquée pour le debrief."}, {"title": "Débriefer", "description": "\"As-tu capté les indices que j'ai glissés ? Tu en as utilisé combien ? Quand tu as rebondi sur [point commun], est-ce que ça sonnait naturel ou calculé ? Est-ce que tu as réutilisé ce point commun plus tard dans le RDV ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client : note 1 point commun que tu as trouvé et comment tu l'as utilisé dans la conversation. Pas juste 'j'ai dit que moi aussi j'aimais ça' — comment est-ce que ça a enrichi le RDV ?\""}], "scenarios": [{"level": "debutant", "title": "Le client qui donne plein d'indices — il suffit d'en saisir un", "objective": "Capter au moins 2 indices de connexion dans la découverte, rebondir naturellement sur l'un d'eux, et l'utiliser pour enrichir une question de découverte.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 38 ans, technicien réseau en télétravail, père de 2 enfants. Habite Bordeaux. Passionné de randonnée."}, {"label": "Comportement", "text": "Parle facilement de sa vie. Mentionne ses week-ends en montagne, ses trajets pour emmener les enfants au sport, son télétravail 4j/5."}, {"label": "Non-verbal", "text": "Détendu, souriant. Gestuelle expressive quand il parle de ses loisirs. Posture ouverte."}, {"label": "Indices à saisir", "text": "\"Je fais souvent la route des Pyrénées le week-end\" / \"J'emmène les gamins au rugby tous les samedis\" / \"Je roule peu en semaine vu que je télétravaile\"."}, {"label": "Frein / tension", "text": "Aucun frein particulier — contexte idéal pour s'entraîner à capter et utiliser les indices."}], "context": "Samedi 10h. Il vient pour renouveler son Dacia Duster de 5 ans qui commence à fatiguer sur les pistes. Budget : 320€/mois. Pas de véhicule à reprendre — sa femme garde le Duster pour la ville.", "stakes": "Le commercial reçoit de nombreux indices tout au long de la découverte. L'enjeu : les saisir au vol, rebondir naturellement sur au moins un, et l'utiliser pour enrichir la conversation plutôt que de simplement l'enregistrer.", "observe": ["Capte-t-il les indices glissés dans la conversation ?", "Rebondit-il naturellement sur au moins un point commun ?", "La connexion sonne-t-elle authentique ou calculée ?", "Utilise-t-il ce point commun pour enrichir la découverte ?"]}, {"level": "intermediaire", "title": "Le client peu loquace qui donne peu d'indices", "objective": "Créer une connexion malgré un client qui parle peu, en posant des questions ouvertes qui invitent à partager, et en rebondissant sur les rares indices donnés.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 52 ans, comptable en cabinet, discrète, efficace. Vient renouveler sa Citroën C5 de 7 ans."}, {"label": "Comportement", "text": "Répond aux questions avec précision mais sans débordements. Ne partage pas spontanément d'informations personnelles. Observe le commercial attentivement."}, {"label": "Non-verbal", "text": "Posture neutre. Regard direct mais peu expressif. Se détend légèrement quand elle parle de ses voyages."}, {"label": "Indices à saisir", "text": "\"Je fais Paris-Nantes régulièrement pour voir ma famille\" — glissé une fois. \"J'aime conduire\" — dit brièvement. Peu d'autres indices disponibles."}, {"label": "Frein / tension", "text": "Méfiance douce vis-à-vis des commerciaux. Ne veut pas de relation personnelle forcée."}], "context": "Lundi 11h. RDV pris par téléphone. Elle est ponctuelle, directe, sait ce qu'elle veut. 35 000 km/an, principalement autoroute.", "stakes": "Le commercial doit travailler avec peu de matière. Les questions ouvertes sur les usages peuvent faire émerger des points communs. L'enjeu : ne pas forcer une connexion inexistante, mais saisir le rare indice disponible avec naturel.", "observe": ["Pose-t-il des questions ouvertes qui invitent au partage ?", "Capte-t-il le rare indice (Paris-Nantes / aime conduire) ?", "Rebondit-il naturellement sans forcer la connexion ?", "Accepte-t-il l'absence de connexion profonde si le client ne s'ouvre pas ?"]}, {"level": "avance", "title": "Le client qui partage une expérience émotionnelle forte", "objective": "Accueillir une expérience émotionnelle forte (attachement à un véhicule, souvenir lié à une voiture), créer une connexion de niveau 3 avec authenticité, et l'utiliser pour ancrer l'argumentation dans le ressenti.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 55 ans, directeur commercial, a toujours conduit des BMW. Vient \"à contrecoeur\" changer de marque pour des raisons fiscales."}, {"label": "Comportement", "text": "Parle de sa vieille BMW Série 5 avec une vraie nostalgie. \"C'était ma voiture préférée — je l'ai gardée 8 ans.\" Légèrement défensif sur le changement de marque."}, {"label": "Non-verbal", "text": "Regard qui se perd un instant quand il évoque la BMW. Ton plus doux sur ce sujet. Légère tension quand on parle de la nouvelle marque."}, {"label": "Indices à saisir", "text": "L'attachement émotionnel à la BMW est l'indice principal. Il cache une vraie difficulté à tourner la page."}, {"label": "Frein / tension", "text": "L'ego autour de la marque. Sentir qu'on comprend son attachement est la clé pour qu'il s'ouvre au changement."}], "context": "Jeudi 14h. RDV pris par son assistante. Il arrive légèrement résigné. Budget : sans limite fixée. Contrainte : TVS qui l'oblige à descendre en gamme d'émissions CO2.", "stakes": "L'enjeu : accueillir l'émotion autour de la BMW sans minimiser, créer une vraie connexion sur l'attachement à un véhicule (que tout bon passionné de voitures peut comprendre), et utiliser ce lien pour repositionner positivement le changement.", "observe": ["Accueille-t-il l'émotion autour de la BMW sans minimiser ?", "Crée-t-il une connexion authentique sur l'attachement à un véhicule ?", "Utilise-t-il cette connexion pour positionner positivement le changement ?", "Son niveau de connexion 3 sonne-t-il naturel et sincère ?"]}]}, "online": {"focus": "la création de connexion", "attentionPoints": ["Capte-t-il les indices de connexion dans la découverte ?", "Rebondit-il naturellement sur au moins un point commun ?", "La connexion sonne-t-elle authentique ou forcée ?", "Réutilise-t-il le point commun plus tard dans le RDV ?"], "grid": ["Indices captés", "Rebond naturel", "Connexion authentique", "Point commun réutilisé"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Quel point commun as-tu trouvé avec ce client ? Quand est-ce que tu l'as capté — et quand est-ce que tu l'as utilisé ? Est-ce que tu penses que ça sonnait naturel ? Tu t'en es resservi plus tard dans le RDV ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand le client a mentionné [indice], tu as rebondi avec [remarque/question]. Le client a réagi en [observation précise]. Ce moment a changé la qualité de la relation — c'est exactement ça.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as trouvé le point commun mais tu ne l'as pas réutilisé dans l'argumentation]. La prochaine fois, quand tu trouves un point commun, note-le mentalement et reviens dessus : 'Et comme vous me disiez tout à l'heure sur [X]...'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client : note le point commun que tu as trouvé ET comment tu l'as réutilisé dans la suite du RDV. Ces deux éléments ensemble. Date de retour : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 3 niveaux de connexion sont connus — faits, valeurs, émotion — chacun a son moment", "offline": "Le geste est pratiqué sur 3 profils différents — capter et rebondir naturellement est un réflexe", "online": "Le coach a observé et débriefé la création de connexion en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/3- Créer du lien/Expériences communes.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('0f9ad597-d5ee-5d64-b28b-0c5a357e1fa9', '3bab76d1-de9e-5f5e-bd84-73008ac714b6');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('0f9ad597-d5ee-5d64-b28b-0c5a357e1fa9', '8355000f-0951-566b-9ac1-377e376128f9');
insert into public.library_dojos (id, title, content, pptx_path) values ('63ffd509-c955-574f-8a89-313e58c5bfc6', 'Rassurer & adapter sa prise en charge', $dojo${"version": 1, "tagline": "Lire l'inquiétude du client et calibrer son accompagnement", "objective": "Le commercial identifie la source d'inquiétude du client, la nomme sobrement, adapte son rythme et sa posture sans concession injustifiée, et donne de la visibilité sur les étapes.", "duration": "20-25 min", "theory": {"intro": "Un client en concession porte presque toujours une inquiétude — souvent non exprimée. La rassurer n'est pas de la psychologie : c'est identifier la source, la nommer sans la dramatiser, et adapter sa posture en conséquence.", "standardTitle": "Le standard : les 4 sources d'inquiétude client en concession", "standard": [{"label": "SE TROMPER", "title": "Peur de faire le mauvais choix", "description": "\"Et si ce véhicule n'est pas le bon pour moi ?\" — surtout pour un primo-accédant ou un client qui change de gamme.", "why": "Reformuler ses besoins avant de proposer. Valider chaque critère avec lui : \"Ça correspond à ce que vous m'avez dit ?\" Le client qui valide se rassure lui-même."}, {"label": "SE FAIRE AVOIR", "title": "Peur de payer trop cher", "description": "\"Est-ce qu'on me donne le juste prix ou on profite de moi ?\" — méfiance vis-à-vis du commercial et du financement.", "why": "Transparence sur les chiffres. Montrer la construction du prix sans attendre qu'on le demande. Ne jamais donner un prix sans l'expliquer."}, {"label": "NE PAS COMPRENDRE", "title": "Peur de ne pas maîtriser", "description": "\"Je ne comprends pas tout ce qu'on me dit — les motorisations, le financement, les options...\" — sentiment d'incompétence face à la complexité technique.", "why": "Adapter le niveau de langage. Reformuler en termes simples. Demander régulièrement : \"C'est clair pour vous jusque-là ?\" sans condescendance."}, {"label": "S'ENGAGER", "title": "Peur de s'engager trop vite", "description": "\"Je ne veux pas prendre une décision sous pression.\" — surtout après une précédente expérience négative avec un commercial insistant.", "why": "Poser le rythme dès le départ : \"Prenez le temps qu'il vous faut.\" Puis respecter ce rythme en toutes circonstances — même quand on sent que la vente est proche."}], "criteria": [{"title": "Il lit les signaux non-verbaux d'inquiétude", "description": "Regard qui fuit, ton qui monte légèrement, bras qui se croisent, phrases qui s'accélèrent — ce sont les signaux d'une inquiétude qui monte. Le commercial qui les lit peut adapter sa posture avant que l'inquiétude ne devienne un blocage."}, {"title": "Il nomme l'inquiétude sans la dramatiser", "description": "\"J'ai l'impression que quelque chose vous préoccupe — c'est normal, c'est un achat important.\" Nommer crée une ouverture. Ignorer crée une distance. Dramatiser amplifie. La formule juste : sobre, directe, bienveillante."}, {"title": "Il adapte son rythme — pas sa substance", "description": "Avec un client anxieux, ralentir le débit, laisser plus de silences, reformuler davantage. Mais ne pas changer l'offre ou faire des concessions non justifiées parce que le client est stressé. La rassurance passe par la posture, pas par le prix."}, {"title": "Il donne de la visibilité sur les étapes", "description": "\"Voilà comment ça va se passer : d'abord on fait le point sur vos besoins, ensuite je vous présente ce qui correspond, et on regarde le financement si ça vous intéresse.\" Un client qui sait où il va est un client qui se détend."}, {"title": "Il ne force pas la rassurance", "description": "\"Ne vous inquiétez pas\" dit trop vite invalide l'inquiétude au lieu de la dissoudre. La vraie rassurance vient de la preuve — un argument concret, une explication claire, un geste attentionné — pas d'une formule de politesse."}], "mistakes": [{"title": "Erreur 1 — Ignorer les signaux d'inquiétude et continuer le script", "description": "Le client commence à se fermer, les réponses se font plus courtes, le regard décroche — et le commercial continue son pitch comme si de rien n'était. L'inquiétude ignorée grossit. Elle devient une objection, puis un refus de décider."}, {"title": "Erreur 2 — Sur-rassurer avec des formules vides", "description": "\"Faites-moi confiance\", \"ne vous inquiétez pas\", \"c'est vraiment le meilleur choix pour vous\" dits sans preuve ni explication. Ces formules sont contre-productives : elles signalent que l'inquiétude n'a pas été vraiment entendue. La confiance se mérite, elle ne se commande pas."}, {"title": "Erreur 3 — Faire des concessions pour calmer l'anxiété", "description": "Baisser le prix, ajouter des options gratuites, ou accélérer les délais pour qu'un client stressé se sente mieux — sans que ces éléments soient justifiés commercialement. Rassurer par des concessions crée de mauvais précédents et dégrade la valeur perçue de l'offre."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je vais jouer un client avec une inquiétude particulière — tu dois la détecter et adapter ta posture. Je ne te la dirai pas d'avance. Tu me diras après quelle inquiétude tu as identifiée.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona fidèlement — exprimer l'inquiétude par des signaux non-verbaux et des formules verbales cohérentes. Ne pas l'exprimer explicitement au départ. Laisser le commercial la détecter. Répondre honnêtement si des questions directes sont posées."}, {"title": "Débriefer", "description": "\"Quelle inquiétude as-tu détectée ? À quel moment as-tu changé ta posture ? Est-ce que tu l'as nommée ? Comment as-tu rassuré — par une formule ou par un argument concret ? Est-ce que tu as fait des concessions non justifiées ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client anxieux : note l'inquiétude que tu détectes et comment tu l'as traitée. Pas une formule — une action concrète. Reviens me voir avec l'exemple. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Le primo-accédant qui a peur de se tromper", "objective": "Identifier la peur du mauvais choix, reformuler les besoins pour rassurer, valider chaque étape avec le client avant de passer à la suivante.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 24 ans, premier achat auto, technicien en CDI depuis 8 mois. C'est son premier RDV en concession seul."}, {"label": "Source d'inquiétude", "text": "Peur de faire le mauvais choix — il ne maîtrise pas les motorisations, le financement, et ne veut pas \"passer pour un idiot\"."}, {"label": "Non-verbal", "text": "Regarde souvent son téléphone. Répond brièvement. Sourit poliment mais semble perdu. Pose des questions puis s'excuse de les poser."}, {"label": "Ce dont il a besoin", "text": "Être guidé pas à pas, sans jargon, avec des validations régulières. Sentir qu'il est entre de bonnes mains."}, {"label": "Ce qui le rassure", "text": "Les reformulations simples, les validations régulières (\"vous suivez ?\"), le fait que le commercial prenne le temps sans le presser."}], "context": "Samedi matin. Il est venu seul après avoir regardé des vidéos YouTube sur \"comment acheter une voiture sans se faire avoir\". Véhicule actuel : aucun — transports en commun. Budget : 200€/mois max.", "stakes": "Le commercial doit adapter son vocabulaire, expliquer simplement les concepts techniques, valider la compréhension sans condescendance, et donner de la visibilité sur les étapes.", "observe": ["Adapte-t-il son vocabulaire au niveau du client ?", "Valide-t-il régulièrement la compréhension ?", "Reformule-t-il les besoins avant de proposer ?", "Donne-t-il de la visibilité sur les étapes du RDV ?"]}, {"level": "intermediaire", "title": "La cliente méfiante qui a eu une mauvaise expérience", "objective": "Détecter et nommer sobrement la méfiance, rassurer par la transparence et les preuves concrètes (pas les formules), maintenir la confiance tout au long du RDV.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 41 ans, responsable administrative, organisée et directe. A eu une mauvaise expérience dans une autre concession il y a 3 ans — elle le dit d'emblée."}, {"label": "Source d'inquiétude", "text": "Peur de se faire avoir sur le prix ou le financement. Méfiance envers les arguments commerciaux. \"On m'a déjà promis des choses qui n'ont pas été tenues.\""}, {"label": "Non-verbal", "text": "Regard scrutateur. Note ce qu'on lui dit. Réaction visible quand quelque chose lui semble flou. Se détend progressivement si les chiffres sont transparents."}, {"label": "Ce dont il a besoin", "text": "Transparence totale sur les prix, les marges, les conditions. Pas de faux enthousiasme — des faits."}, {"label": "Ce qui le rassure", "text": "Les chiffres expliqués, les conditions écrites, les formules directes sans enrobage commercial."}], "context": "Mardi 14h. RDV pris en ligne. Elle a envoyé 3 questions par e-mail avant de venir. Véhicule actuel : Peugeot 308 2019, bien entretenu. Budget : 420€/mois.", "stakes": "Le commercial doit résister à l'envie de \"vendre\" et adopter une posture de conseil transparent. Toute formule vague ou enthousiasme excessif déclenchera une résistance.", "observe": ["Accuse-t-il réception de la mauvaise expérience sans minimiser ?", "Rassure-t-il par des faits concrets plutôt que des formules ?", "Évite-t-il les formules vagues (\"faites-moi confiance\") ?", "Maintient-il la transparence sur les chiffres et conditions ?"]}, {"level": "avance", "title": "Le client sous pression familiale qui doute en cours de RDV", "objective": "Détecter un changement d'état émotionnel en cours de RDV, adapter sa posture en temps réel, nommer le doute sans forcer, et créer les conditions d'une décision sereine.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 46 ans, cadre, vient seul mais a \"sa femme au téléphone\". Projet décidé en couple — il a un mandat flou."}, {"label": "Source d'inquiétude", "text": "Peur de s'engager sans l'accord de sa femme. Arrivé motivé, il commence à douter à mi-RDV quand les chiffres sont posés. \"Je vais devoir en reparler à la maison.\""}, {"label": "Non-verbal", "text": "Regarde son téléphone de plus en plus. Ton qui devient moins affirmatif. Répond \"oui oui\" sans vraiment valider. Posture qui se ferme légèrement."}, {"label": "Ce dont il a besoin", "text": "Se sentir libre de ne pas décider aujourd'hui. Avoir des éléments concrets à ramener chez lui. Ne pas se sentir coincé."}, {"label": "Ce qui le rassure", "text": "\"Pas de pression — prenez le temps qu'il vous faut.\" + document récapitulatif à emporter. La liberté de partir sans décider réduit l'anxiété et favorise le retour."}], "context": "Jeudi 16h. Il est venu seul, très engagé au départ. Mi-RDV, il reçoit un message de sa femme et son attitude change. Le commercial risque de perdre la vente en forçant la décision — ou de la préparer pour la prochaine visite en gérant bien ce moment.", "stakes": "L'enjeu : détecter le changement en temps réel, nommer le doute sobrement, ne pas forcer, et transformer ce RDV en étape vers la décision.", "observe": ["Détecte-t-il le changement d'état émotionnel en cours de RDV ?", "Nomme-t-il le doute sobrement sans le dramatiser ?", "Résiste-t-il à l'envie de forcer la décision ?", "Crée-t-il les conditions d'un retour (récap, liberté de partir) ?"]}]}, "online": {"focus": "la gestion de l'inquiétude", "attentionPoints": ["Détecte-t-il les signaux non-verbaux d'inquiétude ?", "Nomme-t-il l'inquiétude sobrement ?", "Rassure-t-il par des arguments concrets ou des formules vides ?", "Adapte-t-il son rythme et sa posture sans faire de concessions ?"], "grid": ["Signaux détectés", "Inquiétude nommée", "Rassurance par preuves", "Posture adaptée sans concession"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Quelle inquiétude as-tu détectée chez ce client ? À quel moment l'as-tu vue apparaître ? Est-ce que tu l'as nommée ? Comment as-tu rassuré — par une formule ou par quelque chose de concret ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand [signal d'inquiétude], tu as [action précise]. Le client a réagi en [observation]. C'est exactement ça — tu as adapté ta posture au bon moment.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as dit 'ne vous inquiétez pas' sans donner d'argument]. La prochaine fois, remplace cette formule par une preuve : 'Je comprends — et voilà pourquoi vous pouvez être serein : [argument concret].'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client anxieux : identifie sa source d'inquiétude et note l'action concrète que tu as faite pour la traiter. Reviens me voir avec les deux. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 4 sources d'inquiétude sont connues — chacune a son geste de rassurance adapté", "offline": "Le geste est pratiqué sur 3 profils d'inquiétude différents — nommer et adapter est un réflexe", "online": "Le coach a observé et débriefé la gestion de l'inquiétude en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/3- Créer du lien/Rassurer et adapter sa prise en charge.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('63ffd509-c955-574f-8a89-313e58c5bfc6', 'd9785f3a-4457-54cc-be33-f69534a54656');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('63ffd509-c955-574f-8a89-313e58c5bfc6', 'bc0b28ed-80d1-5aa0-9883-fb2beb3054c0');
insert into public.library_dojos (id, title, content, pptx_path) values ('f7d08e38-05a9-5623-a5fd-748c31913f37', 'L''essai véhicule', $dojo${"version": 1, "tagline": "Conduire et exploiter l'essai comme levier de vente", "objective": "Le commercial sait structurer un essai en 4 temps, exploiter les sensations en les reliant à la découverte, et poser la question de closing avant de sortir du véhicule.", "duration": "30-40 min", "theory": {"intro": "L'essai n'est pas une promenade — c'est un acte commercial structuré. Chaque minute au volant doit servir à renforcer le désir d'achat, ancrer les bénéfices dans le ressenti, et préparer le closing.", "standardTitle": "Le standard : l'essai en 4 temps", "standard": [{"label": "AVANT", "title": "Préparer l'essai", "description": "Préparer le véhicule (propre, plein, climatisation). Briefer le client sur le parcours. Rappeler 1-2 points clés à ressentir : \"Pendant l'essai, faites attention à [point découverte].\"", "why": "Le client qui sait quoi observer ressent plus — et valide des bénéfices qu'il a lui-même identifiés."}, {"label": "DÉPART", "title": "Lancer l'essai", "description": "Se taire les 2 premières minutes. Laisser le client s'installer, ressentir, toucher. Poser une question ouverte après le démarrage : \"Alors, comment vous sentez-vous à bord ?\"", "why": "Les premières secondes sont émotionnelles. Parler coupe le ressenti. Le silence est commercial."}, {"label": "PENDANT", "title": "Exploiter pendant l'essai", "description": "Pointer les bénéfices au moment où le client les ressent : \"Vous sentez comme ça passe bien les dos d'âne — c'est exactement ce que vous me disiez sur votre route de montagne.\"", "why": "Le bénéfice ressenti physiquement au moment où on le nomme crée une ancre mémorielle forte."}, {"label": "RETOUR", "title": "Conclure l'essai", "description": "Sur le parking, avant de sortir du véhicule : \"Alors, comment vous avez trouvé ? Qu'est-ce qui vous a le plus convaincu ?\" Laisser le client verbaliser son ressenti positif.", "why": "Le client qui dit lui-même ce qu'il a aimé se convainc lui-même. C'est la base du closing par l'essai."}], "criteria": [{"title": "Il prépare le véhicule ET le client", "description": "Un véhicule propre et plein, c'est le minimum. Un client briefé sur ce qu'il va ressentir, c'est le niveau au-dessus. Le commercial qui dit \"faites attention à la tenue de route\" oriente l'attention."}, {"title": "Il se tait au démarrage", "description": "Les 2 premières minutes appartiennent au client. Le commercial qui parle immédiatement coupe l'expérience sensorielle. Le silence crée de l'espace pour ressentir — et pour vendre."}, {"title": "Il relie les sensations à la découverte", "description": "\"Vous sentez ce silence à 110 km/h — c'est exactement ce que vous me disiez sur vos longs trajets.\" Chaque sensation devient une preuve de bénéfice ancré dans un besoin réel."}, {"title": "Il fait parler le client pendant et après", "description": "\"Qu'est-ce que vous en pensez jusqu'ici ?\" / \"Comment vous sentez-vous ?\" Le client qui verbalise ses ressentis positifs se convainc lui-même et facilite la transition vers le closing."}, {"title": "Il conclut avant de sortir du véhicule", "description": "La question de closing se pose sur le parking, dans le véhicule, avant de rentrer. \"Alors — c'est le bon ?\" Le désir est au maximum à ce moment-là. Rentrer en concession fait redescendre."}], "mistakes": [{"title": "Erreur 1 — Parler trop pendant l'essai", "description": "Le commercial qui commente chaque virage, chaque équipement, chaque panneau de circulation transforme l'essai en démo technique. Le client n'a plus le temps de ressentir — il écoute. Or c'est lui qui doit vivre l'expérience."}, {"title": "Erreur 2 — Ne pas relier les sensations à la découverte", "description": "\"Le moteur est puissant, non ?\" ne vaut rien si le client ne fait pas le lien avec son besoin. Sans ancrage dans la découverte, les sensations sont agréables mais pas convaincantes. Ce n'est pas un essai, c'est une balade."}, {"title": "Erreur 3 — Rentrer en concession sans conclure", "description": "Rentrer, proposer un café, et seulement là demander \"alors qu'est-ce que vous en avez pensé ?\" — c'est rater la fenêtre de closing. Le désir est au pic sur le parking. Chaque minute qui passe le fait redescendre."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario adapté au niveau. Préparer un véhicule disponible pour la simulation ou travailler en jeu de rôle dans la concession en simulant les étapes à l'oral. Donner les infos de découverte du client fictif."}, {"title": "Lancer le scénario", "description": "\"Je suis ton client. Tu viens de me montrer le véhicule. On va faire l'essai maintenant — tu te comportes exactement comme si c'était un vrai essai.\" Observer sans intervenir pendant toute la durée."}, {"title": "Débriefer", "description": "\"Pendant l'essai, combien de fois tu as parlé ? Est-ce que tu as relié ce que je ressentais à ce que je t'avais dit en découverte ? Qu'est-ce que tu m'as demandé sur le parking ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain essai, tu t'engages sur quoi ? Je veux qu'on se redonne rdv après — tu me racontes comment ça s'est passé sur le parking, et ce que le client t'a dit.\""}], "scenarios": [{"level": "debutant", "title": "Le primo-accédant enthousiaste", "objective": "Maîtriser la structure des 4 temps : préparer, silence au démarrage, relier 1 sensation à la découverte, poser la question de closing sur le parking.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 27 ans, premier achat personnel, salarié en CDI depuis 1 an. Budgete serré à 250€/mois."}, {"label": "Comportement", "text": "Enthousiaste, pose beaucoup de questions, facilement impressionnable. Il veut être rassuré que c'est le bon choix."}, {"label": "Motivation principale", "text": "Autonomie, fierté d'avoir sa propre voiture, économies sur les transports."}, {"label": "Frein / objection probable", "text": "\"Je suis pas sûr d'en avoir besoin...\" — doute de dernière minute sur la nécessité."}, {"label": "Véhicule actuel", "text": "N'a pas de voiture. Utilise les transports en commun + covoiturage."}], "context": "La découverte a révélé : 25 km de trajet domicile-travail, pas de voiture sur le lieu de travail, concerts le week-end en dehors de Paris, budget carburant important. Véhicule sélectionné : citadine hybride compacte.", "stakes": "L'essai se déroule sur un parcours court : 10 min en ville + périphérique. Le client est nerveux au démarrage car il conduit peu. Il s'installe en prenant le temps de régler les rétroviseurs.", "observe": ["Le commercial prépare-t-il l'essai en rappelant 1 point à ressentir ?", "Garde-t-il le silence les 2 premières minutes ?", "Relie-t-il au moins 1 sensation à la découverte ?", "Pose-t-il la question de closing sur le parking avant de rentrer ?"]}, {"level": "intermediaire", "title": "La cliente pressée qui hésite entre deux modèles", "objective": "Exploiter l'essai pour trancher entre deux modèles, utiliser les sensations comme arguments de différenciation, gérer la comparaison sans dénigrer l'alternative.", "duration": "35 min", "persona": [{"label": "Profil", "text": "Femme, 38 ans, cadre, mère de 2 enfants (8 et 11 ans). Habituée de la concession, 3ème achat ici."}, {"label": "Comportement", "text": "Directe, peu de temps, a déjà fait ses recherches en ligne. Compare précisément deux modèles. Méfiante vis-à-vis de l'argumentaire commercial classique."}, {"label": "Motivation principale", "text": "Praticité, fiabilité, image professionnelle. Veut quelque chose qu'elle n'aura pas à ramener en SAV."}, {"label": "Frein / objection probable", "text": "\"L'autre modèle a l'air plus spacieux à l'arrière pour les enfants.\" Comparaison concurrente en tête."}, {"label": "Véhicule actuel", "text": "Citroën C5 Aircross de 4 ans — bien entretenu, revente prévue."}], "context": "Découverte : beaucoup d'autoroute (Paris-Lyon régulièrement), enfants à emmener, image professionnelle importante pour ses rendez-vous clients, veut se sentir en sécurité la nuit. Budget : 550€/mois.", "stakes": "Elle a essayé le modèle concurrent la semaine dernière. Elle comparera pendant tout l'essai. Le commercial doit orienter l'attention sur les points différenciants favorables sans mentionner l'autre véhicule négativement.", "observe": ["Oriente-t-il l'attention sur les points forts spécifiques à ce véhicule avant de partir ?", "Gère-t-il les comparaisons pendant l'essai sans dénigrer la concurrence ?", "Relie-t-il les sensations aux besoins découverts (autoroute, image, sécurité) ?", "Conclut-il avant de sortir du véhicule malgré la résistance ?"]}, {"level": "avance", "title": "Le client rationnel qui ne veut pas s'emballer", "objective": "Travailler l'essai avec un client qui verbalise peu, qui contrôle ses émotions, et amener le closing sans question directe — en utilisant des questions ouvertes sur le ressenti.", "duration": "40 min", "persona": [{"label": "Profil", "text": "Homme, 52 ans, ingénieur, rationnel, peu expressif. Achète un véhicule tous les 6 ans, ne décide jamais sur le coup."}, {"label": "Comportement", "text": "Silencieux pendant l'essai, observe tout, répond par des phrases courtes. Dit \"très bien\" à tout même quand il n'est pas convaincu. Difficile à lire émotionnellement."}, {"label": "Motivation principale", "text": "Fiabilité long terme, coût total de possession, rapport qualité/prix. Veut être sûr de ne pas se tromper."}, {"label": "Frein / objection probable", "text": "\"Je vais réfléchir\" est sa phrase par défaut. Ne décide jamais en séance."}, {"label": "Véhicule actuel", "text": "Toyota Prius 2018 — 145 000 km. Il a gardé 6 ans la précédente."}], "context": "Découverte longue et riche : 40 000 km/an principalement autoroute, coût carburant très important (700€/mois actuellement), mécontent de l'acoustique de sa Prius sur autoroute, apprécie les longues distances confortables. Véhicule sélectionné : berline hybride haut de gamme.", "stakes": "Le commercial doit gérer le silence du client, l'amener à verbaliser ses ressentis par des questions courtes et précises, et ne pas paniquer face au manque de retour émotionnel visible. La question de closing devra être indirecte.", "observe": ["Gère-t-il confortablement le silence du client sans parler pour combler ?", "Pose-t-il des questions courtes et précises pour faire verbaliser (\"Et là, le son ?\") ?", "Relie-t-il les sensations à l'acoustique et au confort longue distance mentionnés ?", "Formule-t-il un closing indirect adapté (\"Vous vous voyez faire Paris-Lyon là-dedans ?\") ?"]}]}, "online": {"focus": "la conduite de l'essai", "attentionPoints": ["Le commercial prépare-t-il le client avant de démarrer ?", "Garde-t-il le silence les 2 premières minutes ?", "Relie-t-il les sensations aux éléments de la découverte ?", "Pose-t-il la question de closing sur le parking, avant de rentrer ?"], "grid": ["Prépare le client avant l'essai", "Silence les 2 premières minutes", "Relie sensations à la découverte", "Closing sur le parking"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Combien de fois tu as parlé dans les 2 premières minutes ? Est-ce que tu as relié une sensation à ce que le client t'avait dit ? Qu'est-ce que tu lui as demandé sur le parking ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand le client a souri en prenant le virage, tu as dit [phrase précise]. C'est exactement ça — tu as transformé un ressenti en argument de vente ancré dans sa découverte.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as posé la question de closing en rentrant en concession — c'est 3 minutes trop tard]. Sur le parking, avant de sortir du véhicule, dis juste : 'Alors, c'est le bon ?'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain essai, tu t'engages sur quoi précisément ? Je veux que tu viennes me voir après avec une phrase que tu as utilisée sur le parking. Date du retour : [date].\""}], "sections": []}, "takeaways": {"theory": "L'essai en 4 temps est connu — préparer, silence, relier, conclure sur le parking", "offline": "Le geste a été travaillé sur 3 niveaux de difficulté — le réflexe est ancré", "online": "Le coach a observé et débriefé l'essai en situation réelle avec précision", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/4- Sélection et argu/L''essai véhicule.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('f7d08e38-05a9-5623-a5fd-748c31913f37', '2b19061e-06d5-5e93-bc67-accb9dbcdd34');
insert into public.library_dojos (id, title, content, pptx_path) values ('a163be47-77fe-52a0-bdf9-4c8d26304d49', 'Méthode CAB Véhicule', $dojo${"version": 1, "tagline": "Caractéristiques → Avantages → Bénéfices client", "objective": "Le commercial sait construire 3 CAB complets avec le bénéfice ancré dans la découverte, utiliser les formules de liaison naturellement, et finir chaque CAB par une question d'adhésion.", "duration": "25-35 min", "theory": {"intro": "La méthode CAB transforme une caractéristique technique en argument de vente personnalisé. Une caractéristique seule ne convainc pas — c'est le bénéfice client, ancré dans ses besoins découverts, qui déclenche l'envie.", "standardTitle": "Le standard : la structure CAB", "standard": [{"label": null, "title": "C", "description": "Caractéristique", "why": "Définition"}, {"label": null, "title": "Le fait technique, objectif, mesurable.", "description": "Exemple", "why": "\"Ce véhicule est équipé d'une motorisation hybride rechargeable de 180 ch.\""}, {"label": null, "title": "Neutre. Le client ne sait pas encore pourquoi ça le concerne.", "description": "A", "why": "Avantage"}, {"label": null, "title": "Définition", "description": "Ce que ça permet de faire grâce à cette caractéristique.", "why": "Exemple"}, {"label": null, "title": "\"Ce qui vous permet de rouler jusqu'à 60 km en mode 100% électrique.\"", "description": "Plus parlant, mais encore générique — tout le monde a le même avantage.", "why": "B"}, {"label": null, "title": "Bénéfice", "description": "Définition", "why": "Ce que ça apporte SPÉCIFIQUEMENT à ce client, selon sa découverte."}, {"label": null, "title": "Exemple", "description": "\"Et comme vous faites surtout des trajets domicile-travail de 30 km — vous ne dépensez quasiment plus rien en carburant.\"", "why": "C'est ici que la vente se fait. Le bénéfice n'existe que s'il est ancré dans la découverte."}], "criteria": [{"title": "Le B est ancré dans la découverte", "description": "Le bénéfice n'est pas générique — il reprend mot pour mot ce que le client a dit. \"Comme vous m'avez dit que...\" est la charnière qui personnalise tout."}, {"title": "Maximum 3 CAB par présentation", "description": "Trop d'arguments tuent l'argument. Le commercial choisit les 3 caractéristiques les plus pertinentes pour ce client, pas celles qu'il préfère personnellement."}, {"title": "La formule de liaison est naturelle", "description": "\"Ce qui vous permet de...\" / \"Et comme vous m'avez dit que...\" / \"Concrètement pour vous ça veut dire que...\" — ces formules doivent sonner naturel, pas récité."}, {"title": "Il finit sur une question d'adhésion", "description": "Après chaque CAB complet : \"Ça correspond à ce que vous cherchez ?\" Le client qui valide s'engage progressivement vers la décision d'achat."}, {"title": "Il adapte le registre au profil client", "description": "Avec un client technique : la C peut être détaillée. Avec un client émotionnel : on saute la C et on va directement au bénéfice ressenti."}], "mistakes": [{"title": "Erreur 1 — S'arrêter à la caractéristique", "description": "\"Ce véhicule a 7 places.\" — point final. Le client sait que ça existe, il a besoin de savoir pourquoi c'est bien POUR LUI. Sans le B, la présentation ressemble à une fiche technique."}, {"title": "Erreur 2 — Un bénéfice générique qui ne vient pas de la découverte", "description": "\"Vous pourrez emmener toute la famille.\" sans que le client ait parlé de sa famille. Le commercial invente un besoin au lieu d'en utiliser un réel — le client le sent et se déconnecte."}, {"title": "Erreur 3 — Trop de caractéristiques, pas assez de bénéfices", "description": "Lister 8 équipements d'affilée noie le client. Chaque C doit être suivie de son A et surtout de son B. Mieux vaut 3 CAB complets qu'une liste de 10 caractéristiques orphelines."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Sortir une fiche technique d'un véhicule de la gamme. Donner au commercial les infos de découverte du client fictif du scénario choisi. Lui demander de préparer 3 CAB avant la séance."}, {"title": "Lancer le scénario", "description": "\"Je suis ton client. Tu viens de me montrer le véhicule. Présente-le moi — je veux entendre au moins 3 CAB complets. Utilise ce que tu sais de ma découverte.\" Jouer le client attentif, ne pas aider."}, {"title": "Débriefer", "description": "\"Sur chaque CAB : est-ce que le bénéfice venait vraiment de ce que le client t'avait dit, ou c'était générique ? Refais-moi le meilleur CAB que tu as fait — en le soignant.\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client, tu t'engages à faire au moins 2 CAB avec le B ancré dans sa découverte. Reviens me voir avec un exemple concret que tu as utilisé. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Le primo-accédant sensible au budget", "objective": "Construire 3 CAB complets où le B reprend explicitement les mots du client liés au budget et aux économies. Utiliser la formule de liaison \"comme vous m'avez dit que...\" sur chaque B.", "duration": "25 min", "persona": [], "context": null, "stakes": null, "observe": ["Le B reprend-il les mots \"budget\" / \"économies\" / \"coût\" entendus en découverte ?", "Utilise-t-il la formule \"comme vous m'avez dit que...\" sur chaque bénéfice ?", "Fait-il minimum 3 CAB complets sans s'arrêter à la caractéristique ?", "Finit-il chaque CAB par une question d'adhésion ?"]}, {"level": "intermediaire", "title": "La cliente famille sensible à la sécurité", "objective": "Construire des CAB dont le B va chercher l'émotion sécurité/protection, pas juste la technique. Adapter le registre au profil émotionnel du client — moins de C, plus de B ressentis.", "duration": "30 min", "persona": [], "context": null, "stakes": null, "observe": ["Le B va-t-il chercher l'émotion (\"vous ne vous inquiétez plus\") plutôt que la technique ?", "Adapte-t-il le niveau de détail de la C au profil non-technique de la cliente ?", "Relie-t-il les équipements sécurité à l'accrochage et aux enfants mentionnés ?", "Évite-t-il le jargon technique sur les CAB orientés sécurité ?"]}, {"level": "avance", "title": "L'acheteur expert qui contre-argumente", "objective": "Construire des CAB avec des C solides et chiffrées face à un client qui questionne, maintenir la structure C → A → B sans se laisser déstabiliser, et gérer les contre-arguments sans abandonner le bénéfice.", "duration": "35 min", "persona": [], "context": null, "stakes": null, "observe": ["Ses C sont-elles précises et chiffrées pour résister aux contre-arguments ?", "Maintient-il la structure C → A → B même quand le client interrompt ?", "Relie-t-il les B aux 650€/mois de carburant et au silence acoustique mentionnés ?", "Gère-t-il les contre-arguments sans abandonner le bénéfice (\"vous avez raison, et...\") ?"]}]}, "online": {"focus": "la méthode CAB", "attentionPoints": ["Le commercial structure-t-il ses arguments en C → A → B ?", "Le bénéfice est-il ancré dans ce que le client a dit en découverte ?", "Utilise-t-il la formule de liaison (\"comme vous m'avez dit...\") ?", "Finit-il sur une question d'adhésion après chaque CAB ?"], "grid": ["Structure C → A → B respectée", "Bénéfice ancré en découverte", "Formule de liaison utilisée", "Question d'adhésion posée"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Sur chaque CAB que tu as fait — est-ce que le bénéfice venait vraiment de ce que le client t'avait dit ? Lequel était le plus fort selon toi ? Lequel était encore trop générique ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que sur [équipement précis], tu as dit 'comme vous m'avez dit que [élément découverte]'. C'est exactement ça — le client a acquiescé, il sentait que c'était pour lui.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tes B étaient encore génériques]. Essaie cette formule : 'Et comme vous m'avez dit que [mot exact du client], concrètement pour vous ça veut dire que...'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client, tu t'engages à faire au moins 2 CAB avec le B ancré dans ses mots. Reviens me voir avec un exemple précis que tu as utilisé. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "La structure C → A → B est connue — le B ancré dans la découverte est la clé", "offline": "Le geste a été pratiqué sur 3 profils différents — les formules de liaison sonnent naturel", "online": "Le coach a observé et débriefé la qualité des CAB en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/4- Sélection et argu/Méthode CAB véhiucle.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('a163be47-77fe-52a0-bdf9-4c8d26304d49', '3485f79f-9e33-59aa-af7c-73ad467dda9a');
insert into public.library_dojos (id, title, content, pptx_path) values ('b5623eac-f435-52fa-8ad4-513970a969d4', 'Trouver le véhicule adapté', $dojo${"version": 1, "tagline": "Reformuler les besoins pour choisir juste — en 3 phases", "objective": null, "duration": null, "theory": {"intro": "Avant de montrer un seul véhicule, le bon commercial reformule ce qu'il a compris. C'est ce geste qui crée la confiance, légitime le conseil et évite les allers-retours inutiles dans le parc.", "standardTitle": "Le standard : la reformulation en 3 temps", "standard": [{"label": "1", "title": "Reformuler les usages", "description": "\"Si j'ai bien compris, vous utilisez votre véhicule principalement pour [usage principal] — c'est bien ça ?\"", "why": "Valider la compréhension, montrer qu'on a écouté, pas seulement entendu."}, {"label": "2", "title": "Reformuler les critères", "description": "\"Vous m'avez dit que pour vous les points importants c'est [critère 1] et [critère 2] — je me trompe ?\"", "why": "Hiérarchiser les besoins réels vs les envies exprimées. Le client confirme ou corrige."}, {"label": "3", "title": "Annoncer la sélection", "description": "\"Sur cette base, j'ai le véhicule qui correspond exactement à ce que vous cherchez — je vous emmène le voir ?\"", "why": "Créer l'anticipation et positionner le véhicule comme une réponse sur-mesure, pas une proposition au hasard."}], "criteria": [{"title": "Il reformule AVANT de montrer", "description": "Le commercial ne dit jamais \"suivez-moi\" sans avoir d'abord verbalisé ce qu'il a compris. La sélection doit sembler évidente, pas aléatoire."}, {"title": "Il utilise les mots du client", "description": "Il reprend les termes exacts de la découverte : si le client a dit \"pratique pour les vacances\", il dit \"pratique pour les vacances\" — pas \"polyvalent\" ou \"spacieux\"."}, {"title": "Il hiérarchise et switche si nécessaire", "description": "Si la découverte révèle que le besoin réel ne correspond pas au véhicule demandé, il l'annonce avec assertivité : \"Sur la base de ce que vous m'avez dit, j'aurais une suggestion différente...\""}, {"title": "Il crée l'anticipation", "description": "La phrase d'annonce du véhicule doit générer une envie de le voir. \"J'ai exactement ce qu'il vous faut\" est plus fort que \"je vais vous montrer quelque chose\"."}, {"title": "Il valide avant d'aller plus loin", "description": "Un simple \"c'est bien ça ?\" ou \"je me trompe ?\" après la reformulation suffit. Le client qui confirme s'engage — il devient acteur de son choix."}], "mistakes": [{"title": "Erreur 1 — Montrer sans reformuler", "description": "\"Suivez-moi, j'ai ce qu'il vous faut.\" — sans avoir verbalisé pourquoi. Le client suit, mais il ne sait pas s'il est entre de bonnes mains. La confiance ne se crée pas."}, {"title": "Erreur 2 — Montrer le mauvais véhicule par peur de contrarier", "description": "Le client demande un SUV mais ses usages indiquent clairement qu'une berline est plus adaptée. Le commercial qui ne switche pas par peur du conflit rate la vente — ou vend mal."}, {"title": "Erreur 3 — Reformuler trop long ou trop scolaire", "description": "Réciter tous les points de la découverte comme un compte-rendu tue la dynamique. La reformulation doit être fluide, conversationnelle — 2-3 points clés maximum, pas un résumé exhaustif."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer le commercial : \"Tu viens de faire une découverte complète — je t'ai donné les infos. Tu dois maintenant reformuler et me proposer le bon véhicule. Je joue le client.\""}, {"title": "Lancer le scénario", "description": "Jouer le client naturellement, sans aider. Laisser les silences. Si le commercial montre un véhicule sans reformuler, noter sans interrompre — le debrief en parlera."}, {"title": "Débriefer", "description": "Commencer par : \"Est-ce que tu as reformulé avant de montrer ? Qu'est-ce que tu as dit exactement ?\" Valoriser la reformulation si elle existe. Corriger la forme si besoin."}, {"title": "Fixer la prochaine étape", "description": "Engagement concret : \"La prochaine fois qu'un client entre, tu t'engages à reformuler avant de te lever. On fait un point vendredi sur comment ça s'est passé.\""}], "scenarios": [{"level": "Scénarios — À piocher selon le profil", "title": "Choisir 1 scénario / séance", "objective": null, "duration": null, "persona": [], "context": null, "stakes": null, "observe": []}]}, "online": {"focus": "la reformulation véhicule", "attentionPoints": ["Le commercial reformule-t-il avant de se lever pour montrer le véhicule ?", "Utilise-t-il les mots et termes de la découverte du client ?", "Propose-t-il le bon véhicule ou cède-t-il à la demande sans questionner ?", "Valide-t-il la reformulation avec le client (\"c'est bien ça ?\") ?"], "grid": ["Reformule avant de montrer", "Utilise les mots du client", "Propose le bon véhicule", "Valide la reformulation"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Est-ce que tu as reformulé avant de proposer un véhicule ? Qu'est-ce que tu as dit exactement ? Tu penses que le client a compris pourquoi tu lui montrais ce véhicule ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que tu as [point précis de reformulation]. C'est exactement ça — le client a acquiescé, il était avec toi.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as montré le véhicule sans annoncer pourquoi]. La prochaine fois, dis juste : 'Sur la base de ce que vous m'avez dit sur [usage], j'ai ce qu'il vous faut.'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Dès ton prochain client, tu t'engages sur quoi ? On se redonne rdv le [date] — tu me diras comment ça s'est passé.\""}], "sections": []}, "takeaways": {"theory": "La reformulation en 3 temps est connue — usages, critères, annonce du véhicule", "offline": "Le geste a été travaillé en sécurité — reformuler avant de montrer est un réflexe", "online": "Le coach a observé et débriefé la reformulation en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/4- Sélection et argu/Trouver un véhicule adapté.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('b5623eac-f435-52fa-8ad4-513970a969d4', '1192fc41-b066-57bb-8539-af2a45d8eb24');
insert into public.library_dojos (id, title, content, pptx_path) values ('ded1a243-8ea4-5737-9608-6484ae2255bf', 'Traitement des objections — introduction', $dojo${"version": 1, "tagline": "La séquence complète — A.R.E. → Exploration → R.A.C.", "objective": null, "duration": null, "theory": {"intro": null, "standardTitle": null, "standard": [], "criteria": [], "mistakes": [], "sections": [{"title": "Une objection n'est pas un refus", "lines": ["\"C'est trop cher\", \"Je dois réfléchir\", \"J'ai vu moins cher ailleurs\" — ces phrases ne sont pas des refus. Ce sont des demandes d'information ou de réassurance déguisées. Un client qui objecte est encore là. Un client qui part sans rien dire, lui, a refusé.", "01", "Une objection = un signal d'intérêt", "Un client indifférent ne prend pas la peine d'objecter. Il part. Celui qui objecte veut être convaincu — il cherche une raison de dire oui, pas de dire non. L'objection est souvent le dernier obstacle avant la décision.", "02", "La réponse immédiate est toujours la mauvaise", "Le réflexe de contre-argumenter à chaud signale qu'on était en mode attente-et-riposte. Le client le perçoit comme un combat. La première action est toujours d'accuser réception — pas de répondre.", "03", "La bonne réponse dépend du type d'objection", "Une objection fondée, un prétexte et un réflexe ne se traitent pas de la même façon. Répondre à un prétexte comme à une objection fondée ne fait qu'augmenter la résistance. Qualifier d'abord — toujours."]}, {"title": "La séquence complète de traitement", "lines": ["Chaque objection suit la même séquence en 3 temps. Les 3 Dojos suivants approfondissent chacun de ces temps. Ce Dojo donne la vision d'ensemble — pour que le commercial comprenne pourquoi chaque étape existe.", "A.R.E.", "1", "Accuser Réception — sans combattre", "Accuser réception  •  Reformuler  •  Explorer", "Avant toute réponse : montrer qu'on a entendu. \"Je comprends\" dit avec sincérité. Reformuler pour valider la compréhension. Poser une question ouverte pour explorer ce qui se cache derrière.", "Signal de réussite : le client développe son objection au lieu de la répéter plus fort.", "Dojo : Comprendre l'objection", "QUALIFICATION", "2", "Qualifier le type d'objection", "Fondée  •  Prétexte  •  Réflexe", "La réponse à apporter dépend entièrement du type d'objection. Une fondée réclame un argument. Un prétexte réclame une question qui révèle le vrai frein. Un réflexe se dissout souvent avec une question ouverte courte.", "Signal de réussite : le commercial sait exactement à quoi il répond avant de répondre.", "Dojo : Déceler l'objection fondée", "R.A.C.", "3", "Répondre & confirmer la levée du frein", "Reconnaître  •  Apporter  •  Confirmer", "Reconnaître la légitimité du doute. Apporter la réponse adaptée, ancrée dans la découverte du client. Confirmer que le frein est levé avant de continuer — ne jamais supposer.", "Signal de réussite : le client valide explicitement (\"ah oui d'accord\") et la dynamique repart.", "Dojo : Argumenter & rassurer", "ÉTAPE", "CE QU'ON FAIT", "SIGNAL DE RÉUSSITE"]}, {"title": "Les 3 types d'objection — et pourquoi ça change tout", "lines": ["Répondre à une objection sans savoir de quel type elle est, c'est comme prescrire un médicament sans diagnostic. La qualification est l'étape que la plupart des commerciaux sautent — et c'est là que se perdent la plupart des ventes.", "FONDÉE", "Définition", "Le client a une vraie raison de douter. Le frein est réel et légitime.", "Exemple auto", "\"Ce coffre est vraiment trop petit pour moi — je transporte du matériel tous les jours.\"", "Signal", "Il peut l'expliquer précisément. Son non-verbal est cohérent avec ses mots.", "Réponse", "Argument ancré dans sa découverte. Preuve si c'est factuel. CAB si c'est sur la valeur.", "Erreur à éviter", "Ne pas répondre ou minimiser. C'est la seule objection qui mérite un vrai argument.", "PRÉTEXTE", "Définition", "L'objection formulée cache un autre frein — souvent émotionnel ou relationnel.", "Exemple auto", "\"C'est trop cher\" dit par quelqu'un dont le vrai frein est qu'il doit en parler à sa femme.", "Signal", "Vague, non développée. L'objection ne tient pas sous une question ouverte.", "Réponse", "\"Si ce point était résolu, qu'est-ce qui changerait ?\" — révéler le vrai frein, traiter lui.", "Erreur à éviter", "Argumenter sur le prix alors que le problème est ailleurs. Efficacité zéro.", "RÉFLEXE", "Définition", "Objection automatique posée par habitude, sans raison précise.", "Exemple auto", "\"Je vais réfléchir\" dit par quelqu'un qui n'a pas de vraie raison de différer.", "Signal", "Ton neutre ou légèrement distant. Se dissout facilement sous une question ouverte.", "Réponse", "\"Qu'est-ce qui vous retient ?\" suffit souvent à révéler qu'il n'y a rien de solide derrière.", "Erreur à éviter", "Argumenter longuement sur une objection qui n'existe pas vraiment. Crée un problème inexistant."]}, {"title": "L'erreur universelle — l'effet combat de boxe", "lines": ["❌  COMBAT DE BOXE — ce qui se passe sans A.R.E.", "CLIENT", "\"C'est vraiment trop cher pour ce que c'est.\"", "COMMERCIAL", "\"Oui mais regardez, en mensualités c'est seulement 290€.\"", "CLIENT", "\"Ça reste cher — j'ai vu moins cher ailleurs.\"", "COMMERCIAL", "\"Oui mais notre qualité est supérieure — et la garantie est de 2 ans.\"", "CLIENT", "\"Je vais réfléchir.\"", "Le client part — l'objection n'a jamais été vraiment entendue", "✅  AVEC A.R.E. → QUALIFICATION → R.A.C.", "CLIENT", "\"C'est vraiment trop cher pour ce que c'est.\"", "COMMERCIAL", "\"Je comprends — c'est-à-dire, c'est par rapport à quoi précisément ?\"", "CLIENT", "\"J'ai vu un modèle similaire 2 000€ moins cher chez un concurrent.\"", "COMMERCIAL", "\"C'était avec les mêmes équipements et la même garantie ? [écoute] — voilà ce qui explique la différence sur votre profil d'usage.\"", "CLIENT", "\"Ah, je vois — ça change les choses.\"", "Le frein est levé — la dynamique vers la décision repart"]}, {"title": "Les 3 Dojos qui approfondissent cette séquence", "lines": ["Ce Dojo pose la vision d'ensemble. Chacun des 3 Dojos suivants zoome sur une étape et la pratique en profondeur avec 3 scénarios progressifs.", "A.R.E.", "Dojo 01", "Comprendre l'objection", "Maîtriser l'accusé de réception sans \"mais\", la reformulation précise, et la question d'exploration. Éviter l'effet combat de boxe dès les premières secondes.", "Scénarios", "3 scénarios : objection prix calme / \"je réfléchis\" / client agressif", "Formule clé : \"Je comprends — c'est-à-dire ?\"", "QUALIFICATION", "Dojo 02", "Déceler l'objection fondée", "Choisir la bonne question d'exploration, laisser le silence travailler, et qualifier le type d'objection avant de construire la réponse.", "Scénarios", "3 scénarios : prix transparent / \"trop cher\" comparatif / \"je réfléchis\" = couple", "Formule clé : \"C'est par rapport à quoi précisément ?\"", "R.A.C.", "Dojo 03", "Argumenter & rassurer", "Appliquer R.A.C. sur une objection qualifiée comme fondée. Ancrer l'argument dans la découverte. Confirmer que le frein est levé avant de continuer.", "Scénarios", "3 scénarios : fiabilité occasion / coût hybride / délai livraison tardif", "Formule clé : \"Est-ce que ça répond à ce qui vous préoccupait ?\""]}]}, "offline": {"guide": [], "scenarios": []}, "online": {"focus": null, "attentionPoints": [], "grid": [], "debrief": [], "sections": []}, "takeaways": {"theory": "Un client qui objecte est encore là. La réponse immédiate est toujours la mauvaise.", "offline": "A.R.E. pour accuser réception → Qualification pour identifier le type → R.A.C. pour répondre.", "online": "Fondée, prétexte ou réflexe — trois traitements différents. Qualifier avant de répondre.", "next": null}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/5- Traiter les objections/0. Traitement des objections.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('ded1a243-8ea4-5737-9608-6484ae2255bf', '6b9e6296-431d-58f1-9be5-ceb956794e11');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('ded1a243-8ea4-5737-9608-6484ae2255bf', 'a0c4a3ba-502f-55ca-97eb-17aea34b48c4');
insert into public.library_dojos (id, title, content, pptx_path) values ('ad2a34ab-aa67-572c-bc1b-af57218e1479', 'Comprendre l''objection', $dojo${"version": 1, "tagline": "Empathie & réception — accuser réception sans effet combat de boxe", "objective": "Le commercial applique la formule A.R.E. complète sur chaque objection : accuse réception sans \"mais\", reformule pour valider sa compréhension, et explore avant de répondre.", "duration": "25-30 min", "theory": {"intro": null, "standardTitle": "Le standard : les 3 types d'objection & la formule A.R.E.", "standard": [{"label": "Une objection n'est pas un refus — c'est une demande d'information ou de réassurance déguisée. Le premier geste n'est jamais de répondre. C'est d'accuser réception. La formule A.R.E. structure ce premier moment.", "title": "LES 3 TYPES", "description": "FONDÉE", "why": "Objection réelle"}, {"label": "Le client a une vraie raison de douter. Le prix est trop élevé pour son budget réel. Le coffre est trop petit pour ses usages. Elle nécessite une réponse argumentée.", "title": "PRÉTEXTE", "description": "Fausse objection", "why": "Le client dit \"c'est trop cher\" mais le vrai frein est la peur de s'engager. L'argument ne servira à rien si le vrai problème n'est pas identifié d'abord."}, {"label": "RÉFLEXE", "title": "Objection automatique", "description": "\"Je dois réfléchir\" — dit par habitude, par peur de décider trop vite, sans raison précise. Poser une question ouverte suffit souvent à la dissoudre.", "why": "LA FORMULE A.R.E. — Accuser Réception avant tout"}, {"label": "A", "title": "Accuser réception", "description": "\"Je comprends tout à fait.\" / \"C'est une remarque légitime.\" / \"Je vous entends.\"", "why": "Désarmer. Ne pas contre-attaquer. Le client qui se sent entendu baisse sa garde."}, {"label": "R", "title": "Reformuler", "description": "\"Si je comprends bien, ce qui vous préoccupe c'est [reformulation].\" — vérifier qu'on a bien compris.", "why": "Confirmer la compréhension. Éviter de répondre à côté. Montrer qu'on a vraiment écouté."}, {"label": "E", "title": "Explorer", "description": "\"C'est-à-dire ? / Qu'est-ce qui vous fait dire ça ? / C'est par rapport à quoi précisément ?\"", "why": "Avant de répondre : comprendre si c'est une objection fondée, un prétexte, ou un réflexe."}], "criteria": [{"title": "Il ne répond jamais à chaud", "description": "La première réaction à une objection n'est jamais une réponse. C'est un accusé de réception. Le commercial qui répond immédiatement envoie le signal qu'il était prêt à contre-attaquer — pas à comprendre."}, {"title": "Son accusé de réception est sobre et sincère", "description": "\"Je comprends\" dit en regardant le client dans les yeux vaut infiniment plus que \"Oui oui je vous entends mais...\" Le \"mais\" annule tout l'accusé de réception. Il n'existe pas dans la formule A.R.E."}, {"title": "Il reformule pour valider sa compréhension", "description": "\"Si je comprends bien, ce qui vous préoccupe c'est le prix mensuel — pas le prix total ?\" La reformulation précise évite de répondre à côté. Un commercial qui répond à l'objection qu'il a entendue, pas à celle exprimée, perd du temps et de la crédibilité."}, {"title": "Il explore avant de répondre", "description": "\"C'est-à-dire ?\" après la reformulation. Cette question ouverte courte invite le client à développer. La réponse à cette question révèle si l'objection est fondée, un prétexte ou un réflexe — et donc quelle réponse apporter."}, {"title": "Il ne montre pas qu'il attendait l'objection", "description": "Sortir une réponse toute prête dès que le client dit \"c'est trop cher\" signale qu'on était en mode attente-et-contre. Le client se sent pris dans un script. La réponse doit sembler construite pour lui, pas récitée."}], "mistakes": [{"title": "Erreur 1 — Répondre immédiatement sans accuser réception", "description": "\"C'est trop cher !\" — \"Oui mais regardez, en mensualités ça fait seulement 280€ par mois.\" Réponse immédiate = combat de boxe. Le client n'a pas été entendu. Il va répéter son objection plus fort pour être entendu. Le commercial a perdu la première manche."}, {"title": "Erreur 2 — Utiliser le \"mais\" qui annule tout", "description": "\"Je comprends tout à fait — MAIS notre véhicule est le meilleur rapport qualité-prix du marché.\" Le \"mais\" efface l'accusé de réception et signale qu'on n'a fait que sembler écouter. Remplacer par \"et\" ou \"en même temps\" : \"Je comprends — et je vais vous montrer pourquoi...\""}, {"title": "Erreur 3 — Répondre à l'objection de surface sans explorer", "description": "Traiter \"c'est trop cher\" comme une objection prix alors que le vrai frein est la peur de s'engager. Apporter des arguments chiffrés à quelqu'un dont le problème est émotionnel ne fait qu'augmenter la résistance. Explorer d'abord — toujours."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je vais jouer un client qui a une objection. Ton seul objectif sur cette séance : appliquer A.R.E. avant de répondre. Je te lève la main si tu réponds avant d'avoir fait les 3 étapes.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona jusqu'à l'objection. Poser l'objection avec l'énergie du persona — sans signal que c'est un exercice. Résister à l'envie d'aider si le commercial cherche. Observer : accuse-t-il réception ? Reformule-t-il ? Explore-t-il avant de répondre ?"}, {"title": "Débriefer", "description": "\"As-tu dit 'mais' dans ton accusé de réception ? Est-ce que tu as reformulé avant de répondre ? Est-ce que tu as exploré pour qualifier l'objection — fondée, prétexte, ou réflexe ? À quel type appartenait l'objection selon toi ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client : quand une objection arrive, temps de silence de 2 secondes avant de parler. Ces 2 secondes t'empêchent de répondre à chaud. Reviens me voir avec l'objection, ton A.R.E., et ce que ça a donné.\""}], "scenarios": [{"level": "debutant", "title": "L'objection prix classique dite calmement", "objective": "Appliquer A.R.E. dans l'ordre sur une objection simple : accuser réception sans \"mais\", reformuler précisément, poser une question d'exploration ouverte.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 35 ans, assistante RH. Calme, posée. Aborde l'objection directement, sans agressivité."}, {"label": "L'objection exprimée", "text": "\"C'est vraiment beaucoup plus cher que ce que j'avais prévu.\""}, {"label": "Non-verbal pendant l'objection", "text": "Ton neutre, regard direct. Pas de tension particulière — elle expose un fait."}, {"label": "Ce qui se cache derrière", "text": "Vraie contrainte budgétaire. Elle a un budget de 280€/mois et le véhicule proposé est à 340€/mois."}, {"label": "Ce qui le ferait avancer", "text": "Une explication sur la construction du prix et les options de financement adaptées à son budget."}], "context": "Le commercial vient de présenter le véhicule sélectionné. Il est 15h, ambiance calme. L'objection arrive après la présentation du prix.", "stakes": "Contexte idéal pour pratiquer la formule A.R.E. sans pression. L'enjeu : ne pas répondre immédiatement sur le prix, accuser réception avec sincérité, reformuler pour confirmer que c'est bien le budget mensuel qui pose problème, et explorer avant de proposer une solution.", "observe": ["Accuse-t-il réception sans utiliser le mot \"mais\" ?", "Reformule-t-il l'objection pour valider sa compréhension ?", "Pose-t-il une question d'exploration avant de répondre ?", "Qualifie-t-il correctement : objection fondée sur le budget réel ?"]}, {"level": "intermediaire", "title": "L'objection \"je dois réfléchir\" de fin de RDV", "objective": "Identifier une objection réflexe, accuser réception sans brusquer, explorer pour comprendre ce qui se cache vraiment derrière, et ne pas forcer la décision.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 43 ans, gérant d'un commerce de quartier. Intéressé tout au long du RDV, puis se referme au moment de décider."}, {"label": "L'objection exprimée", "text": "\"C'est très bien tout ça — mais je vais quand même réfléchir. Je vous rappelle.\""}, {"label": "Non-verbal pendant l'objection", "text": "Regard qui fuit légèrement. Commence à récupérer ses affaires. Ton qui devient moins engagé. Sourire poli mais de recul."}, {"label": "Ce qui se cache derrière", "text": "Peur de s'engager sans avoir consulté sa femme. Il prend toutes les décisions importantes en couple — il ne l'a pas mentionné."}, {"label": "Ce qui le ferait avancer", "text": "La liberté de partir sans pression + une proposition claire pour la prochaine étape (rdv avec sa femme)."}], "context": "Fin de RDV, 17h30. Tout s'est bien passé — la découverte était riche, le véhicule correspondait bien. Le commercial sentait que ça allait se conclure. L'objection arrive au moment de signer.", "stakes": "L'enjeu : résister à l'envie de \"forcer\" la décision, accuser réception de l'hésitation avec légèreté, explorer avec une question ouverte courte (\"qu'est-ce qui vous retient ?\"), et créer les conditions d'un retour.", "observe": ["Résiste-t-il à l'envie de forcer la décision ?", "Accuse-t-il réception de l'hésitation sans pression ?", "Explore-t-il ce qui se cache derrière \"je réfléchis\" ?", "Crée-t-il les conditions d'un retour sans créer de pression ?"]}, {"level": "avance", "title": "L'objection agressive — \"on essaie de m'avoir\"", "objective": "Accuser réception d'une objection formulée avec agressivité sans entrer dans le rapport de force, maintenir la posture calme, et transformer la tension en exploration.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 51 ans, chef d'équipe BTP. Habitué à négocier, méfiant, teston. Teste les limites dès le départ."}, {"label": "L'objection exprimée", "text": "\"Franchement j'ai l'impression qu'on essaie de me vendre un truc trop cher — j'ai vu le même modèle 2 000€ moins cher ailleurs.\""}, {"label": "Non-verbal pendant l'objection", "text": "Ton qui monte légèrement. Bras croisés. Regard frontal, intense. S'attend à ce que le commercial se déstabilise ou se justifie."}, {"label": "Ce qui se cache derrière", "text": "Technique de négociation classique. Il veut voir comment le commercial gère la pression — et potentiellement obtenir un geste commercial."}, {"label": "Ce qui le ferait avancer", "text": "Une posture calme et assurée qui ne rentre pas dans le jeu. Un accusé de réception sobre et direct, suivi d'une exploration factuelle."}], "context": "Milieu de RDV. Le commercial vient de finir la présentation du prix. Le client avait semblé intéressé — l'objection arrive comme un coup de théâtre pour tester la réaction.", "stakes": "L'enjeu majeur : ne pas se justifier immédiatement, ne pas devenir défensif, ne pas baisser le prix par réflexe. Accuser réception avec calme et assurance, reformuler factuellement, et explorer : \"Le modèle que vous avez vu — c'était avec les mêmes équipements ?\"", "observe": ["Maintient-il une posture calme sans entrer dans le rapport de force ?", "Accuse-t-il réception sans se justifier ni baisser le prix ?", "Reformule-t-il factuellement sans dramatiser ?", "Explore-t-il la comparaison (équipements identiques ?) avant de répondre ?"]}]}, "online": {"focus": "la réception de l'objection", "attentionPoints": ["Applique-t-il A.R.E. dans l'ordre ?", "Utilise-t-il le \"mais\" qui annule l'accusé de réception ?", "Reformule-t-il pour valider sa compréhension ?", "Explore-t-il avant de répondre ?"], "grid": ["Accusé réception (sans \"mais\")", "Reformulation précise", "Question d'exploration", "Type d'objection qualifié"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Qu'est-ce que tu as dit en premier quand l'objection est arrivée ? Est-ce que tu as utilisé 'mais' ? Est-ce que tu as reformulé avant de répondre ? Tu as exploré — et qu'est-ce que ça t'a appris sur le type d'objection ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand l'objection est arrivée, tu as [action précise]. Le client a réagi en [observation]. Ce moment — accuser réception sans contre-attaquer — c'est exactement ça qui évite l'effet combat de boxe.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as dit 'oui mais' — le 'mais' annule tout]. La prochaine fois, remplace 'mais' par 'et' ou retire-le : 'Je comprends tout à fait — [pause] — qu'est-ce qui vous fait dire ça ?'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ta prochaine objection : 2 secondes de silence avant de parler. Note l'objection, ton accusé de réception exact, et si tu as exploré avant de répondre. Reviens me voir avec les 3 éléments. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 3 types d'objection et la formule A.R.E. sont connus — répondre à chaud n'existe plus", "offline": "Le geste est pratiqué sur 3 niveaux d'intensité — A.R.E. est un réflexe ancré", "online": "Le coach a observé et débriefé la réception de l'objection en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/5- Traiter les objections/a. Comprendre l''objection.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('ad2a34ab-aa67-572c-bc1b-af57218e1479', '6b9e6296-431d-58f1-9be5-ceb956794e11');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('ad2a34ab-aa67-572c-bc1b-af57218e1479', 'a0c4a3ba-502f-55ca-97eb-17aea34b48c4');
insert into public.library_dojos (id, title, content, pptx_path) values ('cbcd48de-dd32-5547-8d0b-a9daddc6c0d2', 'Déceler l''objection fondée', $dojo${"version": 1, "tagline": "Poser la bonne question ouverte pour qualifier le vrai frein", "objective": "Le commercial choisit la bonne question d'exploration, la pose sans la compléter, laisse le silence, écoute pour qualifier (fondée / prétexte / réflexe), confirme sa qualification avant de répondre.", "duration": "25-30 min", "theory": {"intro": null, "standardTitle": "Le standard : les 4 questions clés d'exploration", "standard": [{"label": "Après l'accusé de réception (étape A de A.R.E.), l'exploration sert à qualifier le vrai frein. La bonne question ouverte révèle si l'objection est fondée, un prétexte ou un réflexe — et oriente la réponse à apporter.", "title": "LA PLUS UTILE", "description": "\"C'est-à-dire ?\"", "why": "Quand : Sur n'importe quelle objection, immédiatement après l'accusé de réception."}, {"label": "Courte, neutre, puissante. Elle invite le client à développer sans orienter sa réponse. Révèle souvent en 10 secondes si c'est fondé ou un prétexte.", "title": "\"C'est trop cher.\" → \"Je comprends — c'est-à-dire ?\" → Le client dit \"le budget mensuel me dépasse\" ou \"j'ai vu moins cher ailleurs\" — deux problèmes complètement différents.", "description": "POUR PRÉCISER", "why": "\"Qu'est-ce qui vous fait dire ça ?\""}, {"label": "Quand : Quand l'objection est vague ou émotionnelle : \"ça me convainc pas\", \"je sais pas\".", "title": "Force le client à argumenter sa propre objection. Souvent, en cherchant à l'expliquer, le client réalise lui-même qu'elle ne tient pas — ou révèle le vrai frein.", "description": "\"Je suis pas convaincu.\" → \"Qu'est-ce qui vous fait dire ça ?\" → \"En fait je voulais aussi voir chez X\" — vrai frein = comparaison concurrente.", "why": "POUR DÉLIMITER"}, {"label": "\"C'est par rapport à quoi précisément ?\"", "title": "Quand : Quand l'objection est large et pourrait avoir plusieurs sources : \"c'est trop cher\", \"c'est compliqué\".", "description": "Évite de répondre à côté. \"Trop cher\" peut signifier budget mensuel, prix total, comparaison concurrente, ou simple négociation. Sans préciser, on répond à une objection imaginaire.", "why": "\"C'est trop cher.\" → \"C'est par rapport à quoi précisément — le prix total ou la mensualité ?\" → Le client pointe la mensualité — on sait où cibler la réponse."}, {"label": "POUR RELATIVISER", "title": "\"Si ce point était résolu, qu'est-ce qui changerait pour vous ?\"", "description": "Quand : Quand on suspecte que l'objection est un prétexte masquant un autre frein.", "why": "Si le client répond \"ben... je signerais\" — l'objection est fondée et résoudre ce point suffit. S'il dit \"ben... je sais pas\" — c'est un prétexte et le vrai frein est ailleurs."}, {"label": "\"C'est trop loin de chez moi.\" → \"Si la distance n'était pas un problème, qu'est-ce qui changerait ?\" → \"Ben j'aurais quand même besoin de réfléchir\" — c'est un prétexte.", "title": "QUESTION", "description": "POURQUOI ÇA MARCHE", "why": "EXEMPLE CONCRET"}], "criteria": [{"title": "Il pose une seule question d'exploration à la fois", "description": "Une seule question, puis silence. Attendre la réponse complète avant de relancer. Deux questions d'affilée créent de la confusion et donnent au client le choix de répondre à la plus facile — pas à la plus révélatrice."}, {"title": "Il laisse le silence travailler après la question", "description": "\"C'est-à-dire ?\" puis silence complet. Ne pas ajouter \"par rapport au prix ?\" ou \"vous trouvez que c'est trop cher ?\". Le silence invite à développer. Chaque mot ajouté oriente la réponse et ferme des possibilités."}, {"title": "Il écoute pour qualifier — pas pour construire sa réponse", "description": "Pendant que le client répond à la question d'exploration, le commercial écoute pour comprendre si c'est fondé, prétexte ou réflexe. Pas pour préparer sa contre-argumentation. Deux écoutes différentes — deux résultats différents."}, {"title": "Il confirme sa qualification avant de répondre", "description": "\"Si je comprends bien, ce qui vous préoccupe vraiment c'est [qualification].\" Cette confirmation évite de répondre à côté. Le client confirme ou corrige — le commercial sait exactement à quelle objection il doit répondre."}, {"title": "Il sait qu'un prétexte ne se traite pas comme une objection fondée", "description": "Si l'exploration révèle un prétexte (\"en fait j'ai besoin d'en parler à ma femme\"), répondre sur le prix ne sert à rien. Traiter le vrai frein — l'engagement en couple — est la seule réponse utile."}], "mistakes": [{"title": "Erreur 1 — Poser une question d'exploration fermée", "description": "\"C'est le prix qui vous pose problème ?\" oriente la réponse sur le prix — même si le vrai frein est ailleurs. Une question fermée suggère la réponse. Le client confirme souvent par défaut ce qu'on lui propose. Le vrai frein reste caché."}, {"title": "Erreur 2 — Combler le silence après la question d'exploration", "description": "\"C'est-à-dire ?... C'est par rapport au budget mensuel ?\" — en ajoutant cette précision, le commercial oriente la réponse et se prive d'une information qu'il n'avait pas. Le silence est l'outil. Le remplir le détruit."}, {"title": "Erreur 3 — Répondre à l'objection sans avoir exploré ni qualifié", "description": "Traiter \"c'est trop cher\" directement avec des arguments prix sans avoir exploré si c'est fondé, prétexte ou réflexe. Résultat : argumenter sur le prix à quelqu'un dont le vrai frein est la peur de s'engager. Efficacité zéro — résistance maximale."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je vais poser une objection. Ton objectif : trouver la bonne question d'exploration, la poser, et qualifier l'objection avant de répondre. Je lève la main si tu poses une question fermée ou si tu combles le silence.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona jusqu'à l'objection. La poser avec naturel. Après la question d'exploration du commercial, révéler progressivement le vrai frein — mais seulement si la question était ouverte et le silence respecté. Observer : question ouverte ? Silence respecté ? Qualification faite ?"}, {"title": "Débriefer", "description": "\"Quelle question d'exploration as-tu choisie — et pourquoi celle-là ? Est-ce que tu as laissé le silence après ? Qu'est-ce que ma réponse t'a appris sur le vrai frein ? Tu as qualifié avant de répondre — fondée, prétexte ou réflexe ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ta prochaine objection : après A.R.E., note la question d'exploration que tu as posée et ce qu'elle a révélé. Reviens me voir avec : l'objection exprimée, ta question, ce que ça a révélé, et comment tu as répondu ensuite.\""}], "scenarios": [{"level": "debutant", "title": "L'objection prix transparente — le vrai frein est clair", "objective": "Choisir \"C'est par rapport à quoi précisément ?\", laisser le silence, écouter la réponse pour confirmer que c'est une objection fondée, et qualifier avant de construire la réponse.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 29 ans, technicien informatique en CDI. Premier achat auto, budget serré."}, {"label": "L'objection exprimée", "text": "\"Franchement c'est vraiment beaucoup — 320€ par mois c'est au-dessus de ce que je voulais mettre.\""}, {"label": "Non-verbal", "text": "Ton direct, regard honnête. Il expose un fait — pas une stratégie de négociation."}, {"label": "Ce qui se cache derrière", "text": "Budget mensuel réellement dépassé. Il avait 270€/mois en tête. L'objection est fondée."}, {"label": "Ce qu'il révèle si on explore", "text": "\"J'avais prévu 270€ max — 320 c'est vraiment trop pour moi.\" Objection fondée sur le budget réel."}], "context": "Samedi 11h. Le commercial vient de présenter le financement. Le client avait semblé intéressé tout au long. L'objection arrive à la présentation du prix mensuel.", "stakes": "Contexte idéal pour pratiquer la qualification sur une objection fondée simple. L'enjeu : poser la bonne question d'exploration sans orienter, laisser le silence, et confirmer que le frein est bien budgétaire avant d'aller sur des solutions (apport, durée, modèle différent).", "observe": ["Choisit-il une question d'exploration ouverte et neutre ?", "Laisse-t-il le silence après sans le combler ?", "Écoute-t-il pour qualifier — pas pour construire sa réponse ?", "Confirme-t-il la qualification avant de proposer une solution ?"]}, {"level": "intermediaire", "title": "L'objection \"trop cher\" qui cache une comparaison concurrente", "objective": "Explorer une objection prix ambiguë, détecter qu'elle cache une comparaison avec un concurrent, qualifier comme objection fondée de nature comparative, et adapter la réponse en conséquence.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 44 ans, directrice d'école. Organisée, a fait ses recherches. A visité une concurrence la semaine dernière."}, {"label": "L'objection exprimée", "text": "\"Honnêtement, j'ai l'impression que c'est cher pour ce que c'est.\""}, {"label": "Non-verbal", "text": "Ton posé mais ferme. Regard qui soutient. Elle attend une réaction — elle a un argument de comparaison en réserve."}, {"label": "Ce qui se cache derrière", "text": "Elle a vu le même type de véhicule chez un concurrent 2 500€ moins cher. Elle teste si le commercial sait défendre sa valeur."}, {"label": "Ce qu'il révèle si on explore", "text": "\"J'ai vu un modèle similaire ailleurs à 2 500€ de moins — je comprends pas la différence.\" Objection fondée — comparaison concurrente."}], "context": "Mardi 15h. Elle a fait le tour de 3 concessions avant. Elle ne l'a pas dit spontanément. L'objection arrive après la présentation du prix véhicule.", "stakes": "L'enjeu : ne pas défendre le prix immédiatement, explorer avec \"qu'est-ce qui vous fait dire ça ?\" pour faire émerger la comparaison, qualifier l'objection comme comparative, et orienter la réponse sur la différence de valeur (équipements, garantie, service) plutôt que le prix brut.", "observe": ["Explore-t-il avec \"qu'est-ce qui vous fait dire ça ?\" ?", "Laisse-t-il le silence pour que la cliente développe ?", "Détecte-t-il que l'objection est comparative, pas budgétaire ?", "Oriente-t-il sa réponse sur la valeur, pas sur le prix brut ?"]}, {"level": "avance", "title": "L'objection \"je dois réfléchir\" qui cache une décision de couple", "objective": "Qualifier une objection réflexe pour révéler le vrai frein (décision en couple non anticipée), utiliser \"Si ce point était résolu, qu'est-ce qui changerait ?\", et créer les conditions d'un retour structuré.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 48 ans, responsable logistique. A l'air intéressé et engagé tout au long du RDV — puis freine brusquement."}, {"label": "L'objection exprimée", "text": "\"Tout ça me semble bien — mais je vais quand même réfléchir. Je vous rappellerai.\""}, {"label": "Non-verbal", "text": "Ton qui se distancie. Commence à récupérer ses affaires. Sourire poli de clôture. Évite le regard direct."}, {"label": "Ce qui se cache derrière", "text": "Sa femme n'est pas au courant du montant réel. Il a besoin de son accord pour s'engager sur ce budget — il ne l'a pas mentionné de tout le RDV."}, {"label": "Ce qu'il révèle si on explore", "text": "\"En fait... ma femme est pas au courant du prix. On avait parlé d'un budget différent.\" Vrai frein = décision non partagée en couple."}], "context": "Jeudi 17h. Fin de RDV. Tout s'était très bien passé — la découverte était riche, le véhicule correspondait parfaitement. Le commercial pensait conclure. L'objection arrive au moment de signer.", "stakes": "L'enjeu : résister à l'envie de contre-argumenter, utiliser \"si ce point était résolu, qu'est-ce qui changerait ?\" pour tester si c'est un prétexte, détecter le vrai frein (sa femme), et proposer une prochaine étape qui inclut les deux décideurs.", "observe": ["Résiste-t-il à l'envie d'argumenter sur \"je réfléchis\" ?", "Utilise-t-il \"si ce point était résolu...\" pour tester le prétexte ?", "Détecte-t-il le vrai frein (décision en couple) ?", "Propose-t-il une prochaine étape qui inclut madame ?"]}]}, "online": {"focus": "l'exploration de l'objection", "attentionPoints": ["La question d'exploration est-elle ouverte et neutre ?", "Laisse-t-il le silence après sans le combler ?", "Qualifie-t-il l'objection avant de répondre ?", "Sa réponse est-elle adaptée au type d'objection qualifié ?"], "grid": ["Question ouverte & neutre", "Silence respecté", "Objection qualifiée", "Réponse adaptée au type"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Quelle question d'exploration as-tu choisie ? Est-ce qu'elle était ouverte et neutre ? As-tu laissé le silence ? Qu'est-ce que ça t'a révélé — et comment tu as qualifié l'objection avant de répondre ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que tu as posé [question précise] — et que tu as laissé le silence. Le client a développé [réponse], ce qui t'a révélé que l'objection était [qualification]. C'est exactement le travail d'exploration.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as comblé le silence en ajoutant 'par rapport au prix ?']. La prochaine fois, pose la question — puis silence complet. Si 5 secondes passent sans réponse, tu peux relancer avec 'qu'est-ce que vous voulez dire exactement ?'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ta prochaine objection : note la question d'exploration que tu as posée, ce qu'elle a révélé, et comment tu as qualifié l'objection. Ces 3 éléments. Date de retour : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 4 questions d'exploration sont connues — le silence après la question est sacré", "offline": "Le geste est pratiqué sur 3 types de frein caché — qualifier avant répondre est un réflexe", "online": "Le coach a observé et débriefé l'exploration en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/5- Traiter les objections/b. déceler l''objection foncée.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('cbcd48de-dd32-5547-8d0b-a9daddc6c0d2', '57672187-a47c-5d0e-8325-aa677c0f03c4');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('cbcd48de-dd32-5547-8d0b-a9daddc6c0d2', '8e216ac8-e4ab-5785-94c8-e059ec8bed9e');
insert into public.library_dojos (id, title, content, pptx_path) values ('6cc075a8-499a-555a-8fc6-be2f7e4b86b8', 'Argumenter & rassurer sur les doutes réels', $dojo${"version": 1, "tagline": "Construire la réponse juste à une objection fondée", "objective": "Le commercial applique R.A.C., choisit le bon type de réponse, ancre son argument dans la découverte, et confirme que le frein est levé avant de continuer.", "duration": "25-30 min", "theory": {"intro": null, "standardTitle": "Le standard : la structure R.A.C. & les 4 types de réponse", "standard": [], "criteria": [{"title": "Sa réponse est ancrée dans la découverte", "description": "\"Avec ce que vous m'avez dit sur vos 40 000 km/an principalement autoroute — voici ce que ça donne sur les coûts réels à 3 ans.\" La réponse qui reprend les mots du client est infiniment plus convaincante qu'une réponse générique."}, {"title": "Il choisit le bon type de réponse selon le doute", "description": "Un doute factuel (\"c'est fiable ?\") appelle une preuve. Un doute sur la valeur (\"c'est trop cher\") appelle un CAB ancré. Un doute partiel appelle une concession partielle honnête. Répondre avec le mauvais outil réduit l'impact."}, {"title": "Il reconnaît la légitimité du doute sans capituler", "description": "\"Vous avez raison de vérifier ce point — et voici ce que les données montrent.\" Reconnaître ne signifie pas baisser le prix ou renoncer à l'argument. C'est valider la question pour que la réponse soit mieux reçue."}, {"title": "Il vérifie que le frein est levé avant de continuer", "description": "Ne pas supposer que la réponse a convaincu. \"Est-ce que ça répond à ce qui vous préoccupait ?\" Si le client dit \"oui\" — le frein est levé. S'il hésite — l'objection n'est pas traitée, il y a autre chose derrière."}, {"title": "Il ne donne pas plus d'arguments que nécessaire", "description": "Un argument fort bien utilisé vaut mieux que 5 arguments qui se diluent. Surargumenter donne l'impression qu'on essaie de convaincre à tout prix — et renforce paradoxalement le doute."}], "mistakes": [{"title": "Erreur 1 — Répondre avec des arguments génériques non ancrés", "description": "\"Notre véhicule est le meilleur rapport qualité-prix du marché.\" dit à quelqu'un qui a exprimé un doute spécifique sur le coût à long terme. La réponse générique ne touche pas le vrai doute — elle glisse dessus. Le client ne se sent pas répondu."}, {"title": "Erreur 2 — Sur-argumenter pour \"être sûr\" de convaincre", "description": "5 arguments chiffrés, 3 comparaisons, 2 témoignages clients — en rafale. Le client est submergé. Il perd le fil, ne retient rien, et finit par se méfier de cette débauche d'arguments. Moins, c'est plus. Un argument fort et ancré suffit souvent."}, {"title": "Erreur 3 — Ne pas vérifier que le frein est levé", "description": "Donner la réponse et enchaîner immédiatement sur la suite sans vérifier si le client est convaincu. \"Donc on fait le dossier ?\" après un argument de réponse suppose que c'était suffisant. Le client qui n'a pas validé va se fermer en fin de RDV."}], "sections": [{"title": "Le standard : la structure R.A.C. & les 4 types de réponse", "lines": ["Une fois l'objection qualifiée comme fondée, la réponse suit la structure R.A.C. : Reconnaître le doute, Apporter la réponse adaptée, Confirmer la levée du frein. La force de la réponse vient de son ancrage dans ce que le client a dit — pas dans un script générique.", "LA STRUCTURE R.A.C.", "R", "Reconnaître", "Valider que le doute est légitime. Ne pas minimiser, ne pas relativiser immédiatement.", "\"Vous avez raison de soulever ce point — c'est une vraie question.\"", "A", "Apporter", "La réponse concrète, chiffrée, ancrée dans ce que le client a dit en découverte.", "\"Avec ce que vous m'avez dit sur vos 35 000 km/an — voici ce que ça donne concrètement...\"", "C", "Confirmer", "Vérifier que la réponse a levé le frein. Ne pas supposer — demander.", "\"Est-ce que ça répond à votre préoccupation ? / C'est plus clair pour vous ?\"", "LES 4 TYPES DE RÉPONSE — selon la nature du doute", "PREUVE", "Données chiffrées, fiches techniques, témoignages. Pour les doutes factuels (\"c'est vraiment fiable ?\").", "CAB", "Caractéristique → Avantage → Bénéfice ancré dans la découverte. Pour les doutes sur la valeur (\"ça vaut pas le prix\").", "CONCESSION PARTIELLE", "Reconnaître un point faible et compenser par des points forts. Pour les doutes fondés partiellement (\"c'est vrai, mais...\").", "REFORMULATION POSITIVE", "Retourner l'objection en avantage. Pour les doutes qui révèlent une attente non exprimée (\"c'est trop petit\" → coffre modulable)."]}]}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Donner au commercial les infos de découverte du client fictif avant de commencer. Briefer : \"Je vais poser une objection fondée. Tu appliques R.A.C. — reconnaissance, réponse ancrée dans ma découverte, confirmation. Je jouerai le client jusqu'à ce que le frein soit levé.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona jusqu'à l'objection. Ne pas valider immédiatement la réponse du commercial — rester dans le doute jusqu'à ce que la réponse soit ancrée dans la découverte et la confirmation posée. Observer : R ? A ancré ? C demandé ?"}, {"title": "Débriefer", "description": "\"Est-ce que tu as reconnu le doute sans minimiser ? Ton argument était-il ancré dans ce que je t'avais dit en découverte — ou générique ? Est-ce que tu as vérifié que j'étais convaincu avant de continuer ? Quel type de réponse as-tu utilisé ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ta prochaine objection fondée : note l'argument que tu as utilisé et s'il était ancré dans la découverte du client. Puis note comment tu as vérifié que le frein était levé. Reviens me voir avec les deux. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Le doute sur la fiabilité d'un véhicule d'occasion", "objective": "Appliquer R.A.C. sur un doute factuel : reconnaître la légitimité, apporter une preuve concrète et chiffrée, confirmer la levée du frein.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 31 ans, électricien indépendant. Premier achat d'occasion. Méfiant sur la fiabilité."}, {"label": "L'objection fondée", "text": "\"Honnêtement j'ai peur d'acheter un véhicule d'occasion — et si ça tombe en panne 3 mois après ?\""}, {"label": "Non-verbal", "text": "Ton sincère, regard direct. Vraie peur, pas une stratégie. Il attend une réponse rassurante et factuelle."}, {"label": "Ce qu'il attend comme réponse", "text": "Des preuves concrètes sur les garanties et les contrôles réalisés. Pas des généralités."}, {"label": "Ce qui le ferait valider", "text": "\"Ah d'accord — donc la garantie couvre ça pendant X mois.\" Il a besoin de comprendre précisément ce qui le protège."}], "context": "Samedi 10h. Le commercial lui a présenté un véhicule d'occasion récent (2 ans, 28 000 km). Le client est intéressé par le véhicule mais la peur de tomber en panne le bloque.", "stakes": "Découverte : il utilise son véhicule pour aller sur ses chantiers tous les jours — une panne = journée perdue. L'argument doit être ancré dans cet usage professionnel critique. Type de réponse = preuve (garantie + contrôles).", "observe": ["Reconnaît-il le doute comme légitime sans minimiser ?", "Ancre-t-il la réponse dans l'usage professionnel du client ?", "Utilise-t-il des preuves concrètes (garantie, contrôle, kilométrage) ?", "Confirme-t-il que le frein est levé avant de continuer ?"]}, {"level": "intermediaire", "title": "Le doute sur le coût total d'un véhicule hybride", "objective": "Répondre à un doute sur la valeur avec un CAB ancré dans la découverte, retourner l'objection prix en argument de coût total d'usage favorable, et confirmer la conviction.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 47 ans, infirmière libérale. Fait 38 000 km/an. Habitée au diesel — hésitante sur l'hybride."}, {"label": "L'objection fondée", "text": "\"Le prix de base est 4 000€ plus cher que la version diesel — je comprends pas pourquoi je paierais plus.\""}, {"label": "Non-verbal", "text": "Ton pragmatique, un peu sceptique. Elle veut être convaincue par les chiffres, pas par le discours."}, {"label": "Ce qu'il attend comme réponse", "text": "Une démonstration chiffrée du retour sur investissement sur ses kilomètres réels. Elle pense en coût total, pas en prix d'achat."}, {"label": "Ce qui le ferait valider", "text": "\"Ah — sur 3 ans ça fait quand même une différence.\" Elle a besoin de voir les chiffres sur sa situation spécifique."}], "context": "Mardi 14h. Découverte riche : 38 000 km/an, 70% trajet ville et périurbain, coût carburant actuel 680€/mois, sensible au coût total sur 3 ans. Elle a comparé deux versions : diesel vs hybride.", "stakes": "L'argument doit reposer sur ses 38 000 km réels et ses 680€/mois de carburant — pas sur des chiffres constructeur génériques. Type de réponse = CAB ancré dans la découverte.", "observe": ["Ancre-t-il son CAB dans les 38 000 km et les 680€/mois découverts ?", "Chiffre-t-il le retour sur investissement sur la durée de possession ?", "Évite-t-il les arguments génériques (\"l'hybride c'est l'avenir\") ?", "Confirme-t-il que la démonstration chiffrée a convaincu ?"]}, {"level": "avance", "title": "Le doute sur le délai de livraison en fin de RDV", "objective": "Traiter une objection fondée qui arrive tardivement, reconnaître honnêtement la contrainte, compenser par des points forts non mentionnés, et maintenir la dynamique vers la signature.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 55 ans, directeur régional. Besoin du véhicule dans 3 semaines pour une prise de poste. Délai non abordé en découverte."}, {"label": "L'objection fondée", "text": "\"Attends — vous m'annoncez 8 semaines de délai ? J'en ai besoin dans 3 semaines maximum. C'est rédhibitoire.\""}, {"label": "Non-verbal", "text": "Ton qui monte. Posture qui se ferme. Déception visible — il pensait pouvoir conclure aujourd'hui."}, {"label": "Ce qu'il attend comme réponse", "text": "Une solution concrète au délai ou une compensation qui justifie d'attendre. Pas d'excuses ni de minimisation."}, {"label": "Ce qui le ferait valider", "text": "Un véhicule de courtoisie pendant 5 semaines + priorité de livraison confirmée par écrit. Ça lui permet de prendre sa nouvelle fonction sans rupture."}], "context": "Jeudi 16h. Fin de RDV, tout allait vers la signature. Le délai de 8 semaines vient d'être annoncé. Le client avait besoin du véhicule dans 3 semaines — information qui n'avait pas été remontée clairement en découverte.", "stakes": "Le commercial ne peut pas changer le délai. Il doit faire une concession partielle honnête (reconnaître la contrainte réelle), proposer une solution de compensation concrète (véhicule de courtoisie), et ancrer cette solution dans la situation spécifique du client.", "observe": ["Reconnaît-il la contrainte sans minimiser ni se justifier ?", "Propose-t-il une solution concrète ancrée dans la situation du client ?", "Utilise-t-il honnêtement la concession partielle sans sur-promettre ?", "Maintient-il la dynamique vers la décision malgré la tension ?"]}]}, "online": {"focus": "la réponse à l'objection", "attentionPoints": ["Reconnaît-il le doute sans minimiser (étape R) ?", "Sa réponse est-elle ancrée dans la découverte (étape A) ?", "Choisit-il le bon type de réponse (preuve, CAB, concession...) ?", "Confirme-t-il que le frein est levé avant de continuer (étape C) ?"], "grid": ["Doute reconnu (étape R)", "Réponse ancrée découverte", "Bon type de réponse", "Frein confirmé levé (étape C)"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Est-ce que tu as reconnu le doute sans le minimiser ? Ton argument était-il ancré dans ce que le client t'avait dit en découverte — ou générique ? Tu as vérifié que le frein était levé — et comment le client a réagi ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand le client a exprimé [doute], tu as dit [R précis]. Puis tu as apporté [argument ancré dans la découverte]. Le client a [réaction]. C'est exactement la structure R.A.C. bien appliquée.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: ton argument était générique — pas ancré dans ce que le client t'avait dit]. La prochaine fois, avant de répondre, dis-toi : 'Comment est-ce que je relie cet argument à ce que le client m'a dit en découverte ?'\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ta prochaine objection fondée : note l'argument utilisé, s'il était ancré dans la découverte, et comment tu as confirmé que le frein était levé. Ces 3 éléments. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "R.A.C. est connu — la réponse ancrée dans la découverte est la clé de la conviction", "offline": "Le geste est pratiqué sur 3 types de doutes différents — le bon type de réponse est un réflexe", "online": "Le coach a observé et débriefé la réponse à l'objection fondée en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/5- Traiter les objections/c. Argumenter et rassurer.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('6cc075a8-499a-555a-8fc6-be2f7e4b86b8', '870ca27d-6132-5fe0-98ba-927d9cc95416');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('6cc075a8-499a-555a-8fc6-be2f7e4b86b8', 'd6f62bd3-075a-5670-98e2-23aa322fa01b');
insert into public.library_dojos (id, title, content, pptx_path) values ('31e048b4-d7ab-59d8-9e06-fd6371c314f2', 'Méthode CAB Financement', $dojo${"version": 1, "tagline": "Transformer les caractéristiques d'une offre Fi en bénéfices client", "objective": "Le commercial choisit le produit Fi adapté au profil client, présente le bénéfice ancré dans la découverte avant les chiffres, et demande l'adhésion avant de détailler les conditions.", "duration": "25-30 min", "theory": {"intro": null, "standardTitle": "Le standard : CAB Fi appliqué aux 3 offres principales", "standard": [{"label": "Présenter un financement en commençant par le taux, la durée et les mensualités, c'est laisser le client calculer seul — et souvent se faire peur. Le CAB Fi part du bénéfice client ancré dans sa découverte, puis justifie les chiffres.", "title": "LOA", "description": "C — Caractéristique", "why": "Location avec Option d'Achat — mensualités fixes sur 24-48 mois, valeur résiduelle garantie, option de rachat en fin."}, {"label": "A — Avantage", "title": "Vous roulez dans un véhicule récent pour un budget mensuel maîtrisé, sans immobiliser votre épargne.", "description": "B — Bénéfice (ancré)", "why": "Et comme vous m'avez dit que vous changez de voiture tous les [X] ans et que vous n'aimez pas les surprises — vos mensualités sont fixes, votre budget prévisible, et dans [X] ans vous choisissez librement."}, {"label": "Profil client", "title": "Client qui change souvent, aime avoir du récent, veut de la prévisibilité.", "description": "CRÉDIT CLASSIQUE", "why": "C — Caractéristique"}, {"label": "Crédit affecté — vous devenez propriétaire immédiatement, remboursement capital + intérêts sur la durée choisie.", "title": "A — Avantage", "description": "Vous êtes propriétaire dès la livraison et pouvez revendre ou modifier le véhicule librement à tout moment.", "why": "B — Bénéfice (ancré)"}, {"label": "Et comme vous m'avez dit que vous gardez vos véhicules longtemps et que la propriété compte pour vous — dans [X] mois le crédit est soldé et le véhicule vous appartient pleinement.", "title": "Profil client", "description": "Client attaché à la propriété, qui garde longtemps, sensible au coût total.", "why": "CRÉDIT BALLON"}, {"label": "C — Caractéristique", "title": "Mensualités réduites sur la durée + solde final (ballon) à régler ou refinancer en fin de contrat.", "description": "A — Avantage", "why": "Vous bénéficiez de mensualités basses pendant toute la durée tout en restant propriétaire du véhicule."}, {"label": "B — Bénéfice (ancré)", "title": "Et comme vous m'avez dit que votre priorité c'est le budget mensuel disponible — vous gardez de la trésorerie chaque mois et vous décidez en fin de contrat si vous soldez, refinancez ou revendez.", "description": "Profil client", "why": "Client sensible à la mensualité, qui veut de la flexibilité en fin de contrat."}], "criteria": [{"title": "Il choisit le bon produit avant d'argumenter", "description": "Proposer une LOA à quelqu'un qui garde ses voitures 8 ans ou un crédit classique à quelqu'un qui change tous les 3 ans — c'est vendre contre le client. Le choix du produit Fi découle de la découverte, pas de la facilité ou de la marge."}, {"title": "Il présente le B avant les chiffres", "description": "\"Avec ce que vous m'avez dit sur votre budget mensuel, voici ce que ça donne — [bénéfice]. Les mensualités sont de X€.\" Les chiffres viennent justifier le bénéfice — pas l'inverse. Un client qui entend d'abord le bénéfice écoute mieux les chiffres."}, {"title": "Il présente une seule offre — la bonne", "description": "Présenter 3 offres en disant \"à vous de choisir\" transfère la décision au client sans l'accompagner. Le commercial qui dit \"pour votre profil, c'est cette offre\" positionne comme conseiller. Il peut présenter une alternative — pas une carte."}, {"title": "Il demande l'adhésion après le B", "description": "\"Ça correspond à ce que vous recherchiez ?\" après le CAB Fi. Le client qui valide le bénéfice avant de voir les chiffres est dans un état de réception bien meilleur que celui à qui on annonce une mensualité sans contexte."}, {"title": "Il ne défend pas le taux — il défend le bénéfice", "description": "Face à \"le taux est élevé\", le commercial qui défend son taux entre dans un débat chiffré qu'il ne peut pas gagner. Celui qui revient sur le bénéfice (\"ce qui compte c'est que votre budget mensuel reste à X€\") reste sur le terrain où il gagne."}], "mistakes": [{"title": "Erreur 1 — Présenter le financement en commençant par les chiffres", "description": "\"Donc sur 48 mois à 5,9% vous avez une mensualité de 342€ avec un apport de 2 000€.\" Le client entend les chiffres avant le bénéfice. Il calcule seul, souvent mal, et se fait peur. Partir du bénéfice change complètement la réception des chiffres."}, {"title": "Erreur 2 — Proposer le même produit à tout le monde", "description": "Le commercial qui propose systématiquement la LOA (ou systématiquement le crédit) sans adapter au profil client ne conseille pas — il place. Un client qui change tous les 3 ans et un client qui garde 8 ans n'ont pas le même intérêt. Le produit se choisit après la découverte."}, {"title": "Erreur 3 — Défendre le taux au lieu du bénéfice", "description": "\"Oui mais notre taux est très compétitif par rapport au marché.\" Argumenter sur le taux appelle une comparaison — et le client a souvent un chiffre plus bas en tête ou en poche. Revenir sur le bénéfice : \"Ce qui compte c'est que votre mensualité reste dans votre budget avec ce véhicule.\""}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Donner au commercial les infos de découverte avant. Briefer : \"Je suis ton client. Tu viens de me présenter le véhicule. Maintenant tu me proposes le financement — en partant du bénéfice pour moi, pas des chiffres. Je t'arrête si tu commences par la mensualité.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona. Répondre naturellement aux questions. Ne pas valider immédiatement si le commercial part sur les chiffres — rester dans l'attente du bénéfice. Si le bon produit est choisi et le B ancré dans la découverte, acquiescer et laisser continuer."}, {"title": "Débriefer", "description": "\"Par quoi tu as commencé — le bénéfice ou les chiffres ? Le produit que tu as proposé, c'est le bon pour mon profil — pourquoi ? Est-ce que ton bénéfice reprenait vraiment ce que je t'avais dit en découverte ou c'était générique ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client : avant de présenter le financement, note le bénéfice que tu vas utiliser et d'où il vient dans la découverte. Reviens me voir avec le CAB Fi que tu as fait et la réaction du client.\""}], "scenarios": [{"level": "debutant", "title": "Le client ouvert à la LOA — profil idéal", "objective": "Choisir la LOA sur la base de la découverte, construire un CAB Fi complet avec le bénéfice ancré, présenter les chiffres après le bénéfice, demander l'adhésion.", "duration": "25 min", "persona": [], "context": null, "stakes": null, "observe": ["Choisit-il la LOA pour les bonnes raisons issues de la découverte ?", "Présente-t-il le B avant les chiffres ?", "Son bénéfice reprend-il \"budget mensuel\" et \"récent\" mentionnés ?", "Demande-t-il l'adhésion avant de détailler les conditions ?"]}, {"level": "intermediaire", "title": "Le client \"je paie comptant\" qui devrait financer", "objective": "Identifier que la LOA est plus adaptée que le comptant pour ce profil, construire un CAB Fi qui montre l'intérêt du financement par rapport à l'achat sec, sans dénigrer le choix du client.", "duration": "25 min", "persona": [], "context": null, "stakes": null, "observe": ["Reformule-t-il l'intérêt du financement sans attaquer la conviction \"comptant\" ?", "Ancre-t-il le bénéfice dans la protection de sa trésorerie professionnelle ?", "Évite-t-il le mot \"crédit\" — et parle-t-il de \"solution de financement\" ?", "Propose-t-il une offre courte (24 ou 36 mois) adaptée à sa résistance ?"]}, {"level": "avance", "title": "Le client qui compare avec son offre bancaire", "objective": "Argumenter le financement concessionnaire face à une offre bancaire existante, construire un CAB Fi différencié sur la valeur globale (service, garantie, simplicité), sans entrer dans une guerre de taux.", "duration": "30 min", "persona": [], "context": null, "stakes": null, "observe": ["Évite-t-il la guerre de taux — et revient-il sur la valeur globale ?", "Construit-il un CAB Fi différencié (simplicité admin, garantie, service intégré) ?", "Ancre-t-il son argument dans le \"temps administratif\" et l'expérience passée ?", "Maintient-il une posture confiante sans être défensif sur le taux ?"]}]}, "online": {"focus": "le CAB Fi", "attentionPoints": ["Le produit proposé est-il adapté au profil découverte ?", "Présente-t-il le bénéfice avant les chiffres ?", "Le B est-il ancré dans la découverte ?", "Demande-t-il l'adhésion avant de détailler ?"], "grid": ["Produit adapté au profil", "B avant les chiffres", "B ancré en découverte", "Adhésion demandée"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Par quoi tu as commencé — le bénéfice ou les chiffres ? Le produit que tu as proposé, c'est le bon pour ce profil — pourquoi ? Ton bénéfice venait vraiment de la découverte ou c'était générique ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que tu as dit [B précis] en reprenant [élément de découverte]. Le client a [réaction]. C'est exactement ça — présenter le bénéfice avant la mensualité change complètement l'état de réception.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as commencé par la mensualité]. La prochaine fois, avant d'ouvrir la fiche de financement, dis-toi : quel bénéfice est-ce que je vais annoncer en premier — et d'où il vient dans la découverte ?\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ta prochaine proposition Fi : note le B que tu as utilisé, d'où il vient dans la découverte, et comment le client a réagi. Ces 3 éléments. Date de retour : [date].\""}], "sections": []}, "takeaways": {"theory": "Le CAB Fi est connu sur 3 produits — le bénéfice ancré précède toujours les chiffres", "offline": "Le geste est pratiqué sur 3 profils Fi différents — choisir le bon produit est un réflexe", "online": "Le coach a observé et débriefé le CAB Fi en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/6- Proposer un Fi & PC/a. CAB financement.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('31e048b4-d7ab-59d8-9e06-fd6371c314f2', 'bc046cae-2099-5d4e-b1b5-8092c49c2de3');
insert into public.library_dojos (id, title, content, pptx_path) values ('9f0bb561-4733-520b-8676-38d88a4c7f37', 'Teasing du financement', $dojo${"version": 1, "tagline": "Introduire le financement naturellement avant la proposition formelle", "objective": "Le commercial choisit la bonne formule de teasing selon le moment, la glisse naturellement dans la conversation, écoute et note la réaction du client, et ne relance pas le sujet Fi immédiatement.", "duration": "20-25 min", "theory": {"intro": null, "standardTitle": "Le standard : pourquoi teaser & les 3 formules", "standard": [{"label": null, "title": "Un client qui entend parler de financement pour la première fois au moment de signer est un client qui n'était pas préparé — et qui peut se bloquer. Le teasing introduit le financement dès la découverte ou la présentation du véhicule, naturellement, sans forcer. Il prépare l'état d'esprit.", "description": "POURQUOI TEASER AVANT DE PROPOSER", "why": "1"}, {"label": null, "title": "Éviter la surprise : un client préparé au financement ne se braque pas quand arrive la proposition formelle.", "description": "2", "why": "Qualifier l'ouverture : la réaction au teasing révèle si le client est ouvert, méfiant ou déjà décidé — avant d'investir du temps."}, {"label": null, "title": "3", "description": "Installer la légitimité : le commercial qui parle de financement naturellement dès le début est perçu comme un conseiller — pas comme quelqu'un qui \"essaie de placer\" du crédit.", "why": "LES 3 FORMULES DE TEASING"}, {"label": null, "title": "EN DÉCOUVERTE", "description": "\"Et pour le financement, vous avez réfléchi à comment vous l'envisagez ?\"", "why": "Pendant la découverte, après les questions d'usage. Naturel, ouvert, non intrusif."}, {"label": null, "title": "APRÈS LE VÉHICULE", "description": "\"Ce véhicule correspond bien à ce que vous cherchez — je vais regarder ce que je peux faire pour que ça rentre dans votre budget mensuel.\"", "why": "Juste après la validation du véhicule, avant de s'asseoir pour la proposition."}, {"label": null, "title": "LORS DE L'ARGUMENTATION", "description": "\"Et avec le financement adapté, ce véhicule peut rentrer dans un budget de [X]€/mois — on en parle après l'essai.\"", "why": "Pendant le CAB véhicule, pour anticiper l'objection prix sans la traiter encore."}], "criteria": [{"title": "Il teaser au bon moment — jamais trop tôt", "description": "Introduire le financement avant d'avoir établi un lien et fait une découverte minimale crée de la méfiance. Le teasing découverte se place après les premières questions d'usage — quand le client est à l'aise, pas en arrivant."}, {"title": "Sa formule est neutre et ouverte", "description": "\"Vous avez pensé au financement ?\" est une question fermée qui appelle oui/non. \"Et pour le financement, vous avez réfléchi à comment vous l'envisagez ?\" est ouverte — elle invite le client à partager sa position sans se sentir orienté."}, {"title": "Il écoute vraiment la réponse au teasing", "description": "La réponse au teasing est de l'or : \"j'ai horreur du crédit\", \"j'ai déjà un accord de ma banque\", \"je sais pas trop\"... Chaque réponse change la stratégie Fi qui suivra. Le commercial qui teaser sans écouter la réponse rate l'intérêt de l'exercice."}, {"title": "Il ne relance pas le sujet immédiatement après le teasing", "description": "Le teasing ouvre une porte — il ne la franchit pas. Après le teasing en découverte, revenir sur le véhicule. La proposition Fi formelle vient après l'essai ou la validation du véhicule. Forcer la conversation Fi immédiatement annule l'effet teasing."}, {"title": "Son ton est celui d'un conseiller — pas d'un placeur de crédit", "description": "\"Je vais regarder ce qu'on peut faire pour vous\" positionne en partenaire. \"On a des offres de financement très intéressantes\" positionne en vendeur. Le teasing doit renforcer la posture de conseiller — jamais la posture commerciale."}], "mistakes": [{"title": "Erreur 1 — Ne pas teaser du tout et arriver avec la proposition sans préparation", "description": "Le financement sort comme une surprise en fin de RDV. Le client qui n'y était pas préparé se braque — même si l'offre est bonne. \"Attendez, je voulais pas de crédit\" arrive souvent là. Le teasing évite exactement cette situation."}, {"title": "Erreur 2 — Teaser trop tôt et trop fort — avant d'avoir créé le lien", "description": "\"Bonjour — et vous financez comment ?\" dès les premières secondes. Le client se sent immédiatement dans le viseur commercial. Le teasing fonctionne quand le client est détendu et en confiance — pas comme première question d'accueil."}, {"title": "Erreur 3 — Enchaîner sur la proposition Fi immédiatement après le teasing", "description": "Le teasing ouvre la porte. Franchir la porte immédiatement, c'est transformer un geste subtil en pitch de vente. La réponse au teasing se note mentalement — la proposition complète vient au moment prévu, pas dans la foulée."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je vais jouer un client — on fait une découverte + présentation du véhicule. Tu dois glisser le teasing Fi au bon moment, avec la bonne formule. Je te lève la main si tu teaseas trop tôt, trop fort, ou si tu enchaînes sur la proposition Fi immédiatement.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona sur toute la durée — découverte + argumentation véhicule. Donner une réaction réaliste au teasing : positive, neutre ou méfiante selon le persona. Observer : quel moment a-t-il choisi ? Quelle formule ? A-t-il écouté la réponse ? A-t-il enchaîné ?"}, {"title": "Débriefer", "description": "\"À quel moment tu as teasé — et pourquoi ce moment-là ? Quelle formule tu as utilisée — ouverte ou fermée ? Qu'est-ce que ma réponse t'a appris sur ma posture vis-à-vis du financement ? Est-ce que tu as relancé le sujet Fi immédiatement après ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client : note à quel moment tu as teasé, quelle formule tu as utilisée, et ce que la réaction du client t'a appris. Ces 3 éléments. Date de retour : [date].\""}], "scenarios": [{"level": "debutant", "title": "Le client neutre — première fois en concession", "objective": "Choisir le teasing découverte au bon moment, utiliser une formule ouverte, écouter la réponse sans relancer le sujet Fi immédiatement.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 27 ans, graphiste en CDI depuis 1 an. Premier achat auto. Ne connaît pas les offres de financement."}, {"label": "Comportement", "text": "Curieux, un peu intimidé par le processus d'achat. Répond aux questions avec honnêteté. Pas de résistance particulière."}, {"label": "Non-verbal", "text": "Regard attentif, posture légèrement en avant quand quelque chose l'intéresse. Décontracté."}, {"label": "Rapport au financement", "text": "Aucune expérience du financement auto. A entendu parler de LOA mais ne sait pas vraiment ce que c'est."}, {"label": "Frein / tension probable", "text": "Peur de ne pas comprendre les produits financiers — ne veut pas \"signer quelque chose qu'il comprend pas\"."}], "context": "Samedi matin. Découverte en cours — l'usage est clair (30 km/jour, pas de trajet spécifique). Le véhicule commence à se dessiner. C'est le bon moment pour glisser le teasing.", "stakes": "Contexte idéal pour pratiquer : client sans résistance, bon moment clairement identifiable après les questions d'usage. L'enjeu est de choisir la formule ouverte et d'écouter la réponse sans rebondir sur le Fi immédiatement.", "observe": ["Choisit-il le bon moment — après les questions d'usage ?", "Utilise-t-il une formule ouverte et neutre ?", "Écoute-t-il vraiment la réponse sans la couper ?", "Revient-il sur le véhicule après le teasing sans enchaîner sur le Fi ?"]}, {"level": "intermediaire", "title": "Le client qui dit d'emblée \"je paie comptant\"", "objective": "Glisser le teasing malgré une résistance initiale au financement, sans confronter la position du client, pour qualifier son ouverture réelle et garder la porte ouverte pour plus tard.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 45 ans, responsable RH, indépendante financièrement. A dit dès l'accueil qu'elle paie comptant."}, {"label": "Comportement", "text": "Directe et efficace. A dit \"comptant\" de façon affirmée — pas agressive. Elle ne ferme pas la porte mais c'est sa position de départ."}, {"label": "Non-verbal", "text": "Posture assurée, ton calme. Légère tension si on parle trop de financement — se détend si on respecte sa position."}, {"label": "Rapport au financement", "text": "A toujours payé comptant. Pas d'expérience de LOA. \"Je veux pas de crédit\" est un principe, pas une allergie absolue."}, {"label": "Frein / tension probable", "text": "Sentiment que le financement va lui coûter plus cher. Ne veut pas être manipulée vers quelque chose qu'elle n'a pas demandé."}], "context": "Mardi 14h. Elle est venue directement pour \"voir le véhicule et si ça convient, on signe\". Elle a mentionné \"je paie comptant\" dans les premières minutes.", "stakes": "L'enjeu : ne pas contourner sa position ni l'attaquer — mais glisser un teasing ultra-léger après la découverte, de type \"je note\" plutôt que relance active, pour garder la porte ouverte sans créer de résistance.", "observe": ["Respecte-t-il la position \"comptant\" sans la contester ?", "Glisse-t-il un teasing ultra-léger et non-intrusif ?", "Sa formule ne ressemble-t-elle pas à une tentative de convaincre ?", "Garde-t-il la porte ouverte sans la forcer ?"]}, {"level": "avance", "title": "Le client pressé qui veut \"juste voir le prix\"", "objective": "Insérer le teasing dans un RDV sous tension temporelle, choisir le bon moment malgré le rythme imposé, et créer l'anticipation positive sur le financement sans ralentir le RDV.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 39 ans, chef de projet BTP. A 45 minutes maximum. Veut aller à l'essentiel."}, {"label": "Comportement", "text": "Entre rapidement, coupe parfois les phrases. Répond couramment. Signale impatience si on s'étend."}, {"label": "Non-verbal", "text": "Regarde sa montre. Répond les bras croisés. Se détend quand on va à l'essentiel."}, {"label": "Rapport au financement", "text": "A eu un crédit auto classique sur son précédent véhicule. Bonne expérience. Ouvert à discuter si c'est rapide."}, {"label": "Frein / tension probable", "text": "Le temps. Toute impression de perdre du temps sur quelque chose de secondaire le fait décrocher."}], "context": "Jeudi 12h30. Il arrive en avance sur son créneau de 45 minutes. A dit \"je veux voir le modèle et avoir un prix — si ça me convient je reviens avec ma femme\".", "stakes": "L'enjeu : trouver le moment et la formule de teasing les plus efficaces dans un temps contraint. Le teasing \"lors de l'argumentation véhicule\" est probablement le plus adapté ici — il est court, intégré dans le flux, et crée l'anticipation sans détourner le sujet.", "observe": ["Identifie-t-il le bon moment malgré la pression temporelle ?", "Sa formule est-elle courte et intégrée au flux — non intrusive ?", "Crée-t-il l'anticipation positive sans ralentir le RDV ?", "La réaction du client au teasing l'informe-t-elle pour la suite ?"]}]}, "online": {"focus": "le teasing financement", "attentionPoints": ["Choisit-il le bon moment pour teaser ?", "Sa formule est-elle ouverte et neutre ?", "Écoute-t-il vraiment la réponse du client ?", "Revient-il sur le sujet principal sans enchaîner sur le Fi ?"], "grid": ["Bon moment choisi", "Formule ouverte & neutre", "Réponse écoutée", "Pas d'enchaînement Fi"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"À quel moment tu as teasé — et pourquoi ce moment ? Quelle formule tu as utilisée ? Qu'est-ce que la réponse du client t'a appris sur sa posture vis-à-vis du financement ? Est-ce que tu as enchaîné sur le Fi ou tu es revenu sur le véhicule ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que tu as glissé le teasing à [moment précis] avec [formule]. Le client a répondu [réaction]. Ça t'a donné une information précieuse sur sa posture — et tu es revenu sur le véhicule naturellement. C'est exactement ça.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as teasé trop tôt — avant d'avoir établi le lien]. La prochaine fois, attends que le client soit à l'aise et que les questions d'usage soient faites. Le teasing fonctionne dans un contexte de confiance — pas en ouverture.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client : note le moment du teasing, la formule utilisée, et la réaction du client. Ces 3 éléments me donnent tout ce qu'il faut pour débriefer. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 3 formules de teasing sont connues — le bon moment et la formule ouverte sont acquis", "offline": "Le geste est pratiqué sur 3 profils et contextes différents — l'insertion naturelle est un réflexe", "online": "Le coach a observé et débriefé le teasing en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/6- Proposer un Fi & PC/b. Teasing du financement.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('9f0bb561-4733-520b-8676-38d88a4c7f37', '5e416cd2-ba71-5b9b-98a3-0677bd11cc05');
insert into public.library_dojos (id, title, content, pptx_path) values ('48dde794-b058-564e-81d6-4c987487234a', 'Recherche véhicule par mensualité', $dojo${"version": 1, "tagline": "Inverser la logique prix → mensualité pour élargir les possibilités", "objective": "Le commercial applique les 4 étapes dans l'ordre (mensu → apport/reprise → durée → véhicule), utilise la durée comme levier positif, et présente une sélection ciblée avec le bénéfice avant la mensualité.", "duration": "25-30 min", "theory": {"intro": null, "standardTitle": "Le standard : la logique inversée & les 4 étapes", "standard": [{"label": "La logique classique part du prix du véhicule et calcule la mensualité. La logique inversée part de la mensualité souhaitée et remonte au véhicule accessible. Pour un client qui raisonne en budget mensuel, c'est la seule approche qui a du sens — et elle ouvre souvent vers des véhicules mieux adaptés.", "title": "❌  LOGIQUE CLASSIQUE", "description": "Prix véhicule  →  Apport  →  Durée  →  Mensualité", "why": "Le client calcule la mensualité à la fin — souvent surprise, parfois déception. L'effet prix bloque avant même la discussion."}, {"label": "✅  LOGIQUE INVERSÉE", "title": "Mensualité souhaitée  →  Apport  →  Durée  →  Véhicule accessible", "description": "Le client valide son budget en premier. La sélection du véhicule se fait dans un espace déjà validé — sans surprise.", "why": "LES 4 ÉTAPES DE LA MÉTHODE"}, {"label": "1", "title": "VALIDER LA MENSU", "description": "\"Vous vous sentez à l'aise avec combien par mois ?\" Poser la question directement, sans tourner autour. Obtenir un chiffre — ou une fourchette.", "why": "Le budget mensuel validé est l'ancre de toute la construction. Sans lui, on construit dans le vide."}, {"label": "2", "title": "INTÉGRER L'APPORT", "description": "\"Vous avez un apport prévu — ou un véhicule à reprendre ?\" L'apport et la reprise s'ajoutent au budget mensuel pour calculer la capacité totale.", "why": "Oublier l'apport, c'est parfois se priver de 5 000 à 15 000€ de capacité d'achat supplémentaire."}, {"label": "3", "title": "CHOISIR LA DURÉE", "description": "\"Sur combien de mois vous souhaitez étaler — 36, 48, 60 ?\" La durée est un levier direct sur la mensualité et sur le véhicule accessible.", "why": "Passer de 36 à 48 mois peut ouvrir 4 000 à 6 000€ de véhicule supplémentaire pour la même mensualité."}, {"label": "4", "title": "PRÉSENTER LE VÉHICULE", "description": "\"Avec [X]€/mois, [Y]€ d'apport sur [Z] mois — voici ce que je peux vous proposer.\" Le véhicule arrive comme la conclusion logique du budget.", "why": "Le client qui a validé son budget reçoit la sélection comme une réponse à sa demande — pas comme une contrainte imposée."}], "criteria": [{"title": "Il pose la question de la mensualité directement", "description": "\"Vous vous sentez à l'aise avec combien par mois ?\" — direct, ouvert, sans jugement. Pas de \"vous avez un budget ?\" qui est vague. Pas de \"vous pouvez aller jusqu'à combien ?\" qui oriente vers le maximum. La question ouverte sur la mensualité donne le vrai chiffre."}, {"title": "Il utilise la durée comme levier positif", "description": "\"Si on passe à 48 mois au lieu de 36, on peut vous accéder à un véhicule avec [équipement important pour vous] pour la même mensualité.\" La durée n'est pas une contrainte — c'est un outil pour accéder à plus dans le même budget."}, {"title": "Il intègre la reprise et l'apport dès le départ", "description": "Ne pas demander l'apport et la reprise à la fin — les intégrer dès le calcul de capacité. Un client avec 5 000€ d'apport + 8 000€ de reprise a 13 000€ de plus à jouer — ce qui change radicalement le véhicule accessible."}, {"title": "Il présente une sélection — pas un catalogue", "description": "Avec le budget calculé, proposer 1 à 2 véhicules maximum qui correspondent. Pas \"voilà tout ce que vous pouvez avoir\" — mais \"voilà ce que je vous recommande dans votre budget\". La sélection conseillée vaut mieux que le catalogue brut."}, {"title": "Il annonce la mensualité finale avec le bénéfice — pas d'abord", "description": "\"Ce véhicule correspond à vos usages et à vos besoins — et dans votre budget, ça donne [mensualité]€/mois.\" Le bénéfice justifie la mensualité. La mensualité seule appelle la comparaison."}], "mistakes": [{"title": "Erreur 1 — Partir du prix et calculer la mensualité à la fin", "description": "Présenter un véhicule à 28 000€ puis annoncer \"ça fait 412€/mois\". Le client qui avait 300€/mois en tête est bloqué — et le commercial doit revenir en arrière. Partir de la mensualité évite toute cette séquence en inversant le point de départ."}, {"title": "Erreur 2 — Oublier d'explorer l'apport et la reprise", "description": "Calculer la capacité sur la seule mensualité sans demander l'apport ni la reprise, c'est travailler sur un budget incomplet. Un client qui a 6 000€ d'apport et un véhicule à reprendre à 7 000€ a 13 000€ de plus — ce qui peut changer entièrement le véhicule proposé."}, {"title": "Erreur 3 — Présenter trop de véhicules dans le budget", "description": "\"Avec 350€/mois vous pouvez avoir ce modèle, ou celui-là, ou encore celui-ci...\" — trop de choix paralyse. Le client ne sait plus quoi choisir et délègue la décision. Une recommandation ciblée (\"pour votre profil, c'est celui-ci\") est bien plus efficace qu'un catalogue complet."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Donner les éléments de découverte au commercial avant. Briefer : \"Je vais jouer un client dont la contrainte principale est le budget mensuel. Tu dois partir de ma mensualité pour trouver le véhicule — pas l'inverse. Je t'arrête si tu pars du prix.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona. Donner la mensualité souhaitée si on la demande directement. Donner l'apport et la reprise seulement si la question est posée. Observer : part-il de la mensualité ? Intègre-t-il l'apport ? Utilise-t-il la durée comme levier ? Présente-t-il 1-2 véhicules ou un catalogue ?"}, {"title": "Débriefer", "description": "\"Par quoi as-tu commencé — la mensualité ou le prix ? As-tu demandé l'apport et la reprise — et à quel moment ? As-tu utilisé la durée comme levier positif ? Combien de véhicules tu m'as présentés — et pourquoi ceux-là ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client qui raisonne en budget mensuel : applique les 4 étapes dans l'ordre. Note la mensualité, l'apport, la durée choisie et le véhicule proposé. Reviens me voir avec ces 4 éléments et comment le client a réagi.\""}], "scenarios": [{"level": "debutant", "title": "Le primo-accédant avec un budget serré et transparent", "objective": "Appliquer les 4 étapes dans l'ordre, intégrer apport et reprise dans le calcul, utiliser la durée comme levier pour accéder à un meilleur véhicule, présenter 1 véhicule ciblé.", "duration": "25 min", "persona": [], "context": null, "stakes": null, "observe": ["Commence-t-il par la mensualité — pas par le prix ?", "Intègre-t-il l'apport de 1 500€ dans le calcul ?", "Utilise-t-il la durée (48 ou 60 mois) pour accéder à plus ?", "Présente-t-il 1 véhicule ciblé avec le bénéfice avant la mensualité ?"]}, {"level": "intermediaire", "title": "Le client avec apport + reprise qui ne les a pas mentionnés", "objective": "Détecter et intégrer l'apport et la reprise dans le calcul de capacité, montrer au client que son budget réel est supérieur à ce qu'il pensait, et élargir la sélection en conséquence.", "duration": "25 min", "persona": [], "context": null, "stakes": null, "observe": ["Pose-t-il la question de l'apport disponible ?", "Pose-t-il la question du véhicule actuel et de sa valeur de reprise ?", "Montre-t-il au client que sa capacité réelle est supérieure à 300€/mois ?", "Élargit-il la sélection en cohérence avec la capacité réelle ?"]}, {"level": "avance", "title": "Le client dont la mensualité souhaitée et le véhicule voulu sont incompatibles", "objective": "Gérer l'écart entre la mensualité souhaitée et le véhicule désiré, utiliser tous les leviers (apport, reprise, durée) pour se rapprocher au maximum, et construire une proposition honnête sans sur-promettre.", "duration": "30 min", "persona": [], "context": null, "stakes": null, "observe": ["Intègre-t-il apport + reprise pour maximiser la capacité réelle ?", "Utilise-t-il 60 mois comme levier pour réduire l'écart ?", "Présente-t-il honnêtement l'écart et les options (descendre en gamme ou augmenter le budget) ?", "Propose-t-il une alternative cohérente avec les vrais critères de découverte ?"]}]}, "online": {"focus": "la recherche par mensualité", "attentionPoints": ["Part-il de la mensualité — pas du prix du véhicule ?", "Intègre-t-il apport et reprise dans le calcul ?", "Utilise-t-il la durée comme levier positif ?", "Présente-t-il une sélection ciblée avec le bénéfice avant la mensualité ?"], "grid": ["Départ : mensualité (pas prix)", "Apport + reprise intégrés", "Durée utilisée comme levier", "Sélection ciblée + B avant mensu"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Par quoi as-tu commencé — la mensualité ou le prix du véhicule ? As-tu demandé l'apport et la reprise — et ça a changé quoi dans ton calcul ? As-tu utilisé la durée comme levier — à quel moment et comment ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que tu as commencé par [mensualité ou autre]. Quand tu as intégré [apport/reprise], la capacité est passée de X à Y — et tu en as profité pour proposer [véhicule plus adapté]. C'est exactement la logique inversée.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as oublié de demander la reprise — et tu t'es limité à une capacité sous-estimée]. La prochaine fois, les 4 étapes dans l'ordre : mensualité, apport, reprise, durée — avant de chercher le véhicule.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client qui raisonne en budget mensuel : note les 4 éléments (mensu, apport, reprise, durée) et le véhicule finalement proposé. Reviens me voir avec ces 4 éléments et la réaction du client. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "La logique inversée est comprise — mensualité → apport/reprise → durée → véhicule", "offline": "Les 4 étapes sont pratiquées sur 3 profils différents — les leviers (durée, apport) sont des réflexes", "online": "Le coach a observé et débriefé la recherche par mensualité en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/6- Proposer un Fi & PC/c. Recherche par mensu.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('48dde794-b058-564e-81d6-4c987487234a', 'c99ab823-c3d0-57c7-beea-134855e30704');
insert into public.library_dojos (id, title, content, pptx_path) values ('01017fe3-2dab-5851-9492-19d47dcef625', 'Closing financement', $dojo${"version": 1, "tagline": "Engager le client jusqu'à l'accord de principe — sans forcer", "objective": "Le commercial détecte les signaux d'achat, choisit la bonne technique de closing selon le profil, pose la question et tient le silence, et gère la dernière objection avec A.R.E. avant de re-proposer.", "duration": "25-30 min", "theory": {"intro": "Closer le financement ne signifie pas forcer une signature. C'est accompagner le client jusqu'à un accord de principe en levant les dernières hésitations. La clé : lire les signaux d'achat et choisir la bonne technique selon le profil.", "standardTitle": "Le standard : signaux d'achat & 4 techniques de closing Fi", "standard": [{"label": "LES 3 SIGNAUX D'ACHAT FI — AVANT DE CLOSER", "title": "Questions sur les délais", "description": "\"Et ça prend combien de temps pour avoir le véhicule ?\" — Il se projette déjà dans la possession — pas dans la décision.", "why": "Questions sur les détails"}, {"label": "\"Et si je prends le financement, la carte grise c'est inclus ?\" — Il règle les détails pratiques d'un projet qu'il a mentalement validé.", "title": "Silence pensif après la proposition", "description": "Le client regarde les chiffres, hoche la tête, ne dit plus d'objection. — L'absence d'objection est souvent un signal positif — pas un désintérêt.", "why": "LES 4 TECHNIQUES DE CLOSING Fi"}, {"label": "CLOSING DIRECT", "title": "\"Alors — on lance le dossier ?\"", "description": "Client clairement engagé, signaux forts, pas d'hésitation visible.", "why": "CLOSING ALTERNATIF"}, {"label": "\"Vous préférez démarrer sur 48 ou 60 mois ?\"", "title": "Client engagé mais qui a besoin d'un dernier choix pour décider.", "description": "CLOSING RÉCAPITULATIF", "why": "\"Donc : [véhicule], [mensualité]€/mois sur [durée], livraison dans [délai]. On y va ?\""}, {"label": "Client qui a besoin de revoir l'ensemble avant de confirmer.", "title": "CLOSING PROGRESSIF", "description": "\"Est-ce que la mensualité vous convient ? ... Et la durée ? ... Alors on peut lancer le dossier.\"", "why": "Client hésitant qui a besoin de valider chaque élément avant l'accord global."}], "criteria": [{"title": "Il détecte le bon moment — et ne tarde pas", "description": "Un commercial qui détecte un signal d'achat et continue à argumenter rate la fenêtre. Le closing se fait quand le client est prêt — pas quand le script est terminé. La lecture du moment est plus importante que la maîtrise des formules."}, {"title": "Il choisit la bonne technique selon le profil", "description": "Un client décidé → closing direct. Un client qui veut choisir → alternatif. Un client rassuré par les récaps → récapitulatif. Un client hésitant élément par élément → progressif. Appliquer la même technique à tout le monde, c'est rater la moitié des closings."}, {"title": "Il pose le closing et laisse le silence", "description": "\"Alors — on lance le dossier ?\" puis silence complet. Ne pas combler. Le commercial qui répond à sa propre question de closing annule l'effet. Le silence après le closing appartient au client."}, {"title": "Il gère la dernière objection comme une vraie objection", "description": "Une objection au moment du closing (\"je voudrais réfléchir encore\") n'est pas un refus — c'est la dernière résistance avant l'accord. Appliquer A.R.E. → qualification → R.A.C., puis re-proposer le closing. Pas de pression, pas d'abandon."}, {"title": "Il célèbre l'accord avec la même énergie qu'il l'a construit", "description": "\"Parfait — on y va !\" dit avec le même naturel que tout le reste du RDV. Pas de soupir de soulagement, pas de changement de ton. L'accord de principe est une étape, pas une fin — le suivi commence immédiatement après."}], "mistakes": [{"title": "Erreur 1 — Continuer à argumenter alors que les signaux d'achat sont là", "description": "Le client pose des questions sur les délais de livraison — et le commercial continue à expliquer les avantages de la LOA. La fenêtre de closing se referme pendant qu'il argumente. Quand le signal est là, on s'arrête et on propose la prochaine étape."}, {"title": "Erreur 2 — Combler le silence après la question de closing", "description": "\"Alors — on lance le dossier ? ... Enfin, si vous êtes prêt hein, pas de pression...\" Le commercial qui comble son propre silence de closing désamorce lui-même sa question. Poser la question — puis silence total. Attendre."}, {"title": "Erreur 3 — Abandonner au premier \"je vais réfléchir\" de fin de RDV", "description": "Ranger ses affaires et dire \"d'accord, revenez quand vous voulez\" à la première hésitation. Le \"je vais réfléchir\" en fin de RDV est presque toujours une objection — pas un refus. L'explorer avec A.R.E., lever le frein, et re-proposer le closing."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je vais jouer un client en fin de RDV — la proposition Fi est faite. Ton objectif : détecter les signaux d'achat, choisir la bonne technique, poser le closing et tenir le silence. Je lève la main si tu continues à argumenter après un signal d'achat.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona en fin de RDV. Donner des signaux d'achat clairs mais non explicites. Si le commercial pose le closing, tenir le silence 3-4 secondes puis réagir selon le persona. Observer : détecte-t-il les signaux ? Quelle technique ? Tient-il le silence ?"}, {"title": "Débriefer", "description": "\"À quel moment tu as décidé de closer — qu'est-ce qui t'a déclenché ? Quelle technique tu as choisie — et pourquoi celle-là pour ce profil ? Tu as tenu le silence après ta question de closing — combien de secondes ? Si j'ai objecté, qu'est-ce que tu as fait ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain closing Fi : note le signal d'achat que tu as détecté, la technique que tu as utilisée, et si tu as tenu le silence. Ces 3 éléments. Date de retour : [date].\""}], "scenarios": [{"level": "debutant", "title": "Le client convaincu qui attend qu'on lui propose", "objective": "Détecter les signaux d'achat explicites, choisir le closing direct, poser la question et tenir le silence sans argumenter davantage.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 34 ans, kinésithérapeute libérale. Tout s'est bien passé — le véhicule lui plaît, la mensualité est dans son budget."}, {"label": "Comportement au moment du closing", "text": "Pose des questions sur la livraison et la couleur disponible. Sourit en regardant la proposition. Hoche la tête sur les chiffres."}, {"label": "Non-verbal", "text": "Posture ouverte, légèrement penchée vers la table. Regard engagé sur la fiche de proposition. Pas de tension."}, {"label": "Ce qui le bloque", "text": "Rien de particulier — elle attend simplement qu'on lui propose la prochaine étape."}, {"label": "Ce qui le ferait signer", "text": "Un closing direct, naturel, sans pression. Elle dit oui facilement si on lui demande clairement."}], "context": "Vendredi 17h. RDV de 1h30 qui s'est très bien déroulé. La proposition LOA à 298€/mois sur 48 mois vient d'être présentée. Elle a dit \"c'est bien\" en regardant les chiffres et a demandé \"et la livraison c'est dans combien de temps ?\"", "stakes": "Signal d'achat clair. Le commercial doit détecter ce signal, s'arrêter d'argumenter, et poser le closing direct. L'enjeu : ne pas continuer à expliquer et tenir le silence après la question.", "observe": ["Détecte-t-il le signal d'achat (question livraison) ?", "S'arrête-t-il d'argumenter au bon moment ?", "Choisit-il le closing direct adapté au profil ?", "Tient-il le silence après sa question de closing ?"]}, {"level": "intermediaire", "title": "Le client hésitant qui valide tout mais ne décide pas", "objective": "Détecter l'hésitation de principe (pas de vrai blocage), utiliser le closing progressif pour valider chaque élément, et amener naturellement à l'accord global.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 42 ans, enseignant. A dit \"oui\" à tout mais reste paralysé au moment de conclure. Pas de raison précise."}, {"label": "Comportement au moment du closing", "text": "Acquiesce sur chaque point. Dit \"oui c'est bien\" sur le véhicule, la mensualité, la durée. Puis reste silencieux sans conclure. Cherche une raison de ne pas décider aujourd'hui."}, {"label": "Non-verbal", "text": "Corps légèrement en retrait quand arrive le moment de signer. Regard qui décroche. Doigts qui tapotent la table."}, {"label": "Ce qui le bloque", "text": "Peur de s'engager sans raison précise — habitude de ne jamais décider sur le moment. Pas d'objection fondée."}, {"label": "Ce qui le ferait signer", "text": "Le closing progressif qui re-valide chaque élément le guide vers l'accord sans qu'il sente de pression."}], "context": "Mercredi 16h. Tout s'est bien passé. Proposition crédit classique à 312€/mois sur 60 mois. Il a dit \"oui\" à tout mais ne propose pas lui-même de signer.", "stakes": "L'enjeu : utiliser le closing progressif pour transformer ses \"oui\" successifs en accord global. Re-valider la mensualité, la durée, puis proposer le dossier. Chaque micro-oui prépare le oui final.", "observe": ["Identifie-t-il l'hésitation de principe sans objection fondée ?", "Choisit-il le closing progressif adapté ?", "Valide-t-il chaque élément avant de proposer l'accord global ?", "Arrive-t-il à l'accord sans créer de pression ?"]}, {"level": "avance", "title": "Le client qui objecte au dernier moment — \"je vais quand même réfléchir\"", "objective": "Appliquer A.R.E. sur l'objection de closing, qualifier si c'est un prétexte ou une vraie hésitation, lever le frein réel, et re-proposer le closing sans pression.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 51 ans, chef d'atelier mécanique. Paraissait convaincu — puis recule juste avant la signature."}, {"label": "Comportement au moment du closing", "text": "A tout validé pendant le RDV. Au moment du closing direct, dit soudainement \"je vais quand même réfléchir encore un peu\". Ton qui change légèrement. Commence à récupérer ses affaires."}, {"label": "Non-verbal", "text": "Posture qui se ferme. Regard qui fuit légèrement. Légère tension dans les épaules. Tout signale une dernière résistance."}, {"label": "Ce qui le bloque", "text": "En réalité : il n'a pas voulu dire à sa femme qu'il allait signer aujourd'hui. Il a besoin de lui en parler — mais n'ose pas le dire."}, {"label": "Ce qui le ferait signer", "text": "Proposer un RDV avec sa femme la semaine prochaine + lui donner un récap écrit à emporter. La liberté de partir sans signer réduit l'anxiété et prépare le retour."}], "context": "Jeudi 18h. RDV qui semblait parfait. LOA à 278€/mois sur 48 mois — dans son budget. Il a posé des questions sur la livraison (signal d'achat). Le commercial a posé le closing direct — et le client recule.", "stakes": "L'enjeu : ne pas abandonner, ne pas forcer. Appliquer A.R.E. sur \"je vais réfléchir\", explorer pour découvrir le vrai frein (sa femme), proposer une solution concrète (RDV à deux), et re-proposer le closing sur cette nouvelle base.", "observe": ["Ne cède-t-il pas immédiatement au \"je réfléchis\" ?", "Applique-t-il A.R.E. pour explorer le vrai frein ?", "Détecte-t-il que le frein est la décision en couple ?", "Propose-t-il une solution concrète et re-close sur cette base ?"]}]}, "online": {"focus": "le closing financement", "attentionPoints": ["Détecte-t-il les signaux d'achat au bon moment ?", "Choisit-il la bonne technique selon le profil ?", "Tient-il le silence après la question de closing ?", "Gère-t-il la dernière objection avec A.R.E. avant de re-closer ?"], "grid": ["Signaux d'achat détectés", "Bonne technique choisie", "Silence tenu après closing", "Dernière objection gérée"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"À quel moment tu as décidé de closer — qu'est-ce qui t'a déclenché ? Quelle technique tu as choisie ? Tu as tenu le silence — combien de temps ? Et si le client a objecté, qu'est-ce que tu as fait ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand [signal d'achat précis], tu as [action : stoppé l'argumentation / posé le closing]. Le client a réagi en [observation]. Ce moment — détecter et agir au bon moment — c'est exactement ça le closing.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as continué à argumenter après le signal d'achat]. La prochaine fois, dès que le client pose une question logistique (délai, couleur, carte grise), stoppe-toi et pose le closing. Ce sont des invitations à conclure.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain closing Fi : note le signal d'achat détecté, la technique utilisée, et si tu as tenu le silence. Si le client a objecté, note aussi comment tu l'as traitée. Ces éléments. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 3 signaux d'achat et les 4 techniques sont connus — le silence après le closing est sacré", "offline": "Le closing est pratiqué sur 3 profils et blocages différents — détecter et agir est un réflexe", "online": "Le coach a observé et débriefé le closing financement en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/6- Proposer un Fi & PC/d. Closing Fi.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('01017fe3-2dab-5851-9492-19d47dcef625', '91501195-b82a-5f95-b077-809cdc12df8c');
insert into public.library_dojos (id, title, content, pptx_path) values ('0120c6e8-66de-5184-b95f-cb577a3894d2', 'Produits assurance & complémentaires', $dojo${"version": 1, "tagline": "Proposer les protections en les liant aux besoins découverts", "objective": "Le commercial sélectionne 1-2 produits adaptés au profil, les présente avec un pont vers la découverte, annonce le B avant le coût, et demande l'accord produit par produit.", "duration": "25-30 min", "theory": {"intro": "Ces produits ne se proposent pas \"par défaut\" — ils se présentent comme des réponses à des besoins identifiés en découverte. Le CAB n'a de force que si le B est ancré dans ce que le client a dit.", "standardTitle": "Le standard : CAB sur les 4 produits complémentaires", "standard": [{"label": "GAP", "title": "C", "description": "Couvre la différence entre la valeur assurée du véhicule et le capital restant dû au financement en cas de perte totale.", "why": "A"}, {"label": "En cas de sinistre total, vous n'avez pas à rembourser une différence qui peut atteindre plusieurs milliers d'euros.", "title": "B", "description": "Vous m'avez dit que vous gardiez le véhicule 4 ans — si un sinistre arrive en année 2, la décote peut créer un écart important. Le GAP vous protège exactement contre ça.", "why": "PERTE D'EMPLOI"}, {"label": "C", "title": "Prend en charge les mensualités du financement en cas de licenciement économique, sur une durée définie.", "description": "A", "why": "Vous continuez à rouler même si vous perdez votre emploi — vos mensualités sont couvertes pendant la période difficile."}, {"label": "B", "title": "Vous m'avez dit que vous étiez en CDI mais que votre secteur est incertain. Cette garantie prend le relais si la situation change — vos mensualités sont protégées.", "description": "EXTENSION DE GARANTIE", "why": "C"}, {"label": "Prolonge la couverture constructeur au-delà des 2 ans standard, sur les pièces mécaniques et électroniques.", "title": "A", "description": "Vous roulez serein au-delà de la garantie constructeur — une panne majeure ne vous coûte pas des milliers d'euros.", "why": "B"}, {"label": "Vous m'avez dit que vous comptiez garder ce véhicule 5-6 ans. Les pannes arrivent souvent après 3 ans — l'extension vous protège exactement pendant cette période.", "title": "CONTRAT ENTRETIEN", "description": "C", "why": "Lisse le coût des entretiens obligatoires sur la durée du financement — vidanges, filtres, freins selon les forfaits."}, {"label": "A", "title": "Vous n'avez plus de surprise sur les coûts d'entretien — un budget mensuel fixe couvre l'ensemble.", "description": "B", "why": "Vous m'avez dit que vous faisiez beaucoup de kilomètres professionnels. Avec 40 000 km/an, les entretiens arrivent vite — ce contrat transforme les coûts imprévus en budget maîtrisé."}], "criteria": [], "mistakes": [], "sections": [{"title": "Quand et comment proposer les produits complémentaires", "lines": ["Le moment de la proposition est aussi important que l'argument. Trop tôt = le client n'a pas encore décidé du véhicule. Trop tard = le client est en train de signer et se sent ralenti. La fenêtre idéale : après la validation du financement principal, avant la signature.", "1", "Sélectionner 1 à 2 produits maximum", "Proposer les 4 d'un coup = impression de \"tout vendre\". Choisir avant le RDV les 1-2 produits les plus adaptés au profil — et ne proposer que ceux-là.", "Signal : le client valide son financement et pose des questions sur les étapes suivantes.", "2", "Introduire avec un pont vers la découverte", "\"En lien avec ce que vous m'avez dit sur [X]...\" Ce pont évite l'effet catalogue et relie le produit à un besoin exprimé par le client lui-même.", "Formule : \"Vu que vous m'avez dit [X], je vous conseille [produit] — parce que [B].\"", "3", "Présenter le B avant le prix", "Bénéfice d'abord, coût ensuite. \"Ça vous protège contre [situation concrète] — et en mensualité ça représente [X]€ supplémentaires.\"", "Règle : entendu après le bénéfice, le coût est comparé à la valeur — pas à zéro.", "4", "Demander l'accord produit par produit", "Ne pas grouper dans une mensualité globale. Présenter chaque produit avec son B et demander l'accord séparément. Un accord partiel vaut mieux qu'un refus global.", "Fermeture : \"On intègre ça dans votre dossier ?\" — pas \"vous prenez tout ?\""]}, {"title": "Critères d'excellence & erreurs à éviter", "lines": ["✅  CRITÈRES D'EXCELLENCE", "Il ancre le B dans la découverte", "\"Vous m'avez dit X\" est la clé. Un B générique ne convainc pas — un B qui répond à quelque chose dit par le client convainc.", "Il propose 1-2 produits max", "Sélection ciblée = conseil. Catalogue complet = vente. Le client perçoit immédiatement la différence.", "Il présente le B avant le coût", "Le coût en mensualité est marginal — mais seulement si le client a déjà mentalement validé la valeur du bénéfice.", "Il demande l'accord produit par produit", "Chaque accord partiel est une vente. Un refus global sur 4 produits présentés ensemble est une occasion manquée.", "❌  ERREURS À ÉVITER", "Proposer tous les produits par défaut", "\"Et avec ça il y a le GAP, la perte d'emploi, l'extension et l'entretien\" sans lien avec le profil. Le client décroche immédiatement.", "Commencer par le coût mensuel additionnel", "\"Ça fait 28€ de plus par mois\" dit avant le B. Le client compare à zéro — et dit non avant d'avoir entendu la valeur.", "Grouper tous les produits en une mensualité totale", "\"Avec toutes les protections c'est 65€/mois en plus.\" Impossible de distinguer la valeur de chaque produit — le refus est global.", "Proposer les produits trop tard", "Après la signature du financement principal, le client est en mode clôture. Il ne veut plus entendre de proposition — la fenêtre est fermée."]}]}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Donner les éléments de découverte avant. Briefer : \"Le financement vient d'être validé. Tu dois maintenant proposer les produits complémentaires adaptés à mon profil. Je t'arrête si tu proposes un produit sans lien avec ce que je t'ai dit en découverte.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona après la validation du financement. Observer : quels produits sont sélectionnés ? Y a-t-il un pont vers la découverte ? Le B précède-t-il le coût ? L'accord est-il demandé produit par produit ? Réagir naturellement selon le persona."}, {"title": "Débriefer", "description": "\"Quels produits tu as choisi — et pourquoi ceux-là pour mon profil ? Comment tu as introduit chaque produit — tu as fait le pont avec la découverte ? Tu as présenté le B avant le coût ? Comment tu as demandé l'accord ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client : avant de proposer les complémentaires, note les 1-2 produits que tu vas proposer et le B ancré dans la découverte pour chacun. Reviens me voir avec ces éléments et la réaction du client.\""}], "scenarios": [{"level": "debutant", "title": "Le client LOA — profil fort kilométrage", "objective": "Sélectionner GAP + contrat entretien sur la base du profil, présenter avec pont découverte, B avant coût, accord produit par produit.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 36 ans, commercial terrain. 45 000 km/an, utilise son véhicule comme outil de travail."}, {"label": "Comportement", "text": "Direct et pragmatique. Pose des questions sur la praticité. Sensible à la prévisibilité du budget."}, {"label": "Non-verbal", "text": "Détendu après validation du financement. Ouvert à entendre des conseils si c'est utile."}, {"label": "Profil produit", "text": "GAP adapté (LOA 48 mois, fort usage). Contrat entretien évident (45 000 km/an = entretiens fréquents)."}, {"label": "Frein", "text": "Peut résister si on lui présente comme \"des options supplémentaires\" sans lien avec son usage."}], "context": "LOA à 310€/mois sur 48 mois vient d'être validée. Découverte : 45 000 km/an, déplacements pros quotidiens, budget mensuel maîtrisé est sa priorité. Il a mentionné que son dernier véhicule avait eu une panne coûteuse hors garantie.", "stakes": null, "observe": ["Sélectionne-t-il GAP et contrat entretien — pas les 4 ?", "Fait-il le pont avec les 45 000 km et la panne mentionnée ?", "Présente-t-il le B avant le coût mensuel additionnel ?", "Demande-t-il l'accord sur chaque produit séparément ?"]}, {"level": "intermediaire", "title": "Le client en CDI précaire — secteur en tension", "objective": "Identifier la perte d'emploi comme produit prioritaire, construire un B ancré dans l'inquiétude exprimée, proposer sans dramatiser, obtenir l'accord.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 31 ans, chargée de communication en CDI dans une agence. Secteur communication en restructuration."}, {"label": "Comportement", "text": "Engagée sur le projet auto. A mentionné en passant que \"le secteur n'est pas stable\". Pas de demande explicite."}, {"label": "Non-verbal", "text": "Légère tension quand on parle de durée de financement sur 48 mois. Se détend si on l'accompagne."}, {"label": "Profil produit", "text": "Perte d'emploi en priorité (elle a signalé l'incertitude). Extension de garantie si elle garde le véhicule longtemps."}, {"label": "Frein", "text": "Peut percevoir la proposition comme alarmiste si le ton est maladroit. Le B doit rassurer, pas inquiéter."}], "context": "Crédit classique à 285€/mois sur 48 mois validé. Découverte : CDI mais secteur fragile mentionné, budget mensuel bien calibré, préfère la propriété à la LOA. Aucune résistance sur le financement.", "stakes": null, "observe": ["Sélectionne-t-il la perte d'emploi en priorité ?", "Fait-il le pont avec ce qu'elle a dit sur son secteur ?", "Son ton rassure-t-il sans dramatiser la situation ?", "Présente-t-il le B avant les 15-20€ de coût mensuel ?"]}, {"level": "avance", "title": "Le client qui dit \"j'ai déjà une assurance — ça sert à rien\"", "objective": "Accuser réception de l'objection, distinguer assurance auto et produits complémentaires Fi, requalifier le besoin selon le profil, et re-proposer le bon produit.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 52 ans, chef d'entreprise. Très bien assuré par ailleurs. Méfiant envers les produits financiers additionnels."}, {"label": "Comportement", "text": "A dit dès le début \"j'ai déjà tout ce qu'il faut comme assurances\". Pas agressif mais ferme. Écoute si l'argument est factuel."}, {"label": "Non-verbal", "text": "Bras légèrement croisés à l'évocation des produits. Se détend si la distinction est claire et le B précis."}, {"label": "Profil produit", "text": "GAP est pertinent (LOA 48 mois, véhicule à 42 000€, fort risque de décote). Sa propre assurance ne couvre pas la différence."}, {"label": "Frein", "text": "Confusion entre assurance auto classique et garantie perte financière Fi. La distinction factuelle est la clé."}], "context": "LOA à 390€/mois sur 48 mois validée sur un véhicule à 42 000€. Découverte : chef d'entreprise, usage mixte pro/perso, très organisé sur les risques. A dit \"j'ai déjà tout\" quand les complémentaires ont été mentionnés.", "stakes": null, "observe": ["Accuse-t-il réception de l'objection sans défensive ?", "Distingue-t-il assurance auto et GAP clairement ?", "Ancre-t-il le B dans les 42 000€ et la durée de 48 mois ?", "Re-propose-t-il le GAP après avoir levé la confusion ?"]}]}, "online": {"focus": "les produits complémentaires", "attentionPoints": ["Sélectionne-t-il 1-2 produits adaptés au profil ?", "Fait-il le pont avec un élément de la découverte ?", "Présente-t-il le B avant le coût ?", "Demande-t-il l'accord produit par produit ?"], "grid": ["Sélection ciblée (1-2 produits)", "Pont vers découverte fait", "B présenté avant le coût", "Accord produit par produit"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Quels produits tu as sélectionnés — et pourquoi ceux-là pour ce profil ? Tu as fait le pont avec la découverte — sur quel élément ? Tu as présenté le B avant le coût — et comment le client a réagi ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que quand tu as proposé [produit], tu as dit [pont vers découverte]. Le client a réagi en [observation]. Ce lien entre le produit et quelque chose qu'il avait dit lui-même, c'est exactement ce qui fait la différence.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as proposé les 4 produits d'un coup]. La prochaine fois, choisis les 1-2 produits les plus adaptés avant de rentrer dans le RDV — et prépare le pont vers la découverte pour chacun.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain client : note les produits que tu as proposés, le pont découverte utilisé pour chacun, et les accords obtenus. Ces 3 éléments. Date : [date].\""}], "sections": []}, "takeaways": {"theory": "Le CAB des 4 produits est connu — le pont vers la découverte est le seul argument qui convainc", "offline": "Les produits sont proposés sur 3 profils différents — sélection ciblée et B avant coût sont des réflexes", "online": "Le coach a observé et débriefé la proposition des complémentaires en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/6- Proposer un Fi & PC/e. Produits assu & complémentaires.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('0120c6e8-66de-5184-b95f-cb577a3894d2', 'ded5b622-e7e6-551c-a5e5-d80230261159');
insert into public.library_dojos (id, title, content, pptx_path) values ('64d7c9fe-7088-5dca-beea-55981ac87236', 'Objections Fi & assurances', $dojo${"version": 1, "tagline": "8 scénarios pour couvrir l'ensemble des objections liées au financement", "objective": "Le commercial applique A.R.E. → qualification → R.A.C. sur chaque objection Fi & assurance, sans défendre le taux à chaud, en ancrant sa réponse dans la découverte.", "duration": "15-20 min / scénario", "theory": {"intro": null, "standardTitle": null, "standard": [], "criteria": [], "mistakes": [], "sections": []}, "offline": {"guide": [{"title": "Choisir 1 à 3 scénarios par séance", "description": "Ne pas faire les 8 d'un coup. Choisir les objections les plus fréquentes pour le commercial concerné. Alterner financement / assurances / tactique selon les lacunes observées en situation réelle."}, {"title": "Briefer sur la méthode avant chaque scénario", "description": "Rappeler : \"A.R.E. d'abord — tu ne réponds pas à chaud. Tu qualifies avant de répondre. Tu ancres ton R.A.C. dans ce que je t'ai dit en découverte. Je lève la main si tu défends le taux avant d'avoir fait A.R.E.\""}, {"title": "Jouer le persona fidèlement", "description": "Chaque scénario précise si l'objection est fondée, prétexte ou réflexe. Jouer en conséquence : résister si c'est fondé, se laisser convaincre si le commercial a bien qualifié et bien répondu. Ne pas faciliter si la méthode n'est pas appliquée."}, {"title": "Débriefer sur 3 points clés", "description": "\"As-tu dit 'mais' dans ton A.R.E. ? As-tu qualifié avant de répondre — fondée, prétexte ou réflexe ? Ton argument R.A.C. était-il ancré dans la découverte ou générique ? Ces 3 points suffisent pour débriefer chaque scénario.\""}], "scenarios": [{"level": "Financement", "title": "\"Je paie comptant — pas de crédit\"", "objective": "Qualifier si c'est un principe, une stratégie de négociation ou une vraie contrainte — et adapter la réponse sans brusquer la conviction.", "duration": "15 min", "persona": [], "context": null, "stakes": null, "observe": ["Accuse-t-il réception sans attaquer le principe 'comptant' ?", "Explore-t-il la réalité financière derrière le principe ?", "Ancre-t-il son R.A.C. dans la trésorerie professionnelle mentionnée ?"]}, {"level": "Financement", "title": "\"Le taux est trop élevé\"", "objective": "Ne pas défendre le taux — défendre la valeur globale de l'offre et revenir sur le bénéfice ancré dans la découverte.", "duration": "15 min", "persona": [], "context": null, "stakes": null, "observe": ["Évite-t-il de défendre le taux brut immédiatement ?", "Explore-t-il la nature de l'offre comparative avant de répondre ?", "Revient-il sur la mensualité totale plutôt que le taux seul ?"]}, {"level": "Financement", "title": "\"J'ai une offre moins chère chez ma banque\"", "objective": "Accuser réception sans paniquer, qualifier l'offre concurrente, et différencier sur la valeur globale (simplicité, garanties, service) plutôt que le taux brut.", "duration": "15 min", "persona": [], "context": null, "stakes": null, "observe": ["Accuse-t-il réception sans paniquer sur le taux ?", "Qualifie-t-il le périmètre exact de l'offre concurrente ?", "Compare-t-il à périmètre égal plutôt que taux brut vs taux brut ?"]}, {"level": "Financement", "title": "\"Je veux réfléchir encore avant de m'engager\"", "objective": "Identifier si c'est un réflexe ou un prétexte, explorer le vrai frein, et créer les conditions d'un retour sans pression.", "duration": "15 min", "persona": [], "context": null, "stakes": null, "observe": ["Explore-t-il le vrai frein derrière 'je réfléchis' ?", "Détecte-t-il la décision en couple comme frein réel ?", "Propose-t-il un retour structuré sans pression ?"]}, {"level": "Financement", "title": "\"Je comprends pas bien comment ça marche\"", "objective": "Rassurer sans condescendance, expliquer simplement le produit adapté au profil, et valider la compréhension avant d'avancer.", "duration": "15 min", "persona": [], "context": null, "stakes": null, "observe": ["Accuse-t-il réception de l'inquiétude sans minimiser ?", "Explore-t-il ce qui est flou précisément avant d'expliquer ?", "Explique-t-il avec une analogie simple et sans jargon ?"]}, {"level": "Assurances", "title": "\"J'ai déjà une assurance — ça me suffit\"", "objective": "Distinguer assurance auto classique et produits complémentaires Fi, requalifier le besoin sur le profil, et re-proposer le bon produit.", "duration": "15 min", "persona": [], "context": null, "stakes": null, "observe": ["Accuse-t-il réception sans argumenter immédiatement ?", "Pose-t-il la question qui révèle la confusion (perte totale) ?", "Explique-t-il la distinction GAP / assurance auto factuellement ?"]}, {"level": "Assurances", "title": "\"C'est trop cher pour ce que c'est\"", "objective": "Qualifier si c'est une objection de valeur ou de prix, ancrer le bénéfice dans la situation concrète du client, et montrer le coût réel vs le coût perçu.", "duration": "15 min", "persona": [], "context": null, "stakes": null, "observe": ["Explore-t-il le coût réel actuel avant de défendre le produit ?", "Ancre-t-il son argument dans les 38 000 km découverts ?", "Montre-t-il le calcul comparatif concret ?"]}, {"level": "Tactique", "title": "\"Enlevez les assurances — baissez la mensualité\"", "objective": "Résister à la pression de retrait, maintenir la valeur des produits proposés, et proposer un arbitrage structuré plutôt qu'une capitulation.", "duration": "20 min", "persona": [], "context": null, "stakes": null, "observe": ["Résiste-t-il à la pression sans se braquer ?", "Qualifie-t-il si c'est une vraie objection valeur ou une tactique ?", "Propose-t-il un arbitrage alternatif sans capitulation ?"]}]}, "online": {"focus": "les objections Fi & assu", "attentionPoints": ["Applique-t-il A.R.E. avant de répondre (pas de 'mais', pas de réponse à chaud) ?", "Qualifie-t-il l'objection : fondée / prétexte / réflexe / tactique ?", "Défend-il le taux brut ou la valeur globale de l'offre ?", "Son R.A.C. est-il ancré dans la découverte ou générique ?"], "grid": ["A.R.E. appliqué (sans 'mais')", "Objection qualifiée", "Valeur défendue (pas taux)", "R.A.C. ancré découverte"], "debrief": [], "sections": [{"title": "Les 8 objections couvertes dans ce Dojo | 01", "lines": ["Les 8 objections couvertes dans ce Dojo", "01", "Financement", "\"Je paie comptant — pas de crédit\"", "Prétexte / principe", "02", "Financement", "\"Le taux est trop élevé\"", "Fondée / comparative", "03", "Financement", "\"J'ai une offre moins chère chez ma banque\"", "Fondée / comparative", "04", "Financement", "\"Je veux réfléchir encore avant de m'engager\"", "Réflexe / peur d'engagement", "05", "Financement", "\"Je comprends pas bien comment ça marche\"", "Fondée / complexité perçue", "06", "Assurances", "\"J'ai déjà une assurance — ça me suffit\"", "Prétexte / confusion produits", "07", "Assurances", "\"C'est trop cher pour ce que c'est\"", "Fondée / rapport valeur-prix", "08", "Tactique", "\"Enlevez les assurances — baissez la mensualité\"", "Tactique / négociation globale", "Chaque scénario applique A.R.E. → Qualification → R.A.C."]}, {"title": "RAPPEL MÉTHODE | Rappel : la séquence sur chaque objection Fi", "lines": ["RAPPEL MÉTHODE", "Rappel : la séquence sur chaque objection Fi", "Les objections Fi & assurances suivent exactement la même séquence que les autres objections. Ce Dojo s'appuie sur les Dojos Objections déjà réalisés et les applique au contexte spécifique du financement.", "A", "Accuser Réception", "Ne jamais répondre à chaud. Accuser réception sans \"mais\". Reformuler pour valider la compréhension.", "Exemple :", "\"Je comprends tout à fait — vous pouvez me dire ce qui vous retient exactement ?\"", "⚠  Piège :", "Sur les objections Fi, le réflexe est de défendre le taux ou la LOA immédiatement. C'est la pire réponse possible.", "Q", "Qualifier l'objection", "Fondée (vrai frein), prétexte (cache autre chose) ou réflexe (automatique). Poser la question d'exploration ouverte.", "Exemple :", "\"C'est-à-dire ? / C'est par rapport au montant ou à la durée ? / Si ce point était résolu, qu'est-ce qui changerait ?\"", "⚠  Piège :", "\"Je paie comptant\" peut être un principe de vie, une stratégie de négociation, ou une vraie contrainte. Sans qualifier, on répond à côté.", "R", "Répondre avec R.A.C.", "Reconnaître le doute, apporter l'argument ancré dans la découverte, confirmer que le frein est levé.", "Exemple :", "\"Vous avez raison de vérifier — avec ce que vous m'avez dit sur [X], voilà pourquoi [produit] répond à votre situation. C'est plus clair ?\"", "⚠  Piège :", "Répondre avec un argument générique sur le financement plutôt qu'ancré dans ce que le client a dit en découverte.", "Rappel méthode  |  A.R.E. → Qualification → R.A.C."]}]}, "takeaways": {"theory": "A.R.E. → Qualification → R.A.C. s'applique à toutes les objections Fi & assurances sans exception", "offline": "8 objections couvertes — financement / assurances / tactique — le bon réflexe sur chacune est ancré", "online": "Le coach a observé et débriefé le traitement des objections Fi en situation réelle", "next": null}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/6- Proposer un Fi & PC/f. Objections Fi & assu.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('64d7c9fe-7088-5dca-beea-55981ac87236', '256eadd1-eeae-59d6-aafe-f906055eb837');
insert into public.library_dojos (id, title, content, pptx_path) values ('5064722d-abcd-5fe7-88c3-82dc406577db', 'Raison de non-vente', $dojo${"version": 1, "tagline": "Communiquer systématiquement la RNV pour préparer la relance", "objective": "Le commercial qualifie la RNV avant de partir, la formule avec précision (chiffre ou date), reformule au client, et fixe une prochaine étape concrète.", "duration": "20-25 min", "theory": {"intro": null, "standardTitle": "Le standard : les 5 familles de RNV & comment formuler", "standard": [{"label": null, "title": "Une RNV précise est la base d'une relance efficace. Trop vague (\"il réfléchit\"), elle ne permet pas de personnaliser le suivi. Bien formulée, elle oriente l'action suivante et maintient la relation ouverte.", "description": "BUDGET", "why": "\"Le véhicule correspond mais la mensualité dépasse son budget actuel de 50€.\""}, {"label": null, "title": "→ Préparer une alternative (durée, modèle, apport) avant la relance.", "description": "DÉLAI", "why": "\"Véhicule validé, financement OK — attend la fin de son contrat LOA dans 3 mois.\""}, {"label": null, "title": "→ Planifier une relance à J-30 du terme avec confirmation des conditions.", "description": "DÉCISION", "why": "\"Doit en parler à sa femme — RDV à deux proposé pour la semaine prochaine.\""}, {"label": null, "title": "→ Ne pas relancer avant le RDV commun. Envoyer un récap écrit pour faciliter la discussion.", "description": "COMPARAISON", "why": "\"A visité 2 autres concessions — compare sur le prix. Point de différenciation : délai de livraison plus court.\""}, {"label": null, "title": "→ Relancer après 5-7 jours avec l'argument de différenciation identifié.", "description": "AUTRE", "why": "\"RNV bien formulée = RNV avec une famille, un chiffre ou une date. RNV floue = opportunité perdue.\""}], "criteria": [{"title": "Il qualifie la RNV avant de partir", "description": "La RNV se collecte avant de quitter le RDV — pas 2 heures après dans le CRM. \"Avant qu'on se quitte — qu'est-ce qui vous retient encore ?\" donne l'information précise au bon moment."}, {"title": "Sa RNV contient toujours un chiffre ou une date", "description": "\"Il réfléchit\" → inutilisable. \"Il compare — délai de livraison de 3 semaines chez nous vs 6 chez la concurrence\" → actionnable. La précision fait la différence entre une relance ciblée et un appel dans le vide."}, {"title": "Il communique la RNV au manager le jour même", "description": "Une RNV notée 48h après est une RNV partiellement reconstituée. Le commercial qui communique sa RNV le soir du RDV donne à son manager les éléments pour préparer une relance efficace — pas une relance générique."}, {"title": "Il termine le RDV en ouvrant la prochaine étape", "description": "\"Je vous rappelle mardi — est-ce que vous avez votre réunion de famille ce week-end ?\" Le commercial qui ferme le RDV avec une prochaine étape précise maintient la relation active. Celui qui dit \"je vous rappelle\" sans date laisse la relation se refroidir."}, {"title": "Il reformule la RNV au client avant de partir", "description": "\"Donc si je comprends bien — ce qui vous retient c'est [RNV précise]. Je vous rappelle [date] avec [élément de résolution]. C'est bien ça ?\" Cette reformulation valide la compréhension et crée un engagement implicite du client sur la suite."}], "mistakes": [{"title": "Erreur 1 — Formuler une RNV vague", "description": "\"Il réfléchit\", \"pas sûr\", \"veut comparer\" — ces RNV ne permettent pas de préparer une relance efficace. Résultat : un appel de relance générique, une conversation qui repart de zéro, et un client qui ressent qu'on ne l'a pas vraiment écouté."}, {"title": "Erreur 2 — Ne pas qualifier la RNV avant de partir", "description": "Partir du RDV sans avoir posé la question \"qu'est-ce qui vous retient ?\" c'est rater l'opportunité d'obtenir l'information la plus précieuse de tout le RDV. Le client à chaud dira plus facilement ce qui le retient que le client relancé 3 jours après."}, {"title": "Erreur 3 — Ne pas fixer de prochaine étape concrète", "description": "\"Je vous rappelle\" sans date et sans objet défini n'est pas une prochaine étape — c'est une formule de politesse. La prochaine étape doit avoir une date, un contenu (\"je vérifie le délai de livraison\") et une raison de rappeler qui soit utile pour le client."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Briefer : \"Je vais jouer un client en fin de RDV — il ne signe pas aujourd'hui. Avant que je parte, tu dois qualifier ma RNV précisément, la reformuler, et fixer une prochaine étape avec une date. Je lève la main si ta RNV est vague.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona en fin de RDV — donner des signaux de non-décision. Ne pas donner la RNV spontanément — attendre que la question soit posée. Si la question n'est pas posée, partir sans donner l'info. Observer : pose-t-il la question ? Reformule-t-il ? Fixe-t-il une date ?"}, {"title": "Débriefer", "description": "\"As-tu posé la question de la RNV avant que je parte ? Ta RNV contenait un chiffre ou une date — laquelle ? Est-ce que tu l'as reformulée pour valider ma compréhension ? Quelle était ta prochaine étape — avec quelle date et quel contenu ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain RDV sans vente : note la RNV exacte que tu as qualifiée, comment tu l'as formulée, et la prochaine étape fixée. Reviens me voir avec ces 3 éléments. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "RNV budget — écart chiffré et clair", "objective": "Qualifier la RNV budget avec précision, chiffrer l'écart, reformuler au client, et fixer une prochaine étape avec une alternative concrète.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Femme, 34 ans, aide-soignante. Très intéressée par le véhicule — bloquée uniquement sur le budget mensuel."}, {"label": "Signal de non-vente", "text": "\"Le véhicule me plaît vraiment — mais 320€/mois c'est un peu au-dessus de ce que je voulais mettre.\""}, {"label": "RNV réelle", "text": "Écart de 45€/mois sur la mensualité. Budget réel : 275€/mois. Pas d'apport supplémentaire."}, {"label": "Prochaine étape idéale", "text": "Rechercher une alternative (durée 60 mois ou modèle légèrement différent) et rappeler avec une proposition à 275€/mois."}, {"label": "Frein", "text": "Elle peut se décourager si le commercial ne prend pas d'engagement précis sur le rappel."}], "context": "Jeudi 16h. Fin de RDV positif — le véhicule correspondait parfaitement. La mensualité à 320€ dépasse son budget de 45€. Elle est honnête sur le montant. Aucune autre objection.", "stakes": "L'enjeu : qualifier précisément l'écart (45€ et pas juste \"un peu\"), reformuler pour valider, et fixer un rappel avec un engagement clair sur ce qu'on va chercher.", "observe": ["Pose-t-il la question de la RNV avant qu'elle parte ?", "Chiffre-t-il l'écart précisément (45€ et non \"un peu trop\") ?", "Reformule-t-il la RNV pour validation ?", "Fixe-t-il une date de rappel avec un contenu précis ?"]}, {"level": "intermediaire", "title": "RNV décision — conjoint non consulté", "objective": "Identifier que le vrai frein est la décision en couple, qualifier sans le faire dire explicitement, et proposer une prochaine étape qui inclut les deux décideurs.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 46 ans, technicien réseau. Venu seul mais décisions importantes = couple. N'ose pas le dire clairement."}, {"label": "Signal de non-vente", "text": "\"C'est bien — mais je préfère réfléchir encore. Je vous rappelle dans la semaine.\""}, {"label": "RNV réelle", "text": "Sa femme n'est pas au courant du montant réel. Il a besoin de son accord avant de s'engager."}, {"label": "Prochaine étape idéale", "text": "Proposer un RDV à deux — lui envoyer un récap écrit à emporter pour faciliter la discussion."}, {"label": "Frein", "text": "Si la prochaine étape n'est pas structurée, \"je vous rappelle\" ne se produira pas."}], "context": "Mardi 17h. RDV bien déroulé. Le véhicule lui plaît, le budget est OK. Mais il devient vague au moment de conclure. Il dit \"je réfléchis\" sans raison précise.", "stakes": "L'enjeu : poser la question \"qu'est-ce qui vous retient exactement\" avec douceur, détecter le frein couple, et proposer un RDV à deux plutôt que d'attendre un rappel hypothétique.", "observe": ["Pose-t-il la question de la RNV avec naturel ?", "Détecte-t-il le frein couple sans forcer l'aveu ?", "Propose-t-il un RDV à deux comme prochaine étape ?", "Envoie-t-il un récap écrit pour faciliter la discussion à la maison ?"]}, {"level": "avance", "title": "RNV comparaison — concurrent identifié", "objective": "Identifier le concurrent et l'argument de comparaison, qualifier précisément l'écart, et préparer une relance avec un argument de différenciation ciblé.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 39 ans, responsable commercial. A visité une concurrence la veille. Pas agressif mais compare."}, {"label": "Signal de non-vente", "text": "\"J'ai vu un modèle similaire ailleurs — je veux comparer encore avant de décider.\""}, {"label": "RNV réelle", "text": "Concurrent X, 1 800€ moins cher sur le prix catalogue. Mais délai de livraison 8 semaines vs 2 semaines ici."}, {"label": "Prochaine étape idéale", "text": "Relancer dans 5 jours avec l'argument délai de livraison — et vérifier si le concurrent a maintenu son offre."}, {"label": "Frein", "text": "Si le commercial ne qualifie pas le concurrent et l'écart précis, sa relance sera générique et inefficace."}], "context": "Vendredi 11h. Tout s'est bien passé. Il était engagé pendant le RDV mais se rétracte à la fin. Mentionne qu'il compare sans donner de nom.", "stakes": "L'enjeu : poser les bonnes questions pour identifier le concurrent, l'écart précis, et l'argument de différenciation (délai). Reformuler la RNV et fixer une relance dans 5 jours avec cet argument précis.", "observe": ["Identifie-t-il le concurrent et l'écart de prix précis ?", "Détecte-t-il le délai de livraison comme argument de différenciation ?", "Reformule-t-il la RNV avec les éléments précis ?", "Fixe-t-il une relance dans 5 jours avec le bon argument ?"]}]}, "online": {"focus": "la qualification de la RNV", "attentionPoints": ["Pose-t-il la question de la RNV avant de partir ?", "Sa RNV contient-elle un chiffre, une famille ou une date ?", "Reformule-t-il la RNV pour valider la compréhension ?", "Fixe-t-il une prochaine étape avec date et contenu précis ?"], "grid": ["Question RNV posée", "RNV précise (chiffre/date)", "Reformulation validée", "Prochaine étape fixée"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"As-tu posé la question de la RNV avant que le client parte ? Quelle RNV tu as notée exactement — est-ce qu'elle contient un chiffre ou une date ? Comment tu l'as reformulée ? Quelle est ta prochaine étape — avec quelle date ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que tu as posé [question précise] — et le client a dit [RNV précise]. Tu as reformulé avec [formulation]. Ça t'a permis de fixer une relance avec [argument ciblé]. C'est exactement ça le but de la RNV.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: ta RNV était encore vague — 'il réfléchit']. La prochaine fois, pose toujours la question 'qu'est-ce qui vous retient exactement ?' — et force-toi à noter un chiffre ou une date avant de fermer le dossier.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain RDV sans vente : note la RNV exacte, comment tu l'as formulée, et la prochaine étape avec sa date. Ces 3 éléments. Date de retour : [date].\""}], "sections": []}, "takeaways": {"theory": "Les 5 familles de RNV sont connues — toute RNV contient un chiffre ou une date", "offline": "La qualification est pratiquée sur 3 types de RNV — reformuler et fixer la suite sont des réflexes", "online": "Le coach a observé et débriefé la qualification de la RNV en situation réelle", "next": "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"}, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/7- Expliquer les next step/a. Raisons de non vente.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('5064722d-abcd-5fe7-88c3-82dc406577db', 'aef3646b-cdfe-5d87-991d-1cc7b698a324');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('5064722d-abcd-5fe7-88c3-82dc406577db', '1f9a18c1-6c28-544c-a4dc-82bdc3975c00');
insert into public.library_dojos (id, title, content, pptx_path) values ('a8159848-35b2-59bd-8391-216ff4ea9c24', 'Personnaliser la relance', $dojo${"version": 1, "tagline": "Calibrer le niveau et le contenu de la relance selon la RNV", "objective": "Le commercial identifie la famille de RNV, choisit le bon timing, prépare un contenu concret, et lance une relance qui apporte une valeur réelle au client.", "duration": "20-25 min", "theory": {"intro": "Une relance générique (\"juste pour savoir si vous avez réfléchi\") ne vaut rien. Une relance personnalisée sur la RNV précise démontre l'écoute et apporte une valeur réelle. La matrice lie chaque RNV à un niveau de relance et un contenu.", "standardTitle": "Le standard : la matrice RNV → relance", "standard": [{"label": "RNV", "title": "Timing", "description": "Niveau de relance", "why": "Contenu de la relance"}, {"label": "Budget", "title": "5-7 jours", "description": "Moyen", "why": "Rappeler avec une alternative concrète (durée, modèle). Pas de relance sans solution préparée."}, {"label": "Délai", "title": "J-30 du terme", "description": "Faible", "why": "Confirmation des conditions + disponibilité. Une seule relance à J-30, pas avant."}, {"label": "Décision", "title": "3-5 jours", "description": "Moyen", "why": "Proposer le RDV à deux. Envoyer le récap avant. Ne pas rappeler sans prétexte utile."}, {"label": "Comparaison", "title": "5-7 jours", "description": "Élevé", "why": "Rappeler avec l'argument de différenciation identifié. Vérifier si le concurrent a maintenu son offre."}, {"label": "Autre / perso", "title": "Date convenue", "description": "Faible", "why": "Respecter le délai fixé. Ne pas relancer avant — une relance anticipée nuit à la relation."}], "criteria": [{"title": "Il prépare la relance avant d'appeler", "description": "Avant de décrocher le téléphone : relire la RNV, relire les notes de découverte, préparer le contenu précis de la relance. Un commercial qui appelle sans préparation parle de \"juste vérifier\" — un commercial préparé apporte une solution ou une information utile."}, {"title": "Sa relance apporte quelque chose de concret", "description": "\"J'ai vérifié — on peut descendre la mensualité à 285€ en passant sur 60 mois.\" Ou : \"J'ai bien regardé le concurrent — leur délai est de 8 semaines, le nôtre est de 2.\" La relance est une réponse à la RNV, pas un simple rappel de curiosité."}, {"title": "Il respecte le timing selon la RNV", "description": "Relancer trop tôt (lendemain d'une RNV délai de 3 mois) = harcèlement perçu. Relancer trop tard (3 semaines après une RNV budget) = laisser refroidir. Le timing est aussi important que le contenu."}, {"title": "Il adapte le canal selon le client", "description": "Certains clients répondent mieux au SMS ou à l'email qu'au téléphone. Un SMS avec le récap de l'alternative préparée avant d'appeler améliore le taux de réponse. La relance multicanal n'est pas de l'acharnement — c'est de l'adaptation."}, {"title": "Il sait quand arrêter", "description": "Après 3 relances sans réponse sur une RNV budget ou comparaison, espacer puis arrêter. Un client qui ne répond plus a pris une décision — le respecter. Une relance de courtoisie à 3 mois (\"votre projet est-il toujours d'actualité ?\") peut rouvrir sans harceler."}], "mistakes": [{"title": "Erreur 1 — Relancer sans contenu préparé", "description": "\"Bonjour, je vous appelle juste pour savoir si vous avez réfléchi.\" Le client répond \"pas encore\" — et la conversation s'arrête. Une relance sans contenu préparé ne fait pas avancer le dossier. Elle rappelle au client qu'il n'a pas décidé, sans lui donner de raison de décider."}, {"title": "Erreur 2 — Appliquer le même rythme à toutes les RNV", "description": "Relancer toutes les RNV à J+3 quelle que soit la nature du frein. Un client en attente d'un délai de 3 mois n'a pas besoin d'être relancé chaque semaine. Un client en comparaison active, si. Le timing se calibre sur la RNV — pas sur une règle générale."}, {"title": "Erreur 3 — Relancer sans raison prétexte", "description": "Appeler sans avoir d'information nouvelle ou d'élément à apporter. Le client perçoit immédiatement qu'il n'y a pas de valeur ajoutée dans l'appel — et décroche plus facilement la prochaine fois. Chaque relance doit avoir un prétexte légitime : une alternative, une info, une confirmation."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Choisir 1 scénario. Donner la fiche RNV au commercial avant. Briefer : \"Tu as cette RNV en main depuis 5 jours. Prépare ta relance — timing, canal, contenu précis. Je joue le client. Je lève la main si ta relance n'apporte pas de valeur ajoutée concrète.\""}, {"title": "Lancer le scénario", "description": "Jouer le client au téléphone (ou simuler l'appel). Répondre naturellement selon le persona — accepter la relance si elle est bien préparée et apporte quelque chose de concret. Résister si le contenu est générique ou le timing mal choisi."}, {"title": "Débriefer", "description": "\"Quel timing as-tu choisi — et pourquoi ce délai pour cette RNV ? Qu'est-ce que tu as préparé comme contenu concret ? Comment as-tu ouvert la relance — tu as rappelé le contexte ou tu as sauté directement au contenu ? Le client a-t-il avancé ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain dossier en RNV : note la RNV, le timing choisi, le contenu préparé, et le résultat de la relance. Ces 4 éléments me permettront de débriefer efficacement. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "RNV budget — relance avec alternative préparée", "objective": "Préparer une alternative concrète sur la RNV budget, ouvrir la relance avec le contexte, apporter la solution, et vérifier si elle lève le frein.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Femme, 34 ans, aide-soignante. RNV budget : 45€ d'écart sur la mensualité."}, {"label": "Situation à J+5", "text": "Elle a réfléchi mais n'a pas rappelé. Elle attend une solution de la concession."}, {"label": "Ce qu'elle attend", "text": "Une alternative concrète — pas un simple rappel de curiosité."}, {"label": "Ce qui la ferait avancer", "text": "\"J'ai regardé — en passant sur 60 mois, la mensualité descend à 278€.\" Concret et utile."}, {"label": "Frein", "text": "Si le contenu est vague, elle dira \"je réfléchis encore\" et le dossier refroidit."}], "context": "J+5 après le RDV. RNV qualifiée : 45€ d'écart mensuel, budget réel 275€/mois. Le commercial a préparé une alternative : passage sur 60 mois → mensualité à 278€. Il doit ouvrir la relance en rappelant le contexte, apporter la solution, et demander si ça répond à son frein.", "stakes": null, "observe": ["Rappelle-t-il le contexte du RDV avant d'apporter la solution ?", "Son contenu est-il concret et chiffré (278€/60 mois) ?", "Vérifie-t-il si l'alternative lève le frein ?", "Propose-t-il une prochaine étape si elle valide ?"]}, {"level": "intermediaire", "title": "RNV comparaison — relance avec argument différenciation", "objective": "Identifier l'argument de différenciation sur la RNV comparaison, l'utiliser comme prétexte de relance, et repositionner la valeur sans attaquer le concurrent.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 39 ans, responsable commercial. Compare avec un concurrent — 1 800€ moins cher."}, {"label": "Situation à J+6", "text": "Il a peut-être obtenu une réponse du concurrent. Il n'a pas rappelé."}, {"label": "Ce qu'il attend", "text": "Un argument qui justifie la différence de prix — pas des excuses ou de la pression."}, {"label": "Ce qui le ferait avancer", "text": "\"J'ai vérifié leur délai — il est passé à 10 semaines. Le nôtre reste à 2 semaines.\" Factuel et utile."}, {"label": "Frein", "text": "Si le commercial attaque le concurrent ou baisse le prix sans justification, il perd la crédibilité."}], "context": "J+6 après le RDV. RNV comparaison qualifiée : concurrent X, 1 800€ moins cher, délai 8 semaines vs 2 semaines ici. Le commercial a vérifié — le concurrent est maintenant à 10 semaines de délai. Il relance avec cet argument factuel et sans pression.", "stakes": null, "observe": ["Ouvre-t-il la relance avec un prétexte utile (information nouvelle) ?", "Présente-t-il l'argument délai factuellement, sans attaquer le concurrent ?", "Repositionne-t-il la valeur globale plutôt que de baisser le prix ?", "Maintient-il une posture confiante sans pression ?"]}, {"level": "avance", "title": "RNV décision — relance avant le RDV à deux", "objective": "Préparer la relance de confirmation avant le RDV à deux, envoyer le bon contenu au bon moment, et créer les conditions d'une décision sereine en couple.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 46 ans, technicien réseau. RNV décision : doit en parler à sa femme. RDV à deux proposé."}, {"label": "Situation à J+3", "text": "RDV à deux planifié pour demain. Il faut confirmer et envoyer le récap pour préparer sa femme."}, {"label": "Ce qu'il attend", "text": "Un récap clair, un message de confirmation chaleureux, pas de pression sur la décision."}, {"label": "Ce qui le ferait avancer", "text": "SMS/email la veille : récap du véhicule, mensualité, et confirmation du RDV — ton léger."}, {"label": "Frein", "text": "Un message trop commercial la veille du RDV peut braquer sa femme avant même le RDV."}], "context": "J+3 après le RDV. RDV à deux prévu demain à 15h. Le commercial doit envoyer un message de confirmation + récap. Puis simuler l'appel de confirmation le matin du RDV. Le ton doit être chaleureux et sans pression — le couple ne doit pas se sentir \"ciblé\" avant d'arriver.", "stakes": null, "observe": ["Le message de confirmation est-il chaleureux et sans pression commerciale ?", "Le récap est-il clair et complet sans être écrasant ?", "L'appel de confirmation du matin est-il court et bienveillant ?", "Le commercial crée-t-il les conditions d'un RDV serein plutôt que pressé ?"]}]}, "online": {"focus": "la relance personnalisée", "attentionPoints": ["Le timing est-il adapté à la RNV ?", "Le contenu est-il concret et préparé avant l'appel ?", "La relance apporte-t-elle une valeur réelle au client ?", "Propose-t-il une prochaine étape si la relance est positive ?"], "grid": ["Timing adapté à la RNV", "Contenu concret préparé", "Valeur réelle apportée", "Prochaine étape proposée"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Quel timing as-tu choisi — et pourquoi ce délai pour cette RNV ? Qu'est-ce que tu avais préparé comme contenu concret avant d'appeler ? Est-ce que le client a avancé ? Quelle est la prochaine étape ?\""}, {"title": "Retour du coach — les réussites", "prompt": "\"J'ai observé que tu as dit [contenu concret préparé]. Le client a réagi en [observation]. Le fait d'arriver avec une solution plutôt qu'une question a changé la dynamique de l'appel — c'est exactement ça.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu n'avais pas préparé d'alternative concrète avant d'appeler]. La prochaine fois, avant chaque relance, note sur papier : quelle est l'information ou la solution que j'apporte — si tu ne trouves pas, ne rappelle pas encore.\""}, {"title": "Engagement & prochaine étape", "prompt": "\"Sur ton prochain dossier en RNV : note la RNV, le timing, le contenu préparé et le résultat de la relance. Ces 4 éléments. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "La matrice RNV → relance est connue — chaque RNV a son timing et son contenu", "02  Offline", "3 types de relance pratiqués — préparer avant d'appeler est un réflexe ancré", "03  Online", "Le coach a observé et débriefé la relance personnalisée en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/7- Expliquer les next step/b. Personnaliser la relance.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('a8159848-35b2-59bd-8391-216ff4ea9c24', '64cf1e1e-b3a0-503a-bd0d-637fd20e5cef');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('a8159848-35b2-59bd-8391-216ff4ea9c24', '13f8b1cb-10f4-561d-9c5b-3fa573ee50b0');
insert into public.library_dojos (id, title, content, pptx_path) values ('89d56615-f1c0-55af-8d04-1644fc50bac8', 'Remise de clés', $dojo${"version": 1, "tagline": "Transformer la livraison en moment mémorable", "objective": "Le commercial prépare le véhicule avant l'arrivée, personnalise avec 1-2 éléments de la découverte, gère le rythme selon l'état du client, et ouvre la prochaine étape.", "duration": "20-25 min", "theory": {"intro": "La remise de clés est souvent le moment le moins travaillé du cycle de vente — alors que c'est le dernier souvenir du client. Un moment mémorable génère des recommandations. Un moment bâclé efface tout le travail commercial précédent.", "standardTitle": "Le standard : le rituel de livraison en 4 temps", "standard": [{"label": "PRÉPARATION", "title": "Vérifier le véhicule avant l'arrivée du client. Propre, jauge pleine, documents prêts. Chaque détail compte.", "description": "La préparation se fait AVANT — pas pendant que le client attend. Un véhicule livré avec un problème annule l'effet positif.", "why": "PERSONNALISATION"}, {"label": "Référencer 1 élément de la découverte dans le discours. \"Vous m'aviez dit que le coffre était important — voilà comment il fonctionne.\"", "title": "Un discours qui reprend la découverte prouve que le commercial a vraiment écouté. C'est rare et ça marque.", "description": "PRÉSENTATION", "why": "Tour du véhicule structuré : extérieur, intérieur, fonctionnalités clés liées à l'usage. Pas le manuel complet — les 3-4 points qui comptent pour lui."}, {"label": "Le client ne retient que ce qui est utile pour lui. L'essentiel personnalisé vaut mieux que tout expliquer.", "title": "PROJECTION", "description": "Terminer en projetant dans l'usage : \"La première semaine vous allez adorer [fonctionnalité clé].\" Puis ouvrir la porte recommandation.", "why": "La projection positive ancre le sentiment d'avoir fait le bon choix — et prépare la recommandation naturelle."}], "criteria": [{"title": "Il arrive avant le client", "description": "Le commercial qui attend avec le véhicule prêt crée immédiatement un effet professionnel. Celui qui court préparer au dernier moment envoie le signal inverse."}, {"title": "Son discours reprend la découverte", "description": "\"Vous m'aviez dit que vous faisiez beaucoup d'autoroute — le régulateur adaptatif va changer votre quotidien.\" Ce lien découverte → livraison est la signature d'un vrai conseiller."}, {"title": "Il gère l'émotion du client", "description": "Certains clients sont émus, d'autres pressés, d'autres ont des questions techniques. Lire l'état du client et adapter le rythme est aussi important que le contenu."}, {"title": "Il documente le moment", "description": "Une photo avec le client, avec son accord, crée un souvenir partageable. C'est le point de départ naturel d'une recommandation."}, {"title": "Il ouvre la prochaine étape", "description": "\"Je vous appelle dans une semaine pour voir comment se passe la prise en main.\" Ce rappel planifié maintient la relation active."}], "mistakes": [{"title": "Erreur 1 — Livrer un véhicule non préparé", "description": "Rayure non signalée, réservoir vide, intérieur poussiéreux. Le client qui découvre un problème à la livraison associe ce sentiment à toute l'expérience. L'effet est dévastateur et difficile à rattraper."}, {"title": "Erreur 2 — Faire le tour du propriétaire complet sans personnalisation", "description": "Expliquer toutes les fonctionnalités pendant 40 minutes. Le client est noyé, ne retient rien, et repart confus plutôt qu'enthousiaste. Aller à l'essentiel personnalisé."}, {"title": "Erreur 3 — Bâcler la livraison parce que le suivant attend", "description": "\"Bon je vous laisse — j'ai un autre client.\" Dit ou ressenti, c'est la pire fin possible. La livraison mérite le même temps et la même qualité que le premier RDV."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Briefer : \"Je joue un client qui arrive pour sa livraison. Ton objectif : créer un moment mémorable avec au moins 1 lien vers la découverte. Je lève la main si tu fais le tour complet sans personnalisation.\""}, {"title": "Lancer le scénario", "description": "Jouer le client à la livraison. Réagir positivement si le discours reprend la découverte. Rester distant si c'est générique. Observer : préparation, personnalisation, rythme, prochaine étape."}, {"title": "Débriefer", "description": "\"Est-ce que tu avais préparé le véhicule avant mon arrivée ? Quel élément de ma découverte tu as utilisé ? Comment tu as géré mon rythme ? Tu as ouvert une prochaine étape ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ta prochaine livraison : note l'élément de découverte utilisé et la réaction du client. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Le client enthousiaste — tout s'est bien passé", "objective": "Structurer en 4 temps, personnaliser avec la découverte, gérer l'enthousiasme, ouvrir la prochaine étape.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 36 ans, commercial terrain. Premier SUV, très content de son achat."}, {"label": "Comportement", "text": "Enthousiaste, parle beaucoup, pose des questions sur tout. Facile à gérer."}, {"label": "Non-verbal", "text": "Souriant, regard brillant. S'approche du véhicule avec impatience."}, {"label": "Attente", "text": "Un moment qui correspond à son enthousiasme — pas un discours plat."}, {"label": "Découverte", "text": "45 000 km/an, autoroute, aime les équipements connectés, famille de 4."}], "context": "Samedi 10h. Il arrive avec sa femme et ses deux enfants, 20 minutes en avance. C'est son premier SUV après 10 ans de berline.", "stakes": "L'enjeu : canaliser l'enthousiasme, structurer en 4 temps, personnaliser sur le connecté et le coffre familial.", "observe": ["Prépare-t-il un discours en 4 temps structuré ?", "Personnalise-t-il sur le connecté et le coffre familial ?", "Gère-t-il l'enthousiasme sans perdre le fil ?", "Ouvre-t-il une prochaine étape concrète ?"]}, {"level": "intermediaire", "title": "Le client pressé — 20 minutes maximum", "objective": "Adapter la livraison à une contrainte de temps, sélectionner 2-3 points essentiels, créer malgré tout un moment mémorable.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 42 ans, directrice commerciale. Agenda serré, dit d'emblée qu'elle a 20 minutes."}, {"label": "Comportement", "text": "Efficace, directe. Coupe si on s'étend. Apprécie la précision."}, {"label": "Non-verbal", "text": "Regarde sa montre. Se détend si on va à l'essentiel."}, {"label": "Attente", "text": "L'essentiel pour elle — pas tout le manuel."}, {"label": "Découverte", "text": "35 000 km/an, déplacements clients, aime la discrétion et la fiabilité."}], "context": "Mardi 12h30. Elle a bloqué 20 minutes entre deux réunions.", "stakes": "L'enjeu : sélectionner les 2-3 fonctionnalités les plus utiles pour ses déplacements clients, et créer quand même 1 phrase mémorable.", "observe": ["Sélectionne-t-il 2-3 points clés (pas tout) ?", "Personnalise-t-il sur les déplacements clients ?", "Respecte-t-il le timing sans bâcler le fond ?", "Crée-t-il malgré tout 1 phrase mémorable ?"]}, {"level": "avance", "title": "Le client déçu — problème découvert à la livraison", "objective": "Gérer une déception (option manquante), récupérer la situation avec empathie, transformer le problème en preuve de sérieux.", "duration": "30 min", "persona": [{"label": "Profil", "text": "Homme, 48 ans, chef d'entreprise. A attendu 6 semaines. Arrive avec de grandes attentes."}, {"label": "Comportement", "text": "Enthousiaste à l'arrivée — silencieux quand il remarque que l'option cuir n'est pas là."}, {"label": "Non-verbal", "text": "Sourire qui se fige. Regard qui cherche. Ton qui change."}, {"label": "Attente", "text": "Être entendu, pas une excuse. Une solution concrète proposée rapidement."}, {"label": "Découverte", "text": "Image pro importante, confort longue distance, budget sans contrainte."}], "context": "Jeudi 16h. Il arrive après 6 semaines d'attente. En faisant le tour, il remarque que la sellerie cuir n'est pas installée — erreur de commande.", "stakes": "L'enjeu : accuser réception avec empathie, proposer une solution immédiate, transformer cet incident en preuve de fiabilité.", "observe": ["Accuse-t-il réception sans minimiser ?", "Propose-t-il une solution concrète immédiatement ?", "Maintient-il la qualité de la livraison malgré la tension ?", "Transforme-t-il l'incident en preuve de sérieux ?"]}]}, "online": {"focus": "la qualité de livraison", "attentionPoints": ["Le véhicule est-il préparé avant l'arrivée ?", "Le discours reprend-il 1 élément de la découverte ?", "Le rythme est-il adapté à l'état du client ?", "Une prochaine étape est-elle ouverte ?"], "grid": ["Véhicule préparé", "Lien découverte fait", "Rythme adapté", "Prochaine étape ouverte"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Est-ce que le véhicule était prêt avant mon arrivée ? Quel élément de ma découverte tu as utilisé ? Comment tu as géré mon rythme ? Quelle était ta prochaine étape ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que tu as dit [lien découverte précis]. Ma réaction a été [observation]. Ce lien découverte → livraison, c'est exactement ce qui crée un moment mémorable.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as fait tout le tour sans personnalisation]. Avant ta prochaine livraison, note les 2 points de la découverte que tu vas utiliser dans ton discours.\""}, {"title": "Engagement", "prompt": "\"Sur ta prochaine livraison : note l'élément de découverte utilisé et la réaction du client. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Le rituel en 4 temps est connu — personnaliser avec la découverte est le geste clé", "02  Offline", "3 profils pratiqués — le lien découverte est un réflexe", "03  Online", "Le coach a observé et débriefé la livraison en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/8- Livraison & fidélisation/a. Remise des clés.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('89d56615-f1c0-55af-8d04-1644fc50bac8', '089a70ed-112f-5a77-8323-e2b0aec2fe39');
insert into public.library_dojos (id, title, content, pptx_path) values ('8bfe02b4-b49d-54dc-8ad8-b84d59dfad22', 'Suivi post-livraison', $dojo${"version": 1, "tagline": "Maintenir la relation après la vente pour préparer la fidélisation", "objective": "Le commercial planifie les 3 contacts dès la livraison, prépare un contenu utile, ouvre avec une question ouverte, et note les informations pour la prochaine interaction.", "duration": "20-25 min", "theory": {"intro": "La plupart des commerciaux disparaissent après la livraison. Le client qui ne reçoit aucun signe de vie se sent abandonné — et ne recommande pas. 3 contacts structurés suffisent à transformer un acheteur en ambassadeur.", "standardTitle": "Le standard : les 3 temps du suivi post-livraison", "standard": [{"label": null, "title": "J+7 — PRISE EN MAIN", "description": "\"Comment se passe la première semaine ?\" Vérifier la prise en main, détecter une friction éventuelle avant qu'elle devienne une réclamation.", "why": "J+7 est le moment où les petites frustrations apparaissent. Un contact proactif transforme un problème en preuve de service."}, {"label": null, "title": "J+30 — SATISFACTION", "description": "\"Vous êtes toujours aussi satisfait ?\" C'est le bon moment pour une demande de recommandation — le client est satisfait et le souvenir est encore vif.", "why": "J+30 est le pic de satisfaction. Le client recommande plus facilement à ce moment qu'à n'importe quel autre."}, {"label": null, "title": "J+180 — FIDÉLISATION", "description": "\"Votre prochain contrôle technique approche — vous voulez qu'on regarde ça ensemble ?\" Prétexte utile à 6 mois. Planter la graine du prochain achat.", "why": "À 6 mois, le client commence à penser à l'avenir de son véhicule. Un contact utile le positionne comme partenaire long terme."}], "criteria": [{"title": "Il planifie les 3 contacts dès la livraison", "description": "Avant de quitter la livraison, noter les 3 dates dans le CRM. Un suivi non planifié à J+0 ne se produit pas — la pression du quotidien l'efface."}, {"title": "Son contact apporte une valeur réelle", "description": "Chaque contact doit avoir un prétexte utile : vérification de prise en main, info sur un service, rappel d'entretien. La valeur justifie le contact."}, {"title": "Il écoute avant de parler", "description": "Commencer par \"comment se passe la première semaine ?\" — pas par \"tout va bien ?\". La question ouverte révèle les frictions réelles. La question fermée donne un \"oui\" de politesse."}, {"title": "Il note les informations pour la prochaine interaction", "description": "Ce que le client dit à J+7 devient un ancrage pour J+30. La continuité de l'information est la signature d'un vrai suivi."}, {"title": "Il reste en contact même sans prétexte commercial", "description": "Un message d'anniversaire du premier mois, une info utile — ces micro-contacts sans objectif commercial maintiennent la relation à coût quasi nul."}], "mistakes": [{"title": "Erreur 1 — Ne pas planifier le suivi à la livraison", "description": "Partir sans avoir noté les 3 dates dans l'agenda. La pression des nouvelles affaires efface les suivis non planifiés. Le client ne reçoit aucun signe de vie — et donne ses recommandations à quelqu'un d'autre."}, {"title": "Erreur 2 — Appeler uniquement pour vendre", "description": "Rappeler à J+30 pour proposer une extension de garantie avant même de demander comment se passe le véhicule. Le client perçoit immédiatement l'intention commerciale — et se ferme."}, {"title": "Erreur 3 — Ne contacter que les clients satisfaits", "description": "Éviter les clients dont on suspecte une insatisfaction. C'est exactement l'inverse. Un client insatisfait contacté proactivement devient souvent un client fidèle."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Briefer : \"Je joue le client à J+7. Ton objectif : ouvrir avec une question ouverte, détecter les frictions, apporter de la valeur. Je lève la main si tu ouvres avec 'tout va bien ?'\""}, {"title": "Lancer le scénario", "description": "Jouer le client à J+7 ou J+30. Donner une info utile si la question ouverte est posée. Répondre \"oui\" si la question est fermée. Observer : question ouverte, valeur apportée, info notée."}, {"title": "Débriefer", "description": "\"Par quelle question as-tu ouvert ? Qu'est-ce que tu as appris sur le client ? Tu as noté pour le prochain contact ? Tu as planifié le J+30 avant de raccrocher ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ta prochaine livraison : note les 3 dates J+7, J+30, J+180 avant de partir. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "J+7 — prise en main sans problème", "objective": "Ouvrir avec une question ouverte, détecter qu'aucune friction n'est présente, apporter une info utile, planifier le J+30.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 36 ans, commercial terrain. Prise en main sans problème — il adore le véhicule."}, {"label": "Comportement", "text": "Content, bavard. A découvert des fonctionnalités. Pas de friction."}, {"label": "Non-verbal", "text": "Ton positif. Répond facilement aux questions ouvertes."}, {"label": "Attente", "text": "Un commercial qui s'intéresse à lui — pas juste à son véhicule."}, {"label": "Info utile", "text": "Il a mentionné qu'il ne savait pas utiliser le mode économie d'énergie."}], "context": "J+7 après la livraison. Tout va bien. Le commercial appelle pour la première fois.", "stakes": "L'enjeu : ouvrir avec une vraie question ouverte, détecter l'info sur le mode éco, apporter une valeur concrète, planifier le J+30.", "observe": ["Ouvre-t-il avec une question ouverte ?", "Détecte-t-il l'info sur le mode éco et y répond-il ?", "Apporte-t-il une valeur sans vendre ?", "Planifie-t-il le J+30 avant de raccrocher ?"]}, {"level": "intermediaire", "title": "J+7 — friction détectée sur une fonctionnalité", "objective": "Détecter une friction technique, la traiter proactivement, transformer la frustration en preuve de service.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 42 ans, directrice commerciale. A un problème de synchro téléphone."}, {"label": "Comportement", "text": "Ton légèrement tendu. A essayé seule — n'a pas réussi. N'allait pas rappeler."}, {"label": "Non-verbal", "text": "Souffle en en parlant. Se détend si le commercial propose une solution."}, {"label": "Attente", "text": "Une solution rapide et concrète — pas des excuses."}, {"label": "Info utile", "text": "La synchro Android nécessite une mise à jour de l'app constructeur — simple à faire."}], "context": "J+7 après la livraison. Elle a un problème de synchro téléphone depuis 3 jours mais n'a pas rappelé.", "stakes": "L'enjeu : détecter avec une question ouverte, proposer la solution immédiatement, transformer ce contact proactif en preuve de service.", "observe": ["Détecte-t-il la friction avec une question ouverte ?", "Propose-t-il une solution immédiate et concrète ?", "Transforme-t-il la friction en preuve de service ?", "Note-t-il l'info pour le J+30 ?"]}, {"level": "avance", "title": "J+30 — demande de recommandation naturelle", "objective": "Évaluer la satisfaction à J+30, créer les conditions d'une demande de recommandation naturelle, formuler sans créer de gêne.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 48 ans, chef d'entreprise. Très satisfait. Entourage de décideurs qui changent souvent de véhicule."}, {"label": "Comportement", "text": "Chaleureux. Parle spontanément de son véhicule à ses collègues."}, {"label": "Non-verbal", "text": "Ton ouvert et positif. Disponible."}, {"label": "Attente", "text": "Un contact sincère — pas un appel de relance commerciale déguisé."}, {"label": "Opportunité", "text": "Il a mentionné que 2 de ses directeurs cherchent un véhicule."}], "context": "J+30. Satisfaction maximale. Il a parlé du véhicule autour de lui sans qu'on le lui demande.", "stakes": "L'enjeu : évaluer avec sincérité, détecter l'opportunité des 2 directeurs, formuler la recommandation naturellement.", "observe": ["Évalue-t-il la satisfaction avant de parler recommandation ?", "Détecte-t-il l'opportunité des 2 directeurs ?", "Formule-t-il la demande naturellement ?", "Évite-t-il toute pression ?"]}]}, "online": {"focus": "le suivi post-livraison", "attentionPoints": ["Ouvre-t-il avec une question ouverte ?", "Apporte-t-il une valeur concrète ?", "Note-t-il une information pour le prochain contact ?", "Planifie-t-il le prochain contact avant de raccrocher ?"], "grid": ["Question ouverte", "Valeur concrète", "Info notée", "Prochain contact planifié"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Par quelle question as-tu ouvert ? Qu'est-ce que tu as appris ? Tu as apporté quelque chose de concret ? Tu as planifié le prochain contact ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que tu as dit [question ouverte] — et j'ai répondu [info]. Tu as immédiatement [action]. Ce contact proactif avec valeur ajoutée, c'est exactement ça la fidélisation.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as ouvert avec 'tout va bien ?']. La prochaine fois : 'Comment se passe la première semaine ?' — 4 mots qui ouvrent vraiment.\""}, {"title": "Engagement", "prompt": "\"Sur ta prochaine livraison : planifie les 3 dates J+7, J+30, J+180 avant de partir. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Les 3 temps sont connus — J+7 / J+30 / J+180 — chacun avec son contenu", "02  Offline", "3 contacts pratiqués — question ouverte et valeur apportée sont des réflexes", "03  Online", "Le coach a observé et débriefé le suivi post-livraison en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/8- Livraison & fidélisation/b. Suivi post livraison.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('8bfe02b4-b49d-54dc-8ad8-b84d59dfad22', '2fdae8d0-a8ea-5230-928e-f24f57e09508');
insert into public.library_dojos (id, title, content, pptx_path) values ('ac667721-d0b1-5609-a8c9-2c281225cd27', 'Demande de recommandation', $dojo${"version": 1, "tagline": "Demander naturellement une recommandation à un client satisfait", "objective": "Le commercial détecte le signal de satisfaction, choisit la bonne formule selon le profil, la place après avoir apporté de la valeur, et remercie sans pression.", "duration": "20-25 min", "theory": {"intro": "La recommandation est la source de leads la plus qualifiée et la moins coûteuse. Pourtant la plupart des commerciaux ne la demandent jamais — par gêne ou par oubli. 3 formules suffisent à en faire un réflexe.", "standardTitle": "Le standard : pourquoi demander & les 3 formules", "standard": [{"label": null, "title": "FORMULE DIRECTE", "description": "\"Si vous avez des proches qui cherchent un véhicule, je serai ravi de les accueillir avec le même soin.\"", "why": "Fonctionne avec les clients en confiance. Claire et honnête — le client sait exactement ce qu'on lui demande."}, {"label": null, "title": "FORMULE INDIRECTE", "description": "\"Est-ce qu'il y a des personnes dans votre entourage qui seraient dans la même situation que vous étiez il y a quelques mois ?\"", "why": "Moins frontale. Invite à réfléchir sans créer d'obligation. Idéale pour les profils réservés."}, {"label": null, "title": "FORMULE CONDITIONNELLE", "description": "\"Si jamais vous parlez de votre expérience autour de vous — n'hésitez pas à donner mes coordonnées.\"", "why": "La plus douce des trois. Elle ne demande rien — elle ouvre une possibilité. Idéale pour un client satisfait mais réservé."}], "criteria": [{"title": "Il demande uniquement quand le client est satisfait", "description": "Demander lors d'un problème est contre-productif. La demande se fait quand le signal de satisfaction est fort et explicite — sourire, phrases positives, envie de partager."}, {"title": "Il choisit la bonne formule selon le profil", "description": "Client chaleureux → directe. Client réservé → indirecte ou conditionnelle. Un profil introverti à qui on pose une question directe sur ses proches peut se sentir mis en demeure."}, {"title": "Sa demande vient après avoir donné de la valeur", "description": "\"Voilà les coordonnées du SAV — et si vous avez des proches...\" Le service rendu crée la réciprocité qui rend la demande naturelle."}, {"title": "Il remercie la recommandation reçue", "description": "Appeler le prescripteur pour le remercier renforce le comportement et incite à recommander à nouveau. La recommandation non remerciée ne se renouvelle pas."}, {"title": "Il ne relance pas si le client n'a pas répondu", "description": "Demander une fois, naturellement. Si le client change de sujet — ne pas insister. La pression transforme une demande naturelle en acte commercial négatif."}], "mistakes": [{"title": "Erreur 1 — Ne jamais demander", "description": "Le commercial qui ne demande jamais laisse des recommandations sur la table. Un client satisfait qui repart sans qu'on lui demande ne recommandera pas spontanément — ou recommandera un autre commercial."}, {"title": "Erreur 2 — Demander trop tôt ou au mauvais moment", "description": "Demander pendant la négociation ou juste après avoir résolu un problème. La demande se fait au pic de satisfaction — pas avant, pas longtemps après."}, {"title": "Erreur 3 — Mettre la pression", "description": "\"J'aurais vraiment besoin que vous me recommandiez.\" Met la responsabilité sur le client. Il se sent obligé — et la gêne efface la bonne expérience."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Briefer : \"Je joue un client satisfait. Ton objectif : choisir la bonne formule, la placer au bon moment, sans pression. Je te lève la main si tu demandes avant d'avoir apporté de la valeur.\""}, {"title": "Lancer le scénario", "description": "Jouer le client satisfait. Réagir positivement si la formule est bien choisie et placée. Changer de sujet si la demande est mal timée. Observer : signal détecté, bonne formule, valeur apportée avant."}, {"title": "Débriefer", "description": "\"À quel moment tu as décidé de demander ? Quelle formule as-tu choisie et pourquoi ? Est-ce que tu avais apporté quelque chose avant de demander ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain client satisfait : note le signal détecté, la formule utilisée, et la réaction. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Client enthousiaste — formule directe", "objective": "Détecter le signal fort, utiliser la formule directe naturellement, réagir avec légèreté si le client nomme des proches.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 36 ans, commercial terrain. Adore son SUV. Dit : \"Je l'ai montré à tout mon bureau.\""}, {"label": "Comportement", "text": "Ouvert, chaleureux. Signal de satisfaction fort et explicite."}, {"label": "Réseau", "text": "Équipe de 12 commerciaux qui changent souvent de véhicule."}, {"label": "Attente", "text": "Un commercial naturel — pas une demande forcée."}, {"label": "Frein", "text": "Aucun — contexte idéal pour la formule directe."}], "context": "J+30. Il a appelé spontanément pour dire qu'il est ravi. Le commercial vient de lui donner un conseil utile sur la mise à jour de son app.", "stakes": "L'enjeu : placer la formule directe après le conseil apporté, réagir avec légèreté.", "observe": ["Détecte-t-il le signal fort avant de demander ?", "Apporte-t-il quelque chose avant la demande ?", "Utilise-t-il la formule directe naturellement ?", "Réagit-il sans pression ?"]}, {"level": "intermediaire", "title": "Client satisfait mais réservé — formule indirecte", "objective": "Adapter la formule à un profil réservé, ne pas insister si pas de réponse directe.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 42 ans, directrice commerciale. Satisfaite mais réservée sur sa vie privée."}, {"label": "Comportement", "text": "Dit que c'est \"très bien\". Ne partage pas sur son entourage spontanément."}, {"label": "Signal de satisfaction", "text": "Discret mais réel — \"je n'ai eu aucun problème\" est sa façon de dire qu'elle est contente."}, {"label": "Réseau", "text": "Entourage de cadres et dirigeants — potentiellement très quali."}, {"label": "Frein", "text": "La formule directe la mettrait mal à l'aise."}], "context": "J+30. Tout va bien. Pas d'enthousiasme débordant mais vraiment satisfaite.", "stakes": "L'enjeu : détecter le signal discret, choisir la formule indirecte, ne pas insister si elle ne répond pas.", "observe": ["Détecte-t-il le signal même discret ?", "Choisit-il la formule indirecte ?", "Formule-t-il sans créer d'obligation ?", "N'insiste-t-il pas si pas de réponse directe ?"]}, {"level": "avance", "title": "Client qui recommande spontanément — amplifier", "objective": "Rebondir sur une recommandation spontanée, remercier, obtenir les coordonnées, renforcer le comportement.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 48 ans, chef d'entreprise. Dit : \"J'en ai parlé à deux de mes directeurs.\""}, {"label": "Comportement", "text": "Proactif. A déjà recommandé. Attend qu'on rebondisse."}, {"label": "Opportunité", "text": "2 directeurs qui cherchent un véhicule. Il peut faciliter la mise en relation."}, {"label": "Attente", "text": "Que le commercial prenne le relais naturellement."}, {"label": "Frein", "text": "Si le commercial ne rebondit pas, l'opportunité reste vague."}], "context": "J+30. Il mentionne en passant qu'il en a parlé à deux directeurs.", "stakes": "L'enjeu : rebondir immédiatement, remercier, obtenir les prénoms et l'accord de contact, renforcer le comportement.", "observe": ["Rebondit-il immédiatement ?", "Remercie-t-il sans exagérer ?", "Obtient-il les prénoms et l'accord de contact ?", "Renforce-t-il le comportement pour la prochaine fois ?"]}]}, "online": {"focus": "la demande recommandation", "attentionPoints": ["Détecte-t-il le signal de satisfaction avant de demander ?", "Apporte-t-il de la valeur avant la demande ?", "Choisit-il la bonne formule selon le profil ?", "Ne met-il aucune pression ?"], "grid": ["Signal détecté", "Valeur apportée avant", "Bonne formule", "Zéro pression"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"À quel moment as-tu décidé de demander ? Quelle formule ? Tu avais apporté quelque chose avant ? Comment le client a réagi ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que tu as dit [formule] après [valeur apportée]. Ma réaction : [observation]. La demande placée après la valeur, c'est ce qui la rend naturelle.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as demandé avant d'avoir rien apporté]. La prochaine fois : service d'abord, demande ensuite.\""}, {"title": "Engagement", "prompt": "\"Sur ton prochain client satisfait : note le signal, la formule, et la réaction. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Les 3 formules sont connues — la valeur avant la demande est la règle", "02  Offline", "3 profils pratiqués — demander naturellement est un réflexe", "03  Online", "Le coach a observé et débriefé la demande de recommandation en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/8- Livraison & fidélisation/c. Demande de recommandation.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('ac667721-d0b1-5609-a8c9-2c281225cd27', 'afdda43e-0a8a-560d-bbda-855b39f24613');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('ac667721-d0b1-5609-a8c9-2c281225cd27', 'ae86ae62-a978-55c8-8178-a71b978cf700');
insert into public.library_dojos (id, title, content, pptx_path) values ('4596718c-7065-5aff-aa3d-df86f31d2a0e', 'Interpréter les signaux', $dojo${"version": 1, "tagline": "Lire les signaux verbaux et non verbaux pour adapter sa posture", "objective": "Le commercial observe les 3 canaux dès l'entrée, croise les signaux avant de conclure, adapte sa posture en temps réel, et pose une question ouverte pour confirmer.", "duration": "20-25 min", "theory": {"intro": "55% de la communication est non verbale, 38% para-verbale, 7% verbale. Un commercial qui n'écoute que les mots rate l'essentiel. Lire les 3 canaux permet d'adapter sa posture en temps réel — avant que la situation se dégrade.", "standardTitle": "Le standard : les 3 canaux de signaux à lire", "standard": [{"label": null, "title": "NON-VERBAL", "description": "Posture, regard, gestes, expressions faciales. Ce que le corps dit — souvent à l'opposé des mots. Bras croisés + sourire poli = résistance masquée.", "why": "Le corps ne ment pas. Quand verbal et non-verbal se contredisent, se fier au non-verbal pour détecter la vraie posture."}, {"label": null, "title": "PARA-VERBAL", "description": "Ton, débit, volume, silences, hésitations. Un \"oui\" dit lentement avec ton descendant signifie souvent \"non\".", "why": "Le para-verbal révèle l'état émotionnel. Un client qui accélère est sous pression. Un client qui parle moins fort devient méfiant."}, {"label": null, "title": "VERBAL", "description": "Le contenu des mots — mais aussi les formulations indirectes (\"c'est intéressant\" = souvent neutre) et les questions logistiques qui signalent l'intérêt d'achat.", "why": "Les formulations indirectes sont des codes sociaux. \"Je vais réfléchir\" dit avec sourire poli signifie souvent \"non\" — pas \"je reviens\"."}], "criteria": [{"title": "Il observe avant de parler", "description": "Les 30 premières secondes d'un RDV donnent plus d'infos que les 5 premières questions. Observer l'entrée du client (posture, regard, allure, tension) donne un premier diagnostic avant même de parler."}, {"title": "Il croise plusieurs signaux avant de conclure", "description": "Un bras croisé seul peut signifier qu'il a froid. Bras croisés + regard fuyant + réponses courtes = résistance. La lecture se fait en constellation — jamais sur un seul signe isolé."}, {"title": "Il adapte sa posture en temps réel", "description": "Détecter un signal de résistance et continuer son pitch comme si de rien n'était est pire que de ne pas détecter. La valeur de la lecture est dans l'adaptation immédiate."}, {"title": "Il pose une question ouverte pour confirmer", "description": "Quand il perçoit un signal négatif : \"J'ai l'impression que quelque chose vous préoccupe — c'est le cas ?\" La question valide l'intuition et invite le client à exprimer ce qu'il retient."}, {"title": "Il lit aussi les signaux positifs", "description": "Question sur le délai, regard qui s'anime, posture qui s'ouvre — ce sont des signaux d'achat. Le commercial qui les détecte ferme au bon moment. Celui qui ne les voit pas continue à argumenter."}], "mistakes": [{"title": "Erreur 1 — N'écouter que les mots", "description": "Un client qui dit \"c'est intéressant\" avec un ton plat et un regard fuyant ne trouve pas ça intéressant. Prendre les mots au pied de la lettre crée des fins de RDV surprises."}, {"title": "Erreur 2 — Sur-interpréter un signal isolé", "description": "\"Il a croisé les bras — il résiste.\" Peut-être. Ou peut-être qu'il a froid. Un signal seul ne dit rien. Croiser 3 signaux cohérents avant de conclure."}, {"title": "Erreur 3 — Détecter sans adapter", "description": "Le commercial qui voit que le client décroche mais continue son argumentaire gaspille les deux ressources les plus précieuses : le temps et l'énergie. Détecter sans adapter ne sert à rien."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Briefer : \"Je vais jouer un client avec des signaux mixtes — verbaux positifs, non-verbal négatif. Ton objectif : détecter la contradiction, la nommer, et adapter. Je lève la main si tu continues à argumenter après un signal de résistance clair.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona avec des signaux non-verbaux clairs mais des mots neutres. Attendre que le commercial détecte et adapte. Observer : détection, croisement de signaux, adaptation."}, {"title": "Débriefer", "description": "\"Quels signaux as-tu détectés — verbaux, para-verbaux, non-verbaux ? Tu en as croisé plusieurs ? À quel moment as-tu adapté ta posture ? Tu as posé une question pour confirmer ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain RDV : note les 3 signaux les plus marquants et comment tu as adapté. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Les mots disent oui, le corps dit non", "objective": "Détecter la contradiction verbal/non-verbal, croiser les signaux, nommer la tension, adapter la posture.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 44 ans, responsable logistique. Dit \"oui, oui\" à tout mais résiste clairement."}, {"label": "Verbal", "text": "\"Oui c'est intéressant\", \"c'est bien\", \"je vois\". Aucune question, aucune objection formulée."}, {"label": "Non-verbal", "text": "Bras croisés, regard qui fuit la fiche de proposition, micro-recul quand le prix arrive."}, {"label": "Para-verbal", "text": "Ton plat, débit lent. \"Oui\" dit sur un ton descendant."}, {"label": "Frein réel", "text": "Il n'est pas décideur seul — doit valider avec son supérieur. N'ose pas le dire."}], "context": "Milieu de RDV. La présentation du véhicule vient de se terminer. Les signaux verbaux sont neutres mais le corps dit non.", "stakes": "L'enjeu : détecter la contradiction, croiser les 3 canaux, et poser la question qui va révéler le vrai frein.", "observe": ["Détecte-t-il la contradiction verbal/non-verbal ?", "Croise-t-il au moins 2 signaux avant de conclure ?", "Nomme-t-il la tension avec une question ouverte ?", "Adapte-t-il sa posture sans se braquer ?"]}, {"level": "intermediaire", "title": "Le client qui se ferme en cours de RDV", "objective": "Détecter un changement de posture en temps réel, identifier le déclencheur, adapter immédiatement.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 38 ans, infirmière. Très engagée au début, se ferme à mi-RDV après un SMS."}, {"label": "Avant SMS", "text": "Posture ouverte, questions actives, contact visuel fort."}, {"label": "Après SMS", "text": "Regard distrait, réponses courtes, commence à regarder l'heure."}, {"label": "Déclencheur", "text": "Message de sa fille — problème familial. Elle n'est plus dans le RDV."}, {"label": "Frein réel", "text": "Externe au RDV — pas lié au produit ou au prix."}], "context": "Mi-RDV. Tout allait bien. Elle reçoit un SMS et son comportement change instantanément.", "stakes": "L'enjeu : détecter le changement, identifier que le déclencheur est externe, proposer de faire une pause ou de reporter.", "observe": ["Détecte-t-il le changement en temps réel ?", "Identifie-t-il que le déclencheur est externe ?", "Propose-t-il une pause ou un report ?", "Maintient-il la qualité de relation malgré l'incident ?"]}, {"level": "avance", "title": "Les signaux d'achat discrets d'un profil flegmatique", "objective": "Détecter des signaux d'achat discrets, les interpréter correctement, passer au closing au bon moment.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 52 ans, directeur de site. Flegmatique, peu expressif. Ses signaux d'achat sont subtils."}, {"label": "Signaux d'achat", "text": "Pose des questions sur le délai de livraison, demande si la couleur noire est disponible, regarde son agenda."}, {"label": "Verbal", "text": "Ton neutre. \"Je vois\", \"d'accord\". Pas d'enthousiasme visible."}, {"label": "Non-verbal", "text": "Posture légèrement en avant quand il parle des détails pratiques."}, {"label": "Frein", "text": "Si le commercial ne détecte pas les signaux discrets, il continue à argumenter et rate la fenêtre."}], "context": "Fin de présentation véhicule. Il pose des questions pratiques sur les délais et la couleur.", "stakes": "L'enjeu : détecter ces signaux discrets comme signaux d'achat, s'arrêter d'argumenter, passer au closing.", "observe": ["Détecte-t-il les questions logistiques comme signaux d'achat ?", "S'arrête-t-il d'argumenter au bon moment ?", "Passe-t-il au closing sans tergiverser ?", "Sa lecture est-elle adaptée au profil flegmatique ?"]}]}, "online": {"focus": "la lecture des signaux", "attentionPoints": ["Observe-t-il les 3 canaux dès l'entrée ?", "Croise-t-il plusieurs signaux avant de conclure ?", "Adapte-t-il sa posture en temps réel ?", "Pose-t-il une question pour confirmer son interprétation ?"], "grid": ["3 canaux observés", "Signaux croisés", "Adaptation en temps réel", "Question de confirmation"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Quels signaux as-tu détectés ? Tu en as croisé plusieurs ? À quel moment as-tu adapté — et comment ? Tu as posé une question pour confirmer ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que quand [signal], tu as [adaptation]. Ma réaction : [observation]. Cette lecture en temps réel et adaptation immédiate, c'est exactement ça.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as continué à argumenter après 3 signaux de décrochage]. Dès 2 signaux cohérents, stoppe et pose la question.\""}, {"title": "Engagement", "prompt": "\"Sur ton prochain RDV : note les 3 signaux les plus marquants et comment tu as adapté. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Les 3 canaux sont connus — croiser avant de conclure est la règle", "02  Offline", "3 configurations de signaux pratiquées — détecter et adapter est un réflexe", "03  Online", "Le coach a observé et débriefé la lecture des signaux en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/9- Adapter ma communication/a. Interpréter les signaux.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('4596718c-7065-5aff-aa3d-df86f31d2a0e', '7921f1d2-245e-5733-85ab-a9373b4fc30e');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('4596718c-7065-5aff-aa3d-df86f31d2a0e', 'be7cb0c7-fb49-5028-9a16-c4618b9ccf4e');
insert into public.library_dojos (id, title, content, pptx_path) values ('85f5b8df-a696-57c7-9ad7-d1e1e02043d1', 'Adapter son comportement', $dojo${"version": 1, "tagline": "Adapter verbal, non-verbal et para-verbal pour favoriser l'échange", "objective": "Le commercial observe avant d'adapter, règle son débit et son vocabulaire sur le profil, se synchronise progressivement sur le non-verbal, et ajuste en continu.", "duration": "20-25 min", "theory": {"intro": "Un commercial qui parle vite avec un client lent crée de la friction. L'adaptation ne signifie pas perdre sa personnalité — c'est régler son canal sur celui du client pour que la communication passe mieux.", "standardTitle": "Le standard : les 3 leviers d'adaptation", "standard": [{"label": null, "title": "VERBAL", "description": "Adapter son vocabulaire (technique vs simple), sa formulation (directe vs nuancée), et la profondeur des explications. Un expert veut des détails. Un novice veut de la clarté.", "why": "Le client qui ne comprend pas se ferme sans le dire. Adapter le vocabulaire est le levier le plus accessible et le plus impactant."}, {"label": null, "title": "PARA-VERBAL", "description": "Adapter son débit, son volume, sa tonalité et la place des silences. Ralentir avec un client anxieux. Accélérer légèrement avec un client pressé.", "why": "Le débit crée ou détruit la connexion. Un commercial qui parle 2× plus vite que son client impose une cadence inconfortable — le client décroche."}, {"label": null, "title": "NON-VERBAL", "description": "Adapter sa posture, son regard et ses gestes. Se synchroniser progressivement — pas immédiatement, ce qui serait perçu comme imitation.", "why": "La synchronisation non-verbale progressive crée un sentiment de similitude inconscient. Le client se sent compris sans savoir pourquoi."}], "criteria": [{"title": "Il observe avant d'adapter", "description": "L'adaptation ne peut pas précéder l'observation. Les 30-60 premières secondes donnent les infos pour calibrer. Parler trop tôt avant d'avoir observé c'est jouer en aveugle."}, {"title": "Son adaptation est progressive — pas mimétique", "description": "Copier exactement la posture du client crée un effet miroir artificiel perçu comme manipulatoire. L'adaptation se fait graduellement — s'approcher sans singer."}, {"title": "Il adapte son niveau de langage sans condescendance", "description": "Simplifier sans donner l'impression de prendre pour un débutant. Expliquer simplement sans le signaler est la façon juste."}, {"title": "Il maintient sa propre identité", "description": "L'adaptation ne signifie pas devenir quelqu'un d'autre. Un commercial calme peut accélérer légèrement sans devenir hyperactif. Rester soi-même dans la direction de l'autre."}, {"title": "Il ajuste en continu si la situation change", "description": "Un client qui était détendu et qui devient tendu a changé de canal. L'adaptation est continue — pas une calibration faite une fois pour toutes."}], "mistakes": [{"title": "Erreur 1 — Imposer son propre rythme", "description": "Parler vite parce qu'on parle vite — sans se soucier du débit du client. Ce rapport de force crée de la fatigue et de la distance. L'adaptation, c'est le commercial qui se règle sur le client."}, {"title": "Erreur 2 — Sur-adapter (imitation visible)", "description": "Copier exactement les gestes et le débit crée un effet miroir artificiel. Le client le détecte — et perçoit une tentative de manipulation. L'adaptation subtile est invisible. La caricature est contre-productive."}, {"title": "Erreur 3 — Ne pas adapter le vocabulaire", "description": "Jargon technique avec un non-expert, ou trop simple avec un expert. Dans les deux cas, le client se sent mal compris. Le vocabulaire est le levier le plus facile à adapter — et le plus souvent oublié."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Briefer : \"Je vais jouer un client avec un style de communication bien défini. Ton objectif : observer, puis adapter progressivement. Je lève la main si tu copies exactement mes gestes ou si tu imposes ton propre rythme.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona avec un style marqué. Réagir positivement si l'adaptation est naturelle. Se fermer si le commercial impose son rythme ou copie maladroitement. Observer : observation préalable, adaptation des 3 leviers."}, {"title": "Débriefer", "description": "\"Qu'est-ce que tu as observé dans les 30 premières secondes ? Comment as-tu adapté ton débit ? Ton vocabulaire ? Ta posture ? Tu t'es ajusté quand j'ai changé de registre ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain RDV : note les 3 adaptations faites (verbal, para-verbal, non-verbal) et les réactions du client. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Le client expert technique", "objective": "Détecter un profil expert, adapter son vocabulaire au niveau technique, présenter avec la profondeur attendue.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Homme, 46 ans, ingénieur mécanique. Connaît très bien les motorisations."}, {"label": "Style", "text": "Direct, factuel. Pose des questions techniques précises. Apprécie les chiffres."}, {"label": "Signal", "text": "\"Quelle est la puissance réelle en kW et le couple maxi à quel régime ?\""}, {"label": "Attente", "text": "Un commercial qui sait de quoi il parle. Pas de simplification condescendante."}, {"label": "Frein", "text": "Si le commercial simplifie trop, il perd sa crédibilité immédiatement."}], "context": "Début de RDV. Il entre en posant une question technique précise sur la motorisation.", "stakes": "L'enjeu : basculer immédiatement vers un registre technique factuel et maintenir la crédibilité.", "observe": ["Détecte-t-il le profil expert immédiatement ?", "Adapte-t-il son vocabulaire au registre technique ?", "Présente-t-il avec la profondeur attendue ?", "Maintient-il sa crédibilité face aux questions pointues ?"]}, {"level": "intermediaire", "title": "Le client anxieux au débit lent", "objective": "Détecter un profil anxieux, ralentir son propre débit, augmenter les silences, adapter son ton pour rassurer.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Femme, 28 ans, aide-soignante. Premier achat. Parle lentement, pose des questions hésitantes."}, {"label": "Style", "text": "Lent, hésitant. Silence fréquent avant de répondre."}, {"label": "Signal", "text": "\"Euh... c'est quoi la différence entre... enfin... la LOA et le crédit ?\""}, {"label": "Attente", "text": "Être rassurée et comprise. Pas bousculée par un commercial rapide."}, {"label": "Frein", "text": "Si le commercial maintient son rythme habituel, elle décroche et perd confiance."}], "context": "Mi-RDV. Elle répond lentement, hésite beaucoup.", "stakes": "L'enjeu : ralentir consciemment, laisser des silences assumés, valider régulièrement sans condescendance.", "observe": ["Ralentit-il consciemment son débit ?", "Laisse-t-il des silences sans les combler ?", "Valide-t-il la compréhension régulièrement ?", "Évite-t-il toute condescendance ?"]}, {"level": "avance", "title": "Le client qui change de registre en cours de RDV", "objective": "Détecter un changement de registre (du formel au détendu) et s'y adapter progressivement.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 42 ans, directeur commercial. Arrive formel et froid — se détend progressivement."}, {"label": "Début", "text": "Costume, ton directif, questions précises. Veut aller à l'essentiel."}, {"label": "Évolution", "text": "Après 15 minutes, se détend. Parle de ses enfants. Sourires. Ton qui change."}, {"label": "Attente", "text": "Que le commercial suive le changement naturellement — ni trop vite ni trop lentement."}, {"label": "Frein", "text": "Si le commercial reste formel quand le client se détend, la connexion ne se crée pas."}], "context": "RDV de 30 minutes. Les 15 premières minutes sont formelles. Puis il se détend et commence à plaisanter légèrement.", "stakes": "L'enjeu : détecter ce changement, s'y adapter progressivement, suivre le registre détendu sans forcer.", "observe": ["Détecte-t-il le changement de registre ?", "S'adapte-t-il progressivement (pas immédiatement) ?", "Suit-il le registre détendu sans forcer ?", "Maintient-il le fond professionnel dans la forme détendue ?"]}]}, "online": {"focus": "l'adaptation communication", "attentionPoints": ["Observe-t-il avant d'adapter ?", "Adapte-t-il débit et vocabulaire au profil ?", "Sa synchronisation non-verbale est-elle progressive ?", "S'ajuste-t-il si le client change de registre ?"], "grid": ["Observation préalable", "Débit + vocabulaire adaptés", "Synchro non-verbale progressive", "Ajustement si changement"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Qu'est-ce que tu as observé dans les 30 premières secondes ? Comment as-tu adapté ton débit ? Ton vocabulaire ? Ta posture ? Tu t'es ajusté quand j'ai changé de registre ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que tu as [adaptation précise]. Ma réaction : [observation]. Cette adaptation progressive et naturelle, c'est ce qui crée la fluidité.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as gardé ton débit rapide alors que je parlais lentement]. Dans les 30 premières secondes, calibre ton débit sur le sien.\""}, {"title": "Engagement", "prompt": "\"Sur ton prochain RDV : note les 3 adaptations et les réactions. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Les 3 leviers sont connus — adaptation progressive, pas mimétique", "02  Offline", "3 profils pratiqués — observer puis adapter est un réflexe", "03  Online", "Le coach a observé et débriefé l'adaptation communication en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/9- Adapter ma communication/b. Adapter son comportement.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('85f5b8df-a696-57c7-9ad7-d1e1e02043d1', 'b9578d3f-4304-5051-be0b-6589422957e6');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('85f5b8df-a696-57c7-9ad7-d1e1e02043d1', '07f9d17f-5688-52b4-b979-a8ac7ebcb049');
insert into public.library_dojos (id, title, content, pptx_path) values ('fe45d204-5571-5e9c-8d3c-bffdbfa76abd', 'Le SONCASE', $dojo${"version": 1, "tagline": "Identifier et activer le levier motivationnel dominant du client", "objective": "Le commercial identifie le levier SONCASE dominant en découverte, ancre son argumentation dessus, utilise les mots du client, et confirme que l'argument a touché.", "duration": "20-25 min", "theory": {"intro": "Chaque client achète pour des raisons différentes. Argumenter sur la Sécurité avec quelqu'un motivé par l'Argent est inefficace. Le SONCASE permet d'identifier le levier dominant et d'ancrer l'argumentation sur ce qui motive vraiment.", "standardTitle": "Le standard : les 7 leviers SONCASE", "standard": [{"label": null, "title": "S — SÉCURITÉ", "description": "Besoin de fiabilité, garanties, certitudes. Peur du risque. \"Et si ça tombe en panne ?\"", "why": "Argumenter sur la garantie, la solidité, les statistiques de fiabilité. Rassurer avec des preuves concrètes."}, {"label": null, "title": "O — ORGUEIL", "description": "Besoin de reconnaissance, statut, distinction. Marque, finition premium, image.", "why": "Argumenter sur l'image, la rareté, ce que le véhicule dit de lui."}, {"label": null, "title": "N — NOUVEAUTÉ", "description": "Attrait pour la technologie, l'innovation. \"Qu'est-ce qui est nouveau ?\"", "why": "Argumenter sur les technologies embarquées, les évolutions récentes."}, {"label": null, "title": "C — CONFORT", "description": "Besoin de bien-être, praticité, absence d'effort. Facilité d'utilisation, habitabilité.", "why": "Argumenter sur le confort de conduite, les assistances. \"Vous n'avez plus à y penser.\""}, {"label": null, "title": "A — ARGENT", "description": "Sensibilité au prix, coût total, économies, rapport qualité-prix.", "why": "Argumenter sur la valeur de revente, les économies carburant, le coût global à 3 ans."}, {"label": null, "title": "S — SYMPATHIE", "description": "Décision influencée par la relation, la confiance, le feeling avec le commercial.", "why": "Soigner la relation, personnaliser, être sincère. Ce client achète autant la personne que le produit."}, {"label": null, "title": "E — ENVIRONNEMENT", "description": "Sensibilité écologique, valeurs de responsabilité, impact environnemental.", "why": "Argumenter sur les émissions, la motorisation hybride/électrique, l'engagement constructeur."}], "criteria": [{"title": "Il détecte le levier dominant en découverte", "description": "Les mots du client révèlent son levier : \"fiable\" → Sécurité. \"économique\" → Argent. \"dernier modèle\" → Nouveauté. L'écoute active des mots exacts est la clé du diagnostic."}, {"title": "Il argumente sur le dominant — pas sur tous", "description": "Dérouler les 7 leviers en espérant qu'un touche juste dilue l'argumentation. 1-2 leviers dominants bien travaillés valent 10 arguments génériques."}, {"title": "Il utilise les mots du client", "description": "\"Vous m'avez dit que la fiabilité était primordiale — avec la garantie 5 ans, vous êtes couvert exactement là-dessus.\" Reprendre les mots exacts crée un effet miroir puissant."}, {"title": "Il adapte si le client change de signal", "description": "Un client peut envoyer des signaux Sécurité au début et Argent quand arrive le prix. Le SONCASE se réévalue en temps réel."}, {"title": "Il confirme que l'argument a touché", "description": "\"Ça correspond bien à ce que vous cherchez sur ce point ?\" Cette question valide le levier détecté — et donne au client l'occasion de confirmer ou rectifier."}], "mistakes": [{"title": "Erreur 1 — Argumenter sur son propre levier", "description": "Le commercial passionné par la tech qui parle innovation à un client motivé par l'Argent. L'argumentation doit être au service du levier du CLIENT — pas de celui du commercial."}, {"title": "Erreur 2 — Vouloir couvrir tous les leviers", "description": "\"Il y a les garanties, c'est économique, c'est le dernier modèle, très confortable...\" 7 arguments génériques = aucun argument marquant. Choisir 1-2 leviers et argumenter en profondeur."}, {"title": "Erreur 3 — Ne pas réévaluer si le contexte change", "description": "Détecter Sécurité en début de RDV et rester dessus alors que le client est clairement préoccupé par le prix à la proposition. Le SONCASE n'est pas un diagnostic figé — c'est une boussole ajustable."}], "sections": []}, "offline": {"guide": [{"title": "Préparer la séance", "description": "Briefer : \"Je joue un client avec un levier SONCASE dominant marqué. Ton objectif : l'identifier en découverte, ancrer ton argumentation dessus, et utiliser mes mots. Je lève la main si tu argumentes sur un autre levier.\""}, {"title": "Lancer le scénario", "description": "Jouer le persona avec des signaux SONCASE clairs. Réagir positivement quand l'argument touche le bon levier. Rester résistant si le commercial argumente à côté. Observer : diagnostic, ancrage, mots du client repris."}, {"title": "Débriefer", "description": "\"Quel levier SONCASE as-tu identifié — et à quel moment ? Sur quoi as-tu argumenté ? Tu as repris mes mots — lesquels ? Tu as confirmé que l'argument avait touché ?\""}, {"title": "Fixer la prochaine étape", "description": "\"Sur ton prochain RDV : note le levier SONCASE et les 2 arguments utilisés. Date : [date].\""}], "scenarios": [{"level": "debutant", "title": "Levier Sécurité — client anxieux sur la fiabilité", "objective": "Détecter Sécurité, ancrer l'argumentation sur fiabilité et garanties, utiliser les mots du client.", "duration": "20 min", "persona": [{"label": "Profil", "text": "Femme, 34 ans, infirmière libérale. Utilise son véhicule pour ses tournées. Peur des pannes."}, {"label": "Signaux SONCASE", "text": "\"Je veux quelque chose de fiable\", \"ça coûte cher une panne\", \"mon dernier m'a laissée tomber\"."}, {"label": "Levier dominant", "text": "Sécurité — fort et explicite."}, {"label": "Attente", "text": "Des preuves concrètes de fiabilité. Pas des généralités."}, {"label": "Frein", "text": "Si le commercial argumente sur la technologie ou le prix, elle reste dans l'inquiétude."}], "context": "Découverte en cours. Elle a mentionné sa peur des pannes 2 fois.", "stakes": "L'enjeu : détecter Sécurité, préparer un argument ancré sur garantie et fiabilité, utiliser ses mots exacts.", "observe": ["Identifie-t-il le levier Sécurité au bon moment ?", "Ancre-t-il sur garantie et fiabilité ?", "Utilise-t-il les mots exacts du client ?", "Confirme-t-il que l'argument a touché ?"]}, {"level": "intermediaire", "title": "Levier Argent — client qui calcule tout", "objective": "Détecter Argent, construire un argumentaire sur le coût total d'usage, connecter à la découverte.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 42 ans, gérant de PME. Très sensible au ROI. Compare tout en coût annuel."}, {"label": "Signaux SONCASE", "text": "\"C'est quoi le vrai coût sur 3 ans ?\", \"la valeur de revente ?\", \"combien j'économise ?\""}, {"label": "Levier dominant", "text": "Argent — très explicite. Raisonne en coût total, pas en prix d'achat."}, {"label": "Attente", "text": "Des chiffres concrets sur son profil (40 000 km/an) — pas des moyennes génériques."}, {"label": "Frein", "text": "Si le commercial argumente sur le confort ou la technologie, il décroche."}], "context": "Milieu de RDV. Il a posé 3 questions financières précises. Levier Argent clairement dominant.", "stakes": "L'enjeu : construire le CAB sur le coût total ancré dans ses 40 000 km/an réels.", "observe": ["Identifie-t-il Argent (et pas Sécurité ou Confort) ?", "Calcule-t-il sur ses 40 000 km réels ?", "Argumente-t-il coût total (pas prix d'achat) ?", "Son argument est-il ancré dans la découverte ?"]}, {"level": "avance", "title": "Levier mixte — Orgueil + Sympathie", "objective": "Détecter 2 leviers coexistants, prioriser le bon selon le moment, alterner dans l'argumentation.", "duration": "25 min", "persona": [{"label": "Profil", "text": "Homme, 50 ans, notaire. Image pro importante ET très sensible à la relation."}, {"label": "Signaux Orgueil", "text": "\"Ce que je cherche c'est quelque chose qui reflète ce que je suis professionnellement.\""}, {"label": "Signaux Sympathie", "text": "Chaleureux, parle de sa vie, veut clairement avoir confiance."}, {"label": "Levier", "text": "Orgueil en contexte pro, Sympathie en contexte relationnel — les deux coexistent."}, {"label": "Frein", "text": "Uniquement Orgueil = manque de chaleur. Uniquement Sympathie = image absente."}], "context": "RDV complet. Il alterne entre des remarques sur l'image et des moments de chaleur relationnelle.", "stakes": "L'enjeu : alterner intelligemment entre les 2 leviers selon le moment.", "observe": ["Détecte-t-il les 2 leviers coexistants ?", "Priorise-t-il le bon selon le contexte ?", "Alterne-t-il naturellement entre les 2 ?", "Ses arguments sont-ils ancrés dans la découverte ?"]}]}, "online": {"focus": "le SONCASE appliqué", "attentionPoints": ["Identifie-t-il le levier dominant en découverte ?", "Ancre-t-il l'argumentation sur ce levier (pas sur tous) ?", "Utilise-t-il les mots exacts du client ?", "Confirme-t-il que l'argument a touché ?"], "grid": ["Levier SONCASE identifié", "Argumentation ancrée", "Mots du client repris", "Confirmation de l'impact"], "debrief": [{"title": "Auto-évaluation", "prompt": "\"Quel levier SONCASE as-tu identifié — et à quel moment ? Sur quoi as-tu argumenté ? Tu as repris mes mots — lesquels ? Tu as vérifié que l'argument avait touché ?\""}, {"title": "Retour du coach — réussites", "prompt": "\"J'ai observé que tu as dit [argument ancré sur le bon levier] en reprenant [mots du client]. Un argument qui touche le bon levier change tout.\""}, {"title": "Axe de travail prioritaire", "prompt": "\"Un seul point : [ex: tu as argumenté sur la technologie alors que mon levier était clairement l'Argent]. Note le mot que le client répète le plus — c'est souvent son levier.\""}, {"title": "Engagement", "prompt": "\"Sur ton prochain RDV : note le levier SONCASE et les 2 arguments utilisés. Date : [date].\""}], "sections": [{"title": "Ce qu'on retient | 01  Théorie", "lines": ["Ce qu'on retient", "01  Théorie", "Les 7 leviers sont connus — détecter le dominant et ancrer dessus est la règle", "02  Offline", "3 profils SONCASE pratiqués — identifier et ancrer est un réflexe", "03  Online", "Le coach a observé et débriefé l'application du SONCASE en situation réelle", "Prochaine étape : retour terrain — date de suivi à planifier avec le manager"]}]}, "takeaways": null, "hasPlaceholders": false}$dojo$::jsonb, 'bibliotheque/9- Adapter ma communication/c. Le SONCASE.pptx');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('fe45d204-5571-5e9c-8d3c-bffdbfa76abd', 'f5dc5226-e0cd-5660-ae96-75027c2b1d54');
insert into public.library_dojo_skills (library_dojo_id, template_skill_id) values ('fe45d204-5571-5e9c-8d3c-bffdbfa76abd', '8d59ac07-d1ab-51d0-85bf-9282ef81284f');
